INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Rum Origens Philippines', 'https://spitus.dk/product/dos-maderas-rum-origens-philippines/', 439, true, 70, 42.7, 'https://spitus.dk/wp-content/uploads/2026/11/dos-madereas-p.jpg', 'Dos Maderas har tidligere hentet rom fra Thailand, og i 2026 er turen kommet til Filippinerne, som har en lang tradition for rom. Rommen er lavet på lokalt dyrket sukkerrør og er produceret i ét enkelt parti på kun 18.000 flasker. Den bliver ikke lavet igen. Det er altså ikke en rom, man kan “tage næste gang”, for næste gang findes ikke. Først lagrede rommen i seks år på bourbonfade på Filippinerne, hvor den fik varme, fugt og masser af tid til at tænke over tilværelsen. Derefter blev den sendt til Jerez i Spanien, hvor Williams &amp; Humbert lod den modne videre på meget sjældne fade, der tidligere har rummet 80 år gammel amontillado-sherry. Rommen har med andre ord fået lov at flytte ind i nogle fade, der var ældre end de fleste af os, og det kan smages. I glasset er den dyb ravfarvet med mahognitoner og en gylden kant. Duften starter med moden banan og diskrete vinagtige nuancer, og så følger karamel, toffee og ristet kokos. Bagved ligger ristede hasselnødder, et strejf af kandiseret appelsinskal og en saltet, næsten jodagtig tone. Du ender sandsynligvis med at snuse til glasset længere, end man helt kan sige i godt selskab. Smagen er rund og omsluttende. Den er sød uden at blive sirupsagtig, og tropisk frugt blander sig med vanilje, honning og blød hasselnød. Fra sherryfadene kommer en elegant oxidativ nøddenote, der får det hele til at virke velpudset. Eftersmagen er lang og varm og ender tør med valnød og ristet træ, og den bliver ved, til du pludselig opdager, at glasset er tomt. Med 42,7% alkohol er der styrke nok til at gøre indtryk, uden at den behøver at råbe. Skænk den ved stuetemperatur i et smagsglas, uden is og uden hast. Den kan også bruges i cocktails, men prøv den ren først, så ved du, hvad du blander væk. Flasken er perfekt til samleren, der allerede har Thailand stående og nu skal have serien til at hænge sammen. Den er også en god gave til den, der tror, at rom kun kommer fra Caribien, og som fortjener at blive klogere. Bemærk, at der på grund af den håndlavede proces kan opstå naturligt bundfald. Det er ikke en fejl, men bevis på, at rommen ikke er pillet unødigt ved. Leveres i gaveæske. Alkohol % : 42,7 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Flor de Cana Centenario 12 års Rom &#8211; i gaveæske med 1 glas', 'https://spitus.dk/product/flor-de-cana-centenario-12-aars-rom-i-gaveaeske-med-1-glas/', 329, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/11/flor_de_cana_centenario_12_years_1_glass_40_70_cl_gbx.png', 'Flor de Caña har rødder helt tilbage til 1890. På San Antonio Sugar Mill i Chichigalpa, Nicaragua, producerer 5. generation af Pellas-familien stadig rom, som man gjorde dengang. Det er ikke noget, man opfinder på en tirsdag. I dag regnes Flor de Caña for det førende rom-destilleri i Mellemamerika, og de senere år har de haft stor succes på eksportmarkederne. Den 12-årige “Old Rom” er vinder af 13 internationale priser og er nok deres bedst kendte produkt. Farven er rav med et rødt skær. I næsen møder du sherry, eg og karamel. I munden er den sødlig, men ikke voldsomt sød, og du kan finde smør, honning, nougat, brændte fade, karamel og dadler. I den lange eftersmag får du mere af det hele, og så træder krydderierne og nogle mørkere noter pænt frem. Der er ingen tilsatte kunstige trylleting. Da det er en fuldlagret 12-årig rom, kan man tydeligt mærke, at de mange år på fad har sat deres spor, som en rom, der har set lidt af hvert og stadig holder humøret oppe. Den er yderst velafbalanceret og nydes bedst ren eller med isterninger. Wine Enthusiast anbefaler den stærkt og har givet den 90-95 points, så vi er ikke de eneste, der er glade for den. At destilleriet går forrest med hensyn til bæredygtighed, er et stort plus. Flor de Caña er certificeret CO2-neutralt, overholder betingelserne for fair trade, bruger 100% vedvarende energi og kompenserer for eventuelle emissioner ved at plante træer. Siden 2005 er det blevet til 50.000 nye træer om året. Vi ka’ li’ det! Skal den forære lidt kærlighed videre, leverer vi den i en gaveæske af genbrugspap inklusive ét Flor de Caña rom-glas, så modtageren kan komme i gang med det samme. Det er egentlig vanvittigt, at man kan få så meget ægte fuldlagret rom for de penge. Leveres i gaveæske med 1 glas. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Kraken Black Spiced: The Legendary Survivor Series, Limited Edition', 'https://spitus.dk/product/kraken-black-spiced-the-legendary-survivor-series-limited-edition/', 409, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/11/kraken-survivor.webp', 'Kraken er kendt for sin næsten sorte flaske, så det er lidt af en overraskelse at møde en hvid en. Legendary Survivor Series er en limited edition, og den hvide flaske fortæller historien om “The Lighthouse Keeper”, fyrvogteren, der overlevede Kraken. Det er de færreste, der kan sige det, og det er en historie, man gerne vil have stående på hylden. Limited edition betyder, at når flaskerne er væk, er de væk. Det gør den interessant for samlere, og det gør den til en gave, der får modtageren til at sige “hold da op”, før proppen er trukket. Det er en sjælden kombination, at flasken både ser godt ud og er god at drikke af. Indeni er det den Kraken, du kender. Den er lavet på karibisk melasserom og tilsat en hemmelig blanding af 11 eksotiske krydderier. Hvad der præcis er i blandingen, får vi ikke at vide, men resultatet kan smages: mørk chokolade, vanilje, kanel, nelliker og et strejf af kaffe. Det hele hviler på rommens naturlige sødme og krydrede karakter, så smagen er rund og fyldig uden at blive sukkersød. Farven er dyb og næsten sort, hvilket er en fin kontrast til den hvide flaske. Med 40% er den en rom, der tåler at blive blandet. Den fungerer glimrende med cola, i en Dark ’n’ Stormy med ginger beer og lime eller i en mørk cocktail, hvor du gerne vil have lidt mere karakter end det, en almindelig hvid rom kan levere. Er du mere til at drikke den ren, kan du stille den på is og lade kanel og kaffe gøre arbejdet. Du behøver ikke være rom-ekspert for at nyde den. Så hvis du kender en, der elsker Kraken, en der samler på særudgaver, eller en der bare mangler en god krydret rom til baren derhjemme, er det her en oplagt kandidat. Den ser godt ud, den smager godt, og der er ikke så mange af dem. Alkohol %: 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hampden Estate Rum 8-Year-Old Pure Single Jamaican Rum 46%', 'https://spitus.dk/product/hampden-estate-rum-8-year-old-pure-single-jamaican-rum-46/', 549, true, 70, 46, 'https://spitus.dk/wp-content/uploads/2026/10/59-1.png', 'Hampden Estate har holdt til i Trelawny på Jamaica siden 1753. Det er så længe, at destilleriet har nået at overleve både uafhængighedskrige, moderigtige drinkstrends og utallige diskussioner om, hvorvidt rom skal være sød. Svaret hos Hampden er et ret tydeligt nej, og det er netop derfor, vi kan lide dem. Sukkerrøret kommer fra destilleriets egne marker, Everglades Farms. Her har man altså styr på tingene fra start til slut. Melassen gærer usædvanligt længe på naturlige, lokale gærsorte, og det giver de intense, højt estrede aromaer, som Hampden er kendt for. Det lyder teknisk, men i praksis betyder det, at rommen dufter af så meget, at man ikke bør åbne flasken, hvis man er i gang med en samtale. Man bliver nemlig tavs. Destillationen foregår udelukkende på pot stills af kobber, blandt andet fra skotske Forsyths. Bagefter modner rommen i mindst otte år på ex-bourbonfade af amerikansk hvid eg. Jamaicas varme og fugtige klima gør, at modningen går hurtigere end i Skotland, så de otte år har ramt noget, der minder om en del flere. Rommen har altså arbejdet hårdere end de fleste af os. Herefter fortyndes den kun med vand fra destilleriets egen bjergkilde til 46%. I glasset er der masser af duft. Tænk moden tropisk frugt, banan, ananas og en krydret, lettere funky karakter, som signalerer, at den her rom ikke vil være pæn og anonym. Smagen er fyldig, kompleks og ægte, og eftersmagen bliver hængende længe nok til, at man når at nikke anerkendende. Den er uden tilsat sukker, farvestof og glycerin, så det, du smager, er det, rommen selv har lavet. Ingen genveje, ingen make-up. Den egner sig til at nyde ren, gerne med en enkelt isterning, hvis du er til det. Den klarer sig også fint i en Daiquiri, hvor den ikke gider være baggrundsstøj. Rommen kommer i en flot gaveæske, så den fungerer lige så godt til julegaven til svigerfar, der påstår, at han ikke bryder sig om rom, indtil han har smagt den. Belønnet med guld ved ISW 2021, så vi er ikke de eneste, der har bemærket det. Skål, og husk at lukke flasken, før naboerne kommer for at spørge, hvad det er, der dufter sådan. Leveres i gaveæske. Alkohol % : 46,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 30th Anniversary FUNDADOR Founder’s Cask Strength Limited Edition 54.3%', 'https://spitus.dk/product/ron-quorhum-30th-anniversary-fundador-founders-cask-strength-limited-edition-54-3/', 995, true, 70, 54.3, 'https://spitus.dk/wp-content/uploads/2026/10/quorhum-fundador-cask.webp', 'Ron Quorhum 30th Anniversary Fundador Cask Strength 54,3%: fire rom-traditioner og ingen vand Rom fra Den Dominikanske Republik bliver ofte beskrevet som blød og venlig. Det her er stadig venligt, men den er også tappet på fadstyrke ved 54,3%, og ingen har tilsat vand. Ron Quorhum 30th Anniversary Fundador Cask Strength er en limited edition, der fejrer Casa Olivers 30-års jubilæum. Den kommer i en gaveæske, så festen kan begynde allerede, når du åbner pakken. Fire traditioner i én flaske Romen er resultatet af et samarbejde mellem Pedro Ramón López-Oliver og hans fire master blenders. De har blandet fire rom-traditioner: dominikansk, colombiansk, venezuelansk og cubansk. Det lyder som en lang rejse, men den foregår i en flaske, så du behøver ikke et visum. Romen er lavet på melasse og lagret efter solera-systemet, hvor forskellige rom modner sammen, så dybden bygges op lag for lag. Hvad betyder cask strength? Det betyder, at romen er tappet direkte fra fadet og ikke fortyndet bagefter. Den har alle den originale Fundadors egenskaber, men intensiteten er skruet op. Strukturen træder tydeligere frem, og træ, krydderier, moden frugt og en let sødme kommer mere klart til udtryk. Den er altså ikke til dig, der vil have en rom, du kan drikke uden at lægge mærke til den. Duft og smag Farven er en dyb, klar ravfarve med kobberfarvede reflekser. I næsen møder du lagret egetræ, vanilje, karamel, modne druer og honning, med et strejf af citrus, tobak og krydderier. På tungen er den fyldig og kraftfuld, men stadig harmonisk, med noter af mørk chokolade, tørret frugt, fint egetræ, naturlig sødme fra sukkerrør og krydrede træ-nuancer. Eftersmagen er lang, varm og kompleks med træ, vanilje, søde krydderier og en elegant tørhed. Sådan drikker du den Skænk den ren i et lille glas, og tag dig god tid. Et par dråber vand kan åbne flere lag af træ, kakao og tørret frugt, og det er ikke snyd. Den passer godt til kraftige desserter som en tærte med mørk chokolade, kakaokage med nødder eller karamelliserede figner. Den fungerer også sammen med lagret ost, ristede nødder eller en cigar. Efter et stort måltid er den en intens og langtidsholdbar digestif. Den er lavet til rom-entusiasten, der allerede har prøvet det meste, og som gerne vil have noget med lidt kant. Den er også en god gave til en samler, fordi det er en limited edition i gaveæske. I (meget) eksklusiv gaveæske. Størrelse : 70 cl Alkohol % : 54,3%');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario Luxus Tasting Set (12 Years+20 Years+25 Years+30 Years), 4 x 5 cl', 'https://spitus.dk/product/ron-centenario-luxus-tasting-set-12-years-20-years-25-years-30-years-4-x-5-cl/', 349, true, 20, 40, 'https://spitus.dk/wp-content/uploads/2026/10/ron-centenario-tasting-set-4x5cl.webp', 'I lang tid var Costa Rica primært kendt for produktion af kaffe. Men på grund af sin placering mellem Caribien og Atlanterhavet, kan der dyrkes sukkerrør af meget høj kvalitet, som derefter kan destilleres til rom. Centenario Rums har bragt nogle premium-rums på markedet, der nyder stigende popularitet. Generelt er rommene fra Centenario gode bud på rom i den søde stil, hvor du får meget for pengene. Fire aldre, fire glas og én meget god aften Der er to måder at finde sin favorit-rom på. Man kan købe fire flasker og håbe på det bedste, eller man kan købe dette sæt. Vi anbefaler den sidste, både af hensyn til din pung og din hylde. Ron Centenario Luxus Tasting Set indeholder fire rom fra Costa Rica på 5 cl hver: 12 Years, 20 Years, 25 Years og 30 Years. Du får altså en hel rejse gennem Centenarios aldersrække, uden at du skal bruge lige så mange år på at gennemføre den. Duft: Sættet holder sig inden for et tydeligt Centenario-register af vanilje, karamel, træ, tørret frugt og blide krydderier. Det ændrer sig fra rom til rom, men familielighederne er til at få øje på. De yngre rom er bløde og imødekommende, mens de ældre har mere struktur og dybde. Smag: Stilen er rund og afbalanceret hele vejen igennem. Du starter med sødere og mere frugtprægede noter og bevæger dig gradvist mod rigere, mere træmodnet krydderi. Det er en lidt som at gå fra forretten til hovedretten, bare med færre servietter. Eftersmag: I de yngre udgaver er den glat og let. I de ældre bliver den længere og mere lagdelt, så du får lov til at have smagen med dig, længe efter glasset er tomt. Med en 12-årig, en 20-årig, en 25-årig og en 30-årig i samme kasse kan du selv sammenligne, hvad ekstra år i fad gør. Det er interessant, og det er hyggeligt, og begge dele kan lade sig gøre samtidig. Til hvem? Til rom-entusiasten, der gerne vil have overblik. Til den nysgerrige, der overvejer at investere i en af de ældre flasker og gerne vil smage først. Og til den, der skal give gave og gerne vil have, at den ser dyr ud, og det gør den. Hæld op, skriv noter, og lad som om, du har gjort det før. Tag dem i rækkefølge, fra 12 til 30, så du får den fulde oplevelse. Du må gerne gå tilbage til din favorit bagefter. Det gør alle. Alkohol % : 40,0 Størrelse : 4 x 5 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario 1985 Cask Selection Rum, Batch 2', 'https://spitus.dk/product/ron-centenario-1985-cask-selection-rum-batch-2/', 495, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2026/10/centenario-1985output_6cb97f0f-d230-4aa9-b517-23d3c38dcfe9.webp', 'Costa Rica møder Skotland, og begge kommer fra det med æren i behold. I 1985 blev Ron Centenario født i Costa Rica. Den fødselsdag blev fejret i 2020 med 35-årsjubilæet, og efterfølgende har de fejret med at udgive flere batches, Dette er Batch 2. Det er en rom, der har lavet lidt ekstra hjemmearbejde. Blandingen består af rom, der har ligget og modnet i mellem 6 og 20 år, lavet på både lettere og lidt tungere destillater. Til sidst har den fået en afsluttende modning på skotske whiskyfade fra Highlands. Fadene blev sendt hele vejen til Costa Rica, hvor de har ligget i junglens varme og fugt. De fik ikke rigtig lov til at vælge, men det ser ikke ud til at have skadet. Resultatet er en rom, der stadig er sød i Centenarios velkendte stil, men med en tydelig kant fra whiskyfadene. Den er altså ikke bare sød og sød. Den har også noget at sige. Farve: Smuk guld i glasset. Duft: Frugt, lidt røg og træ. Det er en duft, der gør, at man holder næsen i glasset lidt længere end høfligt. Smag: Frisk og frugtig i starten, med kirsebær, jordbær og rødt æble. Derefter kommer eg, et strejf af røg og en lille buskagtig kant, der giver karakter. Det er sødmen fra rommen og det tørre fra whiskyfadene, der finder ud af at dele bord. Eftersmag: Lang og blid. Den bliver hængende, så du får lov til at nyde den en ekstra gang. Med 43% har den lidt mere kant end de fleste, og den er stadig rund og let at drikke. Den er perfekt ren i et godt glas, eventuelt med en enkelt isterning, hvis du har lyst til det. Flasken er flot med guldpræget etiket og står godt på hylden. Den er også en oplagt gave til rom-elskeren, der har prøvet det meste og gerne vil overraskes. Det er en begrænset udgave, så der er ikke et uendeligt lager at tage af. Størrelse : 70cl Alkohol % : 43,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Non Plus Ultra Very Rare', 'https://spitus.dk/product/old-st-croix-non-plus-ultra-very-rare/', 795, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2026/10/NPU-11-Very-rare.png', 'Old St. Croix Non Plus Ultra Very Rare er mærkets &#8220;Ultra Premium Product&#8221;, der fuldender Old St. Croix (tidligere A. H. Riise) sortimentet. Begrebet, &#8220;Non Plus Ultra&#8221;, stammer fra Herkules&#8217; Søjler, der, ifølge den romerske mytologi, blev bygget nær Gibraltarstrædet og markerede grænsen af den kendte verden. Søjlerne bar skriften, &#8220;Non Plus Ultra&#8221; (Latinsk for: Nothing Further Beyond), som en advarsel til søfarende om ikke at fortsætte sejladsen ud i det ukendte. Denne Old St. Croix Non Plus Ultra Rare lever fuldt op til sit navn. Non Plus Ultra er håndblendet af deres Master Blender, som personligt udvælger hvert fad, der indgår i den færdige rombaserede spirit drink (grundet indholdet af sukker pr. liter, må indholdet ikke længere benævnes rom, men nu en rombaseret spirit drink). Farven på A.H Riise Non Plus Ultra er mørk maghoni. I næsen er der en elegant krydret bouquet af appelsin, egetræ, vanilje, tobak og rosiner. I munden får du sherrynoter, appelsin, karamel, vanilje og egetræ. Det hele lukker i en flot finish, der efterlader et sødmefuldt velbehag. Spirit drinks fra Old St. Croix er søde i stilen, og danskerne er vilde med dem! De ligger konstant i toppen af listen over ”mest solgte”. Er du fan af sød rom, bliver det ikke bedre end dette! A.H. Riise Non Plus Ultra er en drik, der udgives i begrænsede mængder, da der kun bliver aftappet 2.000 flasker om året. Flasken ligner en million (cirka), og leveres i en flot gavekasse, der matcher. Størrelse : 70 cl Alkohol % : 42,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Non Plus Ultra Ambre d&#8217;Or Excellence', 'https://spitus.dk/product/old-st-croix-non-plus-ultra-ambre-dor-excellence/', 795, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2026/10/NPU-11-ambre-dor.png', 'Old St. Croix Non Plus Ultra Ambre d’Or Excellence, er den ene af de fire brødre i den eksklusive Non Plus Ultra-serie (De andre er ”Non Plus Ultra Very Rare” og ”Non Plus Ultra Black Edition” og &#8220;Old St. Croix La Galante&#8221;). Navnet forpligter; Non Plus Ultra (Nothing Further Beyond), henviser til Herkules stolper, der markerer enden eller grænsen for den kendte verden. Denne Ambre d’Or Excellence er helt speciel, idet den bl.a. modnes i de ældste og bedste fade som tidligere er brugt til at modne søde dessertvine . Det franske ord “Ambre” er valgt af respekt for franskmændene, og deres unikke evne til at lave førsteklasses vin og ikke mindst dessertvin. Udtrykket er en let mildere og lysere drik i forhold til brødrene, men alligevel med fantastisk pondus og karakter. Farven er rav, og i næsen får du florale noter, blommer og eksotiske frugter. I munden supplerer de varme krydderier og chokolade. Der er sublime sherry- og sauternes toner fra fadene, og du overraskes af den stigende intensitet og øgede velsmag. Eftersmagen er virkelig lang og smooth. Ekstravagance på flaske. Old St. Croix når det er aller, aller bedst! Leveres naturligvis i eksklusiv flaske med tilhørende gaveæske. Alkohol % : 42,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Non Plus Ultra La Galante', 'https://spitus.dk/product/old-st-croix-non-plus-ultra-la-galante/', 995, true, NULL, NULL, 'https://spitus.dk/wp-content/uploads/2026/10/NPU-11-Galante.png', '”La Galante” er navngivet efter Columbus skib Santa Maria La Galante, som han førte da han opdagede St. Croix og de vestindiske øer. Dette eksklusive Limited Edition blend er lavet af Old St.- Crox&#8217;s master destiller med kun de bedste dråber fra Vestindien og Central Amerika. Hvert eneste fad er nøje udvalgt med henblik på at skabe et udsøgt fadlagret blend, der indfanger essensen af Vestindien og øernes flora. Der er ikke gået på kompromis nogen steder. Hverken når det kommer til den facetslebne karaffel, den mørkerøde mahogniglød eller hele den herlige smagsoplevelse. Non Plus Ultra – det betyder “intet videre” eller “det ypperste”. Og lad os være ærlige: det er ikke bare et fancy navn, det er en erklæring. Old St. Croix Non Plus Ultra La Galante er rommens svar på en Oscar-vinder – den slags flaske, der får selv garvede connaisseurs til at nikke respektfuldt og mumle: “Den dér… den er noget særligt.” La Galante er ikke bare en titel, det er en attitude. Den er elegant, sofistikeret og samtidig så caribisk, at du næsten kan høre bølgerne slå mod stranden, når du åbner flasken. Her taler vi om en dram, der har ligget og hygget sig på nøje udvalgte fade, indtil den har opnået en modenhed og dybde, som kun de bedste kan prale af. Duften? Den er som en symfoni af tørret frugt (appelsiner og mango), krydderier og et strejf af honning og mahogni. Der er varme noter af vanilje og karamel, men også en kompleksitet, der får dig til at stoppe op og tænke. Det er solskin og historiefortælling på én gang. Smagen er rund, fyldig og med lag på lag af oplevelser. Først kommer den bløde sødme, så krydderierne, og til sidst en lang, elegant eftersmag, der hænger ved som en god sang, du ikke kan få ud af hovedet. I finishen møder du også de aromatiske Bay rom træer, der vokser vildt på De Vestindiske Øer. Det er en oplevelse, der kræver, at du tager dig tid. Flasken ser ud som noget, du ville finde i en skattekiste på en caribisk ø – tung, majestætisk og med et design, der liger et trofæ. Perfekt til at imponere gæster, til at give som gave, eller til at minde dig selv om, at du fortjener det bedste. Old St. Croix Non Plus Ultra La Galante er en erklæring. Den er til dig, der vil have det ypperste, til dig der ikke nøjes, og til dig der ved, at livet er for kort til middelmådige drikkevarer. Klik “Læg i kurv” – og lad La Galante tage dig med på en rejse til spiritussens absolutte top. Leveres i flot gaveæske.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Non Plus Ultra Black Edition', 'https://spitus.dk/product/old-st-croix-non-plus-ultra-black-edition/', 795, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2026/10/NPU-11-Black.png', 'Old St. Croix Non Plus Ultra Black Edition er den 3. udgave i Old St. Croix Non Ultra Plus Serie. (Den første var &#8220;Very Rare&#8221;, og den anden var &#8220;Ambre d&#8217;or/Sauternes Cask&#8221; versionen &#8211; og den 4. og sidste Old St. Croix La Galante). Begrebet &#8220;Non Plus Ultra&#8221; stammer fra Herkules søjler, der ifølge den Romerske mytologi blev bygget nær Gibraltarstrædet, og markerede grænsen af den kendte verden. Søjlerne bar skriften &#8220;Non Plus Ultra&#8221; (latinsk for: Nothing Further Beyond) som en advarsel til søfarende om ikke at fortsætte sejladsen ud i det ukendte. A.H. Riise Non Plus Ultra Black Edition Rum er baseret på den første &#8220;Very Rare&#8221; udgave, men NPU Black Edition er et blend af mere end 50 forskellige, eksklusivt udvalgte fade. Farven på Old St. Croix Non Plus Ultra Black Edition blandingen er næsten sort. Selve smagen er lige så intens som flasken antyder. Først kommer den dybe karamel og mørke sukker, som lægger en varm base. Derefter folder de tunge frugtnoter sig ud – rosiner, svesker og mørke bær, der giver den en næsten vinøs fylde. Egetræet ligger som en mørk skygge i baggrunden, med en let bitterhed og krydderi, der giver struktur. Og så er der den lange, mørke finish, hvor kakao, kaffe og en snert af røg hænger ved som en sidste, langsom hilsen. Flot og imponerende flaske og gaveæske! Størrelse : 70cl Alkohol % : 42,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Royal Danish Navy Westindian, 50cl &#8211; old edition', 'https://spitus.dk/product/a-h-riise-royal-danish-navy-westindian-50cl-old-edition/', 239, true, 50, 32, 'https://spitus.dk/wp-content/uploads/2023/05/ahr-danish-navy-westindian-bitter-old-edi.png', 'A.H. Riise Royal Danish Navy Westindian er egentlig udgået og erstattet af Pharmacy 1838 Bitter, men vi har flere kunder, som gerne vil holde fast i ”den gamle”, så vi har sat os på et restparti hos vores leverandør. A.H. Riise har anvendt den populære XO Reserve rom som base, men den indeholder også ekstrakter fra mere end 30 forskellige planter, krydderier og urter. Hovedparten af disse kommer fra Caribien; herunder ensianrod, kinin, appelsin, nelliker, sandeltræ, kakaobønner, kaffebønner og vanilje. Farven er lys mahogni. I næsen citrus, let mynte og smørkaramel. Smagen er meget fint afbalanceret kamfer med citrus på toppen efterfulgt af et bombardement af varme krydderier. I afslutningen får du blide noter af eg, kamfer og lidt mynte. Dejlig bitter fra A.H. Riise! Alkohol %: 32,0 Størrelse: 50 cl Tilbuddet gælder til og med 30. nov. &#8211; så længe lager haves!');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Doorly&#8217;s 3 Years Old Fine Old Barbados White Rum', 'https://spitus.dk/product/doorlys-3-years-old-fine-old-barbados-white-rum/', 245, true, 70, 47, 'https://spitus.dk/wp-content/uploads/2026/09/doorly3.jpg', 'Doorly&#8217;s White Rum 3 YO Barbados – Den velopdragne ballademager. Nogle rom er skabt til at stå bagerst i barskabet og samle støv. Doorly&#8217;s White Rum 3 YO er ikke en af dem. Denne barbadianske charmetrold er lavet til at blive hældt op, blandet, rystet og nydt med det samme. Bag flasken står Foursquare Distillery på Barbados, som nærmest er romverdenens svar på den elev, der altid afleverede sine lektier til tiden og stadig fandt tid til at vinde fodboldturneringen. Resultatet er en hvid rom, der har langt mere karakter end mange af sine gennemsigtige kollegaer. Doorly&#8217;s White Rum lagres faktisk i tre år, før den filtreres klar igen. Det betyder, at du får langt mere dybde og kompleksitet, end farven umiddelbart afslører. Duften byder på noter af vanilje, kokos, tropisk frugt og et strejf af egetræ. Smagen er blød, ren og afrundet med sødmefulde nuancer af sukkerrør, citrus og let krydderi. Det er rommen, der får Mojitoen til at ranke ryggen, Daiquirien til at smile lidt bredere og Cuba Libre til at opføre sig som en rigtig cocktail i stedet for en tilfældig blanding fra gymnasiefesten. Doorly&#8217;s White Rum 3 YO er kort sagt et bevis på, at hvid rom ikke behøver være anonym. Tværtimod. Den er elegant uden at være snobbet, kompleks uden at være besværlig og alsidig uden at miste personlighed. En seriøs rom med 47% for folk, der ikke tager sig selv alt for seriøst. Skål. Alkohol % : 47,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo 7 år Anejo Reserva Superior Rom', 'https://spitus.dk/product/abuelo-7-aar-anejo-reserva-superior-rom/', 235, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/09/abuelo-7.jpg', 'Abuelo 7 Años Añejo Reserva Superior er rommens svar på en perfekt hverdagsluksus: elegant, varm, charmerende – og med nok personlighed til at få selv den mest kræsne romnyder til at nikke anerkendende. Det er en Single Estate Rum , hvilket betyder, at Abuelo styrer hele processen selv: fra de første sukkerrør bliver plantet i den frodige dal i Pesé, til den færdige rom hældes på flasken. Ingen genveje, ingen kompromiser – kun ren panamansk dedikation. Markerne dyrkes ved håndkraft, gæringen foregår på egne kedler, og lagringen sker i små, nøje udvalgte bourbonfade. Her arbejder klimaet med: kolde nætter, fugtige dage og moderat nedbør skaber en modning, der er helt unik i romverdenen. Det giver en Angel’s Share på op til 10 % om året – englene i Panama er åbenbart tørstige. For at holde rommen i balance bruger Abuelo den såkaldte Vintage Pallet‑metode , hvor fadene genopfyldes hvert andet år med rom fra samme batch. Det sikrer både fylde og ensartet alder. Duften er fyldig og indbydende: appelsin, kandis, figen, kanel og tørrede frugter . Smagen er kompleks og silkeblød med dadler, rosiner og vanilje , mens eftersmagen er sød, afrundet og fuld af karamel . Det er en rom, der både fungerer neat , i en luksuriøs cocktail eller som den perfekte slappe-af-dram. Fætteren her er tappet ved 40 % ABV , og den leverer en smagsoplevelse, der rammer lige mellem det elegante og det uimodståeligt behagelige. En rom, der ikke prøver at være noget den ikke er – men som alligevel imponerer hver eneste gang. Abuelo 7 Años er Panamas bud på den perfekte, daglige luksusrom – skabt med håndkraft, tålmodighed og en smag, der gør hverdagen lidt bedre. Der er simpelt hen tale om Panamas mest prisvindende añejo‑rom, som har samlet over 35 internationale medaljer siden 2015. F.eks. Double Gold – San Francisco World Spirits Competition (2022 &amp; 2023). Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('2026 &#8211; Julekalender Rom', 'https://spitus.dk/product/2026-julekalender-rom/', 685, true, 48, 42.37, 'https://spitus.dk/wp-content/uploads/2026/09/julekalender-rom-2026.jpg', 'December 2026 bliver officielt året, hvor rom‑julekalenderen gør voksne mennesker mere spændte end børn. Det er den slags kalender, der får dig til at stå op om morgenen og tænke: “Hvad mon jeg skal smage i dag – og kan jeg tillade mig at åbne lågen før morgenmaden?” (Svaret er ja. Det er december. Der gælder andre regler.) Her får du 24 dage med gedigen rom , håndplukket fra de tre store stilretninger: Britisk, Fransk og Spansk . Det betyder, at du både møder de tørre britiske klassikere, de funky franske agricole‑vidundere og de solmodne, bløde spanske crowd‑pleasers. Der er noget til begynderen, noget til eksperten – og noget til den person, der altid siger “jeg er ikke så meget til rom”, men som alligevel ender med at købe to kalendere. Hver dag åbner der sig en virtuel låge , hvor du får beskrivelser, videoer og små rom‑historier, der gør dig klogere, gladere og måske en smule mere klar til at diskutere ester‑niveauer til julefrokosten. Du følger bare linket på undersiden af kalenderen, og så er du inde i universet. Det føles lidt som at have en personlig rom‑guide, der hver morgen siger: “Kom, vi tager lige en tur til Caribien.” Designet er elegant, indholdet er varieret, og oplevelsen er gennemført. Du kommer langt omkring – geografisk, smagsmæssigt og måske også følelsesmæssigt, hvis du er typen der bliver rørt af god rom. Å rets mest velsmagende, humoristiske og luksuriøse måde at tælle ned til jul på. Perfekt til den, der skal forkæles, udfordres – eller bare have en december, der smager af noget. ADVARSEL: INDHOLD I ALFABETISK RÆKKEFØLGE Abuelo 12 år Anejo Gran Reserva &#8211; Panama Abuelo 7 år Anejo Reserva Superior &#8211; Panama Abuelo XII Anos &#8220;Three Angels&#8221; Abuelo XII Anos &#8220;Two Oaks&#8221; Abuelo XV Finish Collection Napoleon Doorly&#8217;s Fine Old Rum 14 YO Barbados Dos Maderas Atlantic Dos Maderas Caribbean Seleccion Triple Aged Rum Kirk &amp; Sweeney Rum &#8211; Gran Reserva Kirk &amp; Sweeney Rum &#8211; Reserva Pusser&#8217;s British Navy Rum (Blå) Pusser&#8217;s British Navy Rum Gunpowder Proof Spiced 54,5% RL Seales Barbados rum 10 år 46% Ron Cueva 1501 &#8211; Sistema 12 &#8211; Panama Ron Cueva 1501 &#8211; Sistema 18 &#8211; Panama Ron Millonario XO Reserva Espicial fra Peru Rum Nation &#8211; Dominicana 8 YO Rum Nation &#8211; Guatemala XO Rum Nation &#8211; Mauritius 6 YO Rum Nation &#8211; Panama 18 år Rum Nation &#8211; Panama 21 år Rum Nation &#8211; Mauritius 8 år Cask Strength Rum St. Etienne Martinique Rhum Vieux VO St. Etienne Martinique Rhum Vieux XO Størrelse: 24 x 2 cl Alkohol % : 42,37');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Plantation Rum BARBADOS XO 20th Anniversary', 'https://spitus.dk/product/plantation-rum-barbados-xo-20th-anniversary/', 399, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/09/Plantation-xo-20-aars.png', 'Den ikoniske Barbados‑klassiker – nu med nyt look. Plantation har gjort det, som kun de mest selvsikre brands tør: skiftet navn uden at ændre det, der gjorde dem berømte. BARBADOS XO 20th Anniversary er stadig den samme overdådige, silkebløde rom, der får voksne mennesker til at smile som børn i en slikbutik – bare med et navn, der passer bedre til nutiden. Her får du Barbados i flydende form: dyb vanilje , ristet kokos , karamel , tørret frugt og grillede bananer og den karakteristiske, elegante sødme, som har gjort denne udgivelse til en moderne klassiker. Det er rom, der ikke behøver prale – den glider bare ind, sætter sig godt til rette og får dig til at overveje, om du burde have købt to. 20th Anniversary‑udgaven er lagret i både tropisk varme og franske egetræsfade, hvilket giver den en finish, der er så blød, at du næsten mistænker den for at være flødeskum i forklædning. Perfekt som gave, perfekt til samlere, perfekt til dig, der vil have en rom, der både er historie , håndværk og ren nydelse i samme flaske. Rommen vinder rutinemæssigt priser ved diverse smagninger, bl.a.: 2016 Guldmedalje, Paris Rom Festival, Frankrig 2016 Årets spiritus, Whisky Exchange 2015 Guldmedalje, Berlin Rom Festival, Tyskland 2015 Guldmedalje, RumXP Competition, USA, og guld i kategorien, “Premium Aged Rum”, ved Miami Rum Festival 2014 Guldmedalje, Rom Festival, Finland 2014 Guldmedalje, RumXP Competition, USA 2013 Guldmedalje, Rum Master, UK 2013 Guldmedalje, RumXP, Competition, USA 2012 Master in the Category Aged over 12 Years, Rum Master, UK 2012 A.Gabriel, World Best Master Blender, Golden Rum Barrel, UK Leveres i gaveæske. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Julekalender 2026', 'https://spitus.dk/product/old-st-croix-julekalender-2026-forudbestilling/', 599, true, 48, 40, 'https://spitus.dk/wp-content/uploads/2026/09/old-st.-croix-julekalender-2026.png', 'Old St. Croix‑julekalenderen 2026 er december, som kun voksne forstår den: luksus, varme, dram i verdensklasse – og et lille glimt i øjet hver eneste morgen. Old St. Croix Julekalender 2026 er en eksklusiv og stemningsfuld julekalender, der byder på 24 unikke smagsoplevelser – én til hver dag i december frem mod jul. Kalenderen er skabt af det traditionsrige spiritusbrand Old St. Croix, tidligere kendt som A.H. Riise, og hylder arven fra den dansk-vestindiske romproduktion med en moderne og luksuriøs twist. Bag de 24 låger gemmer der sig Old St. Croix‑rom i små, elegante flasker , udvalgt så du får hele spektret af husets stil. De bløde, fadlagrede klassikere. De krydrede, dybe limited editions. De frugtige, eksotiske overraskelser. Designet er lige så lækkert som indholdet: en mørk, elegant æske med diskret julepræg, der ligner noget, man burde åbne iført smoking eller silkekåbe. Old St. Croix Julekalender 2026 er ideel som gave til spirituselskeren, som selvforkælelse eller som en festlig tradition i december. Leveres i oktober og kan forudbestilles allerede nu. En julekalender, der gør ventetiden til jul både smagfuld og mindeværdig. 24 låger, 24 grunde til at smile som en romglad nisse. Alkohol % : 40% -&gt; 60% Størrelse : 24 x 2cl = 48cl.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Luksus Julekalender Rom', 'https://spitus.dk/product/luksus-julekalender-rom/', 1195, false, 48, 43.5, 'https://spitus.dk/wp-content/uploads/2025/10/julekalender-rum.png', 'Men; glem alt om chokolade og tørre pebernødder – i år skal december smage af rom! God rom! Vores lækre romjulekalender er som en tropisk ferie i små flasker, pakket ind i julehygge og nissehuer. Hver låge gemmer på en ny romoplevelse: fra krydret piratjuice til blød vaniljeduftende luksus. Kalenderen indeholder således 24 nøje udvalgte romme fra hele verden – og nej, du behøver ikke dele med svigermor. Der medfølger et lækkert rom-glas. Så gør december lidt mere eksotisk og meget mere velsmagende. Bestil din romjulekalender nu – og lad nedtællingen til jul blive en rejse gennem sukkerrør, fadlagring og festlighed. Skål i rom og god jul! Alkohol % : 43,5 Størrelse : 24 x 2cl ADVARSEL ! Nedenfor angiver vi, i alfabetisk rækkefølge, de flasker du vil møde i løbet af december: (spring afsnittet over, hvis du hellere vil overraskes hver dag). 1731 Fine &amp; Rare DOMINICAN REPUBLIC 5 Years Old Single Origin Rum 46% Vol. Amrut Two Indies Rum 42,8% Vol. Belizean Blue SIGNATURE BLEND Rum 48% Vol. Captain Cane XO Rum 40% Vol. Dictador AURUM Colombian Aged Rum 40% Vol. Flying Dutchman 3 Years Old Premium Dutch Rum AMARONE Cask 40% Vol. FRC Caribbean Rum from Barbados and Jamaica 40% Vol. Hampden Estate 8 Years Old Pure Single Jamaican Rum 46% Vol. J. Bally Rhum Vieux Agricole Martinique Habitation Lajus 45% Vol. Kinghaven Premium Single Cask Rum 58% Vol. Langs Banana Jamaican Spirit Drink 37,5% Vol. MacNair&#8217;s Peated Exploration Rum Jamaica 46% Vol. MacNair&#8217;s Unpeated Exploration Rum Jamaica 46% Vol. Navy Island JAMAICA XO Reserve Rum 40% Vol. Old Man Rum Project CHRISTMAS in Love with Rum 40% Vol. Renegade NURSERY Cane Rum 50% Vol. Ron Larimar 5 Years Old Small Batch Rum Bourbon Cask Finish 40% Vol. Romero &amp; Sons 9 Years Old Ecuador Rum 44% Vol. Rum Nation Panama 18 Years Old Decanter 40% Vol. Savanna 5 Years Old Traditionnel Reunion Island Rum 43% Vol. Sea Shepherd Rum 40% Vol. Takamaka EXTRA NOIR Rum 43% Vol. Takamaka ZEPIS KREOL Rum 43% Vol. The Best of Two Continents AFRICAN &amp; ASIAN Fusion 45,2% Vol');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Julekalender Rom', 'https://spitus.dk/product/julekalender-rom-2/', 599, true, 48, 43.18, 'https://spitus.dk/wp-content/uploads/2025/09/julekalender-rom-2.png', 'Rom Julekalender – 24 dage med tropisk nydelse Gør december lidt varmere med denne lækre Rom Julekalender. En eksklusiv og smagfuld nedtælling til jul, fyldt med solskin, krydderier og caribisk charme. I stedet for chokolade og småskrammel, får du 24 flasker med nøje udvalgte rom-varianter fra hele verden, hver med sin egen unikke historie og smagsprofil. Der er repræsentanter fra de 3 forskellige stilarter; Britisk, Fransk og Spansk. Altså noget for enhver. Der er tale om en sammensat kalender, der tager dig med på en rejse gennem rommens mangfoldige univers. Fra mørk og fyldig rom fra Jamaica og Barbados til blød og sød rom fra Venezuela og Guatemala – du får både klassiske favoritter og spændende nyheder, der kan overraske selv den mest erfarne romelsker. Indholdet er 24 flasker á 2 cl, og hver flaske ledsages af information om oprindelse, destilleri og smagsnoter, så du kan lære og nyde på samme tid. Du kan forvente noter af karamel, vanilje, tropisk frugt, egetræ og krydderier. Nogle er perfekte til sipping, andre egner sig til cocktails – og alle er en invitation til at udforske rommens verden. Julekalenderen er en oplagt gave til livsnyderen, den nysgerrige smager eller som selvforkælelse i den mørke december. Hver låge er som en mini-ferie i glas. Perfekt til dig, der synes julen bliver bedre med rom i hånden og sand mellem tæerne. En festlig, lærerig og lækker måde at gøre december lidt mere eksotisk og meget mere velsmagende. INDHOLD I ALFABETISK RÆKKEFØLGE • Abuelo 7 år Anejo Reserva Superior • Abuelo XII Anos &#8220;Three Angels&#8221; • Abuelo XII Anos &#8220;Two Oaks&#8221; • Dos Maderas Caribbean Seleccion Triple Aged Rum • Dos Maderas Luxus – Barbados-Guyana blended rom 10+5 år • Doorly&#8217;s Fine Old Rum 12 YO Barbados • Doorly&#8217;s XO Fine Old Rum Barbados • Ocean’s Atlantic Rum 16–21 år Limited Edition – 1,0L • Pusser’s British Navy Rum Black Label Gunpowder Proof 54,5% • Pusser’s Select Aged 151 Navy Strength 75,5% • Ron Millonario 10th Aniversario Cincuenta • Ron Millonario 10th Aniversario Reserva • Ron Millonario XO Solera Reserva Espicial fra Peru • Rum Nation – Dominicana Rum 8 YO • Rum Nation – Guatemala XO 20th Anniversary • Rum Nation – Jamaica 5 år Sherry Finish • Rum Nation – Mauritius Triple Cask 6 • Rum Nation – Panama 10 år • Rum Nation – Panama 18 år Decanter • Rum Nation – Peruano 8 år • Rum Nation – Venezuela XO 25th Anniversary • St. Etienne Agricole Black Sheriff American Barrel • St. Etienne Martinique Rhum Très Vieux VSOP Størrelse: 24 x 2 cl Alkohol % : 43,18');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Julekalender 2023', 'https://spitus.dk/product/a-h-riise-julekalender-2023/', 599, true, 48, 43.92, 'https://spitus.dk/wp-content/uploads/2023/08/a.h.-riise-julekalender-2023.png', '24 oplevelser – 24 forkælede dage i december! Den kendte julekalender fra A.H. Riise indeholder i 2023-udgaven smagsprøver på nogle af de mest udsøgte og velsmagende rombasereret blends. Den gemmer bl.a. på nogle af de historier, møder og begivenheder, der ligger bag udgivelserne. De 24 flasker af hver 2cl. repræsenterer en historisk rejse i A.H. Riises smagsunivers &#8211; fra prisvindende blends baseret på brandets vestindiske arv og flådetraditioner til moderne fortolkninger baseret på helt nye samarbejder. Alkohol % : 43,92 (gennemsnit) Størrelse : 24 x 2cl = 48cl. (der står ikke årstal på julekalenderen)');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Julekalender 2021', 'https://spitus.dk/product/a-h-riise-julekalender-2021/', 599, true, 48, 60, 'https://spitus.dk/wp-content/uploads/2023/11/ahr-riise-julekalender-2021-k.png', 'Den kendte og elskede julekalender fra A. H. Riise – her i 2021-udgaven (der står ikke årstal på) Indeholder 24 forskellige flasker @ 2 cl. af de bedst sælgende produkter fra A.H. Riises univers. Dvs. A.H. Riises og Santos Dumonts spiritus baseret på premium rom, Lakrids- &amp; Cream Likører. En hyggelig forkælelse, og en god måde at finde din favorit på. For samlere, kan det desuden være svært at få fat i denne ældre udgave. Alkohol % : 18-60% Størrelse : 24 x 2cl = 48cl.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Tribute Reserve', 'https://spitus.dk/product/old-st-croix-xo-tribute-reserve/', 639, true, 70, 43.8, 'https://spitus.dk/wp-content/uploads/2026/08/2.png', 'Old St. Croix XO Tribute Reserve, blev udgivet i september 2026 i i alt 24.407 flasker. Den er skabt som en hyldest til historien , men smager som en invitation til fremtiden. Den er perfekt til dem, der elsker en blød, afrundet XO‑profil – og til dem, der vil have en dram, der føles som kvalitet uden at kræve en doktorgrad i romnørderi. Old St. Croix XO Tribute Reserve er flasken, du tager frem, når du vil imponere uden at prale. En stille luksus. En varm oplevelse. En hyldest, der faktisk lever op til sit navn. Profilen rammer den perfekte balance mellem tropisk lagring , blød sødme og let krydderi. Den er skabt til dem, der elsker en god, let drikkelig dram, der glider ned som en god fortælling – uden skarpe kanter, uden dramatik, bare ren nydelse. Næsen åbner med chokolade og bergamot med et diskret strejf af tobak. karamel, brun farin, tørret frugt og mild vanilje titter frem . Der ligger en rolig tropisk varme under det hele, som om den har taget en lille del af Caribien med hjem i flasken. Smagen er l et og frugtig med et strejf af pebermynte og bergamot. Elegant integreret med rosiner, dadler, let citrus og en mild trænote , der binder det hele sammen. Tribute har den der klassiske St. Croix‑signatur: en udgivelse, der føles som et velkomment håndtryk. Den er nem at drikke, men langt fra simpel. Finishen er rolig og vedvarende, og domineret af pebermynte og mælkechokolade . Dertil et lag af vanilje, krydderi og en blød trævarme , der bliver hængende som en stille luksus. Leveres i gaveæske. Alkohol %: 43,8 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Foursquare 19 Years Old EPILOGUE Exceptional Cask Selection Mark XXXI Rom', 'https://spitus.dk/product/foursquare-19-years-old-epilogue-exceptional-cask-selection-mark-xxxi-rom/', 1045, true, 70, 57, 'https://spitus.dk/wp-content/uploads/2026/08/foursquare-Penultimus.jpg', 'Foursquare Epilogue er ikke bare endnu en rom. Det er finalen , punktummet , det sidste kapitel i den ikoniske Exceptional Cask Selection – en serie, der har sat standarden for, hvordan ægte, uforfalsket Barbados‑rom skal smage. Som Mark XXXI markerer Epilogue afslutningen på en epoke, og Foursquare har valgt at gøre det med stil. Stor stil. Denne 19‑årige single blended rom er skabt ved at kombinere destillater fra både pot still og column still – en signaturstil, der giver dybde, elegance og en kompleksitet, som kun Foursquare kan levere. Rommen har lagret i minimum 19 år på ex‑bourbonfade af amerikansk hvid eg, hvilket giver en imponerende balance mellem moden frugt, varme krydderier og en silkeblød struktur. Duften åbner med mørk chokolade, tørret frugt, orange, kirsebær og marcipan – en aromatisk buffet, der føles som en invitation til noget stort. Smagen er fyldig, blød og frugtdrevet med noter af honning, citrus og en let tobaksagtig dybde. Finishen er lang, elegant og olieret, med hints af ananas, melassekage og varme krydderier. Det er en rom, der bliver ved med at tale, længe efter du har taget den sidste tår. Epilogue tappes ved 57% – naturlig farve, ingen sukker, ingen tilsætninger, ingen chill‑filtrering. Det her er rom i sin reneste form , og Foursquare holder fast i deres filosofi: kvalitet først, kompromiser aldrig. For samlere er Epilogue et must‑have. For nørder er det en milepæl. For alle andre er det en mulighed for at smage, hvordan 19 års tropisk lagring kan forvandle rom til ren kunst. Nyd den rent i et godt glas – og lad den fortælle historien om en serie, der har formet moderne romkultur. Størrelse: 70 cl Alkohol %: 57,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Stroh 80% Original Rum', 'https://spitus.dk/product/stroh-80-original-rum/', 299, true, 70, NULL, 'https://spitus.dk/wp-content/uploads/2026/07/stroh-70cl.jpeg', 'Stroh 80% er ikke bare en rom. Det er en institution . En østrigsk kultklassiker, der har opnået status som både elsket, frygtet og dybt respekteret af alle, der nogensinde har sagt: “Jeg kan godt tåle stærk rom.” Det her er flasken, der ikke behøver introduktion. Den kommer ind ad døren som en alpejæger i vinteruniform , stiller sig midt i rummet og siger: “Nå. Hvem er modig?” Stroh 80 er i ntens, varm og krydret med noter af karamel, vanilje, mørk sirup og en dyb, brændende sødme, der føles som en flydende pejs. Den er ikke subtil. Den er ikke forsigtig. Den er Stroh . Du kan f.eks. bruge den til: Flambering — Den er så kraftig, at den nærmest tænder sig selv. Bagværk — Romkugler, julekager, alt der skal have “lidt mere”. Cocktails — Når du vil have varme, dybde og en cocktail, der får folk til at hæve øjenbryn. Historiefortælling — For du får altid en historie med, når Stroh er involveret. Stroh 80 er ikke for alle. Men for dem, der elsker den, er den uerstattelig. Den leverer varme, kraft og en smagsoplevelse, der er lige så ikonisk som dens alkoholprocent. 80% &#8211; og ja, det kan smages. Fordi Stroh 80 er ærlig . Den lover styrke, og den leverer. Den lover smag, og den leverer. Den lover en oplevelse, og den leverer mere end du bad om. Det her er flasken, du tager frem, når du vil være helt sikker på, at ingen går hjem og siger: “Det var da en lidt kedelig aften.” Størrelse : 70 cl Alkohol % : 80,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Deadhead 6 Years Rum', 'https://spitus.dk/product/deadhead-6-years-rum/', 439, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/11/deadhead-6-y.jpg', 'Du har sikkert set flasken før. Den er udformet som et ”Shrunken Head”, hvilket symboliserer hvordan man i Mexico tog hovedet fra ens fjender som trofæ &#8211; for blod, ære og åndelig fornyelse. Markant design! Deadhead 6 Years er &#8220;flasken&#8221;, der ikke bare står på hylden… den stirrer på dig. Den ikoniske shrunken‑head‑flaske er ren attitude, men indholdet er heldigvis lige så spændende som udseendet. Den er fadlagret i 6 år på brugte bourbon-fade, hvorefter den er iblandet økologisk kakao. I næsen er den rig på mørk chokolade, kaffe og karamel. Smagen giver muskatnødder, chokolade, kaffe, ristet eg, nelliker og delikate krydderier. Mellemlang finish med frugter og flødekaramel. Den har en blød, næsten dessertagtig profil, men stadig med nok kant til at føles voksen og velbalanceret. Den højere alkoholprocent og længere tid på fad, end ”Deadhead Chocolate”, giver mere bid og substans. Det er den, du hiver frem, når du vil servere noget, der både smager godt og starter samtaler. Perfekt til ren nydelse, tiki‑cocktails eller som den flaske, der får gæsterne til at sige “okay… hvad er det der?” Deadhead 6 Years: Smag, stil og en flaske, du aldrig glemmer. Det er den mexicanske klassiker med voodoo‑vibes og masser af smag. Dejlig dram, som er perfekt at sippe. Men den er ligeledes en oplagt makker i en række eksotiske cocktails og drinks. Se de mange forslag på www.deadheadrum.com/cocktails. NB! Dette er ikke udgaven lavet i plastic 😉 Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Zacapa Centenario XO Solera Gran Reserva Especial', 'https://spitus.dk/product/ron-zacapa-centenario-xo-solera-gran-reserva-especial/', 995, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/ron-zacapa-xo-k.png', 'Ron Zacapa har ikke mindre end i 7 år i træk fået titlen som verdens bedste rumproducent ved den seriøse &#8220;The International Rum Festival&#8221;. Ron Zacapa 15 år, 23 år og 25 år er alle lavet på en såkaldt solera. Før rommen hældes igennem soleraen, har den haft forskellig &#8220;opvækst&#8221; på friske egefade, ex-bourbon, ex-sherry, ex-madeira o.s.v. De fleste kender Ron Zacapa 23 års, som nok er den rom både herhjemme og globalt, der har fået flest menneskers øjne op for god fadlagret rom . For mange er det her kærligheden til rom startede. Denne Zacapa Centenario XO Solera Gran Reserva Especial, er faktisk en ”videreudvikling” af denne kendte 23 års rom. En stor del af forskellen består i, at man har taget den klassiske 23 års, og så lige givet den 2 års mere lagring på franske cognacfade. Det giver en noget mere kompleks smag, mere voluminøst, men faktisk også en anelse sødere. I næsen dyb og mørk sødme, nødder, rosin og et strejf af cognac. Noterne fra fadene er meget markante, og går fint i samspil med duften af sukkerristet banan. Dejlig intens og fløjlsblød oplevelse. Super lækker fylde i munden med et dejligt potpurri af smagsnuancer . En helt eminent eftersmag, der hænger på tungen, tænderne og i ganen længe. Der er temmelig meget power og smæk på det hele. Hvis du synes Ron Zacapa 23 års er god, må du absolut ikke snyde dig selv for at prøve denne XO-udgave. Der er virkeligt skruet op for ALT, og du vil straks komme i problemer med at få tømt din gamle 23 års. Selve flasken og tilhørende gaveæske matcher fint det høje niveau denne rom befinder sig på. 92 point Romhatten Leveres i flot gaveæske. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Planteray Rum BARBADOS XO 20th Anniversary', 'https://spitus.dk/product/planteray-rum-barbados-xo-20th-anniversary/', 399, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/07/planteray-20.webp', 'Den ikoniske Barbados‑klassiker – nu med nyt navn og samme luksus Planteray (tidligere Plantation) har gjort det, som kun de mest selvsikre brands tør: skiftet navn uden at ændre det, der gjorde dem berømte. BARBADOS XO 20th Anniversary er stadig den samme overdådige, silkebløde rom, der får voksne mennesker til at smile som børn i en slikbutik – bare med et navn, der passer bedre til nutiden. Her får du Barbados i flydende form: dyb vanilje , ristet kokos , karamel , tørret frugt og grillede bananer og den karakteristiske, elegante sødme, som har gjort denne udgivelse til en moderne klassiker. Det er rom, der ikke behøver prale – den glider bare ind, sætter sig godt til rette og får dig til at overveje, om du burde have købt to. 20th Anniversary‑udgaven er lagret i både tropisk varme og franske egetræsfade, hvilket giver den en finish, der er så blød, at du næsten mistænker den for at være flødeskum i forklædning. Og ja, navneskiftet fra Plantation til Planteray betyder absolut ingenting for smagen. Det er stadig den rom, som entusiaster har råbt op om i årevis. Perfekt som gave, perfekt til samlere, perfekt til dig, der vil have en rom, der både er historie , håndværk og ren nydelse i samme flaske. Rommen vinder rutinemæssigt priser ved diverse smagninger, bl.a.: 2016 Guldmedalje, Paris Rom Festival, Frankrig 2016 Årets spiritus, Whisky Exchange 2015 Guldmedalje, Berlin Rom Festival, Tyskland 2015 Guldmedalje, RumXP Competition, USA, og guld i kategorien, “Premium Aged Rum”, ved Miami Rum Festival 2014 Guldmedalje, Rom Festival, Finland 2014 Guldmedalje, RumXP Competition, USA 2013 Guldmedalje, Rum Master, UK 2013 Guldmedalje, RumXP, Competition, USA 2012 Master in the Category Aged over 12 Years, Rum Master, UK 2012 A.Gabriel, World Best Master Blender, Golden Rum Barrel, UK Leveres i gaveæske. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bayou Single Barrel Rum', 'https://spitus.dk/product/bayou-single-barrel/', 389, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/12/bayou-single-barrel.jpg', 'Bayou Rum er vaskeægte amerikansk rom fra sydstaten Louisiana. Rommen er produceret på en lokal sukkerrørsmelasse som destilleres på små batch-destilleringsapparater, og herefter modnet i forskellige fade, normalt i et solera-system, men nogle varianter også som single barrel. Destilleriets masterblender er den unge romkomet, Reiniel Vicente Diaz, som har rødder i den cubanske og dominikanske romproduktion. Som navnet antyder, er denne Bayou Single Barrel Rum modnet i et fad, og altså ikke efter solera-metoden. Derefter har den ligget 3 år på brugte californiske rødvinsfade, og dermed adskiller den sig fra de øvrige Bayou-rom. Bayou Single Barrel er rommen, hvor hver eneste flaske har sin egen historie. Den er tappet fra ét enkelt bourbonfad – ikke en blanding – hvilket giver en unik, intens og karakterfuld oplevelse, der skiller sig ud fra alt andet i Bayou‑familien. Næsen er rig på eg, figner, røde bær og krydderier. Smagen er dyb, varm og markant med noter af karamel, vanilje, ristet eg, toffee og en tydelig bourbon‑kant, der giver ekstra power og personlighed. Den er mindre sød end mange Caribiske rom, men til gengæld rig, krydret og uimodståeligt smooth. Det er rommen, du vælger, når du vil have noget med kant, karakter og en tydelig “single barrel”-signatur. En flaske til nørderne, til connaisseurerne – og til alle, der elsker rom med attitude. Bayou Single Barrel: Én tønde. Én smag. Én oplevelse. Bayou Single Barrel Rum – Louisiana, når det bliver helt personligt. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XV Finish Collection Oloroso Cask, 20cl Rom', 'https://spitus.dk/product/abuelo-xv-finish-collection-oloroso-cask-20cl-rom/', 199, true, 20, 40, 'https://spitus.dk/wp-content/uploads/2026/07/Abuelo-XV-Finish-Collection-Oloroso-20cl-1.jpg', 'Abuelo XV Oloroso har været en tur i Jerez og nu insisterer på at gå i skræddersyet jakkesæt. Den starter som klassisk Abuelo: 15 års tropisk lagring i Panama, hvor varmen og tiden skaber dybde, sødme og karakter. Men så får den sit sidste, forførende touch i Oloroso‑sherryfade – og det er her, den bliver alles darling.. Duften åbner med mørk frugt, rosiner, karamel, nødder og dyb sherry‑sødme , som om nogen har kombineret en romkælder i Panama med en bodega i Andalusien. Der er også strejf af tobak, vanilje og krydret eg , som giver rommen en moden, aristokratisk kant. Smagen er en blød, rund og uimodståelig symfoni af tørret frugt, chokolade, brændt sukker, nødder, appelsinskal og sherry , der glider over tungen som silke med attitude. Oloroso‑fadet giver en vinøs dybde og en mørk elegance, der løfter Abuelo‑profilen til et niveau, hvor man begynder at overveje, om rom egentlig burde serveres med dæmpet belysning og klassisk musik. Eftersmagen er lang, varm og krydret , med lag af eg, rosiner, karamel og en let tannin , der giver en smuk afrunding. Den hænger i munden som et sidste, flirtende farvel fra en rom, der godt ved, at den har gjort indtryk. Den lille 20 cl‑flaske gør Oloroso‑udgaven perfekt som gave, som luksus‑smagsprøve eller som “jeg skal bare lige prøve den her” – og vi ved begge, at det sjældent stopper der. Abuelo XV Oloroso er rommen til dig, der elsker dybde, elegance og sherry‑kysset luksus . En lille flaske med stor personlighed – og masser af Oloroso‑charme. Alkohol % : 40,0 Størrelse : 20 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XV Finish Collection Napoleon, 20cl Rom', 'https://spitus.dk/product/abuelo-xv-finish-collection-napoleon-20cl-rom/', 199, true, 20, 40, 'https://spitus.dk/wp-content/uploads/2026/07/Abuelo-XV-Finish-Collection-Napoleon-20cl.jpg', 'Abuelo XV Napoleon har været et smut i Frankrig og insisterer nu på at udtale alt med let accent. Den starter som klassisk Abuelo: 15 års tropisk lagring i Panama, hvor varmen, fugten og tiden skaber dybde, sødme og karakter. Men så får den sit sidste touch i Napoleon‑cognacfade – og det er her, den bliver til noget helt særligt. Duften åbner med tørret frugt, karamel, rosiner, vanilje og en elegant cognac‑parfumeret note , der føles som at træde ind i en fransk salon med poleret træ, bløde lænestole og diskret luksus. Der er også strejf af nødder, toffee og krydret eg , som giver rommen en moden, aristokratisk kant. Smagen er en blød, rund og uimodståelig kombination af chokolade, druer, karamel, appelsinskal, nødder og cognac‑varme , der glider over tungen som silke med attitude. Cognac‑fadet giver en vinøs elegance og en frugtig dybde, der løfter Abuelo‑profilen til et niveau, hvor man begynder at overveje, om rom egentlig burde serveres i et tulipanglas og med hvide handsker. Eftersmagen er lang, varm og raffineret , med lag af eg, frugt, karamel og en let tannin , der giver en smuk afrunding. Den hænger i munden som et sidste, flirtende farvel fra en fransk charlatan, der godt ved, at han har gjort indtryk. Den lille 20 cl‑flaske gør Napoleon‑udgaven perfekt som gave, som luksus‑smagsprøve eller som “jeg skal bare lige prøve den her” – og vi ved begge, at det sjældent stopper der. Abuelo XV Napoleon er rommen til dig, der elsker finesse, dybde og en smule fransk attitude . En lille flaske med stor personlighed – og masser af cognac‑kysset charme. Alkohol % : 40,0 Størrelse : 20 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XV Finish Collection Tawny Cask, 20cl Rom', 'https://spitus.dk/product/abuelo-xv-finish-collection-tawny-cask-20cl-rom/', 199, true, 20, 40, 'https://spitus.dk/wp-content/uploads/2026/07/Abuelo-XV-Finish-Collection-Tawny-20cl.jpg', 'Abuelo XV Tawny Cask er rommens svar på en verdensmand, der både taler flydende spansk, portugisisk og “jeg kan godt lide luksus”. Den starter sit liv i Panama, hvor 15 års tropisk lagring giver den dybde, varme og sødme – og derefter får den sit sidste, forførende touch i portvinsfade fra Portugal , nærmere bestemt Tawny‑fade. Det er her, magien sker. Duften åbner med røde bær, karamel, nødder, rosiner og en vinøs elegance , der føles som at træde ind i en portvinskælder, hvor nogen har glemt at låse døren. Der er også strejf af vanilje, toffee og krydret eg , som giver rommen en moden, aristokratisk kant. Smagen er en blød, rund og uimodståelig kombination af tørret frugt, portvinssødme, chokolade, nødder, appelsinskal og let krydderi , der glider over tungen som silke med attitude. Tawny‑fadet giver en smuk, rødfrugtet dybde, der løfter Abuelo‑profilen til et niveau, hvor man begynder at overveje, om rom egentlig burde serveres i krystalglas og med hvide handsker. Eftersmagen er lang, varm og vinøs , med lag af eg, bær, karamel og en elegant sødme , der bliver hængende som et sidste, flirtende farvel. Den lille 20 cl‑flaske gør den perfekt som gave, som luksus‑smagsprøve eller som “jeg skal bare lige prøve den her” – og vi ved begge, at det sjældent stopper der. Abuelo XV Tawny Cask er en del af den ikoniske Finish Collection, hvor hvert udtryk får sin egen personlighed gennem fadfinish. Tawny‑udgaven er den mest frugtige, elegante og vinøse af dem alle – en rom med charme, dybde og international attitude. Det her er flasken til dig, der elsker rom med finesse, karakter og et strejf af portugisisk romantik . En lille flaske med stor personlighed – og masser af Tawny‑magnetisme. Alkohol % : 40,0 Størrelse : 20 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XII Anos &#8220;Two Oaks&#8221; 20cl Rom', 'https://spitus.dk/product/abuelo-xii-anos-two-oaks-20cl-rom/', 209, true, 20, 40, 'https://spitus.dk/wp-content/uploads/2026/07/Abuelo-XII-Anos-Two-Oaks-20cl.jpg', 'Abuelo Two Oaks er rommens svar på en gentleman, der både kan tale pænt og tænde et bål med et blik. Den er lagret i 12 år i Panama – og derefter sendt på et lille eventyr i to forskellige typer egetræsfade , hvor den får sin signatur: dybde, røg, karamel og en attitude, der siger “jeg er ikke her for at være almindelig”. Første del af rejsen foregår i klassiske, medium‑ristede fade, hvor rommen får sin bløde sødme, sin vanilje og sin elegante, modne karakter. Men så kommer anden del: heavy charred oak – fade, der er brændt så hårdt, at de næsten burde have brandslukker stående ved siden af. Her får Abuelo Two Oaks sin mørke kant, sin røgede dybde og den intense, karamelliserede profil, der gør den til noget helt særligt. Duften åbner med ristet eg, karamel, toffee, kakao og en snert af røg , som om nogen har lavet dessert over åben ild. Smagen er en cremet, fyldig og uimodståelig kombination af mørk chokolade, brændt sukker, vanilje, kaffe, nødder og let røg , der glider over tungen som silke med attitude. Det er sødt, men aldrig sløvt. Kraftfuldt, men aldrig brutalt. Perfekt balanceret – som en rom, der har været i træningslejr i to forskellige egetræsuniverser. Eftersmagen er lang, varm og krydret , med lag af eg, karamel, røg og en dyb sødme , der bliver hængende som et sidste, flirtende farvel. Den lille 20 cl‑flaske gør den perfekt som gave, som luksus‑smagsprøve eller som “jeg skal bare lige prøve den her” – og vi ved begge, at det sjældent stopper der. Abuelo Two Oaks er rommen til dig, der elsker dybde, elegance og en smule drama . En lille flaske med stor personlighed – og dobbelt egetræ. Alkohol % : 40,0 Størrelse : 20 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XV Finish Collection Oloroso Cask Rom', 'https://spitus.dk/product/abuelo-xv-finish-collection-oloroso-cask-rom/', 599, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/07/abuelo-finish-olorosso.jpg', 'Når panamansk rom får spansk temperament og bliver til ren flydende charme. Abuelo XV Oloroso Cask er rommens svar på en diplomat med perfekt strøget jakkesæt, skinnende sko og et smil, der kan få selv de mest skeptiske til at overgive sig. Den er født i Panama, men har fået sin finpudsning i Oloroso‑fade fra Jerez – og det kan smages. Det her er ikke bare rom. Det er en kulturel udveksling, hvor Panama og Spanien har besluttet sig for at lave noget, der er farligt tæt på perfektion. Duften åbner med varm karamel, rosiner, mørk frugt, valnødder og en dyb sherry‑sødme , der føles som at træde ind i et gammelt andalusisk bodega‑loft, hvor træet dufter af historier og fadene af hemmeligheder. Der er også et strejf af tobak, vanilje og krydret eg , som giver rommen en moden, aristokratisk kant. Smagen er en blød, rund og uimodståelig symfoni af tørret frugt, brændt sukker, chokolade, appelsinskal, nødder og sherry , der glider over tungen som silke. Oloroso‑fadet giver en dyb, vinøs elegance, der løfter Abuelo‑profilen til et niveau, hvor man begynder at overveje, om rom egentlig burde være lovligt. Det er sødt, men aldrig tungt. Kompleks, men aldrig kompliceret. Luksus, uden at være selvhøjtidelig. Eftersmagen er lang, varm og krydret , med lag af eg, rosiner, sherry og en let tannin , der giver en smuk afrunding. Den hænger i munden som et sidste, flirtende blik fra en person, du godt ved, du burde holde dig fra – men ikke har tænkt dig at gøre det. Abuelo XV Oloroso Cask er en del af den ikoniske Finish Collection, hvor hvert udtryk får sin egen personlighed gennem fadfinish. Oloroso‑udgaven er den mest elegante af dem alle: dyb, mørk, sherry‑kysset og perfekt balanceret. Det her er flasken til dig, der elsker rom med karakter, finesse og international attitude . En dram, der både imponerer samlere, entusiaster og alle, der mener, at rom skal være lige så sofistikeret som whisky. Leveres i eksklusiv gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bayou Mardi Gras XO', 'https://spitus.dk/product/bayou-mardi-gras-xo/', 699, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/03/Bayou-mardi-gras-XO.png', 'Bayou Rum er vaskeægte amerikansk rom fra sydstaten Louisiana. Rommen er produceret på en lokal sukkerrørsmelasse som destilleres på små batch-destilleringsapparater, og herefter modnet i forskellige fade, normalt i et solera-system, men nogle varianter også som single barrel. Destilleriets masterblender er den unge romkomet, Reiniel Vicente Diaz, som har rødder i den cubanske og dominikanske romproduktion. Denne Bayou Mardi Gras XO er rommen, der ankommer med samme energi som et Mardi Gras‑optog: farverig, fyldig og fuld af charme. Den er lagret på bourbonfade i Louisiana‑varmen, hvilket giver en dyb, sød og krydret profil, der skiller sig ud fra de klassiske Caribiske rom. Bayou Mardi Gras XO er Louisiana i festhumør. Farven er dyb mahogni. I næsen blommer, cedertræ, tørrede, mørke frugter. Smagen er rund og intens med noter af karamel, vanilje, ristet eg, mørk frugt og en varm, krydret finish. Den har en amerikansk bourbon‑agtig kant, men stadig den bløde rom‑sødme, der gør den farligt drikkevenlig. Det er rommen, du vælger, når du vil have noget anderledes, karakterfuldt og med masser af sydstats‑attitude. Bayou Mardi Gras XO er en flydende fest fra Louisiana. Dejlig, sød og fed rom, der emmer af varmen og omgivelserne i Sydstaterne. Guld ved San Francisco World Spirits Competition, 2019. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hunter Laing Kill Devil 16 Y.O. Guyana', 'https://spitus.dk/product/hunter-laing-kill-devil-rom/', 1099, false, 70, 46, 'https://spitus.dk/wp-content/uploads/2020/10/Kill-Devil-100289-1.jpg', 'Hunter Laing, kendt for whisky af høj kvalitet, lykkes igen og igen med at præsentere romtyper i topklasse fra de caribiske øer med deres Kill Devil-serie. Det legendariske, og nu lukkede, Uitvlugt Distillery på Guyana destillerede i december 1999 et fad, og efter 16 år på dette fad i Skotland, har Hunter Laing nu i alt tappet 370 flasker af denne unikke rom . Kill Devil er meget efterspurgt af rom-fans over hele verden, og denne eksklusive udgave er bestemt ingen undtagelse. Kraftige, krydrede toner kridter banen op i næsen. Vanilje, peber, kanel og eg udgør den krydrede del. Derudover er der saftige frugtnoter af blomme, abrikos, grønne bananer og mango. Disse ledsages af fine pærenoter og lette citrusnoter. I munden er der er en overraskende friskhed over den, men bag det hele lurer en tung oplevelse af røg og ristet eg. Enorm kraft, krydderi og søde frugtsmag. På ganen er der også whisky-noter, og der er endda røgfyldte, næsten tørvede noter samt tungere elementer af røget kød og læder. Der er en lille øgning af krydderierne i midten af ganen, men strukturen forbliver sød. Eminent finish, og igen trænger det sødlige og lette røgfyldte igennem i en lang, lang burn-out. Faaaantastisk oplevelse for de få, som nogensinde får muligheden for at smage denne herlige dram. Størrelse : 70cl Alkohol % : 46,0 Leveres i gaverør.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Foursquare 15 Years Old PENULTIMUS Exceptional Cask Selection Mark XXX Rom', 'https://spitus.dk/product/foursquare-15-years-old-penultimus-exceptional-cask-selection-mark-xxx-rom/', 1045, true, 70, 57, 'https://spitus.dk/wp-content/uploads/2026/05/foursquare-Penultimus.jpg', 'Den næstsidste. Den uundgåelige. Den, du ikke må gå glip af. Dette er den næstsidste udgivelse i en af romverdenens mest ikoniske serier. Et punktum‑før‑punktummet, skabt af Richard Seale, der er kendt for at lave rom med samme kompromisløshed som en kirurg med OCD. PENULTIMUS er en 15 år gammel single blended rom , skabt på både pot still og column still, og en del er lagret 15 år på eks-bourbonfade, mens en anden del er modnet 10 år på bourbonfade efterfulgt af 5 år på søde, spanske Moscatel-vinfade. Det er første gang, Foursquare bruger Moscatel‑fade – og resultatet er lige så elegant, som det lyder. Ved 57% ABV leverer den en intens, men silkeblød oplevelse, hvor bourbonfadets vanilje, kokos, mørk chokolade og karamel møder Moscatelens mørke frugt, ananas, rosiner, figner og varme krydderier. Ingen sukker. Ingen farve. Ingen pynt. Bare ren, ærlig Barbados‑rom, præcis som Seale insisterer på, at rom skal være . Det er en rom, der både taler til samlere, entusiaster og dem, der bare gerne vil drikke noget, der får dem til at føle sig som et bedre menneske. PENULTIMUS er ikke bare endnu en udgivelse. Det er en afskedssalut til en serie, der har sat standarden for moderne rom. Efter Mark XXXI “Epilogue”, er det slut. Derfor er denne flaske ikke kun en smagsoplevelse – det er et stykke romhistorie. Kort sagt: Hvis du vil have en rom, der kombinerer seriøs håndværk, luksus og en smule “jeg ved noget, du ikke ved”, så er PENULTIMUS svaret. Størrelse: 70 cl Alkohol %: 57,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation &#8211; Meticho Coconut', 'https://spitus.dk/product/rum-nation-meticho-coconut/', 289, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/05/Met.jpg', 'Der findes kokoslikører, der smager som en ferie, du ikke bad om. Og så findes der Meticho Coconut – flasken, der beviser, at kokos faktisk kan være både premium, elegant og seriøst velsmagende. Det her er ikke en sød, klistret stranddrik. Det er en moderne, balanceret kokoslikør med kvalitet i centrum og et udtryk, der rammer lige mellem luksus og lethed. Meticho Coconut er lavet på en base af rom, der giver struktur og varme, og en naturlig kokossmag, der er ren, præcis og uden kunstig eftersmag. Det betyder, at du får en likør, der både er blød, rund og overraskende velafbalanceret. Den er sød – men ikke for sød. Den er cremet – men ikke tung. Den er aromatisk – men uden at overtage hele rummet. Smagen er solmodne kokosnødder, pakket fint ind i et lag af silkeblød karamel, vanilje og et strejf af tropisk chokolade. Kort sagt: kokos, som voksne faktisk gider drikke. Meticho Coconut fungerer perfekt rent, afkølet eller over is, hvor den virkelig viser sin rene smagsprofil. Men den er også et stærkt kort i cocktails. Den løfter alt fra simple mixere til mere avancerede kreationer, og den gør det uden at overdøve resten af glasset. Det er en likør, der spiller med – ikke en, der kræver hovedrollen. Hvis du er træt af kokosprodukter, der smager som en dessertbuffet, så er Meticho Coconut den opgradering, du har ventet på. En likør med renhed, balance og en smagsprofil, der rammer plet – hver gang. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rammstein Rum Cognac Cask Finish 2021', 'https://spitus.dk/product/rammstein-rum-cognac-cask-finish-2021/', 749, true, 70, 46, 'https://spitus.dk/wp-content/uploads/2023/05/rammstein-cognac-cask-finish-2021-gb-k.png', 'Rammstein Rum Cognac Cask Finish 2021 er rommen der skriger “Feuer Frei!” uden at du behøver ørepropper. Denne limited edition er rommens svar på en stadionkoncert: høj, mørk, intens og fuld af attitude. Rammstein har taget deres allerede potente rom og sendt den på cognacfade – og resultatet er så smooth og samtidig så voldsomt, at du næsten forventer pyroeffekter, når du åbner flasken. Rammstein Rum er en perfekt afbalanceret blanding af Jamaica og Guyana Pot Still Rom, samt Column Still Rom fra Trinidad, Guyana og Jamaica. Alderen er op til 12 år, og efter blendingen, får den 9 måneder ekstra i brugte cognac-fade. Den er sød og nærmest smøragtig – modsat bandets musik. Næsen indeholder masser af fermenterede frugter – der er en del Jamaica funk over den. I munden sødlig med vanilje, saftige frugter, cognac-druer og banan. Ret kraftfuld (cognac-fadene?), men stadigvæk frisk og imødekommende. Som en læderjakke med silkefoer. Rammstein Rum Cognac Cask Finish 2021 er umiddelbart den eneste rom, der kan lave pyro… i din mund. Udgivet i 3.989 flasker, og de er efterhånden ved at være udsolgte, og dermed ret efterspurgte. Både til samleren, nyderen og fans af bandet! Leveres i gaverør. Alkohol %: 46,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Zacapa Centenario EDICIÓN NEGRA Sistema Solera Gran Reserva', 'https://spitus.dk/product/ron-zacapa-centenario-edicion-negra-sistema-solera-gran-reserva/', 689, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2023/11/ron-zacapa-centenario-edicion-negra-sistema-solera-gran-reserva-k.png', 'Ron Zacapa fra Guatemala producerer nogle af verdens mest solgte og kendte rom. Rommene laves på sukkerrørssaft i stedet for melasse, hvilket giver den en dyb og kompleks smag. Rommen modnes som regel i en proces kaldet “Sistema Solera”, hvor nye og gamle rom blendes over tid. I denne Edición Negra, lanceret i 2018, er blendet mellem 6 og 24 år. Lagringen er foregået på bourbon, Pedro Ximenez sherry og forkullede amerikanske egefade. Farven er gyldent kobber. I næsen massive tørrede frugter, chokolade og vanilje, samt et let lag af sød tobak. I munden sødmefuld, som vi kender det fra Ron Zacapa, med karamel, honning, rosiner og chokolade. Men; den er ikke helt så butterscotch-agtig som vi kender det fra Ron Zapaca 23, og adskiller sig dermed fra familiemedlemmerne. Zacapa Edición Negra kommer i en slank og elegant flaske, samt meget smuk ibenholt-gaverør. Dette nye flaskedesign skiller sig ud fra mængden, og er med til at gøre Zacapa Edición Negra til den perfekte gave. Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cueva 1501 Solera 25', 'https://spitus.dk/product/ron-cueva-1501-solera-25/', 949, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/04/Ron-Cueva-1501-Solera-25.png', 'Med en gennemsnitlig alder på 25 år (en del af blendet er meget ældre), får du her beviset hvad alder gør for en i forvejen god rom. Manner. Farven er mørk gylden, og gardinerne klæber sig til glassets inderside. I næsen en eksplosion af anciennitet, velsmag og overskud. Friskmalet kaffe, dadler, rosiner, mørk chokolade og Madagaskar-vanilje smelter sammen i en herlig aroma. I ganen fuldfed, og selv om vaniljen er fremtrædende, er den ikke over-sød. Fløjlsblød tekstur, men i sin natur også ret voldsom og tilstedeværende. Der er smæk på, og der elementer af god cognac og god whisky i oplevelsen. Lang eftersmag, der efterlader dig med et stort smil om munden. Ron Cueva 1501 Solera 25 er en rom, der smager af tålmodighed, håndværk og ren luksus. Den er sød, fyldig og så afrundet, at du næsten får lyst til at klappe glasset. Godt, gedigent håndværk fra Ron Cuevo, og hvis stammerne havde haft adgang til denne rom i 1501, er jeg sikker på de havde kunnet bestukket europæerne til ren overgivelse. Leveres i flot gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('SeRum Mamie', 'https://spitus.dk/product/serum-mamie/', 299, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/04/8.png', 'SeRum Mamie er en hyldest til Panamas livlige bartradition, og kombinerer modne rom fra Panama med fine aromaer af toffee, kakao og vanilje. Inspireret af Mamie, ejeren af den legendariske Kelley&#8217;s Ritz – en bar kendt for sin kosmopolitiske atmosfære i Panama City i 1920&#8217;erne. (læs: der var gang i den). Fremstillet af udvalgte mørke rom, der er omhyggeligt modnet, er SeRum Mamie kendetegnet ved en blød, cremet tekstur og et harmonisk samspil af søde og krydrede noter. Kombinationen af den caribiske destillationskunst med naturlige aromaer skaber en fyldig smagsoplevelse, der vil glæde de fleste. Farven er dyb guld med ravfarvede refleksioner. I næsen stærke aromaer af toffee og mørk chokolade, underlejret med noter af vanilje og honning. Smagen Perfekt både til at nippe rent og til at hælde i en drink, når du vil imponere uden at anstrenge dig. Den har en rundhed, der føles som en venlig skulderklap, og en sødme, der aldrig bliver kvalm – bare behagelig, balanceret og lige til at smile af. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Flor de Caña Centenario 12 Years Old Rum', 'https://spitus.dk/product/ron-flor-de-cana-centenario-12-years-old-rum/', 329, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/03/16-1.png', 'Ron Flor de Caña Centenario 12 Years Old Rum er en velanset og prisbelønnet rom fra foden af San Cristobal vulkanen i Nicaragua, Mellemamerika. Her har de i over 130 år og i nu femte generation, produceret &#8220;ærlig og ægte rom-oplevelser&#8221;. Rommen her er fuldlagret i 12 år uden indblanding &#8211; de kalder det selv &#8220;Slow Aged&#8221;, og der er ikke tilsat sukker eller kunstige stoffer. Den er ikke engang blended med andre rom fra f.eks. andre årgange. Det her er rom uden dikkedarer. Og så er der lige den detalje, der gør romnørder ekstra glade: Flor de Caña er et af verdens mest bæredygtige romdestillerier. CO₂‑neutral produktion (de bruger 100% vedvarende energi), fair trade‑certificeret, og de planter hvert år &gt;50.000 træer. Det er rom, der både smager godt og opfører sig ordentligt. I næsen får du en varm og indbydende duft af karamel, vanilje, let ristet egetræ og tørret frugt. Det hele er roligt, afbalanceret og uden den tunge sødme, som mange andre rom i samme alder ofte har. Det er en duft, der får dig til at tænke på meget, meget gammel rom. Smagen er blød, rund og fyldig. Du får noter af karamel, toffee, nødder, let krydderi og en mild frugtighed, der trækker i retning af svesker og modne æbler. Teksturen er silkeblød, og alkoholen er så fint integreret, at du næsten glemmer, at det faktisk er en 40 % rom. Eftersmagen er lang, varm og behageligt tør – en af de ting, der gør Flor de Caña 12 så nem at drikke. Det her er en rom, der fungerer perfekt rent eller på is, men den gør sig også fremragende i cocktails, hvor du vil have noget med dybde uden at overdøve resten. En Old Fashioned med Flor de Caña 12? Det er næsten for nemt. Flor de Caña Centenario 12 Years Old er kort sagt en rom, der rammer den perfekte balance mellem kvalitet, renhed og drikkeglæde. Den er elegant uden at være snobbet, kompleks uden at være svær og smooth uden at blive sød. Aldrig har det være lettere at vælge noget bæredygtigt. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix A.H. Riise XO Explorer Reserve (Germany Edition)', 'https://spitus.dk/product/old-st-croix-a-h-riise-xo-explorer-reserve-germany-edition/', 599, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/08/Old-St.-Croix-A.H.-Riise-XO-Explorer-Reserve-Austria-Version.png', 'Old St. Croix A.H. Riise XO Explorer Reserve – Germany Edition Old St. Croix XO A.H. Riise Reserva Explorer Germany, er den ene af de 10 udgivelser i den eksklusive Explorerer-serie. Flasken er en hyldest til de modige forskere og opdagelsesrejsende, som tilbage under A.H. Riises tid, bidrog til kortlægningen og forståelsen af verden. Eventyrerne tilsidesatte egen sikkerhed og rejste ud i verden, og det hyldes nu af A.H. Riise med en serie af skønne flasker. XO Explorer-serien består af en række Limited Editions, der udkom i en række forskellige lande i begrænsede antal nummererede flasker. Hver Edition er skabt specielt til A.H. Riises mange fans og samlere i de forskellige lande, hvor de lokale pionerer var forgangsbilleder for at søge ny viden og sætte deres nation på landkortet, nøjagtig som A.H Riise gjorde. Denne Østrigske Old St. Croix XO Explorer, som er lavet i et begrænset oplag i nummererede flasker, er et eksklusivt Limited Edition-blend fra Vestindien og Mellemamerika, sammensat af A.H. Riises master blender. Spiritussen er sammensat af nøje udvalgte fade fra Vestindien og Mellemamerika, og blendet af A.H. Riises masterblender med fokus på dybde, sødme og kompleksitet. Den tappes ved 40 % alkohol og fremstår med en mørk ravfarve, der vidner om dens lange modning og rige karakter. I næsen mødes man af intense noter af karamel, vanilje og modne tropiske frugter, efterfulgt af varme krydderier og et strejf af egetræ. Smagen er blød og fyldig med lag af søde rosiner, appelsinskal, flødekaramel og ristede nødder. Eftersmagen er lang og behagelig med vedvarende sødme og en let krydret afslutning, der gør den velegnet til både ren nydelse og som ledsager til dessert eller mørk chokolade. Germany Edition leveres i en elegant gaveæske med et design, der afspejler både eventyrlyst og klassisk luksus. Den er ideel som gave til samleren, den passionerede romelsker eller som et eksklusivt indslag i hjemmebaren. Old St. Croix XO Explorer Reserve GermanyEdition er ikke blot en spiritus – det er en fortælling om opdagelse, håndværk og kulturarv. En flaske, der inviterer til at udforske smag, historie og det ukendte – præcis som de opdagelsesrejsende, den er skabt til at ære. I flot gaveæske. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Foursquare 14 Years Old EQUIDEM Exceptional Cask Selection Mark XXVII Rom', 'https://spitus.dk/product/foursquare-14-years-old-exceptional-cask-equidem-selection-mark-xxvii-rom/', 1139, true, 70, 61, 'https://spitus.dk/wp-content/uploads/2026/03/9-1.png', 'Denne Foursquare Equidem er den syvogtyvende(!) udgivelse (Mark XXVII) i den prestigefyldte Exceptional Cask Selection-serie. Det er ikke en rom, man bare lige “snupper med”. Det er en af de udgivelser, hvor entusiaster sætter sig op i stolen og samlere får pulsen en anelse op. Mark XXVII viser endnu en gang, hvorfor Barbados‑destilleriet har opnået kultstatus. Her får du en rom, der har tilbragt 14 år i en kombination af ex‑bourbon og, helt specielt og for første gang fra Foursquare: 9 år i Black Muscat-fade (en sød dessertvin). Tappet ved fuld fadstyrke uden sukker, uden tilsætninger og uden kompromiser. Det er rom til folk, der vil have det ægte udtryk. I næsen møder du en dyb og kompleks aroma: mørk karamel, tørret frugt, egetræ, vanilje og en diskret krydret tone, der afslører sherryfadenes indflydelse. Det er intenst, men aldrig rodet. Foursquare har en evne til at få selv kraftige profiler til at fremstå rene og præcise, og EQUIDEM er ingen undtagelse. Smagen er fyldig, varm og lagdelt. Du får en flot balance mellem bourbonfadets vanilje og kokos, sherryfadets rosiner og mørke frugt, og den karakteristiske Foursquare‑dybde af egetræ, krydderi og tørhed. Alkoholstyrken er markant, men integreret – det er en rom, der belønner langsomme slurke og et godt glas. Eftersmagen er lang, tør, kompleks og vedholdende. Det er her, man mærker, hvorfor samlere går efter disse udgivelser. EQUIDEM er ikke en rom, man serverer for hvem som helst. Den er til dem, der forstår håndværket, til dem der følger serien, og til dem der sætter pris på rom, der ikke forsøger at være sød, nem eller mainstream. Det her er Barbados‑rom på sit mest seriøse og mest ærlige. For samlere er Mark XXVII endnu en brik i en serie, der kun bliver mere eftertragtet. For kendere er det en smagsoplevelse, der viser, hvorfor Foursquare fortsat er blandt verdens mest respekterede destillerier. Foursquare EQUIDEM 14 Years Old er en rom med autoritet, dybde og samlerværdi . En flaske, der ikke behøver hype – den skaber den selv. Størrelse: 70 cl Alkohol %: 61,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('New Grove 10 Years', 'https://spitus.dk/product/new-grove-10-years/', 419, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/11/new-growe-10yo.jpg', 'New Grove 10 Years er rommen, der beviser, at Mauritius ikke kun laver paradisstrande – de laver også seriøst undervurderet rom. Her får du en elegant, fadlagret rom med masser af karakter, varme og tropisk charme. Lagret i mindst 10 år, først på nye franske egetræsfade, og til sidst på brugte cognacfade. Smagen er rund og moden med noter af karamel, vanilje, tørret frugt, let citrus og et strejf af egetræ. Den har en naturlig, balanceret sødme og en blød finish, der gør den både nydelsesvenlig og interessant at dykke ned i. Det er rommen, du hiver frem, når du vil have noget, der er anderledes end de klassiske Caribiske flasker – men stadig smooth, velafbalanceret og super drikkelig. New Grove 10 Years er Mauritius, men i premium‑format. Leveres i et gaverør. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Emperor Mauritian Rum Aged Blend Sherry Finish', 'https://spitus.dk/product/emperor-mauritian-rum-aged-blend-sherry-finish/', 279, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/03/emperor-mauritian-rum-sherry-finish-k.jpg', 'Emperor Rom har specialiseret sig i at lave blended rombaserede spiritusser af sukkerrørsdestillater og sukkerrørssaft fra Mauritius. De eksperimenterer også med forskellige fadtyper, og her har de altså anvendt brugte sherry-fade. Dette store mix af metoder og tilgange, skal måske ses i sammenhæng med Mauritius temmelig omtumlede historie. Mauritius har nemlig både været en hollandsk koloni (1638-1710), en fransk koloni (1715-1810) og en britisk koloni (1810-1968). Derfor er øen også multietnisk, multireligiøs, multikulturel, flersproget og naturligvis multi-romproducerende. Emperor Rum er derfor et godt eksempel på øens arv og historie. Der er i dag 6 destillerier på øen som producerer alt fra den traditionelle Agricole Rom til den sødere spanske stil. Øen er for 85 % vedkommende dækket af sukkerrørsmarker, så jorden er prioriteret rigtigt! Blandingen af sukkerørssaft og sukkerørsmelasse, giver en anderledes smagsoplevelse, og mange har taget Emperor-udgivelserne til sig. Selve navnet Emperor, er skabt for at ære Kong George den 5. som var kejser af det britiske imperium og dermed også over Mauritius. Han var en meget stor fan af Sherry, og Emperor Sherry Cask er skabt til hans ære. Denne Sherry-version, dufter af friskpresset sukkerørssaft, vanilje og masser af eksotiske frugter. I munden mødes du af karameliserede frugter, krydderier, chokolade samt en liflig note af blomster. Du er ikke i tvivl om at den har været i sherry-tønder, og den mørke chokolade med mokka smyger sig dejligt rundt i munden. Dejlig, let-at-gå-til udgivelse &#8211; leveres i flot gaveæske. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bacardi Caribbean Spiced', 'https://spitus.dk/product/bacardi-caribbean-spiced/', 279, true, 100, 40, 'https://spitus.dk/wp-content/uploads/2026/02/2.png', 'Bacardi Caribbean Spiced er Bacardis bud på en moderne, tropisk romoplevelse, hvor klassisk caribisk rom møder en velafbalanceret blanding af naturlige krydderier og frugtnoter. Det er ikke en flaske, der forsøger at være kompleks, tung eller fadnørdet – den er skabt til at være letdrikkelig, festlig og umiddelbart charmerende. Men under den solmodne overflade gemmer der sig faktisk mere finesse, end man lige forventer af en flaske, der nærmest dufter af strandbar og solnedgang. Selve basen er Bacardis velkendte rom, som her er infuseret med ananas, kokos, vanilje og en mild krydderprofil, der giver en varm, rund og næsten dessertagtig karakter. Det er ikke en spiced rom, der forsøger at slå dig i hovedet med kanel og nelliker; den er langt mere tropisk i sit udtryk, som om Bacardi har kigget på en Piña Colada og tænkt: “Hvad nu hvis vi bare putter hele stemningen direkte ned i flasken?” Resultatet er en rom, der både dufter og smager af ferie – uden at blive kvalm eller kunstig. I næsen får du straks ananas og kokos, men der ligger også en blød vaniljetone og en let krydret varme, der minder om bagt banan og brun farin. Smagen følger trop: sødmefuld, rund og frugtig, men med en lille tør kant, der gør, at den ikke tipper over i ren likør. Det er en rom, der er skabt til at blive drukket på mange måder – rent, over is, i simple cocktails eller som turbo‑opgradering af alt fra cola til ginger beer. Den fungerer især godt i drinks, hvor man gerne vil have tropisk karakter uden at skulle jonglere med halvdelen af frugtafdelingen. Bacardi Caribbean Spiced er ikke en rom for purister, der sidder med næsen dybt begravet i et glas 25‑årig pot still‑rom og diskuterer estere. Den er for alle os andre, der nogle gange bare vil have noget, der smager godt, dufter af sol og gør livet en lille smule mere afslappet. Det er en flaske, der inviterer til grin, musik og gode venner – ikke til dybe analyser, selvom den faktisk kan tåle et par stykker. Og så er der prisen, som gør den til en af de mest tilgængelige tropiske oplevelser på markedet. Du får masser af smag, masser af stemning og en flaske, der kan trylle selv den mest regnfulde danske torsdag om til en caribisk mini‑ferie. Alkohol % : 40,0 Størrelse : 1 liter');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Royal Danish Navy, 35 cl', 'https://spitus.dk/product/a-h-riise-royal-danish-navy-35-cl/', 239, true, 35, 40, 'https://spitus.dk/wp-content/uploads/2022/11/a.h.-riise-danish-navy-35-cl.png', 'A.H. Riise Royal Danish Navy – Den kompakte kraftpakke på 35 cl. A.H. Riise Royal Danish Navy er lille broderen, der ikke behøver en stor flaske for at levere stor smag. Selv i 35 cl‑udgaven får du den fulde Navy‑oplevelse: mørk, sødmefuld, intens og pakket med den aromatiske dybde, som har gjort serien legendarisk. A.H. Riise Royal Danish Navy 40 % er skabt med inspiration i de originale recepter på Royal Navy Rum. Opskrifterne blev udviklet af A.H. Riise, og spiritussen leveret til flådens skibe, når de anløb havnen i Charlotte Amalie i det tidligere Dansk Vestindien. A.H. Riise Royal Danish Navy har ikke samme tørre stil og element som typiske engelske navy-rom. Den er markant lettere at gå til, og har noget ganske fint og sart over sig. I næsen møder du cedertræ, karamel, lakrids og appelsiner. I munden får du eksotiske krydderier, kandiserede æbler, appelsin, kokos og karamel. Meget eksotisk og elegant. Fed, olieret og lang eftersmag med abrikos og sødmefulde krydderier. Det er en udgivelse, der føles som en dyb, mørk dessert med maritime muskler – perfekt til dem, der elsker den klassiske A.H. Riise‑stil, men vil have en mere håndterbar flaske til gaver, smagninger eller ren selvforkælelse (og naturligvis samlere). A.H. Riise Royal Danish Navy 35 cl: Lille flaske, stor personlighed. Alkohol % : 40,0 Størrelse : 35 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Doorly&#8217;s 5 Years Old Fine Old Barbados Rum', 'https://spitus.dk/product/doorlys-5-years-old-fine-old-barbados-rum/', 235, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/02/6-1.png', 'Denne Doorly&#8217;s er kun fem år gammel, men den har allerede den der Barbados‑selvtillid, som kun kommer af at vokse op et sted, hvor solen skinner, havet glitrer, og alle tager livet en lille smule mindre alvorligt. Det er en rom, der ikke prøver at være noget, den ikke er – og det er præcis derfor, den fungerer så godt. Når du hælder den i glasset, får du en duft, der føles som at åbne døren til et køligt rum efter en varm dag. Der er en friskhed, en lethed, en sødme, der ikke forsøger at charmere dig – den gør det bare. Den første slurk er blød og imødekommende, som om rommen siger: “Rolig nu, vi tager det stille og roligt.” Karamellen og vaniljen ligger som en varm base, mens de frugtige noter danser ovenpå med en energi, der minder om en strandbar, hvor ingen har travlt med noget som helst. Doorly’s 5 blandes og lagres på det legendariske Foursquare, og den har den der særlige Foursquare‑signatur: ren, ærlig og uden unødvendige dikkedarer. Den er ikke overdrevet sød, ikke overdrevet krydret, ikke overdrevet noget som helst. Den er bare… god. Den slags rom, der glider ned uden modstand, men stadig efterlader et lille smil på læben. Egetræet giver en mild kant, der holder det hele i balance, og finishen er overraskende ren – som om rommen lige vil minde dig om, at den måske er ung, men den ved godt, hvad den laver. Det bedste ved Doorly’s 5 er, at den er så ufatteligt alsidig. Du kan drikke den rent og få en let, elegant oplevelse. Du kan hælde den over is og få en rom, der føles som en lille ferie. Eller du kan smide den i en cocktail, hvor den opfører sig som den perfekte wingman: den løfter stemningen uden at stjæle spotlightet. Det er en rom, der ikke kræver noget af dig – men som alligevel giver dig mere, end du forventer. Doorly’s 5 Years Old er kort sagt rommens svar på en god ven: altid klar, altid venlig, altid i godt humør. Den er måske ikke den ældste, den mest komplekse eller den mest højlydte rom på hylden – men den er den, du ender med at tage med hjem, fordi den bare føles rigtig. I overensstemmelse med god Barbados-tradition, er der ikke tilsat sukker for at søde rommen. Destillationsmetoden med både pot stil og kolonnekedel samt hele lagringsprocessen, sikrer en naturlig sødme og den herlig fyldig smag. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Foursquare 14 Years Old CONVOCATION Exceptional Cask Selection Mark XXVIII Rum', 'https://spitus.dk/product/foursquare-14-years-old-convocation-single-blended-rum/', 995, true, 70, 62, 'https://spitus.dk/wp-content/uploads/2026/02/2-1.png', 'Dette er den 28. udgivelse i den legendariske Exceptional Cask Selection fra Foursquare i Barbados. Convocation 14 Years Old er en såkaldt single blended rom &#8211; en specialitet fra Foursquare Distillery, som skabes ved at blende destillater destilleret i en pot still og en kolonnestill. Derefter modnes den i 14 år i 3 forskellige fade. Altså: ét 14-årigt bourbonfad, ét 14-årigt Madeirafad og et tredje fad med dobbeltlagret rom, der har tilbragt sine første 10 år på bourbonfad og de sidste 4 år på et Madeirafad. Disse 3 fade er blended, og efterfølgende aftappet ved en fadstyrke på 62 % ABV. Naturligvis uden tilsætning af noget &#8211; uden kuldefiltrering, sukker eller farvestoffer mm. Når du dufter til den, får du en antydning af noget, der minder om en bibliotekssal, hvor alle bøgerne handler om rom. Mørke stenfrugter, blommer, kirsebær, rosiner og svesker. Egetræ og let krydret. Kardemomme og sort peber. Med tiden (og den har fortjent noget tid med sine 62%) kommer der vanilje, banan og kokos&#8230; Alt det rigtig gode fra Barbados. Smagen er intens og meget fyldig. Den åbner sødmefuld fra Madeirafadet. Mørke frugter og krydret egetræ med en varmende alkohol. Papayafrugt, vanilje og lidt sort peber. Den har en tør, krydret varme, der giver rommen en næsten intellektuel skarphed — den slags smag, der får dig til at stoppe op og tænke over, hvad der egentlig foregår i glasset. Finishen er lang, kompleks og fuld af nuancer (mørk frugt, læder, eg, karamel, vanilje), der bliver hængende, længe efter du har taget den sidste slurk. Foursquare‑destilleriet er efterhånden blevet romverdenens svar på en Michelin‑kok: kompromisløs, fokuseret og helt uinteresseret i at lave noget, der ikke er fremragende. Convocation er ingen undtagelse. Den er ikke tung eller støvet af sin alder, men med en modenhed, der er blevet til gennem tålmodighed og perfektionisme. Med denne udgave viser Foursquare endnu en gang, hvorfor deres aftapninger er blandt de mest eftertragtede samlerobjekter. Så længe lager haves! Størrelse: 70 cl Alkohol %: 62,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Foursquare 16 Years Old MANDAMUS Exceptional Cask Selection Mark XXIX  Rom', 'https://spitus.dk/product/foursquare-16-years-old-mandamus-single-blended-rum/', 995, true, 70, 57, 'https://spitus.dk/wp-content/uploads/2026/02/3-1.png', 'Foursquare 16 Years Old Mandamus Single Blended Rum 57% er en enestående aftapning fra det anerkendte Foursquare Destilleri på Barbados og en del af den eftertragtede Exceptional Cask Series (udgave XXIX (29)). Denne serie er verdensomspændende synonym med perfekt håndværk, gennemsigtighed og kompromisløs kvalitet. Mandamus er en enkelt blendet rom bestående af en kombination af pot-still og kolonne-still destillater, som har fået lov at modne i over 16 år i ex-bourbon- og tawny port-fade. Denne dobbeltmodning giver den dens enorme kompleksitet, dybde og aromatiske kompleksitet. Fadtappet ved 57% ABV er Mandamus et autentisk udtryk for Foursquares håndværk. Kombinationen af tropisk fadlagring og de søde og krydrede noter af portvin skaber en unik balance mellem frugt, krydderi og træ. Resultatet er en rom med imponerende struktur og elegance, der vil glæde både kendere og samlere. Farve: Dyb mahogni med rubinrøde reflekser. I næsen modne brombær, ananas, blomme og kirsebær, ledsaget af rosiner, vanilje, karamel, ingefær og nøddeagtige noter. Smagen er fyldig og blød med aromaer af saftige kirsebær, hindbær, blommer, rosiner og et strejf af appelsinskal. Eftersmagen er meget langtidsholdbar, kompleks og kraftfuld med noter af mørk chokolade, sort te, hvid peber og en fin træagtig varme. Det her er Foursquare, når Foursquare beslutter sig for at lave noget, der ikke bare er godt – men noget, der skal diskuteres, analyseres og nydes i stilhed. Den er ikke lavet til at blive drukket hurtigt. Den er lavet til at blive forstået. Som altid med disse Exceptional Cask Series fra Foursquare, er den udgivet i en begrænset mængde. Størrelse: 70 cl Alkohol %: 57,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Reserve Haakon Royal Reserve', 'https://spitus.dk/product/old-st-croix-xo-reserve-haakon-royal-reserve/', 419, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2025/12/croix-haakon-GB.png', 'Inden Kong Haakon den 7. af Norge i 1905 blev kronet som konge, havde han titel og opvækst som Prins Carl af Danmark. Han gjorde karriere i Den Kongelige Danske Flåde. Siden førte hans karriere ham til tjeneste på Fregatten Jylland. På et tidspunkt anløb Fregatten Jylland og den unge prins De Vestindiske Øer. Her mødte han Valdemar Riise, søn af A.H. Riise. Deres møde førte til venskab, og de erfarede, at de begge havde gensidig interesse for god, vellagret kvalitetsrom. Denne eksklusive aftapning, Old St. Croix Kong Haakon X.O. Royal Reserve, hylder både venskabet mellem de 2 mænd, og mødet over et velskænket glas rom. Denne spiritus-drik er genskabt med inspiration efter den originale opskrift. Netop Old St. Croix Kong Haakon X.O. Royal Reserve var efter sigende Kong Haakons absolutte favorit. Der er tale om en herlig dram i den elskede A.H. Riise/Old St. Croix stil. Dyb, fyldig, sød og med masser af tropiske frugter; primært appelsiner, mango og papaya. Dejlig fløjlsblød tekstur med vanilje, honning og tørrede rosiner, samt et snert af portvin. Lang eftersmag med masser af sødme og velintegreret velsmag. Old St. Croix Kong Haakon X.O. Royal Reserve er en ægte kongelig, vestindisk rombaseret spititus der får dig til at rette ryggen, pudse kronen og føle dig som en del af kongehuset. I gaveæske Størrelse: 70 cl Alkohol % : 42,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Black Barrel Navy Spiced', 'https://spitus.dk/product/old-st-croix-black-barrel-navy-spiced/', 295, true, NULL, NULL, 'https://spitus.dk/wp-content/uploads/2025/12/Croix-black-barrel.png', 'Black Barrel Navy Spiced fra Old St. Croix (tidligere A.H. Riise) er tæt knyttet til verdenshavene og søfart, hvilket flaskens udformning også bærer stærkt præg af, og den bygger på mere end 175 års knowhow i at blende og lagre rom og rombaserede spiritusser. Via lagringen på stærkt brændte egefade, ja faktisk forkullede indersider på fadene, får den en krydret karakter og ’spice’, der fuldt ud lever op til dens navn. I glasset er Black Barrel Navy Spiced næsten kulsort, og i næsen får du velkendte toner af vanilje, kaffe, nødder og eksotiske krydderier. Det er en duft, der lover eventyr – og leverer. Smagen er sødmefuld og fyldig, med chokolade, kanel, mokka, eg og søde krydderier. Eftersmagen er ”spiced”, og med mørk chokolade og mere mokka. Black Barrel Navy Spiced er i den søde stil, som altid med Old St. Croix, men denne er infuseret med en række eksotiske krydderier, og dermed får du masser af krydret velsmag! Flasken ser ud som noget, du ville finde i kaptajnens private gemmer – mørk, robust og med et design udformet som en tønde. Old St. Croix Black Barrel Navy Spiced er som en sømandssang på flaske: rå, kraftfuld og med en rytme, der får dit glas til at vippe i takt');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Millonario XO Solera Reserva Especial', 'https://spitus.dk/product/ron-millonario-xo-solera-reserva-especial-2/', 799, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/02/ron-millonario-XO_Ny-GB.png', 'Så for pokker; her har vi fat i toppen fra Ron Millonario. Med en alder på 15 – 20 år er den blandt Sydamerikas ældste rom, og kun de allerbedste fade bliver til Ron Millonario XO, Udgaven her blev kåret som ”Verdens Bedste Rom” i både 2008 og 2009. Nu er der mange kåringer, og det kan være lidt svært at tage seriøst, men godt det smager den!. Millonario XO er skabt i Peru, hvor sukkerrør, solskin og tålmodighed går hånd i hånd. Og det kan smages. Det er en rom, der er så blød, så sød og så elegant, at du næsten får lyst til at sige “Señor” til flasken, hver gang du går forbi den. Duft : En duft af sødme og tropiske frugter (primært appelsin) rammer næsen som det første, hvorefter en mere krydret note med tobak og tørrede frugter tager over. Smag: Smagen er behagelig sødmefyldt til at begynde med, men noter af karamel, dadel og figen. Derefter trænger en note af nelikke frem på tungen, men hele tiden i en fin symbiose med søde, eksotiske frugter. En anelse sødere end 15-års udgaven. Eftersmag: Den lukker med en behagelig og meget landvarig sødme med brun farin, svage krydderier og egetræsfad. Mums en livsglad eliksir, med den vildeste glas-gardiner. Dobbelt Guld v. Spirits Selection 2022 97/100 points af Mads ”Romhatten” Heitmann Super eksklusiv rom i super eksklusiv flaske og tilhørende gaveæske. Hvis der fandtes en rom, der kunne få dig til at føle dig som en sydamerikansk millionær med hængekøje, palmer og nul bekymringer, så ville det være Ron Millonario XO Solera Reserva Especial . Det her er ikke bare en rom – det er en oplevelse . En luksusrejse. En flydende ferie. En “jeg fortjener det her”-flaske, der står og blinker til dig fra hylden. Denne udgave er med 2026-designet. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Tabu Dominican Anejo Dark Rum', 'https://spitus.dk/product/tabu-dominican-dark-rum/', 159, false, 70, 38, 'https://spitus.dk/wp-content/uploads/2020/08/100262-1.jpg', 'Ron Tabú Añejo er fremstillet af sukkerrørsaft produceret i Den Dominikanske Republik. Fuldstændig perfekt hvis du vil have en prisvenlig, fadlageret rom &#8211; f.eks. til drinks og cocktails. Dejlig, klassisk smooth rom, med tydelige noter fra lagringen i amerikanske egetræsfade. Vanilje, rosiner, nødder, marcipan og karamel. Meget fint afstemt og afbalanceret, så den ikke stikker af i en bestemt retning der vil præge dine cocktails eller drinks for meget. Varm, og for prisklassen lang og elegant finish. Du får uendeligt meget rom for pengene her, hvor budgettet er brugt på råvarer og produktion, og ikke på branding og markedsføring! Vi har selv agenturet for Tabu i Norden, og det gør blandt andet, at vi kan sælge til helt uhørt lave priser. Størrelse : 70 cl Alkohol % : 38,0 Drinksopskrifter: MANHATTAN TABÚ Denne cocktail er en krydret og &#8220;varm&#8221;variant af den klassiske Manhattan. Ingredienser: En anelse kanel 5cl Anejo Rom Tabú 2cl rød Olave Vermouth 3 tsk appelsinsaft Hæld og ryst alle ingredienserne sammen, og sil den forsigtigt ud i et cocktailglas. Pynt med et amarena kirsebærspyd eller blot kirsebær. PIÑA COLADA 4cl Anejo Rom Tabú 3cl Teichenné kokoslikør 15 cl Folkington&#8217;s ananas juice Bland og ryst alle ingredienserne i en shaker med knust is. Serveres i et højt glas (uden at fjerne isen) og pynt cocktailen med et ananasblad og et kirsebær.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Tabu Caribbean White Rum', 'https://spitus.dk/product/tabu-caribbean-white-rum/', 159, false, 70, 37.5, 'https://spitus.dk/wp-content/uploads/2020/08/100261-1.jpg', 'Ron Tabú Blanco (hvid rom) er lavet af de bedste Dominikanske sukkerrørsdestillater. Elegant, smooth og fuldstændig perfekt til brug i drinks og cocktails. Fin, delikat aroma med antydninger af sprødt destilleret rørsukker. Klassisk smag med nødder, dadler og marcipan. Du får uendeligt meget rom for pengene her, hvor budgettet er brugt på råvarer og produktion, og ikke på branding og markedsføring! Og igen gør vort nordiske agentur på produktet, at du får den endnu billigere og uden fordyrende mellemled. Størrelse : 70 cl Alkohol % : 37,5 Anbefalet cocktails: Mojito 15 mynteblade 2 lime 5 cl Tabu Caribbean white rum 15 cl. Folkington&#8217;s Club Soda (=1 dåse) 2 spsk sukker (gerne rørsukker) Knust is M ango-Mojito Ingredienser: 5cl rom Tabú (hvid) 3 cl Teichenne Mango sirup 2 spsk sukker 1/2 lime 5 mynteblade Top med Folkingtons Club Soda Knust is Tag et stort glas og læg alle mynteblade i. Tilsæt sukker og lime. Brug en morter til at blande alle ingredienser. Tilsæt derefter den knuste is, op til halvdelen af glasset, og tilsæt den hvide rom og Mango-sirup. Tilsæt knust is op til kanten af glasset, og top op med club sodaen. Pynt med mynteblade Klassisk Daiquiri Daiquiri er en populær cocktail fra Cuba Daiquiri er en familie af cocktails, hvis vigtigste ingredienser er rom, citrussaft (typisk limesaft) og sukker eller andre sødestoffer. En klassiker, der ligger i top 10 af verdens mest konsumerede cocktails. Vores version af den klassiske Daiquiri-cocktail: &#8211; 6 cl Ron Tabú (hvid rom) &#8211; 2 cl Lime sirup fra Teichenne &#8211; 2cl hyldeblomst (Elderflowerjuice) fra Folkingtons. Ryst alle ingredienserne sammen, og server i et Martini-glas, og pynt med lime-skræl.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Stroh 80% Original Rum, 1 liter', 'https://spitus.dk/product/stroh-80-original-rum-1-liter/', 349, false, 100, 60, 'https://spitus.dk/wp-content/uploads/2026/01/Stroh-80-1-liter.png', 'Stroh 80% er flasken der ikke spørger om lov. Det er en liter ren østrigsk selvtillid, der kommer buldrende ind som en snestorm i juli og spørger: “ Var det her stærkt nok, eller skal jeg lige tage trøjen af også ?” Hvis du leder efter en stille og rolig rom, der kan nippes til i fred og ro… så er du gået helt, helt forkert. “Kan den bruges i cocktails?” Ja. “Kan den bruges i bagværk?” Yep. “Kan den bruges til at rense en motor?” Ja. Stroh 80% er den østrigske klassiker, der har opnået kultstatus blandt bartendere, bagere, eventyrlystne sjæle og folk, der elsker en rom, der både kan varme, flambere og muligvis starte en samtale om brandsikkerhed. Her på alle cylindre &#8211; ikke noget med vattede 60% alkohol. Den er intens, krydret, sødlig og fuld af power – som en flydende pejs, der har besluttet sig for at være alkohol. Man bruger den der hvor almindelig rom giver op. Stroh 80 er genial i cocktails, hvor du vil have varme og dybde. Den er legendarisk i bagværk, især i julekager, romkugler og alt, der har godt af et lille “hold nu fast”. Og ja – den kan også drikkes rent… hvis du er typen, der ikke blinker i modvind. Den sikrer oplevelser og stor underholdningsværdi. Det er den slags rom, der giver historier – og som regel også et par grin. Her får du en liter &#8211; så kan du holde dig varm en hel vinter. Størrelse : 1 liter Alkohol % : 80,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Appleton Estate Reserve 8 Years Jamaica Rum', 'https://spitus.dk/product/appleton-estate-12-years-old-rare-casks-jamaica-rum-i-gaveaeske-med-2-glas/', 299, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2026/01/Appleton-Estate-8.png', 'Appleton Estate Reserve 8 Years er en rom, der viser, hvorfor Jamaica er et af de mest teknisk interessante rom-områder i verden. Det er ikke bare en standard “8-års rom” – det er et blend, der bygger på jamaicansk long fermentation , pot still‑estere, tropisk modning og en fadprofil, der giver langt mere kompleksitet, end prisen egentlig antyder. Her får du en rom, hvor nørderiet faktisk giver mening i glasset. Appleton arbejder med en af de mest kontrollerede, men stadig karakterfulde fermentationsprocesser i Jamaica. Reserve 8 er et blend af pot still og column still rom, og det er netop kombinationen, der skaber balancen mellem frugt og struktur. Pot still‑delen giver estere, tunge frugtnoter og den klassiske jamaicanske “funk”. Column still‑delen giver renhed, lethed og en mere afrundet profil. Fermentationen er relativt lang (for rom), hvilket giver flere komplekse aromastoffer: bananester, ananas, overmoden frugt, let limonadeagtig syre. Appleton er kendt for en kontrolleret esterprofil – ikke så voldsom som Hampden eller Long Pond, men stadig markant nok til at være tydeligt jamaicansk. Reserve 8 er lagret fuldt tropisk , hvilket betyder: høj temperatur → hurtigere ekstraktion af træets lignin, vanillin og tanniner høj luftfugtighed → langsommere alkoholfordampning, hurtigere vandfordampning større “angel’s share” → mere koncentreret spiritus Iflg. flere eksperters undersøgelser, har et 8-årigt tropisk lagret romfad har typisk samme modningsintensitet som 18–22 år i Europa. Derfor føles Appleton 8 langt mere moden, end tallet antyder. Appleton bruger primært ex-bourbonfade af amerikansk hvideg. Det giver: vanilje (vanillin) kokos og let smørfedme (lactoner) karamel og brændt sukker (fra fadets toast/char) let krydderi og tannin (fra lignin og hemicellulose) Over 8 år i tropisk klima udvikler rommen en tydelig note af appelsinskal, tørret frugt og egetræ – en signatur for Appleton. Næsen er et studie i balanceret jamaicansk rom: appelsinskal og kandiseret citrus, banan, ananas og let tropisk frugt. Karamel, vanilje og brunt sukker. Let funk – men mere elegant end “høj-ester” destillerier. Tørret egetræ og en snert af krydderi. Det er en duftprofil, der er kompleks uden at være ekstrem. På tungen er Appleton 8 både fyldig og tør – en sjælden kombination i romverdenen. Du får citrus og tropisk frugt, karamel, honning og vanilje. Let funk fra pot still‑delen og tørret egetræ samt mild tannin. En tør, krydret finish, der er mere whisky‑agtig end mange rom. Det er en rom, der både fungerer rent og i cocktails, fordi den har både sødme og struktur. Appleton 8 viser jamaicansk esterprofil uden at være ekstrem. Den er tropisk lagret, hvilket giver dybde og modenhed og er teknisk velkomponeret: pot + column, bourbonfade, lang gæring. Appleton 8 er kort sagt rommen, der viser, at Jamaica ikke kun handler om eksplosiv funk – det kan også være elegant, struktureret og teknisk imponerende. En af de mest pris‑til‑kvalitet‑stærke rom i kategorien. Størrelse : 70cl Alkohol % : 43,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Appleton Estate 12 Years Old Rare Casks Jamaica Rum i gaveæske med 2 glas', 'https://spitus.dk/product/appleton-estate-12-years-old-rare-casks-jamaica-rum-i-gaveaeske-med-2-glas-2/', 449, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2026/01/TAppleton-Estate-12-prs-i-gaveaeske-med-2-glas.png', 'Historien om Appleton Estate Jamaica Rum begynder for over 270 år siden i et unikt, mystisk sted kendt som Nassau Valley. Dette sted er kendetegnet ved et særegent landskab med kegleformede kalkstensformationer, huler og underjordiske vandkilder. Det særlige terræn fungerer som et naturligt filter for regnen, hvilket giver krystalklart vand og giver sukkerrørsplanterne i denne dalregion en unik smagsprofil. Appleton Estate er dybt forankret i jamaicansk tradition, hvor folkets særlige ånd ikke blot former rommen, men frem for alt definerer virksomhedens identitet. Af denne grund er Appleton Estate-firmaets logo en kombination af fem ikoniske jamaicanske symboler, der fortæller en historie om passion, dedikation og livsglæde. Appleton Estate Rare Blend 12 Year Old er lavet på melasse, destilleret på både gamle kobberpot- og kolonnestills og lagret minimum 12 år på amerikanske egetræsfade. 12 års lagring i Jamaicas tropiske klima er ret meget, og svarer til en del flere år under mildere temperaturer. Appleton Estate 12 Years Old er en af de romme, der ikke behøver at forklare sig. Den er jamaicansk, den er lagret i tolv år, og den smager præcis så godt, som du håber. Det er en rom, der er lavet med tålmodighed og håndværk – ikke med hastværk og held. Og når du får den i en gaveæske med to glas, så er det næsten som om Appleton siger: “Du må gerne dele… men du behøver ikke.” Duften er varm og dyb, uden at være tung. Der er karamel, egetræ og en lille smule krydret sødme, der gør dig nysgerrig uden at overdøve noget. Det er en rom, der dufter af kvalitet, ikke af parfumeret overkompensation. Den første slurk bekræfter det hele: blød, afrundet og med en kompleksitet, der ikke kræver, at du sidder med et notatark og nikker alvorligt. Den er bare god – på den der rolige, selvsikre måde. Smagen balancerer mellem sødme og tørhed, som om nogen har brugt lang tid på at finde det helt rigtige punkt midt imellem. Der er mørk karamel, småkager, en smule appelsinskal, lidt krydderi og en cremet finish, der bliver hængende længe nok til, at du overvejer, om du skal hælde en lille smule mere op. Gaveæsken med de to glas gør det hele endnu bedre. Det er ikke bare en “her, tag en flaske”-gave. Det er en gave, der signalerer omtanke. En gave, der ser godt ud. En gave, der får modtageren til at tænke, at du faktisk har styr på tingene. Og hvis du køber den til dig selv? Så er det bare god smag. Ingen grund til at forklare sig. Appleton Estate 12 Rare Casks er en rom, der fungerer lige så godt alene som i selskab. Den er elegant uden at være snobbet, kompleks uden at være kompliceret og luksuriøs uden at være prætentiøs. Det er en rom, der leverer kvalitet uden at gøre et stort nummer ud af det – og det er præcis derfor, den er så nem at holde af. Størrelse : 70cl Alkohol % : 43,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura 1824 12 Year Premium Caribbean Rum', 'https://spitus.dk/product/angostura-1824-12-year-premium-caribbean-rum/', 429, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/01/Angostura-1824.png', 'Angostura 1824 12 Year Premium Caribbean Rum er en enestående rom, der afspejler det høje ambitionsniveau på det anerkendte Angostura-destilleri. Destilleriet er kendt for deres aromatiske bitters, men producerer (heldigvis) også et bredt udvalg af højkvalitetsrom, respekteret for deres fylde, balance og dybe smagsprofil. Denne Angostura 1824 er et fremragende blend af 3 forskellige rom der har lagret mellem 5 og 17 år. Fadene er håndplukket, og der modnes i brændte amerikanske eks-bourbon fade Når du hælder den i glasset, møder du en duft, der er varm og rund. Der er karamel, vanilje og en dyb sødme, der føles som en lille pause fra verden. Ikke noget overdrevet, ikke noget der forsøger at imponere dig – bare en behagelig, velafbalanceret aroma, der gør dig nysgerrig på, hvad der kommer næste gang. Den første slurk er silkeblød &#8211; næsten sensuel med noter af bananer og vanilje. Karamellen ligger som en varm base, mens de mørke frugter dukker op med en rolig selvsikkerhed. Der er en fornemmelse af egetræ, der giver struktur, men uden at blive bitter eller tung. Det hele er afstemt, som om nogen har brugt lang tid på at finde den helt rigtige balance mellem sødme, krydderi og varme. Og det har de jo også. Angostura 1824 har vundet så meget guld, at selv OL bliver lidt misundelig. Bl.a.: Dobbeltguld ved San Francisco World Spirits Competition i 2015. Mellem 2010 og 2018 hentede Angostura 1824 i alt 35 medaljer i prestigefyldte konkurrencer, herunder World Rum Awards, Rum Master Awards, World Spirits Awards, International Wine and Spirit Competition og mange flere. Der produceres 5000 kasser årligt &#8211; og dem er der ingen problemer med at få afsat. I gaverør. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura No. 1 Cask Collection First Fill Oloroso Sherry Cask Premium Rum', 'https://spitus.dk/product/angostura-no-1-cask-collection-first-fill-oloroso-sherry-cask-premium-rum/', 699, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/01/Angostura-No.-1.png', 'I gaverør. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura 1787 15 Years Old Super Premium Rum', 'https://spitus.dk/product/angostura-1787-15-years-old-super-premium-rum/', 599, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/01/Angostura-1787.png', 'Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Angostura Dark Rum 7 Years Old', 'https://spitus.dk/product/angostura-dark-rum-7-years-old/', 229, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2026/01/Angostura-Dark-Rum-7-Years.png', 'Angostura blev grundlagt i hjertet af Trinidad og Tobago for næsten to århundreder siden. Oprindeligt startede det som et apotek, hvor der blev lavet bitterstoffer, men snart opdagede man potentialet i rom. Passionen for håndværk og tradition er stadig mærkbar i hver flaske Angostura. Mærket forbliver tro mod sit arv og bruger kun de bedste ingredienser, hvilket gør, at de gang på gang skaber fremragende rom. Angostura Dark 7 Years produceres af højkvalitets sukkerrørsmelasse. Gæringsprocessen giver rommen dens unikke karakter. Derefter lagres rommen i syv år på egetræsfade, hvilket sikrer den fyldige smag og aromaer. Hvis du leder efter en rom, der både er seriøs, smooth og fuld af karakter, så er Angostura Dark Rum 7 Years Old meget muligt flasken, du mangler. Det her er ikke en rom, der er blevet smidt sammen i hast. Den har taget sig god tid. Syv år, faktisk. Syv år på fade i Trinidads varme klima, hvor den langsomt har udviklet sig til en mørk, dyb og uimodståelig lækker sag. Angostura er mest kendt for deres bitters, men deres rom? Det er her, de virkelig viser, hvad de kan. 7‑års udgaven er som en velklædt gentleman, der både kan fortælle gode historier og blande en cocktail, uden at det bliver prætentiøst. Den er fyldig, aromatisk og så afrundet, at du næsten får lyst til at give den et kram. Du får karamel og brun farin, mørk chokolade og ristede krydderier. Et strejf af tropisk frugt og en varm, rund finish, der bliver hængende længe nok til, at du overvejer at tage en slurk mere (og det gør du jo nok). Det er en rom, der både fungerer rent, over is og i cocktails. Den er kraftig nok til at give en Dark ’n’ Stormy ryggrad, men blød nok til at nydes helt uden selskab. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Professor Cornelius Rumbullion! Navy-Strength Rom', 'https://spitus.dk/product/professor-cornelius-rumbullion-navy-strength-rom/', 479, true, 70, 57, 'https://spitus.dk/wp-content/uploads/2020/12/professor-cornelius-rumbullion-navy-strength.jpg', 'Dette er Navy Strength udgaven af den almindelige Rumbulion!-rom. Det betyder bl.a. 57,0% alkohol i stedet for 42,6% alkohol. Der er tale om et blend af forskellige caribiske mørke rom, hvor der er tilført ekstra krydderier; primært vanilje fra Madagaskar, kanel, nelliker, appelsinskaller og en smule kardemomme. Farven er mørkt rav, og i næsen får du herlig, sød rom med vanilje, appelsiner og en anelse nellike. I munden er den cremet og fylder munden godt. Der er sød vanilje, honning, appelsiner og ristet kanel. I finishen er der chokolade og modne blommer, samt vanilje og fin kompleksitet. Den højere alkohol i denne version betyder, at der er mere smæk på det hele her. Den er mere intens, mere varm men stadig forrygende! Det er jo en sød rom, og trods den høje alkoholstyrke, vil den tiltage langt de fleste. Som alle fine spiritusser i professor Cornelius Ampleforths arsenal, er hver flaske pakket ind i plisseret brunt papir, viklet med sejlgarn og forseglet med sort voks. Størrelse : 70 cl Alkohol % : 57,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Family Reserve 1838', 'https://spitus.dk/product/a-h-riise-family-reserve-solera-1838/', 459, false, 70, 42, 'https://spitus.dk/wp-content/uploads/2020/12/a.h.riise-family-reserveI.jpg', 'Denne luksus-udgivelse var egentlig tiltænkt og forbeholdt efterkommerne af A.H. Riise, men nu er det besluttet at frigive 3000 flasker hvert år. Der er tale om en håndblended rombaseret spiriyus af noget af det bedste og ældste fra A. H. Riise, og den er at betragte som en storebror til den almindelige, og kendte XO-variant. Du får solbær, mango og vanilje, i den sædvanlige, søde A.H. Riise stil. I eftersmagen også en del krydderi med kanel og kardemomme. Nærmest cremet i strukturen. Fløjlsblød og delikat. Er du til spiritus i den søde stil, må du ikke gå udenom denne! A.H Riise Family Reserve 1838 leveres i en flot gaveæske. Alkohol % : 42,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Royal Danish Navy The Original', 'https://spitus.dk/product/old-st-croix-royal-danish-navy-the-original/', 399, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/12/croix-danish-navy-gb.png', 'Old St. Croix Royal Danish Navy 40 % er blended af flere forskellige og op til 20 år gamle romdestillater fra Caribien. Efterfølgende bliver den destilleret til den rammer 85 % i alkoholstyrke. Det sker ved den traditionelle pot still-destillering, der giver den et højt indhold af estere og kraftig duft. Først til sidst vandes blended ned til lettere drikkelige 40 %, inden der tappes på de eksklusive flasker. Når man kalder sin spiritus for The Original , så er det ikke bare for sjov. Old St. Croix Royal Danish Navy The Original er selve fundamentet – den klassiske, den ikoniske, det produkt, der har været med til at skrive historien. Den er som en fanfare i flydende form: kraftfuld, krydret og med en pondus, der får dig til at rette ryggen og sige: “Skål – for kongen og flåden!” Duften er som at åbne en skattekiste på en caribisk ø. Noter af cedertræ, vanilje, karamel og krydderier vælter frem, blandet med et strejf af ristet egetræ. Det er en bouquet, der både lover sødme og styrke – som en sømand, der kan synge både vuggevise og kampsang. Smagen er fyldig, krydret og med en robust karakter, der matcher navnet. Først kommer den bløde sødme med kandiserede æbler, appelsin, kokos og karamel, så krydderierne, og til sidst en fed eftersmag, der hænger ved længere end en god sømandsanekdote. Det er ikke bare god dram – det er en oplevelse, der kræver, at du tager dig tid til at nyde hvert eneste lag. Old St. Croix Royal Danish Navy The Original er en hyldest til Danmarks stolte søfartshistorie, til eventyrlyst og til krydderiernes magi. Den er til dig, der vil have mere end bare spiritus i glasset. Den er til dig, der vil have historier og en snert af havets rå kraft. En dram med kongelig ballast og sømandsblod i årerne. Vinder af flere internationale priser. Flot flaske og tilhørende gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Danish Navy Frigate Jylland', 'https://spitus.dk/product/old-st-croix-danish-navy-frigate-jylland/', 439, true, 70, 45, 'https://spitus.dk/wp-content/uploads/2025/10/old-st.-croix-frigate.png', 'Fregatten Jylland er verdens længste træskib, og har tidligere bl.a. fungeret som dansk kongeskib. Alene i årene 1871-1887 var skibet på fem togter til Vestindien for at repræsentere de danske interesser. Så dette danske klenodie af et skib, har stolte og tætte historiske bånd til de tidligere Dansk Vestindiske Øer. Når man navngiver en spiritus efter Fregatten Jylland, så er det ikke for sjov. Vi taler om et af Danmarks stolte maritime symboler – og nu også en flaske, der kan få selv den mest landfaste dansker til at føle sig som kaptajn på åbent hav. Old St. Croix Danish Navy Frigate Jylland er en hyldest til sømandsmod, tradition og den slags eventyr, der smager af saltvand og krydderi. Fregatten ligger som bekendt nu i Ebeltoft, og for hver solgt flaske af denne herlige drik, doneres der et beløb til bevarelsen. Old St. Croix Royal Danish Navy Fregatten Jylland er skabt med inspiration i de originale recepter på Royal Navy Rum. Opskrifterne blev udviklet af A.H. Riise, og rommen leveret til flådens skibe, når de anløb havnen i Charlotte Amalie i det tidligere Dansk Vestindien. Selve spiritussen på 40 % er blended af flere forskellige og op til 20 år gamle romdestillater fra Caribien. Den er melassebaseret, frembragt ved langsom gæring. I næsen får du cedertræ, karamel, lakrids og appelsiner. Det er en bouquet, der får dig til at rette ryggen og sige: “Klar til afgang!”. I munden får du eksotiske krydderier, kandiserede æbler, appelsin, kokos og karamel. Meget eksotisk og elegant. Fed, olieret og lang eftersmag med abrikos og sødmefulde krydderier. Old St. Croix har ikke samme tørre stil og element som typiske engelske navy-rom. Den er markant lettere at gå til, og har noget ganske fint og sart over sig. Den kommer med historisk ballast og maritim swagger. Den er en hyldest til Danmarks stolte søfartshistorie, til eventyrlyst og til krydderiernes magi. Den er til dig, der vil have mere end bare spiritus i glasset. Den er til dig, der vil have historier, smagslag og en snert af havets rå kraft. Flot, elegant flaske med tilhørende gaveæske. Alkohol % : 45,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 12 Años Solera', 'https://spitus.dk/product/ron-quorhum-12-anos-solera/', 369, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/10/ron-quorhum-12-aars.png', 'Hvis Ron Quorhum-serien var en familie, så er 12 Años Solera den unge, energiske og charmerende lillebror, der altid formår at stjæle opmærksomheden – ikke fordi han råber højt, men fordi han bare er naturligt god . Det her er rommen, der beviser, at alder ikke altid er alt. Nogle gange handler det om attitude, håndværk og en smule caribisk selvtillid. Den er lagret efter Solera-metoden, hvilket i praksis betyder, at den har haft en flydende form for gruppeterapi med både unge og ældre rom. Solera-producenterne siger, at den unge rom optager meget af den ældre roms karakter, og samtidig giver en friskhed til det færdige produkt. Der tappes normalt på flaske et par gange årligt. &#8220;Solera&#8221; kommer af det spanske ord for gulv, nemlig &#8220;suelo&#8221;. Så når du køber en ”gulv-rom”, så vær opmærksom på, at alderen på flasken er solera-rækkens alder, og ikke et gennemsnit eller en fast/vintage årgang. Her giver det en smagsprofil, som er langt mere moden, end alderen antyder. Det er lidt som at møde en 12-årig, der taler som en professor. Ron Quorhum 12 Años Solera dufter af sukkerrørsjuice, bourbon-fade, vanilje, karamel samt abrikos, rosin og egetræ. Det er en utrolig tiltalende og afbalanceret vifte af duftnuancer. Yderst delikat næse, og den forholdsvise unge 12-års angivelse, er ingen steder at spore. I munden byder den både på en frisk åbning, men samtidig indeholder den tunge noter af karamel, vanilje og egetræ med mørk chokolade. På mange måder smager den som en blanding af agricole-rom og sød, lækker, spansk kolonne-rom. Den har styrken og kraften kendt fra agricole-rommen, og det søde og imødekommende kendt fra de fleste dominikanske kolonne-rom. Quorhum-serien er da også gæret og destilleret på den friske sukkerrørsjuice, &#8220;Guarapo&#8221;, og ikke på melasse, som 95% af alt rom ellers er gæret og destilleret på. Til forskel fra agricole-rom, er denne blanding destilleret op til 96 %, og herefter iltet og lagret på amerikansk egetræ. Dette er med til at sikre, at smagsoplevelsen ikke er tør og kradsende som en traditionel agricole-rom ofte er det. Eftersmagen er utrolig lang og kompleks for en spiritus drik i denne prisklasse. Quorhum 12 er den perfekte introduktion til serien. Den er mild nok til nybegyndere, men kompleks nok til at erfarne romnydere nikker anerkendende. Ron Quorhum 12 Años er som den charmerende onkel, der altid møder op til familiefester med en skinnende skjorte, en sødlig duft – og en historie, der starter med “Det var på Cuba i ‘72, og ender med dengang han “boede med en flamencodanser i Barcelona&#8221;. Som Mads ”Romhatten” Heitmann bl.a. skriver: ”Dette kunne godt gå hen og blive en af mine nye favoritter”. Størrelse : 70cl Alkohol % : 40,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 15 Años Solera', 'https://spitus.dk/product/ron-quorhum-15-anos-solera/', 425, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/10/ron-quorhum-15-aars.png', 'Denne 15 års minder meget om den 12-årige udgave. Den er dog en anelse mere rund, og de ældre blends kan godt fornemmes – primært i smagen, og ikke så meget i næsen eller farven. Den dufter sødt, næsten som bagværk med noter af brun farin, vanilje, karamel og et hint af abrikos. De overvejende smagsindtryk er karamel, træ og ristede nødder. Man kan fornemme den vinøse tone af sukkerrør, men det er trængt i baggrunden af smagsindtrykkene. På mange måder smager det som en blanding af agricole-rom og sød, lækker, spansk kolonne-rom. Den har styrken og kraften kendt fra agricole-rommen, og det søde og imødekommende kendt fra de fleste dominikanske kolonne-rom. Quorhum-serien er da også gæret og destilleret på den friske sukkerrørsjuice, &#8220;Guarapo&#8221;, og ikke på melasse, som 95% af alt rom ellers er gæret og destilleret på. Til forskel for agricole-rom, er denne blanding destilleret op til 96 %, og herefter iltet og lagret på amerikansk egetræ. Dette er med til at smagsoplevelsen ikke er tør og kradsende som en traditionel agricole-rom ofte er det. Lige niveauet over 12-års udgaven – som forventet! Leveres i flot gaveæske Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 23 Años Solera', 'https://spitus.dk/product/ron-quorhum-23-anos-solera/', 529, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/ron-quorhum-23.png', 'I Quorhum-serien finder du både en 12, 15, 23 og 30 års solera-udgave, og vi har hos Spitus.dk forhandlet nogle meget skarpe priser hjem på hele serien, fordi vi gerne vil tilbyde danskerne en rom som kan noget andet end de fleste andre rom. Quorhum skiller sig ud, og det kan vi godt lide! De er søde i stilen, med mellem 25 og op til 55 g sukker per liter, men der er substans og finesse. Det er i denne 23-års Quorhum, at det er mest evident, at Quorhum rom er lavet på destillater af Guarapo. Både i duft og i smag er sukkerrørene tydelige, med en anelse grønt græs og en vinøs smag af rosin og citrus. Disse naturrige og friske smagsnuancer er fint afbalanceret med en dyb smag af egetræsfad og krydderier, som kanel og nellike. En elegant og overlegen rombaseret spiritus, som man kan blive ved med at opdage nye nuancer i. Forskellen fra 12-års og 15-års udgaverne er altså ret markant, og du får virkeligt meget, meget mere af det hele i denne ældre udgave. Den er til entusiasterne, som ikke lade sig kyse af, men derimod søger og elsker det ekstraordinære, hvor munden er ved at eksplodere i et væld af forskellige noter. Nøøøøj det er godt det her! Læs her den samlede anmeldelse af Mads ”Romhatten” Heitmann: (afsløring: han er begejstret!) ”Til forskel fra de to mindre søskende, den 12- og 15-årige Quorhum-rom, er denne 23-årige solera-rom noget mere voluminøs både i duft og smag. Duften er helt klart langt tungere, tykkere og besidder super lækre elementer, som de to yngre årgange ikke på samme måde gør. De officielle duftnoter siger bl.a.: ”grønt græs”… Det ved jeg nu ikke om jeg er enig i. Den er bestemt ikke så ”frisk” som 12’eren, hvor jeg måske ville være tilbøjelig til at give den ”grønne græs”-note en tommelfinger opad. Denne rom fylder bare utrolig godt i næsen og jeg kan sidde i timer med snuden begravet i glasset. Smag Specielt i smagen træder forskellen igennem. Det er en helt anden oplevelse at drikke 23’eren frem for 12’eren og 15’eren. Smagsnoteren er mere eller mindre de samme, men i denne rom bliver disse blot forstærket med 100 %. ”Eksplosionen” af smagsnuancer, som mange taler om, er i denne rom en realitet. Hér er der tale om en rom der vil fremad – det er en sand fornøjelse at smage et produkt der lukker op for posen af sødme, kraft, styrke og en lille friskhed som jeg ikke helt kan sætte min finger på. Denne friskhed indhyllet i tyk, fed og bombastisk sødme er med til at skabe et utroligt komplekst produkt. Måske er det hér det ”grønne græs” kommer ind i billedet? Stor applaus herfra! Bedømmelse Igen bliver jeg nødt til at nævne prisen. Hvis man holder pris og kvalitet op imod hinanden er Quorhum-rom bare eminent . Det er egentlig lidt en skam, at jeg taler så meget pris og kvalitet, da jeg i virkeligheden bare burde tale om kvalitet, kvalitet, kvalitet &#8211; da det er dét det er… Denne rom er stærk og anderledes, og klart en af mine nye favoritter . Vi kommer op omkring El Dorado 21-niveau med denne flaske…og det siger ikke så lidt, da jeg er en hund efter El Dorado’s rom! Under en smagning af Ron Quorhum 23 Anõs Solera bliver der nok måske krævet lidt mere af smageren end hos fx Plantation 20th Anniversary Rum og Ron Zacapa Centenario XO Solera, som også begge er fantastiske rom. Med dét mener jeg at man som smager, skal være forberedt på et spark i munden – et smagsmæssigt spark! Rommen er ikke så ”venlig” som de to førnævnte, men til gengæld har den noget andet at byde på. Denne rom skal helt sikkert nok ”gøre nogen fortræd” derude, men det er ikke mig . Det er så afgjort en ”top-shelf”-rom og jeg er sikker på at den vil falde i rigtig god jord hos mange derude. 93 points.” Størrelse : 70cl Alkohol % : 40,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 30 Aniversario Old Vintage Rum', 'https://spitus.dk/product/ron-quorhum-30-aniversario-old-vintage-rum/', 695, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/ron-quorhum-30-ann.png', 'I Quorhum-serien finder du både en 12, 15, 23 og 30 års solera-udgave, og vi har hos Spitus.dk forhandlet nogle meget skarpe priser hjem på hele serien, fordi vi gerne vil tilbyde danskerne en dram som kan noget andet end de fleste andre i kategorien. Quorhum skiller sig ud, og det kan vi godt lide! Søde, men med karakter og finesse! Hvis du har læst vore beskrivelser af seriens 12, 15 og 23 års udgaver, ved du, at vi godt kan lide Ron Quorhums signatur med styrken og kraften kendt fra agricole-rommen og det søde og imødekommende kendt fra de fleste dominikanske kolonne-rom. Og hvis du er enige med os i, at 23-års udgaven er eminent, så er dette klart et niveau op. Som Mads ”Romhatten” Heitmann slutter sin anmeldelse fra 2013: ” Jeg er målløs. 98 points – det er nok måske verdens bedste rom til prisen, efter min mening!!!” Voluminøs duft af mørk farin, vanilje og citrusfrugt. Denne rom er indbegrebet af stor rom; blød, rund og fed. Smagen kombinerer flødekarameller og honning med appelsinskal. Læg dertil masser af egetræ, juicen fra sukkerrørene (som giver et helt vidunderligt og anderledes udtryk), ristede kaffebønner og mørkt chokolade der smelter det hele sammen. Smagsindtrykkene spiller sammen i en harmonisk kombination, hvor de hver især får lov at træde frem uden at dominere. Dette er den største, og fedeste limousine af en rom. Vi har lyst til at husstandsomdele Ron Quorhum 30 Aniversario Old Vintage Rum, for alle burde prøve, bare én gang, hvor godt det er muligt at få en rom til at smage. Læs her hele anmeldelsen af Mads ”Romhatten” Heitmann: (afsløring: han går helt amok i begejstring – det forstår vi udmærket!) ”Duft Man kunne godt have frygtet, at forskellen på Ron Quorhum 30 Aniversario og Ron Quorhum 23 Anõs Solera var lige så lille som på Ron Quorhum 15 Anõs Solera og Ron Quorhum 12 Anõs Solera, men dette er heldigvis ikke tilfældet! Det er klart en af de største duftoplevelser jeg har haft indenfor rom. Den matcher endda Legacy By Angostura og det siger ikke så lidt! Rommen har en forrygende duft af farin, vanilje, mørk chokolade, tung sødmefyldt træ og et hint citrusfrugt der lyser op midt i de tunge noter. Smag Der er ingen tvivl. Få rom besidder en volumen som Ron Quorhum 30 Aniversario. Den fylder munden op med smag som Ron Millonario XO Solera Reserva Espicial gør det. Der er stor forskel – endda meget stor forskel – på denne rom og så dens lillebror på 23 år. Den har en helt anden fylde. Denne sværvægter af en rom fusionerer smagen af fed flødekaramel og honningsødme med appelsinskal, egetræsfad og kaffe-noter. Jeg bliver helt høj af at drikke den! Bedømmelse Dette er et vanvittigt godt produkt ! Så er det sagt. Rommen kunne snildt koste mindst 900 danske kroner uden jeg ville sige at det på nogen måde var en unfair pris. Kvaliteten af denne rom finder man, efter min mening, ikke ret mange steder. Den har givetvis den længste og mest kraftige eftersmag jeg personligt har oplevet. Den er sød, og samtidig kraftig som bare fanden – og det tiltaler mig gevaldigt. Sådan en rom som denne er mere end bare langtidsholdbar i munden, da man ikke kan drikke så meget af den ad gangen. Den er simpelthen så smagsholdig og voldsom, at et glas eller to er nok til at stille éns rom-trang. Der findes masser af rom som er dejlige og som man raskvæk kan drikke en hel flaske af, og det er alt sammen fint. Dette er bare et produkt, som holder længe i barskabet – måske er det en rom i den dyre ende, men samtidig er det en rom der ganske enkelt mætter folk på en anden måde. Det er en unik rom med en helt utrolig fylde, som er lagret i 25-30 år. Jeg er målløs. 98 points – det er nok måske verdens bedste rom til prisen, efter min mening!!!” Vilde ord, og der er løbet meget rom igennem årene siden 2013, men i klassen og stilen er Ron Quorhum 30 års bare stadig en gigant. Størrelse : 70cl Alkohol % : 40,0 Leveres i en flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 30 Aniversario Old Vintage Rum (u/gaveæske)', 'https://spitus.dk/product/ron-quorhum-30-aniversario-old-vintage-rum-2/', 645, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/09/Ron-quorhum-30-aniversario-uden-gaveaeske.png', 'I Quorhum-serien finder du både en 12, 15, 23 og 30 års solera-udgave, og vi har hos Spitus.dk forhandlet nogle meget skarpe priser hjem på hele serien, fordi vi gerne vil tilbyde danskerne en rom som kan noget andet end de fleste andre rom. Quorhum skiller sig ud, og det kan vi godt lide! Hvis du har læst vore beskrivelser af seriens 12, 15 og 23 års udgaver, ved du, at vi godt kan lide Ron Quorhums signatur med styrken og kraften kendt fra agricole-rommen og det søde og imødekommende kendt fra de fleste dominikanske kolonne-rom. Og hvis du er enige med os i, at 23-års udgaven er vild, så er dette en decideret atombombe af en rom. Som Mads ”Romhatten” Heitmann slutter hans anmeldelse: ” Jeg er målløs. 98 points – det er nok måske verdens bedste rom til prisen, efter min mening!!!” Voluminøs duft af mørk farin, vanilje og citrusfrugt. Denne rom er indbegrebet af stor rom; blød, rund og fed. Smagen kombinerer flødekarameller og honning med appelsinskal. Læg dertil masser af egetræ, juicen fra sukkerrørene (som giver et helt vidunderligt og anderledes udtryk), ristede kaffebønner og mørkt chokolade der smelter det hele sammen. Smagsindtrykkene spiller sammen i en harmonisk kombination, hvor de hver især får lov at træde frem uden at dominere. Dette er den største, og fedeste limousine af en rom. Vi har lyst til at husstandsomdele Ron Quorhum 30 Aniversario Old Vintage Rum, for alle burde prøve, bare én gang, hvor godt det er muligt at få en rom til at smage. Læs her hele anmeldelsen af Mads ”Romhatten” Heitmann: (afsløring: han går helt amok i begejstring – det forstår vi udmærket!) ”Duft Man kunne godt have frygtet, at forskellen på Ron Quorhum 30 Aniversario og Ron Quorhum 23 Anõs Solera var lige så lille som på Ron Quorhum 15 Anõs Solera og Ron Quorhum 12 Anõs Solera, men dette er heldigvis ikke tilfældet! Det er klart en af de største duftoplevelser jeg har haft indenfor rom. Den matcher endda Legacy By Angostura og det siger ikke så lidt! Rommen har en forrygende duft af farin, vanilje, mørk chokolade, tung sødmefyldt træ og et hint citrusfrugt der lyser op midt i de tunge noter. Smag Der er ingen tvivl. Få rom besidder en volumen som Ron Quorhum 30 Aniversario. Den fylder munden op med smag som Ron Millonario XO Solera Reserva Espicial gør det. Der er stor forskel – endda meget stor forskel – på denne rom og så dens lillebror på 23 år. Den har en helt anden fylde. Denne sværvægter af en rom fusionerer smagen af fed flødekaramel og honningsødme med appelsinskal, egetræsfad og kaffe-noter. Jeg bliver helt høj af at drikke den! Bedømmelse Dette er et vanvittigt godt produkt ! Så er det sagt. Rommen kunne snildt koste mindst 900 danske kroner uden jeg ville sige at det på nogen måde var en unfair pris. Kvaliteten af denne rom finder man, efter min mening, ikke ret mange steder. Den har givetvis den længste og mest kraftige eftersmag jeg personligt har oplevet. Den er sød, og samtidig kraftig som bare fanden – og det tiltaler mig gevaldigt. Sådan en rom som denne er mere end bare langtidsholdbar i munden, da man ikke kan drikke så meget af den ad gangen. Den er simpelthen så smagsholdig og voldsom, at et glas eller to er nok til at stille éns rom-trang. Der findes masser af rom som er dejlige og som man raskvæk kan drikke en hel flaske af, og det er alt sammen fint. Dette er bare et produkt, som holder længe i barskabet – måske er det en rom i den dyre ende, men samtidig er det en rom der ganske enkelt mætter folk på en anden måde. Det er en unik rom med en helt utrolig fylde, som er lagret i 25-30 år. Jeg er målløs. 98 points – det er nok måske verdens bedste rom til prisen, efter min mening!!!” Vilde ord, og der er løbet meget rom igennem årene siden, men i klassen og stilen er Ron Quorhum 30 års bare en gigant. Bemærk : denne udgave leveres UDEN gaveæske. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Signature', 'https://spitus.dk/product/a-h-riise-signature/', 1375, true, 70, 43.9, 'https://spitus.dk/wp-content/uploads/2022/05/a.h.riise-signature-k.jpg', 'A.H. Riise Signature er en udgivelse, der stempler lige ind i toppen af brandets sortiment. Men det er desværre også nu en udgået variant, som A.H. Riise i deres navneskifte til St. Croix har valgt, ikke længere skal produceres. Flasken er allerede udsolgt mange steder. Lidt om flasken og indholdet: Hver udgave af A.H. Riise Signature er skabt af meget små partier rest premium-rom og resulterer i mindre end 2000 flasker Spirit drinks pr. batch. Hvert fad er nummereret, og hver flaske ligeså. Antallet af flasker varierer fra batch til batch, og indholdet og smagen vil også variere. Som små, forskellige kunstværker. Fælles for alle batches af A.H. Riise Signature er dog, at de skal være de bedste repræsentanter for A.H. Riises kendte smagsunivers af sødme, mildhed og aroma. A.H. Riise Signature er når spiritus bliver til haute couture. A.H. Riise Signature er ikke bare en lækker udgivelse. Det er A.H. Riises catwalk‑moment . Den er håndplukket, håndsamlet og håndforkælet – en luksusblend, hvor master blenderen har valgt de absolut mest ekstreme, aromatiske og sjældne fade i hele kælderen. I næsen, modne tropiske frugter, kokosnødder og karamel ledsaget af kølige myntenoter. Smagen er dyb, sød og vanvittigt kompleks med lag af karamel, vanilje, tropisk frugt, mørk sirup, krydderier og en næsten dessertvinsagtig fylde. I eftersmagen får du en sand symfoni af modne tropiske frugter og karamel. Subtile myntenoter tilføjer en fin harmoni til den lange og dybe eftersmag. Hvis du er til den søde og meget imødekommende stil fra A.H. Riise, må du ikke snyde dig selv for at opleve denne premium-udgivelse: Signature. Leveres i flot, flot karaffel i gaveæske. Alkohol %: 43,9 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Reserve Christmas Edition', 'https://spitus.dk/product/old-st-croix-xo-reserve-christmas-edition/', 499, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/10/old-st.-croix-christmas.png', 'Old St. Croix XO Reserve Christmas udgives i en begrænset mængde hvert år. Udgangspunktet for denne herlige, let-krydrede dram er ”den almindelige” XO Reserve, men for at tilføje julenoter, har den fået yderligere fadlagring på brugte PX (Pedro Ximinez) sherry-fade. Historien bag den er en blanding af klassisk St. Croix‑håndværk og en smule festlig selvtillid. XO‑basen er lagret i tropisk varme, hvor den har fået tid til at blive blød, afrundet og fuld af dybde. Derefter har man givet den et strejf af jul – ikke på den overgearede gløgg‑måde, men med en elegant, aromatisk varme, der føles som at træde ind i et rum, hvor nogen lige har bagt noget godt. Smagen er præcis det, man håber på, når man ser flasken. Først kommer den klassiske St. Croix‑karamel og vanilje, som giver en blød og rund start. Så begynder krydderierne at røre på sig – kanel, nellike, måske en anelse appelsinskal – ikke så meget at det bliver dessert, men nok til at du får den der “nu er det december”-fornemmelse. Egetræet ligger i baggrunden og holder det hele samlet, og til sidst glider den ud i en varm, rolig finish, der føles som at sidde foran et juletræ, mens sneen falder udenfor. Også selvom du godt ved, at det sandsynligvis regner. Aftappet single barrel, og påført flaske- og fadnummer samt aftapningsdato. En skøn juledrik lige i Old St. Croix (tidligere A. H. Riise) stil, som leveres i en flot gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Millonario 15 Solera Reserva Especial i gaveæske med glas', 'https://spitus.dk/product/ron-millonario-15-solera-reserva-especial-i-gaveaeske-med-glas/', 449, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/11/ron-millonario-15-yo-i-gaveaeske-med-to-glas-2.png', 'Ron Millonario 15 Solera Reserva Especial – nu med gaveæske og to glas, så du ikke skal drikke alene! Er du klar til at føle dig som en sydamerikansk sukkerbaron med hang til luksus? Så er Ron Millonario 15 Solera Reserva Especial i gaveæske med to glas lige noget for dig. Det er en oplevelse pakket ind i bast og blær. Denne peruvianske darling har ligget i solera-systemet i op til 15 år og er blevet forkælet som en VIP hele vejen. Resultatet? En sød, blød og krydret oplevelse, der smager som flydende dessert med attitude. Ron Millonario Solera Reserva Especial 15 år blev kåret til bedste premium rom ved International Rum Festival i Florida 2009, og da alle dommerne bedømte den til mere end 90 points, tog den også titlen som ”Best of Show”. Siden er det gået stærkt for destilleriet fra Peru, men Solera Reserva Especial er stadig flagskibet. En sammenligning med de første Ron Zacapa 23 års Solera er absolut ikke helt ved siden af, trods forskellige oprindelseslande. Næsen minder meget om hinanden, med mandler, brun farin, vanilje, mørk chokolade og rosiner. I munden sød, blød og rund. Masser af karamelliserede frugter, krydderier, honning og vanilje. Herlig dram i danskernes fortrukne ”spanske” stil, som du bare får lyst til at sippe mere af. Perfekt som gave til romelskeren, svigerfar, dig selv eller den ven, der altid tømmer dine flakser og aldrig tager noget med. Bemærk; gavesættet her indeholder den originale bast-flaske &#8211; som helt sikkert bliver et samlerobjekt. Og med to glas i æsken, er du allerede halvvejs til en hyggelig aften. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador Colombiana Reserva Aged Rum', 'https://spitus.dk/product/dictador-colombiana-reserva-aged-rum/', 349, true, 70, 38, 'https://spitus.dk/wp-content/uploads/2025/11/Dictador-colombian-asged-rum.png', 'Dictador – den colombianske original, der ikke bare smager godt, men også har historie, karakter og en smule oprør i flasken . Med Reserva Aged Rum får du en oplevelse, der er blød, krydret og fuld af personlighed – som en latinamerikansk gentleman med solbriller og hemmeligheder. Historien begynder i Cartagena, hvor Dictador har perfektioneret kunsten at lave udgivelser på sukkerrørshonning. Det giver en dybere, mere aromatisk base end klassisk melasse, og når den så får lov at modne i Colombias varme klima, sker der noget særligt. Tålmodighed, tid og tropisk varme gør deres arbejde, og resultatet er en oplevelse, der føles både moderne og traditionel på samme tid. Dictador er opkaldt efter Severo Arango y Ferro – en spansk skatteopkræver, der kom til Colombia i 1700-tallet og fik tilnavnet “El Dictador”. Han blev så vild med rom, at han glemte skatterne og begyndte at handle med spiritus i stedet. Og ja – det er den slags passion, du smager i hver dråbe. Denne Dictador Colombiana Reserva Aged Rum er en eksklusiv specialudgave. Aftapningen kombinerer traditionel romproduktion med en innovativ lagringsfilosofi og understreger mærkets unikke stil. Udgivelsen er lavet af melassebaseret rom modnet ved hjælp af solera-metoden og er kendetegnet ved en enestående balance mellem sødme, krydderi og struktur. Farven er mørk rav med rødlig-gyldne refleksioner. I næsen rød karamel, kaffe, tørret frugt, vanilje og et strejf af ristede nødder. Smagen er blød og fyldig med aromaer af kaffebønner, karamel, brun farin, eg og tropisk krydderi. Finishen er lang, behageligt glat med noter af kakaobønner og karamel. Med sine 38 % alkohol er den mildere end diverse cask strength-monstre , men stadig med nok power til at få dig til at bede om et glas mere. Flasken er elegant, mørk og mystisk – og med Dictadors kunstneriske branding er den oplagt til både samleren, romelskeren og den stilbevidste ven . Den pynter på hylden og performer i glasset. Ideel til fornøjelige aftener, særlige lejligheder eller som en stilfuld gave til elskere af fint spiritus med en latinamerikansk sjæl. Størrelse : 70cl Alkohol % : 38,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Brugal 1888 Gran Reserva', 'https://spitus.dk/product/brugal-1888-gran-reserva-rom/', 355, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/11/brugal-1888-gran-reserva.png', 'Ron Brugal stammer fra Den Dominikanske Republik, og blev etableret af Don Andres Brugal Montaner i 1888, i byen Puerto Plata på den nordlige del af øen. I dag er det 5. generation af familien der leder destilleriet, og denne ”Brugal 1888” er naturligvis skabt for at hylde selve etableringen af den succesfulde producent. Noget af det specielle ved Brugul rom er, at de anvender absolut førsteklasses sherryfade, som de kun har adgang til, fordi de er ejet af The Edrington Group, som også ejer Macallan Whisky (som er førende indenfor sherrylagret whisky). Brugal 1888 er en kolonnedestilleret rom, som er lagret på to slags egetræsfade: 8 års amerikanske bourbon-fade og 6 års europæiske sherry fade. Stilen er således typisk spansk, med karamel, vanilje, chokolade og sherry-noter. Smagen er først sødmefuld, men der er også en del tørhed, som bevidner den håndværksmæssige høje klasse. Chokolade og en let bitterhed går igen. Den er ikke ultra sød, som andre spansk-inspirerede rom, og sukkermålinger viser også et så lavt sukker indhold som ca. 8–12 g/L Brugal 1888 Gran Reserva er en yderst smooth og lettilgængelig rom. Den ligger sig flot på den sti, langt de fleste romdrikkere sætter så stor pris på. Det er en rom som falder i de flestes smag, og en rom som man meget gerne sidder og sipper, f.eks. i festligt lag. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bacoo 11 Y.O. i gaveæske med Tiki Mug (keramisk kop)', 'https://spitus.dk/product/bacoo-11-y-o-i-gaveaeske-med-tiki-mug-keramisk-kop/', 419, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/10/bacoo-gb-mug.png', 'Bacoo rom er en fløjlsblød bekendtskab, der stammer fra Den Dominikanske republik. Rommen er produceret på saften fra sukkerrør høstet i nærheden af destilleriet. Efter destillationsprocessen lagres rommen på brugte Bourbon fade i 11 år før den flaskes. Så Bacoo 11 Y.O. er ikke nogen nybegynder. Den har ligget og hygget sig i mange år i den Dominikanske Republik, hvor den har suget sol, fad og attitude. Resultatet er en bronzefarve rom med en meget imødekommende rund smag og aroma af chokolade, karamel, eg og vanilje. En anelse lys honning i eftersmagen efterlader en sødlig velbehag. Er du træt af kedelige gaver, flade flasker og rom, der smager som en regnvåd chartertur til Gran Canaria? Så hold fast i din palmehat – for med dette lækre gavesæt med Bacoo 11 Y.O., får du med i pakken en ægte Tiki Mug, der ligner noget Indiana Jones ville drikke af, hvis han havde smag. Den er funky, farverig og klar til at gøre dine cocktails til samtaleemner. Perfekt til: Gaven til ham, der har alt – undtagen en rom med personlighed og en krus med attitude. Din egen hjemmebar, der skriger på lidt tropisk flair og en undskyldning for at lave Mai Tais. Den spontane fest, hvor dresscode er “flipflops og dårlig dømmekraft”. En “Bacoo Mojo” – 5 cl Bacoo 11 Y.O., 2 cl limejuice, 1 cl sukkersirup, masser af is og en skive ananas. Serveres i din Tiki Mug med et blink og en strandmelodi i baggrunden. Den her gaveæske sælger som rom til en pirat med dankort! Størrelse: 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Stroh Jagertee, 1 liter', 'https://spitus.dk/product/stroh-jagertee-1-liter/', 229, true, 100, 40, 'https://spitus.dk/wp-content/uploads/2025/10/Stroh-tea-1-liter-med-skrielaag.jpg', '1 liters flydende afterski med attitude. Hvis du nogensinde har stået på en alpetop og tænkt: “Jeg kunne godt bruge noget, der smager af varme, krydderier og lidt vildskab,” så er Stroh Jagertee svaret. Denne østrigske klassiker er ikke bare en drik – det er en institution. En flydende undskyldning for at tage skistøvlerne af og hygge igennem. Jagertee er en traditionel østrigsk vinterdrik, og Stroh har perfektioneret opskriften: sort te, krydderier og en god portion romlikør. Resultatet? En kraftfuld, krydret og varmende eliksir, der smager af afterski, jagthytte og “bare én mere.” Det er smagen af Sort te og citrus, k rydderier som kanel og nellike – julestemning på flaske. Romlikør med punch – varm, sød og lidt farlig Stroh Jagertee kommer klar til brug – du skal bare blande den med varmt vand (eller nyde den rent). Den er perfekt til kolde aftener, vinterfester eller som hemmelig ingrediens i din gløgg. Sådan serverer du den: Klassisk: 1 del Jagertee, 3 dele varmt vand – og et tæppe Vintercocktail: med appelsinskiver, kanelstænger og lidt citron On the rocks? Kun hvis du har en jernmave og en snescooter En god gave til din ven, der elsker afterski og alpestemning. Til din onkel, der stadig taler om den gang i Tyrol. Eller til dig selv, fordi du fortjener en flaske, der både varmer og vækker minder. Stroh er Østrigs mest ikoniske romproducent, og Jagertee er deres vinterlige mesterværk. Flasken på 1 liter sikrer, at du har nok til både gæster og gensmag – og den ser lige så hyggelig ud, som den smager. Størrelse : 1 liter Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Matusalem Gran Reserva 23 Y.O', 'https://spitus.dk/product/matusalem-gran-reserva-23-y-o-2/', 479, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/10/matusalem-23.png', 'Matusalem Gran Reserva 23 Solera er en super premium udgivelse fra den Dominikanske Republik. Der produceres stadig den dag i dag efter familiens oprindelige og hemmelige opskrift. De ”Master Blenders”, der laver produkterne, er efterkommere af grundlæggerne og opretholder den århundrede gamle Solera-lagringsteknik. Historien bag den er næsten lige så glat som smagen. Matusalem startede i Cuba, men flyttede senere til Den Dominikanske Republik, hvor safterne i dag, som nævnt, modnes i solera‑systemet. Det betyder, at yngre og ældre romme blandes i et system, der er lige så kompliceret som en familiefest, men langt mere harmonisk. 23‑års udgaven er husets mest polerede udtryk – en dram, der har fået tid, varme og masser af kærlighed. Smagen er præcis så luksuriøs, som flasken antyder. Først kommer den dybe karamel og den bløde vanilje, som lægger en silkeblød bund. Derefter folder de mørke frugter sig ud – rosiner, svesker og en anelse kandiseret appelsin, der giver rommen en næsten dessertlignende fylde. Egetræet ligger i baggrunden og giver struktur, mens en let krydret varme holder det hele fra at blive for sødt. Det hele slutter med en lang, glat finish, der føles som at glide ned i en lænestol, du ikke har lyst til at rejse dig fra. Den lukker med en snert af noget floral som magnolia og mandelblomster, med en bund af karamel med toner af mango, hvid chokolade og mandler. I forhold til 15-års udgaven, er den klar mere voluminøs, men også mindre sprittet. Mads ”Romhatten” Heitmann: ”Endnu engang har Matusalem æstetikken i højsædet, både i smag, men i særdeleshed også i den fysiske indpakning. Ligesom med Matusalem 15 års er 23&#8217;erens flaske noget for sig og gør helt igennem smagsoplevelsen til en af de store. Yderst delikat rom!” Den er blød nok til at alle kan lide den, men kompleks nok til at nørderne nikker anerkendende. Matusalem Gran Reserva 23 Y.O. er kort sagt en dram, der smager som en god beslutning. Og det er ikke alle beslutninger, man kan sige det om. Størrelse : 70cl Alkohol % : 40,0 Leveres i flot gaveæske &#8211; NYT design');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Kraken Roast Coffee, 1 liter', 'https://spitus.dk/product/kraken-roast-coffee-1-liter/', 299, true, 100, 40, 'https://spitus.dk/wp-content/uploads/2025/10/kraken-coffee.jpg', 'Kraken Roast Coffee er en fusion af den klassiske Kraken Black Spiced Rum og intens Arabica-kaffe. Resultatet? En uimodståelig blanding af mørk elixir, ristede kaffebønner, vanilje, kanel og et strejf af muskatnød. Den smager som en pirat, der har fået baristauddannelse – den er blød, men med bid og lidt farlig. Flasken er selvfølgelig lige så mørk og mystisk som indholdet. Med sin ikoniske blæksprutte og sorte design ligner den noget, der burde ligge i en skattekiste – eller stå i din hjemmebar, hvis du har god smag og hang til eventyr. Kraken Roast Coffee er perfekt til dig, der elsker både kaffe og rom – og ikke vil vælge. Den gør sig fantastisk i en Espresso Rum-tini, som en twist på en White Russian, eller bare rent over is, når du vil forkæle dig selv med noget, der smager af nat og nydelse. Den er også oplagt som gave til den ven, der altid siger “jeg elsker kaffe og rom” – nu kan de få begge dele i én flaske. Og lad os være ærlige: det er lidt sjovere end endnu en pose bønner eller en flaske standardrom. Alkohol %: 40,0 Størrelse : 1 liter');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Reserve 1888 Copenhagen', 'https://spitus.dk/product/old-st-croix-xo-reserve-1888-copenhagen/', 359, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/12/croix-cpoenhagen-1888-GB.png', 'Indholdet i Old St. Croix XO Reserve 1888 Copenhagen er et nøje udvalgt premium-blend af helt op til 21 år gammel rombaseret spiritus fra Vestindien og Centralamerika, og ingen at de benyttede rom til denne spirit-drink er yngre end 7 år. Historien bag flasken lyder, at København i 1888, var vært for den store Nordiske Industri-, Landbrugs &amp; Kunstudstilling, og A.H. Riise (som nu hedder Old St. Croix) deltog på udstillingen med sin Vestindiske rom, hvor den vandt en førsteplads. Denne Old St. Croix XO 1888 Copenhagen Reserve er genskabt som en hyldest, og er efter den oprindelige opskrift fra dengang. 1888 – et årstal, der emmer af historie. København summede af liv, og verden var i forandring. Og nu kan du få en flaske, der hylder netop den tid: Old St. Croix XO Reserve 1888 Copenhagen . Det er en tidsmaskine på flaske, der tager dig med tilbage til en æra, hvor elegance og håndværk var i centrum. Duften er som at gå en tur gennem en københavnsk gade anno 1888, hvor bageren lige har trukket karamel ud af ovnen, og tobaksforretningen sender krydrede noter ud i luften. Vanilje, tørret frugt og et strejf af egetræ mødes i en bouquet, der både er varm og sofistikeret. Smagen er rund, fyldig og med lag på lag af oplevelser. Først den bløde sødme, så krydderierne, og til sidst en lang, elegant eftersmag, der hænger ved som en god historie fortalt over et glas. Det er den slags rom, der får dig til at læne dig tilbage og tænke: “Sådan smager tradition – med et twist af eventyr.” Flasken er designet med samme pondus som navnet – tung, elegant og med et historisk udtryk. Perfekt til at imponere gæster, til at give som gave, eller til at minde dig selv om, at du har god smag og sans for historie. Old St. Croix XO Reserve 1888 Copenhagen er ikke bare en forbandet god dram. Den er en hyldest til tradition, til forbindelsen mellem Danmark og Caribien, og til den slags håndværk, der aldrig går af mode. Den er til dig, der vil have mere end bare spiritus i glasset. Den er til dig, der vil have historier, smagslag og en snert af historisk elegance. Old St. Croix XO 1888 Copenhagen leveres i en flot gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bacardi Carta Blanca, 10 x 5cl', 'https://spitus.dk/product/bacardi-carta-blanca-12-x-5cl/', 199, true, 50, 37.5, 'https://spitus.dk/wp-content/uploads/2026/02/bacardi-10-x-5cl.png', 'Små flasker. Store fester. Masser af mojito-muligheder. Er du klar til at skrue op for tropestemningen – uden at tømme barskabet eller bondegården? Så sig “hola” til Bacardi Carta Blanca i praktisk 10-pak med 5 cl flasker . Det er som at få en miniferie til Caribien – 10 gange i træk. Her får du den klassiske, krystalklare rom, som har været festen tro i over 150 år. Bacardi Carta Blanca er blød, let og alsidig – og i disse små flasker er den klar til alt fra spontane cocktails til shots med stil. Det er rommen, der kan både mojito og piña colada – og gør det med et smil. Hvad får du? 10 x 5 cl Bacardi Carta Blanca – perfekt doseret til drinks, smagning eller festlige indslag. Den ikoniske hvide rom med noter af vanilje, mandel og tropisk lethed. En pakke, der passer i tasken, i gavekurven og i enhver planlagt (eller uplanlagt) fest. Perfekt til: Gaveidéen til ham, der elsker rom – men også elsker at dele. Velkomstdrinks til bryllup, firmafest eller sommerfest med stil. “Smag på verden”-aftener, hvor du vil imponere med klassikere i mini-format. Dig selv, når du vil have lidt luksus i lommestørrelse. En “Mini Mojito Bar” – mynte, lime, sukker, danskvand og en 5 cl flaske Bacardi. Gæsterne mixer selv, og du ligner en cocktailkonge uden at løfte en shaker. Bacardi blev grundlagt i 1862 i Cuba – og har siden da været synonym med sol, samba og seriøst gode cocktails. Med denne 10-pak får du en smagsprøve på historien – i handy format. Klar til at gøre hver dag lidt mere caribisk? Bacardi Carta Blanca 10 x 5 cl sælger som mojitos på en dansk sommerdag med over 20 grader og fri bar. Alkohol % : 37,5 Størrelse : 10 x 5cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Reserve 175 Years Anniversary', 'https://spitus.dk/product/old-st-croix-xo-reserve-175-years-anniversary/', 425, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2025/10/old-st.-croix-175-anni.png', 'Old St. Croix (tidligere A.H. Riise) XO 175th Anniversary blev fremstillet første gang i 2013 &#8211; præcis 175 år efter A.H. Riise for første gang slog dørene op til sit apotek på St. Thomas. Der er tale om en særlig jubilæumsmodel, hvor hovedblended er lagret i 21 år, men tilsat yngre destillater for at øge spændstigheden. 175 Years Anniversary er en hyldest til fortiden, men også en toast til fremtiden – en rom, der kombinerer tradition med innovation. Old St. Croix XO 175th Anniversary er lagret ved lave temperaturer og høj luftfugtighed i dybe mørke kældre, hvor den har haft de bedste betingelser for en god spirit drink. Det specielle ved denne jubilæums-drik er, at den efterlagres på PX- og Oloroso-sherryfade. Netop disse fade giver drikken sit udtryk af mørk, sødmefuld sherry. I næsen og ganen er sherry-noterne tydelige, og du får dertil fyldig vanilje og karamel. Skovbær og figner kommer tydeligst frem i den lange, cremede eftersmag. Som altid med Old St. Croix er der tale om en meget sød spirit drink. En let tilgængelig stil som danskerne i den grad har taget til sig. Leveres i flot gaveæske. Alkohol % : 42,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Family Reserve', 'https://spitus.dk/product/old-st-croix-family-reserve/', 459, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2025/10/old-st-croix-family-reserve.png', 'Old St. Croix (tidligere A.H. Riise) Family Reserve er en luksus-udgivelse, som i tidernes morgen egentlig var tiltænkt og forbeholdt efterkommerne af A.H. Riise, men nu er det besluttet, at der fremadrettet bliver frigivet 3000 flasker hvert år. Old St. Croix-serien bygger på forbindelsen mellem Danmark og De Amerikanske Jomfruøer, og Family Reserve er den mest “hyggelige” i familien. Den er skabt af udvalgte fade, der har fået lov at modne i Caribiens varme klima, indtil de var klar til at blive blandet til en rom, der både er blød, dyb og charmerende. Der er tale om en håndblend af noget af det bedste og ældste fra Old St. Croix, og den er at betragte som en storebror til de almindelige, og kendte XO-varianter. Smagen er lige så imødekommende som navnet antyder. Først kommer den varme karamel og brun farin, som giver en blød start. Så dukker de tørrede frugter op – rosiner, dadler og en lille smule tropisk sødme, der minder dig om, hvor den kommer fra. Vaniljen og egetræet ligger som et roligt fundament, og til sidst glider den ud i en harmonisk finish, der føles som et langt, tilfreds suk. Old St. Croix Family Reserve er den slags flasker, der føles som at træde ind i en stue, hvor nogen allerede har tændt stearinlysene og sat en god plade på. Den har en ro over sig, en modenhed, der ikke behøver at prale. Leveres i en flot gaveæske. Alkohol % : 42,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Reserve Port Cask', 'https://spitus.dk/product/old-st-croix-xo-reserve-port-cask/', 435, true, 70, 45, 'https://spitus.dk/wp-content/uploads/2025/12/croix-port-cask-gb.png', 'Old ST. Croix XO Reserve Port Casker sammensat af nogle af de bedste og ældste fade fra Vestindien og Centralamerika som destilleriet råder over. Faktisk går der helt op mod 15 forskellige destillater til denne rombaserede spiritus. Og med en gennemsnitsalder på 20 år er det ikke ligefrem en vårhare. Alle destillater er nøje udvalg af A.H. Riise’s masterblender og skaber en spiritus udover det sædvanlige. Den nænsomme lagring og sammensætning gør i sig selv Old St. Croix X.O. Port Cask til noget særligt. Men for at gøre oplevelsen endnu større, er den efterlagret på udsøgte fade, der tidligere har været hjem for klassisk portvin. Den får nemlig en slut-lagring på mindst seks måneder på portvinsfade fra det kendte hus Cálem. Det giver en unik fadfinish, der gør denne udgivelse til noget særligt, med stor kompleksitet og fylde. Hvert fad er specielt udvalgt og håndaftappet enkeltvis. Produktionstallet er begrænset, og alle flaskerne er desuden mærket med et individuelt flaske- og fadnummer samt aftapningsdato. Når du åbner flasken, mødes du af en bouquet, der er som en kærlighedserklæring fra både Caribien og Douro-dalen. Tænk tørret frugt, modne bær, et strejf af chokolade og den der varme, vinøse sødme, som kun portvin kan levere. Det er som at få en krammer af både solen og en vinbonde på samme tid. XO Reserve betyder, at vi er i den modne afdeling. Ingen ungdommelige kanonslag – men en dram, der har fundet sin ro og besluttet sig for at blive voksen på den lækre måde. Port Cask-finishen giver den et ekstra lag af kompleksitet, som gør, at du næsten får lyst til at tage noter, mens du smager. Men bare rolig – du behøver ikke være sommelier for at nyde den. Smagen? Rund, fyldig og med en sødme, der balancerer perfekt med krydderier og egetræ. Den starter blødt, bygger op med bær og chokolade, og slutter med en lang, elegant eftersmag, der hænger ved som en god punchline. Det er den slags oplevelser, der får dig til at tænke: “Hvorfor drikker jeg egentlig andet?” Flasken? Den ser ud som noget, du ville finde i en hemmelig kælder under et portugisisk slot – tung, elegant. Perfekt til gave, til gæster eller til dig selv, når du vil forkæle din indre livsnyder. Old St. Croix XO Reserve Port Cask er ikke bare en flaske spiritus – det er en rejse mellem kontinenter, en fusion af tradition og tropisk livsglæde. Den er til dig, der vil have mere end bare spiritus i glasset. Den er til dig, der vil have historier, smagslag og et strejf af luksus. I flot gaveæske. Størrelse: 70 cl Alkohol % : 45,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Royal Danish Navy Frogman Conventus Ranae 60%', 'https://spitus.dk/product/old-st-croix-royal-danish-navy-frogman-60/', 485, true, 70, 60, 'https://spitus.dk/wp-content/uploads/2025/09/Old-st.-corix-frogman.png', 'Old St. Croix Royal Danish Navy Frogman Conventus Ranae er lavet som en hyldest til det danske Frømandskorps. The Frogman Association Conventus Ranae blev oprettet i 1957 (inspireret af lignende foreninger i den Britiske Specialbådtjeneste (SBS), det Amerikanske Undervandsnedrivningshold (UDT) og Navy SEALS). Efter afsluttet tjeneste kan frømændene melde sig ind i ”Conventus Ranae” (latinsk betegnelse for ”en samling af frøer”) – frømændenes formelle forening, der har til formål at styrke båndet mellem aktive- og pensionerede frømænd. I de senere år har Old St. Croix samarbejdet med Conventus Ranae, hvilket blandt andet førte til lanceringen af den berømte Royal Danish Navy Frogman Rum 58%. I 2017 kom Royal Danish Navy Frogman 60% for at markere Frømandskorpsets 60-års jubilæum. Der er tale om et ”hand-blend” i små partier af flere rom, der er op til 20 år gamle. Den destilleres i en traditionel “Pot Still” og kommer fra karet med en alkoholstyrke på 65 %. Den er ikke koldfiltreret eller tilsat karamel. Den har noter af kaffe, lakrids, brændt karamelmelasse, krydderier og cedertræ, men der er også en eksotisk og elegant smag af Sevilla appelsiner og bergamot frugt. Finishen er lang og er i perfekt balance mellem det sødlige og varmen fra de 60% alkohol. Du er ikke i tvivl om den høje alkoholprocent, men hold da op: de er flot pakket ind! Det her er. Old. St. Croix&#8217;s svar på en kold dukkert i Øresund kl. 05:00 om morgenen: Vågn-op, mand dig op, og nyd det. Den står der som en elitesoldat i paradeuniform, og egentlig havde vi ikke forventet, at noget så potent kunne være så velopdragent. Leveres i flot gaveæske Størrelse : 70cl Alkohol % : 60,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('The Rum Factory 8 Y.O. Oloroso Cask', 'https://spitus.dk/product/the-rum-factory-8-y-o-oloroso-cask/', 475, true, 70, 45, 'https://spitus.dk/wp-content/uploads/2025/10/The-Rum-factory-oloroso-cask.png', 'Forestil dig en rom, der har ligget og hygget sig i otte år under tropesolen – og derefter fået en ekstra tur i Europa i et spansk Oloroso-sherryfad. Det er ikke bare lagring. Det er efteruddannelse. Og resultatet? En rom med både caribisk charme og europæisk elegance. The Rum Factory lyder som noget, der burde ligge i en gammel hangar med duft af melasse og mahogni – og det føles faktisk sådan. Vi har fat i et udvalgt blend af rom fra Barbados, som gennemsnitligt er lagret i otte år på gamle bourbonfade og har fået sin finish i Oloroso-fade fra Spanien, hvilket giver en smagsprofil, der balancerer sødme, krydderi og et strejf af nøddeagtig finesse. Farven er nærmest rustik bronze med små gyldne skær, mens aromaen, der stiger op fra glasset, bugner med smeltet sukker, vanilje, bittermandler og frugt. Mørk chokolade, urter, tørrede rosiner og intense sherrynoter fylder hele munden, inden eftersmagen tager over med en lang og varmende finish med allehånde, salvie og spidskommen. En rom med ryggrad og raffinement. Det er en rom, der både kan nydes rent og bruges i cocktails – men lad os være ærlige: den fortjener sit eget glas, sin egen aften og måske lidt baggrundsmusik fra en cubansk guitar. Flasken er elegant og industriel på den fede måde – som en rom, der både kan stå i barskabet og på en hylde med designobjekter. The Rum Factory er kendt for sin kompromisløse tilgang til kvalitet – og 8-årsudgaven med Oloroso-finish er ingen undtagelse. 92 Points i den seriøse Falstaff Tasting. I gaveæske Alkohol % : 45,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Flor De Cana 7 Y.O. Grand Reserve Rum', 'https://spitus.dk/product/flor-de-cana-7-y-o-grand-reserve-rum/', 219, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/10/Flor-De-Cana-7-Y.O.-Grand-Reserve.png', 'Ron Flor de Caña Gran Reserva 7 År fremstilles på en fuldstændig bæredygtig måde lige ved siden af San Cristobal-vulkanen, den højeste og mest aktive i Nicaragua. Faktisk henter Ron Flor de Caña Gran Reserva 7 Años alle sine ressourcer fra denne kolos: den vulkanske jord (som er yderst frugtbar på grund af den konstant udspyrede aske), mineralrigt vand og klimaet (med høje temperaturer). Alt dette kombineres og skaber den perfekte sammensætning for fremstilling og modning af denne herlige fætter. En ekstraordinært blød rom, som er lagret i syv år i hvide egetræsfade. Den har en dyb mahognifarve, og byder på duftnoter af ristet kokosnød, vanilje, karamel og undertoner og frugter såsom figner. Som en dessert, du gerne vil drikke. Smagspaletten afslører udsøgte nuancer af honning, kaffe og chokolade. Blød og behaglig finish, og fremstillet uden tilsætning af kunstige ingredienser eller ekstra sukker. Den er perfekt til cocktails, men også så smooth, at du sagtens kan nyde den rent – især hvis du har en hængekøje og lidt baggrundsmusik. Prøv den i Mojitos med dybde, Cuba Libres med karakter, Espresso Martini med rom-twist, eller bare on the rocks, hvis du vil holde det simpelt og lækkert. Flor de Caña er et af verdens mest bæredygtige rombrands – CO₂-neutral og Fair Trade-certificeret. Så du kan skåle med god samvittighed og lidt ekstra stil. Flor de Caña bruger i ngen dosering (sukker) , ingen kunstige smagsstoffer og ingen farvestoffer. En rom med vulkansk temperament og caribisk charme Guld ved IWSC Guld ved San Francisco World Spirits Competition Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Plantation XO 20th Anniversary i gaveæske m/2 glas', 'https://spitus.dk/product/plantation-xo-20th-anniversary-i-gaveaeske-m-2-glas/', 489, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/09/Plantation-xo-gb-k.png', 'Plantation XO 20th Anniversary i flot gaveæske med to signatur glas. Rommen er en blanding af flere meget gamle rom fra Barbados. Først modnet lokalt i Bourbon-fade i adskillige år, for derefter at blive hældt på små, franske limosinefade, der førhen har været brugt til lagring af Pierre Ferrand Fine Grande Champagne Cognac. Denne lagring foregår på Château de Bonbonnet i den franske region Charente, hvor den bringes ned i de kølige kældre og modner yderligere. Rommen er således lagret på flere forskellige fadtyper, deriblandt de fineste cognacfade, som er Plantations signatur, men der bruges også helt nye fade af amerikansk hvid-eg. Disse fade giver yderligere vaniljenoter til Barbados-rommen, som i forvejen emmer af tropiske frugter. Denne komplicerede aldringsproces frembringer en uforlignelig blødhed og fylde. Vi ser tit &#8220;Plantation XO 20th Anniversary” annonceret som en 20 års rom, men det er ikke helt korrekt. Der er tale om en jubilæums rom, som er fremstillet for at fejre Alexandre Gabriel&#8217;s 20 års jubilæum som øverste chef for Cognac Ferrand. Det er et blend af 12 år gammel rom, som tilsættes en række tudsegamle årgange for at give yderligere fylde og kompleksitet. Denne rom er sandsynligvis den mest kendte og elskede af alle Plantations rom. I næsen er der vanilje, karamel og ristede bananer. Den er ikke for sød – men utrolig lækker! Orange chokolade, kokos og ananas. Barbados for fuld skrue! I munden fylder den godt; nærmest cremet og olieret. Den er sød, men det tager ikke overhånd, og det hele er perfekt afbalanceret. Du får vanilje, bounty, tørret mango og mazarin. Dernæst en lækker, lækker mørk og krydret smag a’la’ kanel, Demerara rørsukker og kakao. Vi har hørt flere udbryde ”Crème Brulée”, før de bad om et glas mere. Det er svært at forestille sig, at man ikke falder pladask for dens uimodståelige charme. Giv den nogle ture rundt i glasset, og du vil opleve, at den returnerer med endnu flere lag og herlige toner af Barbados og hvide sandstrande. Det er kvalitet og en god oplevelse – heldigvis fader den først ud efter laaaang tid i munden. Den skal naturligvis drikkes rent og gerne i gode venners lag. Vi leverer den i en flot gaveæske; mest hvis du vil forkæle en god veninde eller ven! Og her får du flasken pakket i en flot gaveæske med 2 signatur glas &#8211; lige til evt. at give i gave til én du holder af. Rommen vinder rutinemæssigt priser ved diverse smagninger, bl.a.: 2016 Guldmedalje, Paris Rom Festival, Frankrig 2016 Årets spiritus, Whisky Exchange 2015 Guldmedalje, Berlin Rom Festival, Tyskland 2015 Guldmedalje, RumXP Competition, USA, og guld i kategorien, &#8220;Premium Aged Rum&#8221;, ved Miami Rum Festival 2014 Guldmedalje, Rom Festival, Finland 2014 Guldmedalje, RumXP Competition, USA 2013 Guldmedalje, Rum Master, UK 2013 Guldmedalje, RumXP, Competition, USA 2012 Master in the Category Aged over 12 Years, Rum Master, UK 2012 A.Gabriel, World Best Master Blender, Golden Rum Barrel, UK Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Royal Danish Navy Naval Cadet', 'https://spitus.dk/product/old-st-croix-royal-danish-navy-naval-cadet/', 449, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2025/09/Old-st.-corix-naval-cadet-GB.png', 'Old St. Croix Naval Cadet ligger med sine 42% i alkoholstyrke, lige et par procent højere end den traditionelle navy-rombaseret spiritus. Naval Cadet er resultatet af et samarbejde med Kadetforeningen ved Søværnets Officersskole – verdens ældste søofficersskole, grundlagt i 1701. Blendet hylder de søfolk, der sikrede freden omkring Dansk Vestindien, og de unge kadetter, der i dag gør sig klar til nye missioner på verdenshavene. En del af salget går til Kadetforeningens arbejde. Den kommer fra De Amerikanske Jomfruøer, hvor romtraditionen er lige så gammel som de kanoner, der engang stod på danske skibe i Caribien. Duften er elegant med lakridsrod, appelsinskal, kokosnød, mynte og de klassiske tropiske frugter. I ganen en sød, rund og fed mundfølelse, der balancerer de grønne noter af eukalyptus, mynte og de gule noter af citrus, med bitterheden fra lakrids og balsamico rigtig fint. Eftersmagen er lang og dvælende, og slutter blødt og varmt, med en anelse læder og tobak. Klassisk og typisk Old St. Croix-produkt, hvor de mange fans værdsætter den søde og let drikkelige stil. Naval Cadet er spiritussens svar på den unge kadet, der lige er mødt ind på kasernen: uniformen sidder perfekt, håret er klippet kort, og han er meget klar til at bevise sit værd. Den er ikke lige så voldsom som Frogman-udgaven, men den har stadig attitude nok til at få dig til at rette ryggen, når du hælder den op. Leveres i gaveæske. Alkohol% : 42,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Millonario Numero 15 Reserva Especial', 'https://spitus.dk/product/ron-millonario-numero-15-reserva-especial/', 375, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/09/ron-millonario-15yo-reserva-especial.png', 'Millonario kommer fra Peru, hvor sukkerrør vokser som om de har noget at bevise. Her laver man sager på den gammeldags måde: langsomt, omhyggeligt og med en solera-lagring, der får yngre og ældre rom til at blande sig som en familie, der faktisk kan lide hinanden. Número 15 er husets signatur – den der gjorde Millonario kendt for deres bløde, dessertlignende stil. Du kender sikkert denne klassiker iført bast om flasken, men nu har destilleriet udgivet den i et nyt design. Smagen har de heldigvis ikke pillet ved, og det nye design er faktisk også mere end godkendt. Ron Millonario Solera Reserva Especial 15 år blev kåret til bedste premium rom ved International Rum Festival i Florida 2009, og da alle dommerne bedømte den til mere end 90 points, tog den også titlen som ”Best of Show”. Siden er det gået stærkt for destilleriet fra Peru, men Solera Reserva Especial er stadig flagskibet. En sammenligning med de første Ron Zacapa 23 års Solera er absolut ikke helt ved siden af, trods forskellige oprindelseslande. Næsen minder om hinanden, med mandler, brun farin, vanilje, mørk chokolade og rosiner. I munden sød, blød og rund. Masser af karamelliserede frugter, krydderier, honning og vanilje. Vi oplever, at den er mere kompleks og har flere strenge at spille på end Ron Zacapa. Mere krydderi, og nok ikke helt så sød. De lidt flere krydderier, giver uden tvivl en længere og mere fyldig eftersmag end hos Zacapa. Ron Millonario 15 er spiritussens svar på at tage en silkekåbe på en tirsdag aften. Den får dig til at føle dig lidt mere luksuriøs, lidt mere afslappet og en lille smule som en person, der burde have en privat kok. Herlig udgivelse i danskernes fortrukne ”spanske” stil, som du bare får lyst til at sippe mere af. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rammstein Rum Cognac Cask Finish Limited Edition', 'https://spitus.dk/product/rammstein-rum-cognac-cask-finish-limited-edition/', 589, true, 70, 46, 'https://spitus.dk/wp-content/uploads/2025/09/rammstein-rum-cognac-cask-limited-edi.png', 'Rammstein Rum Cognac Cask Finish Limited Edition – En rockstjerne i glasset. Hvis du troede, Rammstein kun lavede musik, der kunne få væggene til at ryste – så vent til du smager deres rom. Rammstein Rum Cognac Cask Finish Limited Edition er ikke bare en spiritus, det er en oplevelse. En mørk, intens og uimodståelig rom, der har fået den helt store tur i cognacfade – og resultatet er lige så eksplosivt som bandets sceneshow. Denne limited edition (udgivet globalt i 5.800 flasker) er skabt til dem, der tør gå lidt længere. Der er tale om en unik blanding af tropiske rom fra Jamaica, Guyana &amp; Trinidad lagret op til 12 år, og slutlagret i tolv måneder på udvalgte cognacfade. Cognac-opholdet tilfører en ekstra dimension af elegance og dybde. Du får en kompleks og velbalanceret smagsprofil med noter af tørret frugt, vanilje, karamel og et strejf af egetræ – alt sammen pakket ind i en flaske, der oser af attitude og kvalitet. Duft: Fyldig og aromatisk med hints af rosiner, mørk chokolade og krydderier. Smag: Rund og blød med lag af cognac, brændt sukker og tropisk frugt. En lang, varm finish med karakter og kant. Design med kant: Flasken er lige så rå som bandet selv – sort, tung og med Rammsteins ikoniske logo. Den er et samlerobjekt i sig selv og et statement på enhver barhylde. Dette er gaven til den rebelske livsnyder. Perfekt til fans af Rammstein, romelskere eller dig, der bare vil have noget helt særligt i glasset. Denne udgave er begrænset, så det gælder om at være hurtig – når den er væk, er den væk. Alkohol%: 46,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 30 Aniversario FUNDADOR Special Edition', 'https://spitus.dk/product/ron-quorhum-30-aniversario-fundador-special-edition/', 799, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2025/09/ron-quorhum-fundador-30yo.png', 'Ron Quorhum 30 Aniversario FUNDADOR Special Edition er en eksklusiv udgivelse fra det dominikanske destilleri Oliver &amp; Oliver, skabt som en fejring af destilleriets 30-års jubilæum. Denne særlige udgave er en hyldest til grundlæggerens vision og passion for romproduktion, og den repræsenterer det ypperste inden for caribisk romhåndværk. Det er ikke en flaske, der stille og roligt glider ind på hylden og håber, du opdager den. Nej. Den kommer brasende ind som en superstjerne, der ved, den er noget særligt. Ron Quorhum 30 Aniversario FUNDADOR er skabt gennem solera-lagring, hvor yngre og ældre rommer blandes i et system, der er lige så kompliceret som en IKEA-manual – men resultatet er langt mere tilfredsstillende. I denne udgave indgår rom, der har lagret i op til 30 år på nøje udvalgte amerikanske og franske egetræsfade, hvilket giver en dyb og raffineret karakter. Visuelt fremstår den med en mørk mahognifarve og gyldne reflekser – et tydeligt tegn på dens lange modning. Duften er intens og flerlaget med noter af vanilje, mørk karamel, tørret frugt, ristet træ og varme krydderier. Smagen er silkeblød og kompleks med nuancer af egetræ, brun farin, chokolade, kanel og et strejf af læder. Eftersmagen er lang, harmonisk og elegant med en velafbalanceret sødme og krydret dybde. Med en alkoholprocent på 42 % (den &#8220;normale Quorhum 30 års er på 40%) er FUNDADOR Special Edition kraftfuld, uden at miste sin finesse. Den egner sig perfekt til ren nydelse ved stuetemperatur, hvor dens fulde aromatiske potentiale kommer til sin ret. Den er også en fremragende ledsager til en god cigar eller som centerpiece i en eksklusiv romsmagning. Flasken leveres i en stilfuld gaveæske, hvilket gør den oplagt som gave til samlere og kendere. Det er en udgivelse, der ikke blot imponerer med sin smag, men også med sin historie og håndværksmæssige kvalitet. Ron Quorhum 30 Aniversario FUNDADOR Special Edition er en sag for dem, der værdsætter dybde, tradition og det ekstraordinære – en ægte jubilæumsudgivelse, der fortjener sin plads blandt de mest ikoniske rflasker i verden. Den &#8220;almindelige&#8221; Quorhum 30 års er blandt de allermest solgte på Spitus.dk, og her får du lige en nøk mere. I eksklusiv gaveæske. Størrelse : 70 cl Alkohol % : 42,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 30 Aniversario Cask Strength', 'https://spitus.dk/product/ron-quorhum-30-aniversario-cask-strength-2/', 939, true, 70, 50, 'https://spitus.dk/wp-content/uploads/2025/08/Ron-Quorhum-30-Aniversario-Cask-Strength.png', 'Den traditionelle Ron Quorhum 30 Aniversario er én af vores absolut mest solgte flasker. Det er en über klassiker, måske specielt i Danmark efter Mads ”Rohatten” Heitmann for efterhånden en del år siden storroste produktet og bl.a. sluttede sin anmeldelse således: ”Jeg er målløs. 98 points – det er nok måske verdens bedste rom til prisen, efter min mening!!” Ron Quorhum er en moderne premium-serie, fejret som nyskabende, men med rødder i gamle cubanske produktionstraditioner. I denne serie, har man både brugt rom destilleret på en base af sukkerrøsjuice samt melasse. Derudover har man ligeledes brugt to typer egetræ under lagringsprocessen; amerikansk egetræ samt fransk egetræ. Dermed møder den spanske romtradition den franske, og har skabt en hybrid med en uovertruffen fylde og kompleksitet. Producenten bag, Oliver &amp; Oliver, er bl.a. kendte for at benytte ”moderrom” og en komponent, der kaldes ”compuesto”. Moderrommen indgår i stort set alle deres aftapninger og har en gennemsnittelig alder på 25 år. Dette tilfører masser af dybde og sødme til de forskellige serier af de udgiver. Compuestoen er en meget gammel rom med masser af egetræssmag og bitterhed, som i sig selv ikke er behagelig at drikke, men som tilfører en masse kompleksitet i det endelige blend. Denne Cask Strength-udgave tager afsæt i den almindelige 30-års Aniversario men med den store forskel, at den er tappet ved fadstyrke (altså ikke tilsat vand efter fadlagringen). Det øger alkoholprocenten fra 40% til 50%, og det er noget, der kan mærkes! Der er simpelthen mere af det hele her, og den opleves endnu voldsommere end ophavet. Den smager af mere, fylder mere, og slår hårdere. Det er stadigvæk flødekaramel, appelsinskal, honning, egetræ, kaffe og dadler med en enorm lang eftersmag, og vi ka’ li det! For mange er det en noget man som fan af den ”almindelige” 30-års Aniversario bare må og bør prøve. En form for naturlig udvikling. En bestseller med endnu mere fart i skoene. Det er faktisk ret vildt Her leverer vi den i en udgave UDEN gaveæske. Størrelse : 70 cl Alkohol % : 50,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum ANTILIA Artisanal Rum', 'https://spitus.dk/product/ron-quorhum-antilia-artisanal-rum/', 359, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/09/ron-quorhum-antilia.png', 'Ron Quorhum ANTILIA Artisanal Rum er en håndlavet premium-sag fra det anerkendte dominikanske hus Oliver &amp; Oliver. Skabt med passion, præcision og respekt for rommens ædle traditioner. Navnet “Antilia” refererer til en mytisk caribisk ø, og denne rom bærer netop den mystik og varme, som man forbinder med tropiske eventyr og dybdegående smagsoplevelser. Quorhum er kendt for at lave blends, der ikke følger alle de klassiske regler. De tager dominikansk rom, lagrer det i solera-systemet, blander forskellige aldre og skaber noget, der føles… ja, artisanal . Ikke i den der hipster-“vi har skæg og seler”-måde, men i den oprigtige “vi gør os umage”-måde. ANTILIA-serien er deres hyldest til Caribien. Ikke det polerede Caribien fra rejsebureauernes brochurer – men det ægte Caribien: varmt, råt, smukt og fuld af smag. Indholdet er fremstillet af nøje udvalgt melasse og destilleret i små batches, hvilket sikrer høj kvalitet og konsistens. Den modnes i egetræsfade, hvor den gennemgår en omhyggelig lagringsproces, der tilfører både dybde og blødhed. Resultatet er en elegant og balanceret oplevelse med en alkoholprocent på 40 %, som både kan nydes rent og bruges i eksklusive cocktails. I næsen mødes man af varme og runde aromaer med noter af vanilje, tørret frugt, egetræ og et strejf af karamelliseret sukker. Smagen er blød og harmonisk med tydelige nuancer af toffee, ristet træ, krydderier og en let sødme, der gør den tilgængelig uden at miste sin kompleksitet. Eftersmagen er lang og krydret med en behagelig sødme og subtile noter af eg, som bliver hængende og inviterer til endnu en tår. Ron Quorhum ANTILIA leveres i en elegant flaske, og den egner sig perfekt til nydelse ved stuetemperatur, men folder sig også smukt ud i klassiske cocktails som Rum Old Fashioned, El Presidente eller en sofistikeret Old Cuban. Denne udgivelse er en hyldest til caribisk håndværk og fortælling – en spiritus, der kombinerer tradition med finesse og inviterer til nydelse i godt selskab. Ron Quorhum ANTILIA Artisanal Rum vækker sanserne og bringer varmen fra Antilias mytiske kyster direkte til dit glas. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bumbu XO', 'https://spitus.dk/product/bumbu-xo/', 399, true, NULL, NULL, 'https://spitus.dk/wp-content/uploads/2021/02/100340-1-Bumbu-XO-1.jpg', 'Bumbu XO er destilleret og lagret i Panama. Destillatet er fremstillet på sukkerrør fra 8 forskellige lande. Destillatet er lagret i brugte bourbon fade og har efterfølgende fået tid i brugte sherry fade fra Andalusien. I næsen er der masser af tropiske frugter og vanilje. Smagen er banan, eg, karamel, lyse citrus noter, blommer og mokka. Meget sød, og med masser af charme og karakter. Bumbu XO har vundet mange priser – bl.a. Guld ved Los Angeles International Spirit Competition 2017. Bumbu storsælger over hele verden, og er du til sød, frugtrig spiritus skylder du dig selv at prøve Bumbu XO. Bumbu XO kommer i en flot og dekorativ matsort flaske. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bayou Spiced', 'https://spitus.dk/product/bayou-spiced/', 299, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/12/bayou-spiced-k.jpg', 'Bayou Rum er vaskeægte amerikansk rom fra sydstaten Louisiana. Rommen er produceret på en lokal sukkerrørsmelasse som destilleres på små batch-destilleringsapparater, og herefter modnet i forskellige fade, normalt i et solera-system, men nogle varianter også som single barrel. Destilleriets masterblender er den unge romkomet, Reiniel Vicente Diaz, som har rødder i den cubanske og dominikanske romproduktion. Denne Bayou Spiced rom er en let krydret rom, da den har lagret med en nøje sammensat krydderiblanding i 30 dage. I næsen er der bagekrydderier, banan og kanel. I munden føles den ret mild men med en kompleks blanding af ahorn, banan, allehånde, nelliker, vanilje og peber. Fyldig og dvælende noter af bagekrydderier. Ægte amerikaner-rom! Guld Global Rum Masters, 2015 Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Black Coral', 'https://spitus.dk/product/a-h-riise-black-coral/', 2995, true, 70, 45.8, 'https://spitus.dk/wp-content/uploads/2024/09/ahr-black-coral.png', 'A.H. Riise eksklusive Black Gem Collection Serie er inspireret af de sjældne sorte ædelstene, der gemmer sig i undergrunden og vandet på eksotiske steder, hvor rom har spillet en afgørende rolle. Denne spændende udgivelse, hylder Black Coral, som er en sjælden type koral, som findes dybt nede i vandet omkring De Vestindiske Øer og Mellemamerika. Den er et produkt af det frugtbare miljø, som også giver næring og mineraler til de sukkerrør, der bruges i “Black Gem Collection”. A.H. Riise Black Coral har en alkoholstyrke på 45,8% og er udgivet i et begrænset antal på 5.990 nummererede flasker på verdensplan, hvilket gør den til et oplagt samleobjekt. Den er er så mørk og elegant, at selv natten bliver en smule misundelig. I næsen en tiltalende duft af tørrede frugter, høje estere efterfulgt af noget frisk hø. Smagen er blød umami fra eg, ristede hasselnødder, tørrede stenfrugter og en meget let hint af sød tobak. Eftersmagen er lang og vedvarende, med smag af eg og ret milde tanniner. Tørret frugtskal og lette krydderier. Farven er lys, poleret rav. Top-lækker udgivelse fra A.H. Riise, som nok skal blive et samleobjekt, men som også i den grad også fortjener at blive serveret i et flot tulipanglas. Den er jo ikke billig, men prisen går forventeligt kun en vej, og det er op! A.H. Riise Black Coral skiller sig ikke bare ud på hylden, men også i glasset. Det her er ikke en flaske, du gemmer væk. Det er den, du viser frem. Med stolthed. Og måske en lille smule pral. Black Gem Serien består af 3 dejlige søskende, som alle udgives i begrænsede mængder: Black Coral, Black Larimar (Januar 2025) og Black Spinel (1. halvår 2025). A.H. Riise Black Larimar A.H. Riise Black Spinel Leveres i en flot gaveæske. Størrelse : 70 cl Alkohol % : 45,8');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Tasting Kit, Valdemar', 'https://spitus.dk/product/a-h-riise-tasting-kit-valdemar/', 319, false, 18, 45, 'https://spitus.dk/wp-content/uploads/2023/08/a.h.-riise-tasting-kit-valdemar-9x2-cl.png', 'A.H. Riise har udgivet 3 forskellige smagebokse, som hver indeholder 8+1 flasker, smageunderlag med smagenoter, et originalt A.H. Riise smageglas og en QR-kode med et link til videoer med A. H. Riise -aficionado Lars Code, som kommenterer hver smagsprøve og fortæller nogle af de fantastiske historier bag dem. Lav din egen smagning, og få en god introduktion til de herlige blends fra A.H. Riise. Dette sæt er opkaldt efter A. H. Riises søn Valdemar, og indeholder bl.a. XO Haakon Royal Reserve – som en reference til at Valdemar var gode venner med Norges Kong Haakon. Den komplette indholdsliste er: 1 x A.H. Riise Royal Danish Navy The Frigate Jylland Premium Matured Rom 2 cl 45% 1 x A.H. Riise Family Reserve Premium Matured Rom 2 cl 42% 1 x A.H. Riise XO Christmas Edition Premium Matured Rom 2 cl 40% 1 x A.H. Riise Signature Premium Matured Rom 2 cl 43,9% 1 x A.H. Riise XO Haakon Royal Reserve Premium Matured Rom 2 cl 42% 1 x A.H. Riise XO Port Cask Premium Matured Rom 2 cl 45% 1 x A.H. Riise Santos Dumont XO Premium Matured Rom 2 cl 40% 1 x A.H. Riise Non Plus Ultra Very Rare Premium Matured Rom 2 cl 42% 1 x A.H. Riise Pharmacy 1838 Bitter 2 cl 40% 1 x Glas med A.H. Riise logo Alkohol% : 40-45 Størrelse: 9 x 2 cl.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Maguá, 35 cl', 'https://spitus.dk/product/ron-magua-35-cl/', 89, true, 35, 37.5, 'https://spitus.dk/wp-content/uploads/2025/09/ron-magua-35cl.png', 'Ron Maguá kommer fra Den Dominikanske Republik, hvor romtraditionen er så dybt forankret, at selv palmerne sikkert har en mening om fadlagring. Maguá er skabt som en hyldest til de lokale håndværkere, der laver rom på den gammeldags måde: langsomt, omhyggeligt og uden at spørge om lov. Det er ikke en rom, der prøver at være fancy. Det er en rom, der prøver at være god . Og det lykkes den faktisk ret godt med. Mørk ravfarvet med en elegant kobberkant. Fin, delikat og kompleks aroma. De aromatiske nuancer af frisk destilleret sukkerrør er absolut tydelige. Vanilje, nødder og kanel med et dejligt lag egetræ fra tiden i fadene. Blød og letflydende nektar, hvor alle kan være med. Den fylder ikke meget i hånden, men den fylder overraskende meget i glasset. Det er den slags flaske, du tager med, når du vil sige: “Jeg er her for smagen – ikke for at slæbe.” Oplagt i skønne cocktails og drinks. Uhyre meget velsmag for pengene. Her i en lille 35 cl&#8217;s udgave &#8211; fås også i alm. 70 cl størrelse, som du finder her Alkohol % : 37,5 Størrelse : 35 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Elixir Orange Grove', 'https://spitus.dk/product/old-st-croix-elixir-orange-grove/', 349, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/09/Old-st.-corix-Orange-Grove.png', 'Med Old St. Croix Elixir Orange Grove får du en unik spiritusoplevelse inspireret af de solrige caribiske øer, hvor friske citrusfrugter og eksotiske aromaer mødes i perfekt harmoni. Denne eliksir kombinerer traditionelt håndværk med en frisk og frugtig profil, som gør den både alsidig og uimodståelig. Smagen er domineret af solmodne appelsiner, der giver en naturlig sødme og friskhed. I næsen fornemmes en intens citrusaroma, ledsaget af subtile krydrede noter, som skaber dybde og balance. På tungen er den blød, rund og forfriskende med en lang, behagelig eftersmag, hvor appelsinens saftige karakter står tydeligt frem. Resultatet er en eliksir, der emmer af sommer, sol og afslappet livsglæde. Old St. Croix Elixir Orange Grove kan nydes på mange måder. Den er oplagt at drikke rent eller over is, hvor den frugtige friskhed kan udfolde sig fuldt ud. Den fungerer samtidig fremragende som ingrediens i cocktails – prøv den eksempelvis i en frisk variation af en Mojito eller som en aromatisk tilføjelse til en klassisk spritz. Kombinationen af citrus og krydderi giver et væld af muligheder, uanset om du ønsker noget enkelt og elegant eller mere eksperimenterende. Det er en romlikør, der tager alt det bedste fra St. Croix – varme, sødme og caribisk charme – og blander det med en citrusfriskhed, der kunne vække selv en mandag morgen. Flaskens design er lige så indbydende som indholdet – farverigt, stilfuldt og med en udstråling, der gør den perfekt som gave eller som blikfang på barhylden. Old St. Croix Elixir Orange Grove er et produkt, der bringer Caribiens livlige ånd direkte til dit glas – perfekt til både hverdagshygge og festlige lejligheder. Alkohol%: 40,0 Størrelse: 70 cl Serveringsforslag Orange Grove Mojito – frisk mynte, rørsukker og lime toppet med Old St. Croix Elixir Orange Grove og danskvand. Tropisk Spritz – bland eliksiren med mousserende vin og en smule dansk vand/clubsoda, pynt med appelsinskive. Simpelt &amp; lækkert – nyd den rent over is eller med tonic for en frisk hverdagsdrink.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix A.H. Riise XO Explorer Reserve (Austria Edition)', 'https://spitus.dk/product/old-st-croix-a-h-riise-xo-explorer-reserve-austria-edition/', 599, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/08/Old-St.-Croix-A.H.-Riise-XO-Explorer-Reserve-Austria-Version.png', 'Old St. Croix A.H. Riise XO Explorer Reserve – Austria Edition Old St. Croix XO A.H. Riise Reserva Explorer Austria, er den ene af de 10 udgivelser i den eksklusive Explorerer-serie. Flasken er en hyldest til de modige forskere og opdagelsesrejsende, som tilbage under A.H. Riises tid, bidrog til kortlægningen og forståelsen af verden. Eventyrerne tilsidesatte egen sikkerhed og rejste ud i verden, og det hyldes nu af A.H. Riise med en serie af skønne flasker. XO Explorer-serien består af en række Limited Editions, der udkom i en række forskellige lande i begrænsede antal nummererede flasker. Hver Edition er skabt specielt til A.H. Riises mange fans og samlere i de forskellige lande, hvor de lokale pionerer var forgangsbilleder for at søge ny viden og sætte deres nation på landkortet, nøjagtig som A.H Riise gjorde. Denne Østrigske Old St. Croix XO Explorer, som er lavet i et begrænset oplag i nummererede flasker, er et eksklusivt Limited Edition-blend fra Vestindien og Mellemamerika, sammensat af A.H. Riises master blender. Spiritussen er sammensat af nøje udvalgte fade fra Vestindien og Mellemamerika, og blendet af A.H. Riises masterblender med fokus på dybde, sødme og kompleksitet. Den tappes ved 40 % alkohol og fremstår med en mørk ravfarve, der vidner om dens lange modning og rige karakter. I næsen mødes man af intense noter af karamel, vanilje og modne tropiske frugter, efterfulgt af varme krydderier og et strejf af egetræ. Smagen er blød og fyldig med lag af søde rosiner, appelsinskal, flødekaramel og ristede nødder. Eftersmagen er lang og behagelig med vedvarende sødme og en let krydret afslutning, der gør den velegnet til både ren nydelse og som ledsager til dessert eller mørk chokolade. Austria Edition leveres i en elegant gaveæske med et design, der afspejler både eventyrlyst og klassisk luksus. Den er ideel som gave til samleren, den passionerede romelsker eller som et eksklusivt indslag i hjemmebaren. Old St. Croix XO Explorer Reserve Austria Edition er ikke blot en spiritus – det er en fortælling om opdagelse, håndværk og kulturarv. En flaske, der inviterer til at udforske smag, historie og det ukendte – præcis som de opdagelsesrejsende, den er skabt til at ære. I flot gaveæske. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 30 Aniversario Oporto Finish', 'https://spitus.dk/product/ron-quorhum-30-aniversario-oporto-finish/', 739, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/09/Ron-quorhum-oporto-finish.png', 'Ron Quorhum er kendt for at lave udgivelser, der ikke følger den klassiske “sød og nem”-skole. De laver rom til folk, der kan lide dybde, karakter og en smule attitude. 30 Aniversario er deres flagskib – en solera-lagret lækkerhed, hvor yngre og ældre rommer blandes i et system, der er lige så komplekst som en familiesammenkomst, men langt mere behageligt. Denne her er en &#8220;Oporto Finish&#8221;, som betyder, at saften til sidst får lov at hvile i portvinsfade . Og det gør noget ved den. Det giver den en vinøs elegance, en frugtig dybde og en “jeg har været i Portugal og lært at nyde livet”-vibe. Quorhum Oporto Finish er et must-try for alle fans af den klassiske Ron Quorhum 30 Aniversario! En god årgangsportvin smager typisk af røde bær, marcipan, blommer, chokolade og vanilje – smagselementer som fungerer godt sammen med rom, hvorfor portvinsfade er velegnede til fadafslutninger af rom. Normalt lagres portvin på store egetræsfade som kan indeholde omkring 500-550 liter portvin. Tømmer man fadet vil der stadig sidde portvinsrester i egetræets struktur, hvilket videregives til rommen, når man på ny har fyldt fadet op. Det betyder altså, at rommen som nu ligger på det brugte portvinsfad, optager nogle af de smagselementer som portvinen besidder. Dette kaldes en finish/afslutning, og det er Ron Quorhum 30 Aniversario Oporto Finish er et godt eksempel på hvor godt kan laves. Med smagen af de klassiske elementer fra Ron Quorhum 30 Aniversario som flødekaramel, honning, appelsinskal, egetræ og kaffe, integreres de rødlige og sødmefulde smagsnuancer fra portvinsfadet på smukkeste vis. De friske citruselementer som findes i originalen akkompagneres af en dyb og bærpræget karakter. Så er man fan af Ron Quorhum 30 Aniversario, er denne Ron Quorhum 30 Aniversario Oporto Finish et must-try! Så længe lager haves! Bemærk: denne udgave leveres UDEN gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Signature, Batch 1', 'https://spitus.dk/product/a-h-riise-signature-batch-1/', 1655, true, 70, 43.9, 'https://spitus.dk/wp-content/uploads/2022/05/a.h.riise-signature-k.jpg', 'A.H. Riise Signature er en udgivelse, der stempler lige ind i toppen af brandets sortiment. Her sælger vi Batch 1 flasker, som er af den første produktion, der blev flasket i 2022. A.H. RIise (nu Old St. Croix) har valgt, ikke at fortsætte udgivelser af Signature, hvorfor denne flaske helt sikkert vil være et flot samleobjekt til en A.H. Riise samling. Hver udgave af A.H. Riise Signature er skabt af meget små partier rest premium-rom og resulterer i mindre end 2000 flasker pr. batch. Hvert fad er nummereret, og hver flaske ligeså. Antallet af flasker varierer fra batch til batch, og indholdet og smagen vil også variere. Som små, forskellige kunstværker. Fælles for alle batches af A.H. Riise Signature er dog, at de skal være de bedste repræsentanter for A.H. Riises kendte smagsunivers af sødme, mildhed og aroma. I næsen, modne tropiske frugter, kokosnødder og karamel ledsaget af kølige myntenoter. Meget lovende! Smagen er ret kompleks og utrolig glat. Glaseret citrus og abrikoser indsvøbt af ristet kokosnød med et strejf af eukalyptus. I eftersmagen får du en sand symfoni af modne tropiske frugter og karamel. Subtile myntenoter tilføjer en fin harmoni til den lange og dybe eftersmag. Hvis du er til den søde og meget imødekommende stil fra A.H. Riise, må du ikke snyde dig selv for at opleve denne nye premium-udgivelse: Signature. Leveres i flot karaffel i gaveæske. Alkohol %: 43,9 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Royal Danish Navy Strength 55%', 'https://spitus.dk/product/old-st-croix-royal-danish-navy-strength-55/', 439, true, 70, 55, 'https://spitus.dk/wp-content/uploads/2025/09/Old-st.-corix-navy-strength-gb.png', 'Old St. Croix Royal Danish Navy Strength er hånd-blended af flere, op til 20 år gamle rom af typen ”Vedderburn og Plummer” &#8211; melassebaseret rom, der kendetegnes ved langsom gæring og Pot-still destilleret op til 85% alkohol styrke inden nedvandingen. Den er ikke koldfiltreret eller tilsat karamel, men den er tilsat sukker i en mængde, som gør, at den ikke kan benævnes rom men hører under kategorien rombaseret spirit drinks. Den deler gener med den traditionelle Old St. Croix Royal Danish Navy Rum, men her er den altså i ”Strength-udgaven”, hvilket betyder 55% i stedet for 40% alkohol. Den højere alkoholprocent giver bestemt et større bid, men smagene og stilen er de samme som udgaven med 40%. Old St. Croix Royal Danish Navy Strength har i næsen karamel, cedertræ, appelsiner og lakrids. I ganen cremet med karamel, eksotiske krydderier, sherry, appelsin og chokolade. Sødmefuld eftersmag, med mange af de samme elementer som umiddelbart i ganen, men der er også et twist af mynte og eukalyptus. Den højere alkoholprocent mærkes, men der er på ingen måde tale om et sprittet udtryk, og faktisk har vi i en blindsmagning svært ved at stadfæste at der er tale om en ”Navy Strength”. Er du til den søde stil, og gerne vil have et lille ekstra bid og varme fra den højere alkohol, er Old St. Croix Royal Danish Navy Strength et af de meste populære produkter overhovedet. Flot flaske og gaveæske. Alkohol %: 55,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Zacapa 12 Y.O. Ambar 1L', 'https://spitus.dk/product/zacapa-12-y-o-ambar-1l/', 559, true, 100, 40, 'https://spitus.dk/wp-content/uploads/2022/08/zacapa-centenario-12.jpg', 'Zacapa Ámbar 12-year-old er en spændende blanding, specielt skabt i et samarbejde med udvalgte bartendere, med fokus på at frembringe verdens bedste klassiske cocktails med rom. Resultatet er en blød oplevelse, der er god til at mikse, og som er kendetegnet af den markante Zacapa-karakter. Blended er lagret i 4-12 år i Zacapa’s ”House Above the Clouds”, og 12 Y.O. Ámbar er den lette, elegante og solmodne side af Zacapa. Zacapa Ámbar 12 er varianten, der tager alt det, folk elsker ved Zacapa – den bløde sødme, den varme dybde, den karakteristiske solera‑stil – og gør det lettere, friskere og mere tropisk. Det er Zacapa i sommertøjet. Smagen er rund, blød og aromatisk med noter af karamel, vanilje, citrus, tropisk frugt og en mild, varm trænote. Den er mindre tung end de klassiske Zacapa‑udgaver, men stadig fyldt med den velkendte guatemalanske charme. Et glas, der både kan nydes rent og løfter cocktails til et højere niveau. Det er flasken, du vælger, når du vil have noget, der er elegant, letdrikkeligt og stadig 100% Zacapa. Zacapa Ámbar 12 er solskin, smoothness og guatemalansk finesse i én liter ren nydelse. Vi leverer den her i en 1 liters version. Alkohol % : 40,0 Størrelse : 1 liter Ron Zacapa Ambar Mojito 5 cl Ron Zacapa 12 Y.O. Ámbar 1½ cl Limejuice. 1½ cl sukkersirup 6 cl Club Soda Friske mynteblade Knuste isterninger Garnish: Myntekvist Fremgangsmåde: &#8211; Kom mynteblade, sikkersirup, limejuice og rom i et Highball Glas &#8211; Fyld det med knuste isterninger og top med club soda &#8211; Garnish evt. med en myntekvist Ambar Cocktail 5 cl Ron Zacapa 12 Y.O. Ambar 1¼ cl Grapefrugt juice 1¼ cl Lime juice 1¼ cl Triple Sec 1¼ cl Sukkersirup ½ cl Campari Isterninger Garnish: Citronskal Fremgangsmåde: &#8211; Hæld alle ingredienserne i en shaker og ryst godt. &#8211; Server i dit yndlings cocktailglas og &#8211; Garnish evt. med en citrtonskal');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Thin Blue Line', 'https://spitus.dk/product/old-st-croix-xo-thin-blue-line/', 398, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/07/old-st-croix-thin-blue-line.png', 'Old St. Croix The Thin Blue Line Denmark er en helt særlig udgave af Old St. Croixs X.O. Reserve (tidligere A.H. Riise). Det er en førsteklasses spirit drink skabt på baggrund af rom fra Vestindien og Centralamerika, hvor destillaterne , der skaber det velsmagende ravfarvede guld, ikke er under 7 år, og nogle er helt op til 21 år gamle. I munden er der vanilje, honning, eksotiske krydderier, læder, lakrids og mild, sødlig tobak. I den lange eftersmag fortsætter noterne og indtrykkene, og det hele lukker med dejlig mørk chokolade og modne blommer. Old St. Croix XO Thin Blue Line er flaskernes svar på en person, der både kan være seriøs og afslappet på samme tid. Den står der i flasken med sit blå bånd og ser ud som om, den er klar til at redde dagen… men når du åbner den, er det mere “Caribbean chill” end “actionfilm med sirener” . Old St. Croix The Thin Blue Line Denmark er samtidig en spirit drink med en mærkesag at støtte. Den er nemlig sammensat til ære for- og som støtte til det danske politi. Den har taget navn efter den danske Thin Blue Line-forening. Foreningen yder støtte til danske betjente, der har lidt skade på krop eller sjæl i tjenesten. Ved at købeThe Thin Blue Line Denmark støtter du således betjente i Danmark, som har betalt en alt for høj pris for at udføre deres arbejde. Køb dette særlige blend og støt samtidig politiets og betjentenes arbejde i Danmark. Leveres i en flot gaveæske. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador 20 Y.O (uden gaveæske)', 'https://spitus.dk/product/dictador-20-y-o-uden-gaveaeske/', 509, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/10/dictador-20-yo-u-GB.png', 'Her præsenterer vi én af klassikerne. Den har siden 2011 vundet et hav af priser og medaljer, og sætter på mange måder standarden for prisklassen. Historien starter i Cartagena, Columbia, hvor Dictador har perfektioneret kunsten at lave klasse-udgivelser på sukkerrørshonning i stedet for den klassiske melasse. Det giver en dybere, mere aromatisk base, som derefter får lov at modne i solera‑systemet. Det betyder, at yngre og ældre romme blandes i et lag-på-lag-system, der er lige så tålmodigt som det er effektivt. 20‑års udgaven er resultatet af den proces: en oplevelse, der er både moden, afrundet og fuld af karakter. Smagen er præcis så mørk og forførende, som flasken lover. Først kommer den dybe karamel og den mørke honningsødme, der giver en blød og fyldig start. Så begynder de mørke frugter at dukke op – rosiner, svesker og en anelse brændt appelsinskal, der giver saften en næsten vinøs dybde. Egetræet ligger som en rolig, tør kontrast i baggrunden, og en let krydret varme binder det hele sammen. Finishen er fedmefyldt og olieret, med en delikat smag af abrikos, romrosin og en herlig blid bourbon sødme. Det er en oplevelse, der både kan nydes rent og bruges i cocktails – men lad os være ærlige: den fortjener sit eget glas, sin egen aften og måske lidt baggrundsjazz. Det ekstra lag af honning, er der hvor denne 20 års udgave primært adskiller sig fra dens 12-årige lillesøster. Stilen er således den samme, men der er noget mere fylde og tyngde her. Ganske som forventet – og håbet. Dictador 20 Y.O. er kort sagt en udgivelse, der smager som om nogen har tænkt sig om. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bally 12 Y.O', 'https://spitus.dk/product/bally-12-y-o/', 589, true, 70, 45, 'https://spitus.dk/wp-content/uploads/2022/12/j-bally-vo-k.png', 'Bally 12 års er en luksusrom, af typen Agricole, hvilket bl.a. vil sige tør og ikke så sød. Faktisk er netop Bally 12 Y.O. en agricole‑klassiker med kant, karakter og caribisk terroir. Bally 12 er rommen, der minder dig om, at rigtig agricole ikke bare er en stil – det er en holdning. Destilleret på frisk sukkerrørssaft og lagret i 12 år på franske egetræsfade, leverer den en smagsprofil, der er både elegant, tør, kompleks og fuld af Martinique‑sjæl. Men, det der primært adskiller J. Bally 12 års fra andre Agricole rom er, at den for kategorien faktisk er ret sød. Derfor er den for mange et godt kompromis mellem det tørre og det søde, eller en god overgangsrom imod mere hardcore Agricole-rom. Farven er helt mørkt mahogni. Konsistensen er nærmest cremet. Smagen er intens, aromatisk og raffineret med lag af tørret frugt og citrus, let ristet eg og krydderi. God fylde med sukkerrør, urter og et strejf af kakao. En lang, tør og struktureret finish Det er en rom for dem, der elsker agricole – ikke sødme, ikke pynt, bare ren, lagret kvalitet med masser af karakter. Bally 12 Y.O.: En moden, terroir‑drevet rom med fransk finesse og caribisk nerve. Leveres i den kendte rektangulære flaske og tilhørende gaveæske. Alkohol %: 45,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Opthimus 18 Años Cum Laude', 'https://spitus.dk/product/opthimus-18-anos-cum-laude/', 495, true, 70, 38, 'https://spitus.dk/wp-content/uploads/2020/06/100249-1.jpg', 'Opthimus er en herlig serie af rombaserede spiritusser fra Oliver y Oliver. Fokus er på at skabe så meget god kvalitet i den populære, søde stil som overhovedet muligt. I denne 18-års version, får du en elegant balance mellem det søde og en enorm substans og krop. Den er sød, men ikke for sød. Du får noter af kirsebær, egetræ og vanilje i næsen. Ret portvinsagtig. I munden er den ikke så sød, som næsen signalerede, og du får mere dadler, nødder og alkoholens varme. Den har en laaang finish, og ingen kan være i tvivl om at dette er en ekstrem vel-produceret fætter, hvor ægte håndværk og know-how kommer flaskens indhold til gode. En vaskeægte value-for-money udgivelse, hvor du klart får mere for pengene end hos de mere kendte mærker. Størrelse : 70cl Alkohol % : 38,0 Land: Den Dominikanske Republik Elegant flaske i en elegant gaveæske.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario 30 Sistema Solera Selección Premium Edicion Limitada', 'https://spitus.dk/product/ron-centenario-30-sistema-solera-seleccion-premium-edicion-limitada/', 999, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/100237-1.jpg', 'I lang tid var Costa Rica primært kendt for produktion af kaffe. Men på grund af sin placering mellem Caribien og Atlanterhavet, kan der dyrkes sukkerrør af meget høj kvalitet, som derefter kan destilleres til rom. Centenario Rums har bragt nogle premium-rums på markedet, der nyder stigende popularitet. Denne Ron Centenario 30 Sistema Solera Selección Premium Edicion Limitada markerer på mange måde højdepunktet for rom fra Costa Rica. Man har åbnet de absolut ældste fade Centenario råder over, og blended dem med stor passion og kærlighed med en række af firmaets andre lagrede fade, for at opnå en perfekt afstemt flagskib. Det er i den grad lykkedes! Tønderne er amerikanske af hvide eg, og brændt indefra. De første leveår fyldes de med whisky, hvorefter rommen får lov at trække noterne ud af de små fade. Inden da, har den været igennem en gammel, klassisk kobber-opstilling. Næse: Rig, intens, vedvarende, men delikat aroma, der balancerer eg og frugtagtig noter med subtile toner af grønne frugter. Farve: Gyldent rav. Smagsnotater: En vidunderlig glat gane af blødt træsmag. Det træede giver en silkeagtig fornemmelse. med en lang, rig og aromatisk finish. Serveringsforslag: rent med is. På International Spirits Challenge 2011 nåede denne Ron Centenario 30 Sistema Solera Selección Premium Edicion Limitada førstepladsen blandt 700 deltagende spiritus. Centenario 30 år Edicion Limitada Rum er flagskibet i Centenario serien fra Costa Rica. Der er tale om et sandt kunstværk og et bevis på at kærlighed også findes i flydende form . Der er tale om en eminent dram hvor duft, smag, farve og den smukke karaffel går op i en højere enhed. Størrelse : 70cl Alkohol % : 40,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix XO Legacy Reserve', 'https://spitus.dk/product/forudbestilling-old-st-croix-xo-legacy-reserve/', 359, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2025/05/old-st-croix-lagacy-gb1.png', 'For 150 år siden introducerede den danske apoteker og eventyrer Albert Heinrich Riise spiritus fra Vestindien til verden under navnet Old St. Croix. Efter i mange år at have solgt rom og spirit drinks under brandet A. H. Riise, går producenten nu tilbage til det oprindelige navn: Old St. Croix. Denne Old St. Croix XO Reserve Legacy er det første blend, der bærer dette genfødte navn. Der er tale om en Limited Edition, hvor Master Destilleren omhyggeligt har udvalgt de bedste fade fra anerkendte destillerier i Vestindien og Centralamerika. Denne Old St. Croix Reserve Legacy er ikke bare en spiritus; det er en tidsmaskine. Én slurk, og du er pludselig på dækket af et piratskib i 1763, mens du forsøger at undgå skørbug og finde ud af, hvem der stjal din papegøje. Flasken ser ud, som om den indeholder en forbandelse, og det er ikke helt forkert. Når du først har åbnet den, forsvinder tiden. Det starter uskyldigt – et nip her, et glas dér – og før du ved af det, står du og holder en meget følelsesladet tale for din stueplante om imperiets fald. Når du skænker den, er farven dyb rav – som solnedgang over en skattekiste (eller urinprøven fra en meget sund sørøver). Duften er solmodne frugter med distinkte umami-noter fra eg, fyldig tobak og gammelt læder. I munden først blidt og sødt, så et lille spark af krydderi, og endelig en lang, varm eftersmag, som om din hals har fået tæppe og pejs. Karamelliserede figner, overmodne tropiske frugter, og lidt af det der krydderi, du aldrig selv ville bruge, men som kokke på tv hele tiden taler om. Spitus synes: Herlig dram, i den elskede Riise stil. Lidt som en Netflix- dramatiseret miniserie i mundformat. Den skal ikke bælles, men det er svært at stoppe. Pludselig holder du skåltaler, og peger mod horisonten og råber: “Til eventyret!” – uanset om du bare skal i Netto efter mere is. Forfører dig langsomt, vælter dig pludseligt. Alkohol %: 42,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Botran Ron Solera 1893 Añejo Decanter', 'https://spitus.dk/product/botran-ron-solera-1893-anejo-decanter/', 359, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/06/Botran-Ron-Solera-1893-Anejo-Decanter.png', 'Denne Botran Rom fra bjergene i Guatemala, laves på første-presset af sukkerrør kaldet ’virgin honey’. Ekstrakten fermenteres og destilleres i en meget langsommelig proces. Der er tale om en sofistikeret blanding af rom modnet i op til 18 år. Den har lageret på forskellige fadtyper: Amerikanske bourbon-fade, brændte amerikanske egetræsfade samt portvins– og sherryfade. Dette er rom-verdenens svar på en dannelsesrejse i Europa. Vi præsenterer her decanter-udgaven, hvilket betyder, at den kommer i en yderst eksklusiv, ja; dekanter. Flasken ligner noget der burde stå i et victoriansk bibliotek ved siden af en globus, der åbner op og skjuler cigarer. Den signalerer hvide handsker, og at den har ligget i tønder længere end du har haft hår på hovedet. Vi taler om en rom, der ankommer i en karaffel så fornem, at du overvejer at tage slips på, før du åbner den. Farven er dyb mahogni med flotte, gyldne lysstråler. Den dufter som et antikt møbel. Først masser af træ, så kakao, vanilje og karamel, og så kommer antydningerne af din fars gamle barvogn fra 70’erne. I munden får du mere noter af tørrede, kandiserede frugter og portvin. En anelse citrus, peber og muskatnød følger med i den varme og søde finish. Den bider ikke, og er en meget høflig rom. Den kommer ind, bukker pænt, tager jakken af og spørger, om det er i orden, at den sætter sig. Hvis du er til de stærke og lidt rebelske romtyper, vil du sikkert savne lidt kant. Spitus synes: Botran Ron Solera 1893 Añejo Decanter er som en gammel, velplejet Jaguar – stilfuld, blød i svingene og fri for hårdtslående overraskelser. Den egner sig perfekt til sofistikerede rom-aftener, til svigerfar-imponering og til at føle sig som en 1800-tals guatemalansk aristokrat. Masser af stil, charme og lettere storhedsvanvid. Det her er rommen der ligner noget, du burde arve, ikke købe. Wiskey &amp; Rom Magasinet: 90 points og Bedste Køb; &#8220;Kraftigt fadpræg i næsen! Bitterhed i smagen som minder om chokolade med højt kakaoindhold. Den er meget tør og direkte på sit krydderi, men slutter af med frugtsødme i eftersmagen.&#8221; Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Botran Ron Añejo 8 Sistema Solera', 'https://spitus.dk/product/botran-ron-anejo-8-sistema-solera/', 195, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/06/Botran-Ron-Anejo-8-Sistema-Solera.png', 'Botran Añejo 8 Sistema Solera er en robust rom af fin kvalitet lavet i højderne i Guatemala. Den er baseret på lokale sukkerør, og lagret på både bourbon- og sherryfade. Farven er mørk rav, som en solnedgang over sukkerrør. Duften vælter op og rammer dine næsebor med abrikos, vanilje, karamel, lidt krydderi og en fjern fornemmelse af egetræ, som om den har ligget på fad og lyttet til klassisk musik. Den danser ind på tungen med sødme fra tørrede frugter; dadler, mango, abrikoser, mandler og appelsiner. Derefter noget brændt sukker og vanilje. Den har et fint lag af krydderier der holder sammen på det hele. Finishen er pænt lang, med friskrevet kanel, sirup og egetræ. Den er ikke tung, men seriøs nok til at blive taget alvorligt. Ret robust, og den skiller sig ud, især i en Daiquiri-drink. Rent går naturligvis også glimrende an. Spitus synes: Botran 8 er alsidig. Du kan drikke den ren, fordi den er smooth som en strandpromenade i solnedgang. Men den spiller også fantastisk i cocktails, hvor den bringer både sødme og dybde til bordet – uden at stjæle hele showet. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Botran Ron Cobre Spiced Rum Edición Limitada', 'https://spitus.dk/product/botran-ron-cobre-spiced-rum-edicion-limitada/', 589, true, 70, 45, 'https://spitus.dk/wp-content/uploads/2025/06/Botran-Ron-COBRE-Spiced-Rum-Edicion-Limitada.png', 'Botran Ron Cobre Spiced Rum Edición Limitada er en special-udgivelse på 10.000 flasker fra Botran. Rommen er gæret på virgin sugar cane honey, og destilleret på kobber-kolonner 2300 meter over havoverfladen i Guatemalas bjerge. Lagret efter den kendte solera-metode på bl.a. brugte portvinsfade. Det er en &#8220;spiced&#8221; rom, hvor du bl.a. møder ingefær, kardemomme, kanel og nelliker på din vej. Men du finder også massive frugt- og trænoter, og i det hele taget er det som om julen og sommeren har indgået en fornuftspagt. Flasken ligner en luksusparfume til mænd, der både laver surdejsbrød og bygger deres egne møbler. Den udstråler tyngde, mørk mystik og noget udefinerbart. Man har næsten lyst til at spørge den, hvilken vinylplade den sidst satte på. Smagen er umiddelbart blød og venlig – men man fornemmer et temperament. Først kommer den klassiske sukkerørs-sødme og en antydning af fadlagret dybde. Men så rammes du af en krydderieksplosion af kanel, peber, ingefær, citrus og varme trænoter. Den er ikke overdrevet sød eller kunstigt parfumeret som mange spiced rums. Den kan drikkes rent, og det bør den. Helst mens du nævner ord som “terroir” og “finish”, selvom du ikke helt ved hvad de betyder. Spitus synes: Perfekt til lange aftener, små glas og store tanker. Eller hvis du vil imponere nogen, der stadig tror, Captain Morgan er det eksotiske valg. Den passer smukt i en mahognibar med indbygget globus og skjult våbenrum. Leveres i gaverør. Størrelse : 70 cl Alkohol % : 45,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('New Grove Double Cask Moscatel', 'https://spitus.dk/product/new-grove-double-cask-moscatel/', 549, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/01/new-grow-double-cask-moscatel.jpg', 'New Grove produceres af destilleriet Grays, der er et førsteklasses vin- og spiritusfirma, og samtidig den største producent på paradisøerne Mauritius. De skabte New Grove-serien i 2006, og navngav den efter en lille by på den sydlige del af Mauritius. New Grove Double Cask Moscatel er rommen, hvor tropisk elegance får et strejf af vinøs luksus. Efter den klassiske lagring på franske egetræsfade i 7 år, får den en ekstra modning på Moscatel‑vinfade i et år , og det giver en aromatisk, frugtig og silkeblød profil, der skiller sig tydeligt ud fra de andre Double Cask‑udgaver. Farven er lys rav. Næsen er ret sammensat, og det kan være svært at skelne det hele ad. Karamel, kanel, vanilje, peber og æble er der umiddelbart, og derefter dukker der valnødder og lakrids op. Kan godt bruge masser af tid i glasset. Smagen er rund, sødmefuld og kompleks med noter af karamel, vanilje, honning, tørret frugt, blomster og en let drueagtig friskhed fra Moscatel‑fadet. Det giver en rom, der både er elegant, eksotisk og farligt drikkevenlig. Det er rommen, du vælger, når du vil have noget med både dybde og finesse – og et strejf af dessertvinens charme. New Grove Double Cask Moscatel er Mauritius med et vinøst smil. New Grove Moscatel har bl.a. vundet guldmedalje ved Rhum Fest 2016 i Paris i kategorien &#8220;Årets Innovation&#8221;. Det forstår vi sådan set godt. Spændende rom! Leveres i gaverør. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Venezuela XO 25th Anniversary rom', 'https://spitus.dk/product/rum-nation-venezuela-xo-25th-anniversary-rom/', 565, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2025/03/rum-nation-venezuela-25-yo-gb.png', 'Rum Nation har i årtier været kendt for at finde de bedste fade i Caribien og Sydamerika, og denne jubilæumsudgave er et af deres mest imponerende værker. Udgivet i 2025, for at fejre mærkets 25-års jubilæum. Den er baseret på venezuelansk rom, lagret i mange år i det tropiske klima, der giver en naturlig sødme og en dyb, afrundet karakter. Derefter får den en ekstra modning i udvalgte fade, som giver endnu mere kompleksitet og finesse. Det er som om, rommen har været på et luksusophold, hvor den både har fået massage, spa og en masterclass i elegance. I næsen chokolade, ristede mandler, nougat og tropiske frugter. Den lange fadlagring er også tydeligt, og du får eg og vanilje i blide bølger. I munden god fylde, med stor cremethed og fuldfed oplevelse. Orangeknas, pikante krydderier, mørk chokolade og kandiserede appelsiner giver en yderst behagelig sødme. Den tropiske fadlagring spiller fint sammen med disse dominerende noter, og alt i alt er oplevelsen en rom i dejlig balance. Lang, smooth eftersmag, der smyger over tungen som tyktflydende orange- og chokoladecrunch. Prestigeprodukt fra Rum Nation! Leveres i en eksklusiv karaffel, og tilhørende gaveæske. Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Foursquare 12 Years &#8220;2011&#8221; Exceptional Cask Selection Mark XXIV Rom', 'https://spitus.dk/product/foursquare-2011-exceptional-cask-selection/', 895, false, 70, 60, 'https://spitus.dk/wp-content/uploads/2025/03/foursquare-2011.png', 'Når Foursquare Distillery lancerer en ny rom, holder entusiasterne verden over vejret. Måske især når der er tale om deres udgivelser i Exceptional Cask Selection (ECS) serien som vi præsenterer her. (Vi har hørt et solidt rygte om, at dette er den sidste ECS-årgang, og at alle fremtidige Foursquare-udgivelser vil blive navngivet). Tidligere ECS-aftapninger har sat standarden i klassen, og rykket grænsen for hvor meget kvalitetsrom du kan få for pengene. Denne 2011-udgivelse er absolut ingen undtagelse, og den har allerede høstet stor anerkendelse i diverse anmeldelser. Der er tale om årgang 8, og som tidligere, er den lagret i 12 år på ex-Bourbon-fade i det tropiske klima på Barbados. Aftappet ved 60% ABV uden tilsætningsstoffer eller kølefiltrering. I næsen meget aromatisk og krydret. Kreolske krydderier, kandiserede ingefær, tørrede hibiscus og lyserød peber. Valnødder, rosiner og rå kakaobønner. En del træ. Jordbærsyltetøj, nelliker, marmelade og tørrede blommer, med syrlige pift af røde æbler og solbær. I ganen meget robust. Halvsure kirsebær, tørrede frugter, krydderier og godt med gammelt træ. Jordbærsyltetøj, blodappelsiner og en del varme krydderier. Egetræet og destillatet komplimenterer virkelig hinanden her. Brombær, ahornsirup, valnødder og karamel. Finishen er lang med krydderier i massevis, elegant suppleret med rige egetræsnoter. WOW – bare WOW. Træintegrationen er virkelig smuk, hvilket giver en rom med masser af forskellige indtryk, krydderier og aromaer. Mere intens end tidligere udgivelser, med mere krydderi og træ, og en anelse mindre frugt. Vi synes, at destilleriejer og masterblender på Foursquare, Richard Seale, her har udgivet den bedste rom i Exceptional Cask Selection-serien hidtil. Vi beder til at det ikke bliver den sidste. The Rum Barrel scorer den 15 points ud af 15 mulige i kategorien ”Value for Money”. Størrelse: 70 cl Alkohol %: 60,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Seleccion de Familia Rom, gaveæske m/2 glas', 'https://spitus.dk/product/diplomatico-seleccion-de-familia-gaveaeske-m-2-glas/', 499, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2025/03/Diplomatico-Seleccion-de-Familia-gaveaeske-m_2-glas.png', 'Diplomático er kendt for deres bløde, søde og uimodståelige rom, men Selección de Familia tager det hele et skridt videre. Her har Diplomáticos master blenders udvalgt nogle af destilleriets mest karakterfulde fade og skabt en rom, der balancerer mellem kraft, dybde og luksus. Diplomático Selección de Familia er et af Diplomáticos nyere udgivelser . Rommen er produceret af destilleriets egen sukkerrørsstamme, Caña Diplomática, som giver den elskede Diplomatico-twist og -karakter i slutproduktet. Diplomático Selección de Familia er et blend af rom fra tre forskellige destilleringstyper: Pot Still, Batch Kettle og Column Still. 90% af rommen stammer fra den traditionelle destilleringsteknik, Pot Still, som giver rommen en udsøgt dybde og kraftfuld smag. Derefter lagres rommen i ca. 12 år på egetræsfade, der tidligere har været anvendt til produktion af bourbon, single malt og sherry, hvilket giver Selección de Familia ekstra kompleksitet og fylde. Denne ret mørke rom har en velbalanceret duft af sukkerrør og honning, efterfulgt af noter af vanilje og eg. Rommen har en fantastisk fyldig smag af blomme, træ og karamel, som afrundes med en lang, lang og dejlig finish. I forhold til klassikeren og dermed mere kendte Diplomatico Reserva Exclusiva, vil vi sige at Selección de Familia har en smule mere tørhed og kompleksitet, men opretholder den efterspurgte velbalancerede sødme og rundhed – trods lavere sukkerindhold. Fornem rom, med fine vurderinger, bl.a. på rumratings.com. Selección de Familia er Diplomáticos hyldest til alt det, der gør deres rom så elsket verden over: sødme, varme, kompleksitet og en silkeblød mundfølelse, der får selv erfarne romnydere til at nikke anerkendende. Den er skabt af Diplomáticos egne master blenders – mennesker, der har dedikeret deres liv til at forstå rom ned til mindste detalje. De har udvalgt fade fra bourbon, sherry og amerikansk egetræ og skabt en rom, der balancerer perfekt mellem kraft og finesse. Det er rommens svar på en skræddersyet smoking: elegant, velduftende og umulig at ignorere. Her leverer vi den i et lækkert gavesæt, inklusive 2 flotte originale rom-glas. Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Black Spinel', 'https://spitus.dk/product/a-h-riise-black-spinel/', 2495, true, 70, 46.1, 'https://spitus.dk/wp-content/uploads/2025/03/a.h.-riise-black-spinel.png', 'A.H. Riise&#8217;s eksklusive Black Gem serie er inspireret af de sjældne sorte ædelstene, der gemmer sig dybt i undergrunden og i vandet i og omkring De Vestindiske Øer. Denne sidste udgivelse, hylder Black Spinel, som er en af de mest sjældne ædelstene der findes. Det siges, at netop denne ædelsten kan fordrive tungsind, samt fremkalde ro og genskabe relationer. Det lyder jo behageligt, og ret meget som at nyde en enkelt eller tre runder af A.H. Riise Black Spinel i selskab med gode venner. Black Spinel er sammensat af nøje udvalgte blends fra en bred vifte af fade, alle med forskellig alder og oprindelse. A.H. Riise&#8217;s master blender har været vidt og bredt for at håndplukke hvert eneste de enkelte fade, der indgår i dette ekstraordinære produkt. I næsen en tillokkende duft af tørrede frugter, dadler, chokolade og slutteligt en halvfræk note af frisk hø. I munden tyktflydende umami, med egetræ, hasselnødder, akaciehonning, frugter, chokoladekage og en anelse sødlig pibetobak. Laaang velsmagende eftersmag, hvor ristede hasselnødder og egetræ er dominerende. I midten kommer der tørrede frugter og eksotiske krydderier. Det er altså smooth og stor velsmag &#8211; hvis du er til Riise stilen. Det er standard Riise med Turbo &#8211; mere af det hele. Tappet i flotte sorte flasker (lig de 2 første i Black Gem serien) ved en alkoholprocent på 46,1%. Der blev tappet i alt 5.570 nummererede flasker, og når de er solgt, er det slut med denne perle. Serien tæller også: A.H. Riise Black Coral A.H. Riise Black Larimar Black Gem Spinel leveres naturligvis i en flot tilhørende gaveæske. Størrelse : 70 cl Alkohol % : 46,1');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Chairman&#8217;s Reserve 1931', 'https://spitus.dk/product/chairmans-reserve-1931/', 699, true, 70, 46, 'https://spitus.dk/wp-content/uploads/2020/10/Chairmans-Reserve-1931-100285-1.jpg', 'Chairman’s Reserve Limited Edition 1931, er en hyldest til den romfilosofi og det håndværk, der blev oprettet af Chairman’s Reserve grundlæggeren, Denis Barnard, da han etablerede destilleriet i 1931. Denne fantastiske prestige-rom, er et blend af kolonnedestilleret rom (Coffey still), og rom fra kobber-destillationsapparater, lagret 6 til 12 år på bourbon-og portvinsfade. 90% af blendet er af melasse rom, mens 10% er af sukkerrørs juice (agricole rom) fra sukkerrør dyrket af St. Lucia Distillers selv. Farven er gylden, og nærmest bronze-agtig i sit udtryk. Næsen er ristet egetræ, læder, tobak og rosiner. Munden fyldes af stor, stor velsmag med karamel, rosiner og en vis tørhed fra egetræet. Destillatet fra sukkerrørene giver en fin aromatisk sødme og eleganthed. Det er en meget balanceret totaloplevelse, og ingen er i tvivl om den høje klasse fra et destilleri der om nogen ved hvordan man skærer fabelagtige rom – endda til meget konkurrencedygtige priser. Størrelse : 70 cl Alkohol % : 46,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Caramel Cream Liqueur m/rom og havsalt', 'https://spitus.dk/product/old-st-croix-caramel-cream-liqueur-m-rom-og-havsalt/', 189, true, 70, 17, 'https://spitus.dk/wp-content/uploads/2025/07/old-st.-croix-cream-likoer-karamel-og-havsalt.png', 'Old St. Croix&#8217;s Likører er fremstillet af fadlagret XO Reserve rom og frisk fløde fra fritgående køer. I produktionen anvendes kun de bedste råvarer uden kunstige tilsætningsstoffer. Romlikørerne har en perfekt balance mellem det søde, cremede og aromatiske, hvor karakteren af fadlagret XO rom træder tydeligt igennem. Faktisk er Old St. Ctoix Liqueur en hyldest til én af de mest entrepenante danskere, Albert Heinrich Riise, der med stor succes drev sit apotek i Charlotte Amalie på St. Thomas i perioden 1838 til 1878. Og denne likør indeholder, ud over frisk fløde, også karamel og ægte havsalt, og det giver den en cremet og blød smag af Rom, en fyldig smag af karamel, afsluttet med en pikant, let og frisk saltet eftersmag. Duft: Lette noter af rom og god gammeldags flødekaramel Smag: Lækker flødesmag med en mint-note efterfulgt af en mere afdæmpet note af kaffe og slutteligt en svag saltet afslutning Nyd den kold ”on the rocks”, måske i kaffen eller rørt sammen med din hjemmelavede vanilje softice! Vælg mellem de to varianter &#8220;Cream likør&#8221; eller denne &#8220;Caramel Cream likør&#8221; &#8211; begge har en alkoholstyrke på 17% og kan nydes kold, i kaffen, eller som prikken over i’et på/i en isdessert. Alkohol%: 17,0 Størrelse: 70 cl Allegener: indeholder MÆLK');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Old St. Croix Cream Liqueur Original', 'https://spitus.dk/product/old-st-croix-cream-liqueur-original/', 189, true, 70, 17, 'https://spitus.dk/wp-content/uploads/2025/07/old-st.-croix-cream-likoer-original.png', 'Old St. Croix’s to creme likører er en hyldest til én af de mest entrepenante danskere, Albert Heinrich Riise, der med stor succes drev sit apotek i Charlotte Amalie på St. Thomas i perioden 1838 til 1878. Denne likør er lavet til dem, der synes at ren rom kan være en udfordring. Den fine gamle rom er nemlig pakket ind i en kappe af den allerbedste creme, man kan forestille sig, hvilket fjerner alle skarpe kanter, og efterlader en kraftig, men smagfuld likør lavet af Old St. Croix X.O. Reserve Rom og frisk fløde, krydret med vanilje, karamel og kakao, samt afrundet med ægte rørsukker. Duft: Fløde, citrusnoter fra rommen blandet med mint og karamel Smag: Varm alkohol med et twist af cappuccino, et strejf af mint, samt blød og varm karamel Eftersmag: En let insisterende mintsmag, efterfulgt af flødekaramel Den kan nydes kold ”on the rocks”, måske i kaffen eller rørt sammen med vanilje softice! Vælg mellem de to varianter &#8220;Caramel Cream likør&#8221; eller denne &#8220;alm. Cream likør&#8221;. Begge har en alkoholstyrke på 17%, og kan nydes kold, i kaffen, eller som prikken over i’et på/i en isdessert. Alkohol%: 17,0 Størrelse: 70 cl Allegener: indeholder MÆLK');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador Aurum Colombian Aged Rum', 'https://spitus.dk/product/dictador-aurum-colombian-aged-rum/', 788, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/01/Dictador-Aurum-Colombian-Aged-Rum.png', 'Dictador XO Aurum er en udsøgt blanding af rom lagret mellem 25 og 35 år. Historien om Dictador går helt tilbage til 1751, hvor Severo Arango y Ferro landede i Cartagena de Indias, en havneby i Colombia, hvor han ville bedrive handel. Hans natur blev hurtigt anerkendt, og han fik tilnavnet &#8220;El DICTADOR&#8221;. Under et ophold på Nueva Grenada blev han forelsket ved første blik (og smag), da han opdagede rommen. Hans dedikation og tilknytning til den tropiske drik førte til, at han blev en nøgleleverandør af eksotisk sukkerrørsspiritus, som på det tidspunkt var regionens valuta. Virksomheden blev grundlagt af en af ​​hans efterkommere, Don Julio Arango y Parra, i 1913 Dictador er kendt for at lave rom, der balancerer mellem tradition og innovation – og Aurum er et af deres mest raffinerede eksempler. Den er skabt på en base af sukkerrørshonning, som giver en naturlig sødme og dybde, og den lagres i et solera-system, der sikrer en silkeblød og harmonisk smagsprofil. Det er som om, den har brugt årevis på at lære at være både sofistikeret og imødekommende. Resultatet er en rom, der føles som en luksusrejse til Cartagena – uden at du behøver at pakke kuffert. Hver en dråbe er en rejse tilbage i tiden, lagret i bourbon og derefter sherryfade, der tilbyder enestående kompleksitet. Aurum er mindre præget af træ end platinversionen, og skinner med sin aromatiske elegance. Forestil dig en symfoni af smag af moden frugt, liflige blomster, et strejf af kanel og en krydret baggrund. Hver sip afslører nye overraskende lag, der medfører en dyb og berigende sanseoplevelse. Dictador XO Aurum er ikke bare en dram, det er en fejring af raffinement. Leveres i flot gaveæske. Størrelse : 70 cl Alkohol % : 40%');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador 2 Masters 1978 39 Years Old Château d’Arche Finish 2nd Release', 'https://spitus.dk/product/dictador-2-masters1978-39-years-old-chateau-darche-finish-2nd-release/', 4899, true, 70, 44.1, 'https://spitus.dk/wp-content/uploads/2025/01/Dictador-2-Masters-1978-39-Years-Old-Chateau-dArche-Finish-2nd-Release.png', 'Dictador 1978 2 Masters Château D&#8217;Arche præsenterer det ypperste indenfor rom fra Columbia. I den eksklusive Dictadors 2 Masters-serie, samler destilleriet ekspertisen fra kældermestre fra hele verden, og udgiver sammen en cuvée. I dette tilfælde valgte Hernan Parra, Dictadors kældermester, at dele en meget gammel tønde rom, destilleret i 1978, med Château d&#8217;Arche. Så, efter 39 års lagring på bourbonfade, blev den sendt til Bordeaux-regionen for at blive modnet i yderligere 12 måneder på amerikanske egetræsfade fra Quintessence-bødkeren. Jérôme Causson. Kældermesteren på Château d&#8217;Arche, udvalgte nøje dette specifikke fad, som tidligere havde huset deres Sauternes Premier Cru. Der findes rom, der er gode. Der findes rom, der er fantastiske. Og så findes der Dictador 2 Masters 1978 – 39 Years Old Château d’Arche Finish … en rom, der får selv erfarne samlere til at trække vejret en ekstra gang. Det her er ikke en flaske, du bare stiller på hylden. Det er en flaske, du viser frem som et trofæ. En rom, der er så sjælden, så kompleks og så gennemført luksuriøs, at den burde komme med sin egen sikkerhedsvagt. Fløjlsblødt, tyktflydende velsmag, der både får mundvandet til at løbe, men også kan kalde en tåre frem i øjenkrogene. Pirrende, sansende og dekadent oplevelse. Der er desværre kun dem der er, og går det som det plejer, skyder disse Dictador 2 Masters hurtigt i vejret prismæssigt. Størrelse : 70 cl Alkohol % : 44,1%');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador Black Edition Colombian Aged Rum', 'https://spitus.dk/product/dictador-black-edition-colombian-aged-rum/', 1195, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2025/01/dictador-black-edition.png', 'Dictador Black Edition Vintage er en eksklusiv rom fra Colombia, bestående af et blend af hengemt rom fra 2003 og 2005. Den imponerer med en umiskendelig aroma domineret af rige, mørke noter af kaffe, karamel og chokolade. Kompleks, men fint afbalanceret i munden, med egetræ, nødder, kakao og krydderier. Lang, sødlig finish, med dvælende trænoter og tyktflydende kakaocreme. Den iøjnefaldende matsorte flaske understreger rommens unikke karakter, og visuelt synes vi at den sidder lige i skabet. For samlere og kendere. Udgivet i kun 1.000 hånd-nummererede flasker på verdensplan . Leveres i gaveæske. Størrelse : 70 cl Alkohol % : 40%');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador 20 Y.O i gaveæske m/2 glas', 'https://spitus.dk/product/dictador-20-y-o-i-gaveaeske-m-2-glas/', 649, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/01/dictador-20-yo-gaveaeske-2glas.jpg', 'Her præsenterer vi én af klassikerne indenfor rom. Den har siden 2011 vundet et hav af priser og medaljer, og sætter på mange måder standarden for prisklassen. Det specielle ved Dictador 20 års, udover at den stammer fra Columbia, er at den er fremstillet på et mix af sukkerrørs- og honning-melasse. En rom som Ron Zacapa laves også på honning-melasse, og kan på visse områder sammenlignes med denne Dictador rom. Hvis du er fan af sødlige rom, anbefaler vi på det varmeste at prøve denne. Dictador 20 Years er rommen, der kombinerer elegance, dybde og en helt særlig colombiansk signatur. Og i denne gaveæske får du ikke bare flasken – du får også to stilrene glas, der gør oplevelsen komplet fra første skænk. Smagen er mørk, rund og raffineret med lag af karamel, kaffe, kakao, tørret frugt og en let ristet trænote. Den er silkeblød, men stadig intens nok til at føles som en seriøs premium‑rom. Dictadors karakteristiske melasse‑stil giver en dyb sødme og en lang, varm finish, der bliver hængende på den helt rigtige måde. Det er gaveæsken der er perfekt til romelskeren, samleren eller som en luksuriøs treat til dig selv. Dictador 20 Y.O Gaveæske: Smagfuld elegance – og to glas, der beder om at blive fyldt. I ganen får du en varm, cremet vanilje og karamel, med toner af brændt honning, toffee, anisfrø og nyristede kaffebønner. Det hele er pakket ind i noterne af egefad. Du fornemmer tydeligt honningen fra destillatet. Og netop dette ekstra lag af honning, er der hvor denne 20 års udgave adskiller sig mest fra dens 12-årige lillesøster. Stilen er således den samme, men der er noget mere fylde og tyngde her. Ganske som forventet. Eftersmagen er fedmefyldt og olieret, med en delikat smag af abrikos, romrosin og en herlig blid bourbon sødme. Her leverer vi den i en flot gaveæske inklusive 2 Dictador tumbling rom-glas. Vi sælger den også i udgave med en gaveæske uden glas. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('New Grove Double Cask Acacia Rom', 'https://spitus.dk/product/new-grove-double-cask-acacia/', 549, true, 70, 47, 'https://spitus.dk/wp-content/uploads/2022/01/new-grow-double-cask-acacia.jpg', 'New Grove produceres af destilleriet Grays, der er et førsteklasses vin- og spiritusfirma, og samtidig den største producent på Paradisøerne Mauritius. De skabte New Grove-serien i 2006, og navngav den efter en lille by på den sydlige del af Mauritius. New Grove Double Cask Acacia er rommen, der beviser, at fadlagring kan være alt andet end kedeligt. Her får du en klassisk Mauritius‑rom, der først modnes på traditionelle egetræsfade i 7 år – og derefter får en ekstra omgang på 1 år på akaciefade, som giver en helt særlig, aromatisk dybde. Farven er rav. I næsen er den ret kraftig, og der sker en masse. Peberet er tydeligt, og generelt er der et vegetabilsk udtryk. Svesker og flydende karamel, understøttet af en anelse bitter mandel, er også til stede. Fadene er også godt repræsenterede.Smagen er rund, varm og elegant med noter af karamel, vanilje, honning, tørret frugt og en floral, let krydret tone fra akacien. Det giver en blød, næsten honningagtig sødme og en finish, der føles både eksotisk og raffineret. Det er rommen, du vælger, når du vil have noget, der skiller sig ud – uden at blive mærkeligt. En perfekt balance mellem innovation og tradition. New Grove Double Cask Acacia er Mauritius, men med et ekstra lag magi. Leveres i gaverør. Størrelse : 70 cl Alkohol % : 47,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Non Plus Ultra Very Rare &#8211; Old Edition', 'https://spitus.dk/product/a-h-riise-non-plus-ultra-very-rare-old-edition-2/', 1049, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2025/01/npu-very-rare-old-edi.png', 'Ja, ja; vi ved det godt! Denne version af A.H. Riise Non Plus Ultra Very Rare Rum er umiddelbart ”kun” interessant for samlere og feinschmeckere. Der er nemlig tale om en såkaldt Old Version , så hvis du er i byen for en standard Non Plus Ultra Very Rare, finder du naturligvis også den her på Spitus.dk. Hvis du stadigvæk læser med her, behøver udgivelsen nok ikke en nærmere introduktion. Det er kvalitet i den søde stil som danskerne elsker det, og Non Plus Ultra er A.H. Riises premium-serie. Der står ”Rum” på gaveæske såvel som på flasken, og designet er anderledes end på den nuværende udgivelse (det design som er afbilledet svarer til det vi leverer ved en bestilling). Skal serien være komplet, er dette et meget sjældent bekendtskab på markedet, og om ikke længe så er de umulige at opdrive. Alkohol % : 42,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Black Larimar', 'https://spitus.dk/product/a-h-riise-black-larimar/', 2499, true, 70, 45.2, 'https://spitus.dk/wp-content/uploads/2025/01/PRODUKT-BILLEDER-2.png', 'Den eksklusive Black Gem Collection Serie fra A.H. Riise, er inspireret af de sjældne sorte ædelstenene som findes i dybet i Vestindien. Dette er den anden udgivelse i serien, og Black Larimar ædelstenene siges at berolige sindet og fremme en god kommunikation. Det lyder jo meget som at nyde et godt glas Riise! Der er i alt udgivet 5.995 unikke og nummererede flasker af denne skønhed, og samlerpotentialet er dermed stort. I næsen vanilje, honning og appelsin. I ganen mørk chokolade, krydderier, appelsin og blød vanilje. En anelse mynte giver en let prikkende fornemmelse. Dejlig, kompleks mundfylde, som vidner om mange års ophold på fadene. Lang eftersmag med fudge, vanilje, chokolade og en anelse læder. De 45,2% i alkohol er også med til at binde tingene sammen og holde dampen oppe. Black Gem Serien består af 3 dejlige søskende, som alle udgives i begrænsede mængder: Black Coral (oktober 2024), Black Larimar (januar 2025) og Black Spinel (marts 2025). Flot sæt! Alkoholprocent : 45,2% Størrelse : 70 cl.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo 12YO + Abuelo Two Oaks Rom 20 cl', 'https://spitus.dk/product/abuelo-12yo-abuelo-two-oaks-20-cl/', 439, true, 20, 40, 'https://spitus.dk/wp-content/uploads/2025/01/Abuelo-12-years-og-20cl.-Abuelo-XII-Two-Oaks.png', '2 top-lækre udgivelser fra Abuelo i en flot gaveæske . Du får en helflaske af den populære 12 års, og derudover 20cl. af destilleriets forrygende 12 års ”Two Oaks”. Så kan du evt. selv opleve forskellene. Det her sæt er som at få både hovedretten og desserten serveret på samme tallerken. To rom, to personligheder, én fantastisk oplevelse. Abuelo Anejo 12 Years er en populær ”Best buy rom”, og nok destilleri Varela Hermanos’ vigtigste eksportprodukt. Abuelo 12 YO er rommens svar på en velklædt herre, der altid møder op til tiden, holder døren for dig og ved præcis, hvordan man imponerer uden at overdrive. Der er tale om en fuldlagret rom, der også findes i udgaver lagret i 5- hhv. 7 år. Denne har ligget på fad i 12 år i Panamas varme klima, og der virkeligt tale om et dejligt bekendtskab. I næsen er der brændt eg, chokolade, karamel, og en anelse syrlighed fra appelsin og hindbær. Spændende næse! I munden sødmefuld, uden det bliver for meget. Det hele virker meget harmonisk. En del noter af ristet træ, men stadig chokolade, krydderier og karamel. Ret lang finish, der efterlader munden med en dejlig, fuldfed sødme. Mads ”Romhatten” Heitmann slutter hans anmeldelse således: ”I dag er det en rom, som jeg godt kan lide netop pga. den tunge egetræssmag. Jeg synes at den har mere at byde på end den gennemsnitlige søde rom. Til 300-350 kr. synes jeg at dette er et kanongodt romkøb, specielt hvis man har en sød tand i ny og næ.” Abuelo XII Anos Two Oaks er dejlig 12 år gammel rom fra Panama. Som navnet siger, har den været lagret på 2 forskellige typer fade. Først fik den nogle år på ryggen i brugte bourbon-fade, hvorefter den, ret specielt, fik en tid i helt nye, men godt forkullede amerikanske ege-fade (sidstnævnte fremstilles i Californien, hvor de først rister de nye fade ved 180° C i 60 minutter, for at åbne træet, og herefter skruer op til 220° C, for at få en dyb forkulning på ca. 0,8 cm.). Dette giver ekstra meget smag fra træet, men også en fin blødhed, da de forbrændte fade fungerer som en slags kulfilter. Hvor den almindelige12 YO er den høflige gentleman, er Abuelo Two Oaks hans mere intense, lidt mystiske fætter. Den type, der dukker op til festen i læderjakke og får alle til at kigge en ekstra gang. I næsen er der masser af træ, kaffe, ristede nødder og en anelse røg. I munden er den sød, med ristede kaffebønner, karamel, eg og vanilje. Stadigvæk en anelse fin røg. Meget blød og imødekommende. I finishen fortsætter noterne, og der dukker yderligere eksotiske krydderier, ristede kaffebønner og en anelse banan og cola(!) op. Abuelo XII ’Anos Two Oaks’ har vundet adskillige internationale priser. Blandt andet har den vundet vundet Dobbelt Guld ved San Francisco World Spirits Competition 2022. Rom i præcis den stil som danskerne elsker! Dejligt sæt, hvor du virkelig kan opleve hvad forskellige fadlagringer betyder for din rom. Alkohol %: 40,0 Størrelse : 70+20 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Black Gem serie &#8211; Black Coral, Black Larimar og Black Spinel', 'https://spitus.dk/product/a-h-riise-black-gem-serie-black-coral-black-larimar-og-black-spinel/', 6893, true, 210, 45.8, 'https://spitus.dk/wp-content/uploads/2025/03/3-gem-collection.png', 'A.H. Riise&#8217;s eksklusive Black Gem serie består af 3 eksklusive flasker, som alle er inspireret af de sjældne sorte ædelstene, der gemmer sig dybt i undergrunden og i vandet i og omkring De Vestindiske Øer. Serien tæller følgende (klik på navnet, og du kan læse mere om den enkelte flaske): A.H. Riise Black Coral A.H. Riise Black Larimar A.H. Riise Black Spinel Indholdet i Black Gem serien er sammensat af nøje udvalgte rom fra en bred vifte af fade, alle med forskellig alder og oprindelse. A.H. Riise&#8217;s master blender har været vidt og bredt for at håndplukke hvert eneste de enkelte fade, der indgår i dette ekstraordinære produkt. Tappet i flotte sorte nummererede flasker i en begrænset mængde. Black Gem Serien leveres naturligvis i flotte matchende gaveæsker. Størrelse : 3 x 70 cl Alkohol % : 45,8%, 45,2% og 46,1%');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H.Riise XO Founders Reserve No 4', 'https://spitus.dk/product/a-h-riise-x-o-founders-reserve-no-4/', 599, true, 70, 45.1, 'https://spitus.dk/wp-content/uploads/2023/02/a-h-riise-founders-reserve-no4-k.jpg', 'Founders Reserve er en XO-serie fra A.H. Riise bestående af blends, der repræsenterer et helt unikt øjebliksbillede. De lækre dråber findes kun i begrænsede- og forskellige antal flasker. Hver batch er unik, og kan aldrig genskabes. Den første udgivelse er fra medio 2021 (Founders Reserve No. 1) (11.232 flasker), og kom med en styrke på 44,5 % og har rød tekst på etiketten. Founders Reserve No. 2 (11.280 flasker) med en styrke på 44,3% blev lanceret i begyndelsen af 2022 og har blå tekst på etiketten. Founders Reserve No. 3 (8.976 flasker) med en styrke på 44,8% blev udgivet medio 2022 og har en grøn tekst på etiketten. Founders Reserve No. 4 var klar i butikkerne fra d. 27. januar 2023 (14.225 flasker, mørkerød tekst og 45,1% alkohol). Founders Reserve No. 5 udkom i maj 2023 (13,995 flasker, orange tekst og 44,4% alkohol). Founders Reserve No. 6 udkom d. 1. september, i et oplag på 13.665 flasker, med lysegrøn tekst og en alkoholprocent på 45,5%. Hver flaske er nummereret med et batch- og flaskenummer. Denne nummer 4 i serien er gylden i farven. I næsen masser af tropisk frugt, en anelse kirsebær samt mild tobak. I ganen stadig tropiske frugter, mørk chokolade, vanilje, blommer, ristede mandler og en anelse brun farin. Vidunderlig blød og vedholdende eftersmag. Founders Reserve No. 4 er en rigtig god repræsentant for A. H. Riise-stilen. Let tilgængelig, sød og masser af velsmag! Den beviser, at sødme, styrke og selvtillid sagtens kan bo i samme flaske. Leveres i gaveæske, og gratis hjem til dig eller til nærmeste pakkeboks. Alkohol% : 45,1 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador XO Perpetual', 'https://spitus.dk/product/dictador-xo-perpetual/', 749, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/10/100288-1-Dictador-XO-Perpetual.jpg', 'Dictador produceres i Colombia på den caribiske kyst i Cartagena de Indias City. I denne Dictador XO Perpetual anvendes udelukkende jomfruelig honning fra sukkerrør – og ikke delvist melasse som f.eks. med 12- og 20 års udgaverne. Der er fokuseret meget på selve fadlagringen, og sammensætningen af fadene ved produktionen af denne fantastiske udgivelse. Der anvendes kun de absolut bedste fade, og den udsættes for 60% gamle bourbon-fade, 20% ex sherry og 20% ex portvinsfade. Denne kombination er med til at give et unik udtryk, med vanvittig meget aroma og kompleksitet. I næsen er der honning, ren vanilje, karamel, moden egetræ og fudge. I munden er den ekstrem glat og smoth, og du rammes af fudge-elementer, suppleret med smag af ren vanilje, parfait-karamel og colombiansk kaffe. Burn-out er enorm og detaljerig, med rå mængder af læder, mørk chokolade, egetræ og tørrede frugter. Der er masser af wow-effekt over Dictador XO Perpetual, og kendere rundt omkring i verden har taget den til sig som en naturlig del af et assorteret barskab. Det forstår vi ganske udmærket! Størrelse : 70cl Alkohol % : 40,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador XO Insolent', 'https://spitus.dk/product/dictador-xo-insolent/', 749, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/10/Dictator-XO-Ensolent-100287-1.jpg', 'Fra Dictador destilleriet, som ligger i byen Cartagena de Indias City på den caribiske kyst i Colombia, kommer denne fabelagtige ”Insolent XO”. Udvælgelsen og sammensætningen af de anvendte fade er yderst interessant ved denne udgivelse. Dictador har nemlig fokuseret, og bruget megen energi og tid på at sikre de bedste fade-forhold. Fadene genforkulles (for at karamellisere sukkeret fra det tidligere indhold) før de fyldes med rom. Det endelige produkt har klare træk fra lagringsperioden i disse fade, primært i form af en dyb, fyldig sødme fra portvinsfadene, og en væld af tørrede frugter fra sherryfadene. Sammen komplimenterer disse tiltag Dictadors destillat helt perfekt. Duften frigiver skønne noter af ren vanilje, ristet honning, karamel og moden eg. Farven er mørk mahogni, men med et elegant gyldent skær. Smagen er utrolig blød og imødekommende, men samtidig uhyre kompleks, med vanilje, Colombiansk kaffe, karamel og med en fin afbalanceret reference til egetræet. Eftersmagen bliver ved og ved, og man er ikke i tvivl om at dette er en helt speciel spirit drink. Fantastisk! Størrelse : 70cl Alkohol % : 40,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomático Reserva Exclusiva Ron Antiguo i gaverør', 'https://spitus.dk/product/diplomatico-reserva-exclusiva-ron-antiguo-i-gaveroer/', 329, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/11/Diplomatico-Reserva-Exclusiva-Ron-Antiguo-i-gaveroer.png', 'Hvis der fandtes en “folkets rom”, så ville Diplomático Reserva Exclusiva uden tvivl være en af de stærkeste kandidater. Det her er nemlig en flaske, der kan noget helt særligt: Den får både nybegyndere og hardcore nørder til at smile. Og det er ikke så mærkeligt – den er blød, sød, rund og så charmerende, at man næsten får lyst til at give flasken et kram. Det er den venezuelanske klassiker, der får alle til at nikke anerkendende. Diplomático Reserva Exclusiva er udvundet af lokale sukkerrør høstet ved foden af Andelsbjergene. Sukkerrørsmelassen destilleres i gamle copper pot stills, og rommen lagres efterfølgende i op til 12 år på amerikanske egetræsfade. Diplomatico er klart i den søde ende, og fans af f.eks. Ron Zacapa vil fint kunne være med her. (Vores måling siger ca. 35–40 g/L sukker). Noterne er egetræ, appelsiner og chokolade. I munden fortsætter den bløde, runde og behagelige stil, og du får også en anelse lakrids og karamel. Sød og delikat. Saftig fudge og meget karamel. Blid og omgængelig – en crowdpleaser! &#8220;Do uble Gold Medal&#8221; fra den første &#8220;International RUM Conference&#8221; i 2013 Leveres her i flot gaverør. Størrelse : 70cl Alkohol % : 40,0 Land: Venezuela');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Reserve Christmas Edition', 'https://spitus.dk/product/a-h-riise-xo-reserve-christmas-edition/', 499, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/10/ahr-christmas-edi-k.png', 'A.H. Riise XO Reserve Christmas udgives hvert år i en begrænset mængde. Udgangspunktet for denne herlige, letkrydrede dram er ”den almindelige” XO Reserve, men for at tilføje julenoter, har den fået yderligere fadlagring på brugte PX (Pedro Ximinez) sherry-fade. A.H. Riise XO Reserve Christmas Edition er brandets svar på en perfekt decemberaften: varm, sød, krydret og fuld af den der “nu må vi godt forkæle os selv”-stemning. Det er en limited edition, hvor Riise går all‑in på julens smage – uden at blive kvalm eller kitschet. Farven er mahogni, og i næsen får du rosiner, vanilje, eg og noget kanel. Smagen er blød, rund og dessertlækker med noter af karamel, vanilje, appelsinskal, kanel, nellike og et strejf af julekage. Den er sød, men elegant sød –den ved præcis, hvad den laver. Perfekt til risalamande, småkager, julefrokoster, gløgg‑alternativer eller bare som “nu tager vi lige et hyggeshot”. A.H. Riise Christmas Edition: Julestemning i hver eneste dråbe. Aftappet single barrel, og påført flaske- og fadnummer samt aftapningsdato. En skøn juledrik lige i den elskede A.H. Riise stil, som leveres i en flot gaveæske. A.H. Riise XO Reserve Christmas Edition er ren julehygge på flaske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Reserve Superior Cask, i gaveæske m/2 glas', 'https://spitus.dk/product/a-h-riise-xo-reserve-superior-cask-i-gaveaeske-m-2-glas/', 549, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/11/a.h.-riise-xo-reserve-superior-cask-gaveaeske-k.jpg', 'A.H. Riise XO er en samling af ekstra gamle blandinger lavet af dobbeltdestilleret førsteklasses modnet caribisk rom. Blandingerne er nøje udvalgt og sammensat af A.H. Riise’s masterblendere for at sikre perfekt afbalancerede og ensartede blandinger. Stilen er den søde, balsamiske og aromatiske med stærke rødder i A. H. Riise’s arv fra Dansk Vestindien. Lagringen i PX og Oloroso sherryfade bidrager til den mørke og søde smag. Blended er sammensat af fine gamle romfade (op til 20 år) samt lidt yngre fade, der giver en perfekt kant og fyldig smagsoplevelse. I næsen får du først lidt mynte, dernæst ​​karamel og citrus, samt en anelse læder. I munden fyldig eukalyptus, blommefyldt tarte tatin og et strejf af te med bergamot. Sød tobak, chokolade og modne frugter. Afslutningen er en fløjlsagtig blød, delikat og sødmefuld nydelse. A.H. Riises (nu: Old St. Croix &#8211; dette er fra tiden de hed A.H. Riise) udgivelser er nogle af de absolut mest solgte i Danmark, og den meget søde stil har mange fans. Det er en ”let at gå til drink&#8221;, som falder i de flestes smag. Leveres her i en flot gaveæske inkl. 2 indgraverede A. H. Riise rom-glas. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Caribbean Triple Aged Rom 5+5 år +Tasting Kit', 'https://spitus.dk/product/dos-maderas-caribbean-triple-aged-55-aar-tasting-kit/', 499, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/11/dos-maderas-caribbean-triple-aged-55-aartasting-k.png', 'Dos Maderas har vundet stort anerkendelse for deres sherry, brandy og rom. Master blenderen udvælger nøje mellem de mest eksklusive rom fra Barbados og Guyana. To lande med deres egen romstil. Begge lande laver nemlig rom på pot stills og kolonneapparat. Den kraftige og aromatiske rom laves på pot stills og den mere blide og afrundede på mere moderne kolonneanlæg. Huset blev grundlagt i 1877 af Sir Alexander Williams, en stor beundrer og connaisseur af sherry – og Arthuur Humbert, specialist i internationale relationer. Dette Dos Maderas Tasting Kit består af en lækker flaske Dos Maderas 5+5 year (70 cl) og 4 små samples: Guyana-Barbados rom (udgangspunktet), Dos Cartados ekstreme tørre sherry, Dos Maderas 5+3 og Don Guido meget søde PX sherry. Processen starter med at den 5 år gamle Guyana-Barbados rom kommer til Jerez, hvor den lægges i 20 år gamle Dos Cartados fade. Efter tre år er den kendte Dos Maderas 5+3 udgivelse færdig til at komme på flaske og nyde. Noget af denne 5+3 blanding fyldes i 20 år gamle Don Guido PX fade, og efter yderligere 2 års lagring, er Dos Maderas 5+5 færdig (den store flaske). Meningen med dette sæt er, at der først smages på den rå rom sample. Herefter den tørre sherry, for at få en idé om, hvad der kommer til at ske med det endelige produkt. Nu smages Dos Maderas 5+3, hvor de tydelige spor af den tørre sherry opleves. Tiden er nu inde til den søde sherry, igen for at forberede sig til det endelige resultat &#8211; Dos Maderas 5+5! Gem gerne en lille smule Don Guido PX, som du blander med din sidste sip af 5+5 drammen &#8211; det er en fuldendelse af rom og sherry! Sjov og lærerig smagning. Alkohol % : 40,0 Størrelse : 1 x 70cl &amp; 4 x 2cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santos Dumont XO Elixir', 'https://spitus.dk/product/santos-dumont-xo-elixir/', 289, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/10/Santos-Dumont-XO-Elixir.png', 'Santos Dumont Elixir er en charmerende sødmefuld rom-likør, som rammer alt til dem som holder af et godt glas med den helt rigtige balance mellem alkohol og sødme. Brasilien er i dag verdens største producent af sukkerrør. En meget stor del af den melasserom der fremstilles verden over, er lavet på melasse fra Brasilien. Dog ikke denne likør. Santos Dumont Elixir er fremstillet på basis af Santos Dumont XO, som er lagret på henholdsvis bourbon, PX sherry og portvinsfade. Sidst men ikke mindst tilsættes lokale urter og en nøje afmålt mængde sukkerrørs honning. På denne måde skabes denne herlige Elixir, som enhver elsker af god, fremragende sødmefuld dram vil holde af. Duft: Banan, kokos, moden frugt og abrikoskerner Smag: Honning og ikke mindst gæret frugt. Hertil kommer en prikken på tungen, som understreger spændstigheden i denne rom-likør. Ravfarvet, fed med flotte gardiner. Drik Elixiren som avec til kaffen eller i et cocktailglas med knust is. Det er en dram, der glider ned som en drøm og efterlader en varm, behagelig eftersmag, der får dig til at smile helt ned i maven. Den er perfekt til dem, der elsker en sød oplevelse – og til dem, der ikke gør… endnu. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santos Dumont XO Super Premium', 'https://spitus.dk/product/santos-dumont-xo-super-premium-spirit-drink/', 459, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/10/Santos-Dumont-XO.png', 'Denne dram er opkaldt efter Alberto Santos-Dumont – en mand, der ikke bare fløj i luftskibe, men også havde en forkærlighed for det gode liv. Santos Dumont XO Super Premium er skabt med samme eventyrlyst og perfektionisme. Santos Dumont XO er fremstillet på den rene nypressede saft fra de friske sukkerrør. Den ny­pressede saft er en delikatesse i sig selv, når så saften nænsomt destilleres på gamle kobberk­edler, opnår man en klar sprød kvalitetsspiritus. Denne nyfødte elixir hældes he­refter på tre forskellige typer egetræsfade som tidligere har indeholdt henholdsvis: Bourbon, der giver noter af vanilje og sort peber. PX sherryfade, der tilføjer moden frugt, hon­ning og en snert af gammelt egetræ. Portvinsfade, med sødme, skarphed og blød vinøs karakter. Herefter er det op til master blenderen at stikke de tre fadtyper sammen i et magisk blend, som giver os en gammel ædel dram. Nu hviler produktet for sidste gang i det enkle hånd­plukkede fad, hvor den får lov til at udvikle sin helt særlige enkeltfadskarakter. En Santos Dumont XO er altid nummereret med angivelse af såvel fad- som flaskenummer. Duft: Banan, kokos moden frugt og abrikoskerner Smag: Bløde tandiner, høje estere, honning og ikke mindst gæret frugt Eftersmag: En dejlig lang eftersmag, med søde rosiner, dadler og fudge. Ravfarvet, fed med flotte gardiner. Drik den som den er, eller i et cocktailglas med knust is til kaffen. Leveres i flot gaveæske. Sættet ligner en million. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Doorly&#8217;s XO Fine Old Rum Barbados', 'https://spitus.dk/product/doorlys-xo-fine-old-rum-barbados/', 325, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2024/10/Doorlys-XO-Fine-Old-Rum-Barbados.png', 'Doorly’s XO er skabt på det legendariske Foursquare Distillery på Barbados, hvor romtraditionen er så stærk, at selv sukkerrørene må føle sig stolte. XO betyder “Extra Old”, og her er det ikke bare et fancy ord – det er en garanti for kvalitet. I overensstemmelse med god Barbados-tradition, er der ikke tilsat sukker for at søde rommen. Doorly’s bruger både pot stil og kolonnekedel destillering i deres rom, og du får et godt mix af sødme, volumen og autensitet. Rommen lagres først i bourbonfade, hvor den suger varme, sødme og vanilje til sig. Derefter får den en ekstra modning i olorosso-sherryfade, som giver dybde, frugtighed og en silkeblød afrunding. Det er som om, rommen har været på et luksusophold: Først sol og strand, så spa og massage. Med 43% alkohol, får du lidt mere bid og spicyness, men alt naturligvis i den fineste balance. I næsen nødder, sherry, vanilje og egetræ. I munden ret voluminøs, med stor fylde og kompleksitet. En del vanilje springer frem, og der er tydelige sherry-noter. Eftersmagen er blid og olieret – og med mere af det hele. Kan med stor fordel iltes inden den nydes. Barbados-rom med charme, dybde og papegøjen, der ved, den sidder på noget godt. Leveres i flot gaveæske. Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Doorly&#8217;s Fine Old Rum 14 YO Barbados', 'https://spitus.dk/product/doorlys-fine-old-rum-14-yo-barbados/', 595, true, 70, 48, 'https://spitus.dk/wp-content/uploads/2024/10/Doorlys-Fine-Old-Rum-14-YO-Barbados.png', 'Doorly’s 14 YO er skabt på det ikoniske Foursquare Distillery på Barbados, hvor rom ikke bare produceres – den formes, forfines og perfektioneres. Foursquare ligger i en gammel sukkerfabrik på Barbados, og kan dateres tilbage til 1820. Efter en total renovering i 1995-1996, fremstår destilleriet i dag moderne og effektivt, samtidig med at man har holdt fast i det gamle håndværk og de game traditioner. Moderniseringen har bl.a. betydet, at man i dag er 100% miljøcertificerede, og faktisk betegnes som et af de mest miljøvenlige destillerier i verden. Det var først i 1906 hvor Rum Duty Act blev vedtaget, at rom-produktionen begyndte at tage fart, og Doorly’s var den første lokale rom overhovedet der blev solgt uden for Barbados. I overensstemmelse med god Barbados-tradition, er der ikke tilsat sukker for at søde rommen. Doorly’s bruger både pot stil og kolonnekedel destillering i deres rom, og du får et godt mix af sødme, volumen og autensitet. De 48% alkohol er også med til at fyre op for varmen. Denne Doorly’s 14 års blev noget af en kendis og darling, ikke mindst i Danmark, da Romhatten v. Mads Heitmann i 2022 simpelt hen kårede den til ”Årets Rom”. Den blev så også lige kåret til ”Rum of The Year 2022” af både The Whisky Exchange og af The Fat Rumpirate. Så jo; der er tale om en anmelderdarling af rang. Primært lagret i brugte bourbon fade, men den har også fået lov til at hvile i brugte Madeira fade, hvilket naturligvis tilføjer en sublim sødme i drammen. I næsen tofee, vanilje, frugter og en anelse ingefær. I ganen appelsiner, egetræ, rosiner, kirsebær og vanilje. Herlig mundfølelse. I eftersmagen får du kanel, vanilje, fudge og vilde bær. Og papegøjen på etiketten? Den ser ud som om, den har været med hele vejen og godkendt hver eneste dråbe. Lækker og meget populær rom, der viser noget af det bedste Barbados kan til prisen. Leveres i flot gaveæske. Alkohol % : 48,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Doorly&#8217;s Fine Old Rum 12 YO Barbados', 'https://spitus.dk/product/doorlys-fine-old-rum-12-yo-barbados/', 399, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2024/10/Doorlys-Fine-Old-Rum-12-YO-Barbados.png', 'Doorly&#8217;s Rum 12 YO er skabt på det legendariske Foursquare Distillery, hvor rom ikke bare laves – den perfektioneres. Foursquare ligger i en gammel sukkerfabrik på Barbados, og kan dateres tilbage til 1820. Efter en total renovering i 1995-1996, fremstår destilleriet i dag moderne og effektivt, samtidig med at man har holdt fast i det gamle håndværk og de game traditioner. Moderniseringen har bl.a. betydet, at man i dag er 100% miljøcertificerede, og faktisk betegnes som et af de mest miljøvenlige destillerier i verden. Det var først i 1906 hvor Rum Duty Act blev vedtaget, at rom-produktionen begyndte at tage fart, og Doorly’s var den første lokale rom overhovedet der blev solgt uden for Barbados. Hvis du tror, at en papegøje på en romflaske betyder, at indholdet er for sjov, så tager du fejl. Doorly’s 12 Years Old er nemlig alt andet end en gimmick. Det her er Barbados-rom i topform – lagret, afrundet og så elegant, at selv papegøjen på etiketten ligner én, der ved, den sidder på noget særligt. I overensstemmelse med god Barbados-tradition, er der ikke tilsat sukker for at søde rommen. Doorly’s bruger både pot stil og kolonnekedel destillering i deres rom, og du får et godt mix af sødme, volumen og autensitet. I denne Fine Old 12-års, er der anvendt ca. 90% kolonnedestilleret rom, og ca. 10% pot stil destilleret rom. Efter blendingen, genlagres det på spanske egefade, som tidligere har huset Oloroso sherry. Denne efterlagring er meget vigtigt her, og sætter sit tydelige præg på slutproduktet. I næsen bourbonnoter, rødvin og smørkage. En del kiwi og frugter der bringer friskhed til næsen. I ganen gylden sirup, kanel og ristede noter. En anelse sprittet, og du kan med fordel lade den få godt med ilt – gerne 15-20 minutter i glasset! Appelsiner og sherry-noter blander sig. I eftersmagen sødlig, med creme brulée, cedertræ og et krydret strejf af røde chili. Glimrende rom i en drikkevenlig stil., men husk iltningen! Leveres i flot gaveæske. Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Caribbean Triple Aged 5+5 år', 'https://spitus.dk/product/dos-maderas-caribbean-triple-aged-55-aar/', 389, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/10/Dos-Maderas-Caribbean-Triple-Aged-55-aar.png', 'Dos Maderas-huset blev grundlagt tilbage i 1877 af Sir Alexander Williams, der var en stor beundrer og connaisseur af sherry, og af Arthur Humbert, der var en fremragende international forretningsmand. Williams &amp; Humbert har siden vundet stor anerkendelse for deres sherry, brandy og rom. I denne Dos Maderas 5+5 Years Old, udvælger Master Blenderen rom fra Barbados og Guyana, hvorefter den lagres 5 år i Caribien. Herefter sejles den over Atlanten til Williams &amp; Humbert i Spanien, hvor anden del af lagringen begynder. Først får den 3 år på ryggen i egetræsfade, der tidligere har været brugt til at modne den respekterede Dos Cartados Oloroso sherry. Den tredje lagring foregår 2 år i fade fra den tungere og mere fyldige ”Don Guido” Pedro Ximenez sherry. (Begge sherry fade indeholdt over 20 år gammel sherry). Hvis flasker kunne få bonuspoint hos flyselskaber, ville Dos Maderas 5+5 altså være guldmedlem for længst det er en globetrotter i glasform. Når du åbner flasken, bliver du mødt af en duft, der er så indbydende, at du næsten overvejer at bruge den som duftlys. Masser af sherry-noter; rosiner og fad. I munden mere sherry, dadler, figner, vanilje og en dejlig sødme. Fornem og lækker, lang eftersmag. 5+5 er ikke bare smart markedsføring. Det er en opskrift. Har bl.a. taget Guldmedalje ved International Rum Expert Panel i 2010. Vi sælger den her inklusiv en fin gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Atlantic Rom', 'https://spitus.dk/product/dos-maderas-atlantic-rom/', 299, true, 70, 37.5, 'https://spitus.dk/wp-content/uploads/2024/10/Dos-Maderas-Atlantic.png', 'Dos Maderas betyder ”2 slags træ” på spansk, og der henvises naturligvis til lagringsmetoden for disse fine rom. Denne Dos Maderas Atlantic er første gang udgivet i 2024, og består af en blanding af 5-årig rom fra Barbados og 5-årig rom fra Guyana (lagret på bourbon-fade). Efter de 2 rom er mixet, transporteres rommen til Jerez i det sydlige Spanien, hvor den får 1 år mere på brugte Pedro Ximenez sherryfade. Dos Maderas er kendt for at lave rom, der rejser mere end de fleste mennesker. Atlantic Rum starter sin rejse i Caribien, hvor den destilleres og lagres i varme omgivelser, der giver den sin søde, tropiske karakter. Men den stopper ikke der. Nej, den sejler videre over Atlanterhavet til Spanien, hvor den får lov at modne videre på sherryfade – og det kan smages. Det er som om, rommen har været på dannelsesrejse: Den starter ung og frisk i Caribien og vender hjem som en moden, selvsikker og charmerende gentleman i Jerez. Efterlagringen på sherry-fadene, tilføjer noget sødme og blødhed, til den eller korpulente rom. Med dens gylden nuance, der minder om en solnedgang over Atlanterhavet, fanger den allerede opmærksomheden i glasset. Livlige noter af krydderier, karamel og ristede nødder, henfører dig til de frodige landskaber i dens transatlantiske oprindelseshistorie – i hvert fald for en stund. Herlig prisvenlig rom, der bl.a. har vundet Meininger’s ISW Blended Rum of the Year 2024. Nyd den rent, eller mix din favorit cocktail. Prøv også: Atlantic Berry Breeze: 5 cl. Dos Maderas Atlantic 10 cl. Wild Berry tonic vand 6-8 friske hindbær Isterninger Myntekvist til pynt Sådan tilbereder du en Atlantic Berry Breeze: Fyld et highball-glas med isterninger. Hæld Atlantic over isen. Tilsæt de Wild Berry tonic vand. Bland forsigtigt de friske hindbær i glasset. Rør forsigtigt rundt. Pynt med en kvist mynte. Værsgo’ Eller, hva&#8217; med: Atlantic Apple Splash 5 cl. Dos Maderas Atlantic 10 cl. naturlig æblejuice Stænk af club sodavand/danskvand Isterninger Æbleskive til pynt Sådan tilbereder du en Atlantic Apple Splash: Fyld et højt glas med isterninger. Hæld Atlantic og æblejuice over isen. Rør godt for at kombinere. Top med et stænk club sodavand for en brusende finish. Pynt med en frisk æbleskive på kanten af glasset. Alkohol % : 37,5 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Kraken Unknown Deep', 'https://spitus.dk/product/kraken-unknown-deep/', 389, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/10/Kraken-Unknown-Deep-1.png', 'Kraken er et velkendt mærke i romverdenen, berømt for sin anderledes flaske og egen smag. Den er navngivet efter det legendariske havmonster kendt som Kraken. Ifølge gamle historier ville dette monstrøse væsen angribe skibe og trække dem ned i havets dyb. Og lad os være ærlige: Hvis Kraken virkelig eksisterede, ville den helt sikkert drikke den her rom. Eller beskytte den. Eller kæmpe for den. For flasken er lige så ikonisk som navnet – mørk, dramatisk og med et markant design. Etiketten på flasken viser en illustration af selve Kraken. Helt så voldsom er selve smagen nu ikke. Langtfra. Fremstillet i Trinidad og Tobago, efter gode, gamle og traditionelle produktionsmetoder. Men; denne udgave, Kraken Unknown Deep er en Limited Edition, og derfor er alt ikke som det plejer. Der anvendes en kombination af kolonne- og pot-stills, for at skabe en blanding, der er både blød og smagfuld. Til sidst får den nogle år på ryggen i egetræsfade. I næsen karamel, krydderier og en anelse nød. I munden vanilje, nellike, muskatnødder, karamel og farin. Ret krydret i finishen. Smagfuld, og en dram, der kombinerer det bedste fra mørk og gylden rom. Alkohol %: 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Deadhead Chocolate Rom-likør', 'https://spitus.dk/product/deadhead-chocolate/', 449, true, 70, 35, 'https://spitus.dk/wp-content/uploads/2021/12/deadhead-dark-chocolate.jpg', 'Okay; flasken må siges at være let genkendelig, og du har sikkert lagt mærke til den. Den er udformet som et såkaldt ”Shrunken Head”, som gik ud på, at man tog hovedet fra ens fjender som trofæ &#8211; for blod, ære og åndelig fornyelse. Hyggeligt, og allerede der ved du, at du ikke har købt en almindelig fætter. Du har tilkaldt en spiritus med personlighed, attitude og muligvis en forbandelse eller to. Hvis Indiana Jones havde en yndlingslikør, ville det være denne. Det er mørk magi i voodoo-flaske og dessertforklædning. Deadhead Chocolate er den rombaserede spiritus, der føles som at få et hemmeligt chokoladekys fra en mexicansk rompirat. Den ikoniske shrunken‑head‑flaske lover noget vildt – og indholdet leverer: en syndigt lækker fusion af rom, kakao og tropisk sødme. Ved åbning bliver næsen overfaldet – på den søde, samtykkende måde – af intens kakao, vanilje, mokka og en anelse tørret frugt. Det føles lidt som at åbne en æske luksus chokolade med hemmelig adgang til underverdenen. Smagen er cremet, rund og uimodståeligt dessertagtig med dybe noter af mørk chokolade, karamel, vanilje og et strejf af krydret romvarme. Det er som om nogen har smeltet en chokoladebrownie og blandet den med en pirats tåre og lidt kaffe. Det er sødt, men ikke kvalmende. Mere til dessertbordet end cigarerne. Der er noter af mørk kakao, kanel, ristede nødder, flødekaramel, men også kirsebær, nelliker, vanilje og eg, samt en diskret antydning af brændt sukker og tropisk oprør. Eftersmagen er lang, som et voodoo-ritual, men noget mere venlig. Den bliver hængende med sødme og varme, og man kunne sagtens finde på at bruge den i stedet for Baileys i en kaffe – eller bare som flydende chokoladekram efter en dårlig dag. Den er ikke kvalm, bare farligt drikkevenlig. Perfekt til cocktails, kaffe, desserter, over is – eller bare som en lille “nu forkæler jeg mig selv”-skænk. Deadhead Chocolate: Når spiritus og chokolade går full‑on voodoo. Deadhead Chocolate er for dig, der synes, din dram godt må smage af dessert og lidt af Halloween. En sjov, skæv flaske fuld af flydende humør. 92 point og Guldmedalje &#8211; ved International Spirits Competition 2017. NB! Dette er ikke udgaverne lavet i plastic 😉 Alkohol % : 35,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO 1888 Copenhagen m/2cl NPU Very Rare', 'https://spitus.dk/product/a-h-riise-xo-1888-copenhagen-m-2cl-npu-very-rare/', 349, true, NULL, 40, 'https://spitus.dk/wp-content/uploads/2024/10/A.H.-Riise-XO-1888-Copenhagen-m_2cl-NPU-Very-Rare.png', 'A.H. Riise XO 1888 Copenhagen er den nye navngivning af den tidligere udgave A.H. Riise 1888 Copenhagen Gold Medal. Historien lyder, at A.H. Riise var nødt til at fjerne &#8220;Gold Medal&#8221; navnet, for at kunne sælge flasken på det Amerikanske marked, hvor en &#8220;guld-medalje&#8221; skal kunne dokumenteres hvis de ville undgå at blive sagsøgt &#8211; Copenhagen Gold kan nemlig &#8220;kun&#8221; bryste sig af, at have vundet en første plads, men ikke en guldmedalje! Og lidt om historien bag flasken: København var i 1888 vært for den store Nordiske Industri-, Landbrugs &amp; Kunstudstilling, og A.H. Riise deltog på udstillingen med sin Vestindiske rom, hvor den vandt en første plads. Denne A.H. Riise XO 1888 Copenhagen Gold er genskabt som en hyldest, og er efter den oprindelige opskrift fra dengang. &#8220;1888&#8221; er et nøje udvalgt premium-blend af helt op til 21 år gammel rom fra Vestindien og Centralamerika, og ingen rom er yngre end 7 år. Farven er rav, og i næsen får du vanilje, abrikos, læder og honning. I munden rammes du af tørrede, eksotiske frugter og krydderier. Eftersmagen er lang, og det sødlige vanilje-touch fra fadene er tydeligt, og efterlader dig med et smil om munden. Dommerne kaldte den i 1888 for ”ypperlig”, og er du til dram i den søde stil, er A.H. Riise det mest populære valg i Danmark overhovedet. A.H. Riise vil gerne promovere deres eksklusive Non Plus Ultra Serie, og i denne version får du en smageflaske med i æsken indeholdende 2 cl. Non Plus Ultra Very Rare. Lækkert og flot sæt, og naturligvis oplagt som gave til rom-elskeren. Alkohol % : 40,0 Størrelse : 70+2 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Single Vintage Rum 2008', 'https://spitus.dk/product/diplomatico-single-vintage-rum-2008/', 989, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2024/09/diplomatico-2008-single-vintage.png', 'Venezuelanske Ron Diplomatico er et af de absolut mest kendte rom-huse i Danmark – og i verden. Dette skyldes ikke mindst deres udgivelse Diplomatico Reserva Exclusiva, som er blevet en gedigen stor-basker. God rom til pengene, men mere hype er der omkring brandets årsudgivelser – Single Vintage. Vi præsenterer her den blot den ottende udgivelse i single vintage-serien. (Tidligere udgivet i høstårene 1997, 2000, 2001, 2002, 2004, 2005, 2007 og så altså denne 2008 som kom på markedet i sommeren 2024). Der er de flasker som der er, og de bliver traditionelt revet væk. De tidligere årgange er auktionsklassikere, og indbringer traditionelt høje beløb. Nå men, rom er skabt for at blive drukket, og heldigvis smager den fremragende! De mange år i subtropisk klima, på først brugte bourbon-fade, og efterfølgende på ryggen i brugte oloroso-sheery fade fornægter sig ikke. Det er et stykke flydende historie, destilleret i Venezuela, modnet med tålmodighed og tappet med en næsten kongelig værdighed. Hvis rom kunne gå på den røde løber, ville denne her ankomme i smoking og stjæle al opmærksomheden. 2008 var året, hvor verden stadig troede på MySpace, og hvor vi alle sammen gik rundt med alt for store solbriller. Men vigtigere: Det var året, hvor Diplomático lagde noget af deres bedste rom på fad. Og de har ikke haft travlt – tværtimod. Denne rom har fået lov at hvile, modne og udvikle sig i årevis, indtil den var præcis, som mesterdestillatørerne ønskede. I næsen en kompleks buket af aromaer med noter af tørrede frugter, træ, vanilje og karamel. Alt andet end beskedent. I munden brun farin, dadler og brownie. Der er masser af punch, og det hele er i overlegen fin balance. Overdådig. Leveres i gaveæske. Alkohol %: 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('The Rum Factory 7 Y.O. Elixir', 'https://spitus.dk/product/the-rum-factory-7-y-o-elixir/', 279, false, 70, 34, 'https://spitus.dk/wp-content/uploads/2024/06/The-Rum-Factory-7-Y.O.-Elixir.png', 'Albert Michler Distillery, er en af de mest kendte og ældste uafhængige aftappere indenfor rom. Historien går tilbage til midten af det 19. århundrede, og deres mål er at skabe unikke blends og fadlagringer, ligesom man kender det inden for whisky. Ambitionen er, at bringe en individuel og kreativ stil ind i hver eneste flaske de udgiver. Her præsenterer vi deres The Rum Factory 7 års Elixir, som ikke er en rom pga. sukkerindholdet og den lavere alkoholprocent, men som er fremstillet og lagret som en rom. Der er tale om et blend fra Panama, som er modnet i 7 år på hvide egetræsfade. Nogle romtyper forsøger at være så komplekse, at man næsten skal have en doktorgrad i kemi for at forstå dem. Ikke denne her. The Rum Factory 7 Y.O. Elixir er som den ven, der altid får dig til at grine, men som samtidig kan overraske dig med en dyb og charmerende personlighed. Den er lagret i syv år – længe nok til at blive voksen, men stadig ung nok til at have det sjovt. Det er klassens svar på en 25-årig med fast job, men som stadig tager i byen torsdag aften. The Rum Factory 7 Y.O. står flot med en strågul farve. I næsen meget sød, med vanilje, banan og creme brulee. I munden er denne premium-elixir cremet og smøragtig, med tydelige noter af karamel, vaniljesukker og tørrede frugter. Fuldfed eftersmag, med rosiner, eksotiske frugter og en anelse fad og flormelis. Det er en sød drik, og der er næsten tale om en dessert på glas, eller som en nyåbnet pose frugtvingummier. Mange er faldet for The Rum Factory Elixir, netop pga. dens sødme, og elsker den til desserter, eller som ren meditation. Voksen fredagssnoller på flaske. Alkohol % : 34,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('The Rum Factory 15 Y.O.', 'https://spitus.dk/product/the-rum-factory-15-y-o/', 379, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2024/06/The-Rum-Factory-15-Y.O.png', 'The Rum Factory 15 fra Panama har brugt mere tid på at modne end de fleste af os bruger på at beslutte, hvad vi skal se på Netflix. I hele 15 år har den ligget og hygget sig på nøje udvalgte fade, hvor den har suget alt det bedste til sig: varme krydderier, sødmefulde noter og en dybde, der får selv erfarne romnørder til at nikke anerkendende. Du får en rom, der er blød som fløjl, men stadig med nok kant til, at du kan mærke, du drikker noget med personlighed. Det er som at få et fast håndtryk fra en gammel sømand, der har set lidt af hvert – men stadig har et glimt i øjet. Du får en smuk mahognifarvet rom med masser af blød vanilje i næsen, inden karamel, ristet egetræ og kanel blander sig. I munden ret fyldig med eksotiske frugter, kokosnød, ananas og blommer, samt et hint af brun farin, chokolade og kaffe. En lang og lækker eftersmag af karamel, mørk chokolade og en anelse sødlig tobaksrøg. Det her er ikke bare en flaske, du gemmer bagerst i barskabet til svære tider. Det er den slags rom, du stiller frem på bordet med et lille smørret grin og siger: “Smag lige det her.” Og så ser du dine gæsters øjne lyse op, som om de netop har fundet ud af, at der er rabat på ferie til Maldiverne. Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('The Rum Factory 10 Y.O.', 'https://spitus.dk/product/the-rum-factory-10-y-o/', 298, true, 70, 41, 'https://spitus.dk/wp-content/uploads/2024/06/The-Rum-Factory-10-Y.O.png', 'Denne The Rum Factory 10 years er produceret af Bodega de America S.A. i Panama, og har fået lov til at lagre i mindst 10 år på amerikansk egetræ. Der er tale om en traditionel melasse-destilleret rom, der har været igennem et Kolonne-system, og aftappet ved 41% alkohol. The Rum Factory kombinerer tradition, håndværk og tropisk lagring, og det kan smages. 10‑års udgaven er et bevis på, at man ikke behøver være 20+ år gammel for at være både kompleks og charmerende. Mørk ravfarve i glasset og med en meget lokkende duft af sødmefuld sirup, figner, bananer og en anelse brændt egetræ. I munden smøragtig, med mandler, karamel og kokosmakroner. En anelse frugt blander sig, før den i finishen lukker med et touch af peber og lette krydderier. Sødlig, og meget let drikkelig sag der bare smager godt. Alkohol % : 41,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Tasting Collection Rom 6&#215;2,5cl', 'https://spitus.dk/product/tasting-collection-rom-6x25cl/', 329, true, 5, 42.3, 'https://spitus.dk/wp-content/uploads/2024/06/Tasting-Collection-Rom-6×25cl.png', 'Skal du arrangere en eksklusiv rom-smagning? Eller måske forkæle en rom-elsker med et flot rom-sæt der sætter en stopper for de bløde pakker? Her får du 6 lækre og kendte rom, inkl. et hæfte med beskrivelser af de enkelte produkter (engelsk tekst). Sættet indeholder 2,5 cl. af hver: Ron Barceló &#8211; Imperial Onyx Appleton Estate – Signature Blend El Dorado – 8 years Goslings – Black Seal Abuelo – 12 years Gran Reserva Ron Cólon – High Proofed Aged Rom Altså lutter anerkendte rom. Og når du har fundet din favorit, har den sikkert i en større flaske et andet sted på Spitus.dk. (Skal du bruge mange sæt så kontakt os, og vi får dem hurtigt hjem fra producenten). Alkohol % : 42,3 Størrelse : 6&#215;2,5cl / 15 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Plantation Sealander', 'https://spitus.dk/product/plantation-sealander/', 368, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/06/Plantation-Sealander.png', 'Plantation Rom sejler rundt. Altså mellem alle de store romproducerende øer, hvor de søger efter de bedste blends. Det har de gjort i 25 år, og det fejrer de ved at udgive en ny rom ved navnet Sealander. Ret opfindsomt. I denne Plantation Sealander er der anvendt rom fra 3 af de allerstørste rom-øer: Mauritius, Fiji og Barbados! Så rammer vi også lige 3 Verdenshave: Atlanterhavet (Barbados), Stillehavet (Fiji) og Det Indiske Ocean (Mauritius) – og man må sige at den har gjort sig fortjent til navnet. Det her er rommens svar på et tropisk samarbejde: en trio af smage fra Barbados, Fiji og Mauritius , samlet i én flaske, der smager som en ferie, du ikke vil hjem fra. Rommen fra Mauritius er lavet på frisk sukkerrørssaft, mens de to andre er lavet på melasse. De har fermenteret i 3 dage til 3 uger og derefter destilleret på enten pot still eller kolonne still. De har lagret i adskillige år på bourbon i tropisk klima, inden de (som traditionen byder for Plantation-rom) kommer til Frankrig og lagrer et ekstra år på Ferrand cognac-fade. Det endelige blend doseres med 20 gram sukker/liter inden aftapningen på flaske. Den anvendte rom er altså ret forskellige, men sammen udgør de en fin harmoni, og balancerer faktisk overraskende godt. Farven er rav. Næsen åbner med en blid og fyldig aroma, der indeholder noter af pære, kvæde og stikkelsbær, samt antydninger fad. I munden en rig og fyldig smag med hints af kløverhonning, lakrids, bivoks, vanilje og svesker. Eftersmagen er lang og vedvarende med noter af bagte æbler, tonkabønner og tørrede bananer. Moderat sød. Spændende udgivelse fra Plantation – der trods navnet ikke smager af sømand og havtang. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador 16 Years Old Icon Reserve Colombian Rum', 'https://spitus.dk/product/dictador-16-years-old-icon-reserve-colombian-rum/', 499, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/06/dictador-16-yo.png', 'En nyere udgivelse fra Columbianske Dictador. Som alle flaskerne i Distileria Colombiana-serien, er Dictador 16 ans en traditionel solera-lagret rom, hvor Masterblenderen kombinerer gamle og yngre rom i et flerfadssystem, så man får friskheden fra de yngre, og robustheden fra de ældre. Dictador 16 Old Icon Reserve er destilleret fra melasse på et Column Still, og flasket ved 40% alkohol. Dictador er kendt for deres mørke, rige og silkebløde udgivelser – og 16‑årgangen er ingen undtagelse. Den er lagret i solens varme, i fade der giver karakter, og med en finesse, der gør den til en af de mest populære flasker i serien. Næsen er meget mørk, og ret kraftig. Kaffe, ristede nødder og karamel. Den bitre, overkogte karamel afbalanceres af en vis cremethed, som meget ristet brød, hvis krumme er forblevet blød. Det mørke forsvinder noget ved iltning. I ganen pænt afbalanceret. Man kunne have forventet et nådesløst stormløb af grillede, ristede og endda brændte noter, men en vis rundhed korrigerer alt dette mørke. Resultatet er en meget velsmagende sag med nødder, sherry og fad. I finishen fortsætter nødderne, for det meste pekannødder, og med et strejf af sød karamel. Dictador 16 Old Icon Reserve er Colombias svar på en smooth talker: rolig, dyb og med en charme, der rammer dig, før du når at sige “skål”. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise old St. Croix XO Reserva Explorer (Denmark Edition)', 'https://spitus.dk/product/a-h-riise-old-st-croix-xo-res/', 599, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/06/ahr-st-croix-explorer-k.png', 'A.H. Riise Old St. Croix XO Reserva Explorer Denmark, er den ene af de 10 nye i den eksklusive Explorerer-serie. Udgivet d. 2. august 2024. Flasken er en hyldest til de modige forskere og opdagelsesrejsende, som tilbage under A.H. Riises tid, bidrog til kortlægningen og forståelsen af verden. Eventyrerne tilsidesatte egen sikkerhed og rejste ud i verden, og det hyldes nu af A.H. Riise med en serie af skønne flasker. XO Explorer-serien består af en række Limited Editions, der udkommer i en række forskellige lande i begrænsede antal nummererede flasker. Hver Edition er skabt specielt til A.H. Riises mange fans og samlere i de forskellige lande, hvor de lokale pionerer var forgangsbilleder for at søge ny viden og sætte deres nation på landkortet, nøjagtig som A.H Riise gjorde. Denne danske Old St. Croix XO Explorer, som er lavet i et oplag på kun 6.960 nummererede flasker, er et eksklusivt Limited Edition-blend fra Vestindien og Mellemamerika, sammensat af A.H. Riises master blender. Duft: Karamel og moden frugt. Fudge og en anelse portvin. Smag: Meget kraftig umami fra egetræ, tobak og gammelt læder. Sødmen leder tanken hen på brændte figner og kandiseret citrusskal. Eftersmag: Finishen er dyb og langvarig, domineret af gammelt egetræ og tørret frugt. Hvis Indiana Jones drak rom (og lad os være ærlige – det gjorde han helt sikkert), så ville han have en flaske A.H. Riise Old St. Croix XO Reserva – Explorer i bæltet. Det her er nemlig ikke bare en god dram. Det er en billet til en smagsrejse, der starter i Caribien og ender i ren lykke. A.H. Riise Old St. Croix XO Reserva Explorer leveres selvfølgelig i den kendte og flotte &#8220;A.H. Riise&#8221; gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Isfjord Premium Arctic Rum', 'https://spitus.dk/product/isfjord-premium-arctic-rum/', 385, false, 70, 44, 'https://spitus.dk/wp-content/uploads/2024/05/isfjord-rum.jpeg', 'Isfjord er et dansk spiritus-brand, som oprindeligt producerede en række premium spiritusser baseret på smeltet, Grønlandsk indlandsis. (Grønlandsk indlandsis har en TDS (Total Dissolved Solids) på under 5 ppm. Dette er den absolut laveste TDS for noget vand i verden). I dag er der begrænsede mængder ægte, smeltede isbjerge i produkterne, for indlandsisen er truet af den globale opvarmning, og det er ikke bæredygtigt at transportere vand over så lange afstande. Derfor har Isfjord investeret i et vandrensningsanlæg, der skal producere og rense vandet, så det matcher vandprofilen fra de grønlandske isbjerge. Der bruges stadig grønlandsk vand i produkterne, men det meste vand stammer fra eget anlæg. Stadigvæk med fokus på at ramme den unikke glathed og smag, der er så karakteristisk for ISFJORD-produkter. Denne Premium Arctic Rom, er destilleret i Saint Croix, Caribien. Med en perfekt balance mellem sol og varme, tilbyder Saint Croix de bedste betingelser for at sikre det rigtige niveau af sødme og kvalitet i sukkerrørene &#8211; fundamentet til Rom af høj kvalitet. Fadlagret i brugte bourbon-fade, og nedvandet med Isfjord vand til 44% alkohol. Selvom navnet skriger frostgrader, så er smagen alt andet end kold. Isfjord Premium Arctic Rum er en rom, der glider ned som silke og efterlader en varme, der føles som at sidde i en hytte med ild i pejsen. Den perfekte kombination af varme fra Caribien og den arktiske kulde samles i denne lækre udgivelse. Let krydret, med mørk chokolade, dadler og fadpræg. Sød og mørk i stilen, men med Isfjords karakteristiske smoothness. Alkohol % : 44,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Millonario Kuytchi', 'https://spitus.dk/product/millonario-kuytchi/', 295, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/06/Millonario-Kuytchi.png', 'Hvis du nogensinde har tænkt: “Gid der fandtes en drik, der både var farverig, eksotisk og smagte som ren glæde,” så har Millonario Kuytchi allerede svaret dig – på perfekt peruviansk vis. Kuytchi er Inkaernes Regnbuegudinde, og det giver mening. Det her er nemlig en dram, der føles som at drikke solskin, farver og god energi på én gang. Millonario er i forvejen kendt for deres søde, bløde og uimodståelige udgivelser – men Kuytchi tager det hele et skridt videre. Det er som om destilleriet har sagt: “Lad os lave noget, der både smager fantastisk og ser ud som en fest.” Og det har de gjort. Millonario Kuytchi er en flaske, der ikke er bange for at være lækker. Den er sød, rund og fyldt med frugtige noter, der gør den til en ren fornøjelse fra første tår. Du får toffee, karamel, vanilje og eksotiske krydderier. Dejlig afbalanceret, og faktisk ikke over-sød. Fløjlsblød som solen og naturen i Peru, og meget nemt at gå til. En oplevelse som et regnbue-kys fra Andesbjergene, Hos Spitus.dk står denne farverige peruvianske skønhed klar til dig. Klik den hjem, skænk et glas, og lad Kuytchi minde dig om, at livet bliver lidt bedre, når der er farver – og god dram – involveret. Perfekt all-round rom, til at nyde rent eller i din favorit cocktail. Alkohol % :40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Rare Rums &#8211; Port Mourant 1999-2020 21 år, 50 cl', 'https://spitus.dk/product/rum-nation-rare-rums-port-mourant-1999-2020-21-aar-50-cl/', 1675, true, 50, 58, 'https://spitus.dk/wp-content/uploads/2024/05/Rum-Nation-Rare-Rums-–-Port-Mourant-1999-2020-21-aar-50-cl.png', 'Hvis romverdenen havde en “boss fight”, så ville Port Mourant 21 år være den. Det her er ikke en sød, blød hyggerom. Det er en kraftfuld, historisk og kompromisløs rom fra et af verdens mest ikoniske destillerier. Rum Nation har håndplukket denne single cask‑perle fra Guyana, destilleret i 1999 på det legendariske Port Mourant double wooden pot still – et destillationsapparat lavet af massivt træ, som har været i brug siden 1700‑tallet. Den får tårerne frem i øjnene på rom-kendere. Den er kendt og elsket for at give masser af power og præsenterer Demerara-rom på aller, aller bedste vis. Destilleret i 1999 hos Diamond Distillery i Guyana, hvor den også fik de første mange års lagring i brugte bourbon-fade i det tropiske klima, før den overnattede de sidste 5 år i brugte sherryfade hos italienske Rossi &amp; Rossi. I alt 21 år til at suge til sig og modne, og tappet ved 58% alkohol (ABV) i i alt 868 nummererede flasker. En klasse-rom, rig på estere, læder, lavendel, mokka, lakrids og røde bær. Ron Nation’s ”Rare Rums” serie er udgivet for at vise hvad de forskellige geografiske områder kan præstere af unikke og karakteristiske rom. Rare Rums‑serien er Rum Nations legeplads for de helt særlige fade – og denne Port Mourant er en af de mest eftertragtede. Her får du ikonerne Port Mourant, Diamond, Demerara og Guyana mokket ned i en eksklusiv flaske. Det kan kun blive godt – og det er det! Bemærk: udgives alene i 50cl. størrelse. Alkohol % : 58,0 Størrelse : 50 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario Reserva de la Familia 18 Selección Premium', 'https://spitus.dk/product/rom-ron-centenario-reserva-de-la-famillia/', 519, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/09/100241-Cen-18.jpg', 'Denne mørke og herlige Ron Centenario Reserva de la Familia 18 års burde gå med smoking og tiltales &#8220;Señor&#8221;. Den kommer fra Costa Rica, og det mærkes – der er sol, sukkerrør og tropisk charme i hver en dråbe. Flasken ligner noget, du stiller frem for at imponere svigerfar, men drikker i smug selv. Etiketten lyder “Reserva de la Familia”, og det forpligter – hvis denne rom er familiens arv, så håber vi, de har mange børn, for det her vil man gerne arve. Der er tale om et nøje sammensat blend, der har modnet på amerikanske egefade i op til 18 år (yngste destillat er 6 år) i et traditionelt solera-system. Ron Centenario 18 Reserva de la Familia 18 produceres nemlig, som efterhånden meget andet rom, efter den såkaldte solera-metode, der har været kendt i spansk sherryproduktion, men som altså har bredt sig til romproduktion. I næsen får du med det samme fornemmelsen af, at der er tænkt over tingene. Masser af sødme: brun farin, tørret frugt, vanilje og et elegant pift af egetræ og tobak. Det hele suppleres med en krydret undertone. Muskatnød og de mange krydderier skiller sig ud – som en dessert serveret af en butler med skæg. Smagen følger trop: cremet og blød som en velpolstret lænestol. Der er noter af karamel, rosiner, appelsinskal og lidt kanel, som var rommen gået i julehumør midt i en tropisk sommer. Alkoholprocenten på 40% holder det hele civiliseret – den skubber ikke, den inviterer dig pænt indenfor. Valnødder og ristede kaffebønner giver den laaange finish en lækker bitterhed. Lidt som en bedstefar med lommelærke og gamle røverhistorier. Denne udgivelse er en special-variant (limited edition) i stærkt begrænsede mængder (og udsolgt fra destilleriet). Ron Centenario 18 Reserva de la Familia, som kan (bør) nydes rent eller med is, er et fremragende alternativ, hvor du får utrolig meget rom for pengene. Spitus synes: Ron Centenario 18 er til dig, der gerne vil drikke rom med stil, uden at det bliver for tungt eller højtideligt. Den er sofistikeret, men stadig til at forstå – lidt ligesom at se James Bond danse salsa Super elegant flaske og gaverør, gør den oplagt som gave til rom-kenderen. Størrelse : 70cl Alkohol % : 40,0 Land: Costa Rica');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Chairman&#8217;s Reserve Forgotten Casks', 'https://spitus.dk/product/chairmans-reserve-forgotten-casks/', 425, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/10/chairmans-reserve-forgotten-cask-k.jpg', 'D. 2 maj 2007 brændte en stor del af St. Lucia Destillers lagerbygninger, og man kæmpede med at redde så mange af fadene som muligt. De fade, som man kunne redde, blev man i hast nødsaget til at opbevare på forskellige andre lokationer. For nyligt fandt man så et af disse midlertidige små lagre, man havde glemt alt om, og da man fik smagt på indholdet og indset den høje, åbenlyse kvalitet, blev det besluttet at udgive disse som en ældre version af Chairmans Reserve og kalde den det, det er: The Forgotten Casks. Glemsomhed har aldrig smagt bedre! Det er altså stadig en ægte St. Lucia rom, som både er destilleret på en Coffey kolonne og gamle kobber-pot apparater, der efter modning i gamle bourbonfade fra Jim Beam, Jack Daniel’s og Buffalo Trace blandes sammen og derefter igen lagres på egefade. Det er en ”ren” rom, og der tilsættes ikke sukker, likør, sherry eller andre «forstærkende» elementer. Farven er mørk maghoni, og næsen er vanilje, rosiner, tobak, egetræ og honning. Smagen er sødmefuld med honning, vanilje, krydderier og træet, der går igen. Rommen er lidt mørkere end dens yngre søskende og mere raffineret. Det er som om hele Caribien har slået sig ned i din mund og besluttet sig for at tale med lav, forførende stemme. Der er dog lidt mere tobak og læder over denne end den originale Chairmans Reserve. St. Lucia Destillers producerer deciderede &#8220;best-value-for-money&#8221; rom, og dette er ingen undtagelse. Guld Medalje (Best in Class) – 2011 International Wine &amp; Spirits Competition. Spitus leverer den i en gaveæske. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Parce Rum 12 år', 'https://spitus.dk/product/parce-rum-12-aar/', 499, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/04/Parce-Rum-12-aar.png', 'Colombianske Parce Rum blev startet af brødrene Jim, Patrick og Brian Powers, sammen med deres colombianske ven, Jaime Uribe. Navnet Parce (udtales par-sey) betyder ”God Ven”, for ligesom venskaber, er god rom karakteriseret ved kærlighed, omsorg og tålmodighed. Master blender er Arthur Fernandes Domecq og dennes søn Brojen. Domecq-familien har igennem mere end 300 år repræsenteret noget af det ypperste indenfor master destillers. Primært kendte fra Sydspanien, hvor de har stået bag nogle af verdens bedste sherry og brandy. Parce efterlever deres motto; “One Bottle, One Tree”, ved at plante et træ i Colombias livsvigtige regnskov for hver flaske der sælges. Hver eneste dråbe af denne gudedrik har fået mindst 12 år i godt forkullede ex-bourbon fade fra Brown Foreman Whisky. Den er sød, den er krydret, den er er kompleks, den er mundvandsdrivende, den er forrygende. Mørk og gylden i farven. I næsen massive tørrede frugter, ristet eg, karamel og fudge. Fylder munden fuldstændigt, og prikker let på tungen af sød pibetobak og hvid peber. Lang finish med creme brûlee, karamel, dadler, sherry og ristede kaffebønner. En anelse orange og frugtsødme. De skriver selv, at det nok er den bedste 12-års rom i verden. Store ord, men anmeldelserne er nu også imponerende: 94 Point i Cigar &amp; Spirits Magazine 93 Point I Whisky &amp; Rom Magasinet 92 Point ved Beverage Tasting Institute 92 Point Tastings.com &#8220;Best Aged Rum&#8221; v. San Francisco World Spirits &#8220;Best Rum&#8221; v. New York International Spirits Competition “World Top 5 Rum under 100$&#8221; i Vinepair + et hav af guldmedaljer og andre kåringer. Et vanvittig godt røverkøb. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Parce Rum 8 år', 'https://spitus.dk/product/parce-rum-8-aar/', 379, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/04/Parce-Rum-8-aar.png', 'Colombianske Parce Rum blev startet af brødrene Jim, Patrick og Brian Powers, sammen med deres colombianske ven, Jaime Uribe. Navnet Parce (udtales par-sey) betyder ”God Ven”, for ligesom venskaber, er god rom karakteriseret ved kærlighed, omsorg og tålmodighed. Master blender er Arthur Fernandes Domecq og dennes søn Brojen. Domecq-familien har igennem mere end 300 år repræsenteret noget af det ypperste indenfor master destillers. Primært kendte fra Sydspanien, hvor de har stået bag nogle af verdens bedste sherry og brandy. Parce efterlever deres motto; “One Bottle, One Tree”, ved at plante et træ i Colombias livsvigtige regnskov for hver flaske der sælges. Denne Parce 8 Anos er et suverænt bevis på destilleriet høje niveau. Lagret fuldfad i 8 år på forkullede amerikanske egetræsfade, der tidligere har indeholdt Brown Foreman whisky, heraf 80% af deres kendte Jack Daniels. Blended af romdestillater fra Panama, Trinidad-Tobago og Guyana, hvor 80% stammer fra sukkerørsjuice og de resterende 20% fra melasse. Rommen opnår yderligere kompleksitet ved at blive destilleret på et mix af ”pot stills” af kobber og kolonnedestilleringsapparater af stål. Kobberfarvet med et gyldent skær. I næsen appelsiner, kirsebær, tørrede eksotiske frugter, egetræ, vanilje og sød tobak. Olieret og cremet i munden, med rige noter af vanilje, mørk chokolade, kandiserede frugter og en lille snert af læder og tobak. Fortjent vinder af en række blindsmagninger og kåringer, bl.a.: 93/100 points Tasting Panel Magazine 90/100 Whisky &amp; Rom: &#8220;Varm og krydret næse. Flot og elegant rom med orangenoter, let sødme og vanilje i smagen. Velbalanceret med en flot krydret afslutning.&#8221; Double Guld – New York World Wine &amp; Spirits Competition 2018 Guld – San Francisco World Spirits Competition 2015 Guld Packaging Design &#8211; San Francisco World Spirits Competition 2015 Guld – Ministry of Rum Tasting Competition 2012 Det her er rommen, der har fået tid nok til at blive klog, men ikke så meget tid, at den er blevet støvet. Den er som den ven, der både kan tage en seriøs snak og stadig danse hele natten. Denne topanmeldte rom rammer plet hos de fleste med sin diskrete sødme og afstemte krydderier. Decideret nam. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Parce Rum 3 year', 'https://spitus.dk/product/parce-rum-3-year/', 359, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2024/04/Parce-Rum-3-year.png', 'Colombianske Parce Rum blev startet af brødrene Jim, Patrick og Brian Powers, sammen med deres colombianske ven, Jaime Uribe. Navnet Parce (udtales par-sey) betyder ”God Ven”, for ligesom venskaber, er god rom karakteriseret ved kærlighed, omsorg og tålmodighed. Master Blender er Arthur Fernandes Domecq og dennes søn Brojen. Domecq-familien har igennem mere end 300 år repræsenteret noget af det ypperste indenfor master destillers. Primært kendte fra Sydspanien, hvor de har stået bag nogle af verdens bedste sherry og brandy. Parce efterlever deres motto; “One Bottle, One Tree”, ved at plante et træ i Colombias livsvigtige regnskov for hver flaske der sælges. Denne Parce 3 Anos er en gylden rom af høj kvalitet, aftappet ved 43% alkohol. Den udgør basisrommen i de prisvindende Parce 8- og 12 Anos. Hvis du tror, at en 3‑årig rom er en lille, uskyldig størrelse uden meget at byde på, så har du ikke mødt Parce Rum 3 Year endnu. Det her er nemlig rommens svar på den unge fyr til festen, der ser stille ud – men som viser sig at være både charmerende, sjov og overraskende god til at danse. Fuldlagret (dvs ikke solera-metoden her), på brugte bourbon-egetræsfade. Fuldfed oplevelse, med smørcreme, honning, rosiner, vanilje og karamel. Sødme og råstyrke nok til at være en oplagt makker i luksus cocktails, men kan naturligvis også sippes rent. Parce 3 Year er en rom, der er skabt til at være nem at elske. Den er ikke tung, ikke overdrevent sød og ikke fyldt med røg og drama. Den er bare… virkelig behagelig. Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cueva 1501 Solera 18', 'https://spitus.dk/product/ron-cueva-1501-solera-18/', 599, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/04/Ron-Cueva-1501-Solera-18.png', 'Med denne 18-års variant, er vi kommet i den tungere vægtklasse. Opholdet i solera-systemet med amerikanske ege, og gamle bourbon-fade, samt den høje gennemsnitsalder, betyder mere substans og elegance. I næsen ristet kaffe, modne frugter, Papaya og vanilje. I munden en snert af bourbon fra fadene, varme eksotiske krydderier, kakao, dadler og figner. Flydende eliksir. Lang finish med sød tobak, eg og cedertræ. Dejlig mundfølelse, og den sætter i den grad sanserne på overarbejde. Det er en rom, der føles som en rejse tilbage i tiden – bare uden risiko for pirater, skørbug eller dårlig navigation. Elegant flaske og tilhørende gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Black Tot Rum', 'https://spitus.dk/product/black-tot-rum/', 345, true, 70, 46.2, 'https://spitus.dk/wp-content/uploads/2024/04/Black-Tot-Rum.png', 'Denne rom er naturligvis navngivet efter den skæbnesvangre Black Tot Day, d. 31. juli 1970, som var dagen, hvor den britiske flåde for sidste gang gennemførte den flere hundrede år gamle tradition med daglige udskænkninger af rom. Én eller andet havde påstået, at håndteringen af atomubåde og krydsermissiler ikke matchede den daglige udskænkning af 7cl. stærk, navy rom. Politik når det er værst, og det forklarer måske, hvorfor de altid så så glade ud på gamle billeder. Selve rommen er naturligvis stærkt inspireret af denne navy-rom, og er nøje komponeret af master blender Oliver Chilton, som er kommet frem til en blanding af 40% 3-5 år gammel rom fra Guyana, 20% ulagret Guyana-rom, 35% 5 år gammel Barbados-rom, og 5% 3 år gammel jamaicarom. Så et ægte Caribbean blend med en rig historie og en ret kompleks smagsprofil. Al rommen er 100% tropisk lagret på ex-bourbonfade. Den er tappet uden kølefiltrering ved 46,2% og uden tilsat sukker eller sødemidler. Ren rom som vi vil ha’ den. I næsen kompleks, med ristede bananer, kokos, friskbagt rugbrød og kakao. I munden fyldig og sødt. Kardemomme, blommer, ristet kaffe og mørk chokolade. Den tropiske lagring, giver den noget tyngde, qua en hurtigere aldring. Masser af herlig velsmag. Det her er ikke en rom, der forsøger at være nuttet, sød eller poleret. Det er en rom med kant . En rom med historie . En rom, der kigger dig direkte i øjnene og siger: “Velkommen ombord.” Hos Spitus.dk står denne historiske kraftkarl klar til dig. Klik den hjem, skænk et glas, og lad Black Tot tage dig med tilbage til en tid, hvor rom var stærk, mænd havde bakkenbarter, og ingen vidste, hvad “light rum” betød. Alkohol % : 46,2 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Barcelo Imperial Rare Blends Porto Cask', 'https://spitus.dk/product/barcelo-imperial-rare-blends-porto-cask/', 399, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/04/Barcelo-Imperial-Rare-Blends-Porto-Cask.png', 'Denne specielle Barceló Imperial Porto Cask, er en del af den ekstraordinære Rare Blends Collection fra Barceló. Den er baseret på saft af det fineste udvalg af dominikanske sukkerrør, dyrket på Barceló’s egne marker. Den lagres først i en række udvalgte fade, der er blevet ristede i forskellige hårdhedsgrader. Efter den egentlig er færdiglagret, er den lige sendt på luksusophold i gamle tawny-portvinsfade i Portugal, hvilket tilføjer den herlige kompleksitet og rigdom. Barceló har i forvejen ry for at lave udgivelser, der er bløde, runde og uimodståelige. Men Porto Cask‑udgaven tager det hele et skridt videre. Det er som om Barceló Imperial Porto Cask har været på spaophold, lært fransk og fået ny garderobe. Den er stadig sig selv – bare mere sofistikeret. Flot, nærmest lilla ravfarve. I næsen figner, karamel, brombærsyltetøj og eksotisk peber. Dens silkeagtige tekstur forkæler ganen, og du, udover noterne fra næsen, får blommer, engelsk butterscotch og tørrede kirsebær. Dvælende og lang finish, hvor der også dukker smørnoter op, og til slut lukker med søde krydderier og en anelse peber. Er du til den sødere stil, er Barceló Imperial Porto Cask altså et uhyre spændende og fabelagtig godt bud. Det er en dram, der glider ned som fløjl og smager som noget, der burde serveres sammen med mørk chokolade, gode venner og nul planer. Leveres i flot gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Tasting Collection Rom 12&#215;2,5cl', 'https://spitus.dk/product/tasting-collection-rom-12x25cl/', 579, false, 5, 41.1, 'https://spitus.dk/wp-content/uploads/2024/06/Tasting-Collection-Rom-12×25cl.webp', 'Skal du arrangere en eksklusiv rom-smagning? Eller måske forkæle en rom-elsker med et flot maxi rom-sæt der sætter en stopper for de bløde pakker? Her får du hele 12 lækre og kendte rom, inkl. et hæfte med beskrivelser af de enkelte produkter (engelsk tekst). Sættet indeholder 2,5 cl. af hver: Ron Barceló &#8211; Imperial Onyx Appleton Estate – Signature Blend El Dorado – 8 years Goslings – Black Seal Abuelo – 12 years Gran Reserva Ron Cólon – High Proofed Aged Rom Plantation – Original Dark Brugal &#8211; 1888 Gran Reserva Mount Gay – Eclipse Pampero – Aniversario Flor de Cana – 7 years Barcardi &#8211; Reserva Ocho 8 Years Altså lutter anerkendte rom. Og når du har fundet din favorit, har den sikkert i en større flaske et andet sted på Spitus.dk. (Skal du bruge mange sæt så kontakt os, og vi får dem hurtigt hjem fra producenten). Alkohol % : 41,1 Størrelse : 12&#215;2,5cl / 30 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Ron Prohibido 15 Y.O.', 'https://spitus.dk/product/el-ron-prohibido-15-y-o/', 289, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/11/el-ron-prohibido-15yo-gran-reserva-k.jpg', 'El Ron Prohibido – kendt som den forbudte flaske fra Mexico. Det er den mørke, mexicanske rebel med sødme og swagger El Ron Prohibido 15 er spiritussens svar på en gotisk roman: mørk, intens, dramatisk – og umulig at slippe igen, når du først er fanget. Den bygger på den gamle Habanero -tradition, hvor destillatet får et vinøst twist fra lagring i tidligere raisin‑wine‑fade, der har fået en ristning, hvilket giver en smagsprofil, der er lige så unik som flaskens dystre udtryk. Smagen er dyb, sød og kompleks med lag af rosiner, karamel, mørk sirup, vanilje, tørret frugt og en let bitter note, der giver perfekt balance. Den er tung, varm og fyldig – en oplevelse, der føles som en mørk dessert med attitude. Det er flasken, du vælger, når du vil have noget, der både er anderledes, dramatisk og uimodståeligt lækkert. El Ron Prohibido 15: Den forbudte fristelse, du gerne må give efter for. Flere kåringer og priser, bl.a. guld ved San Francisco World Spirits Competition 2022 (og dobbelt guld ved samme konkurrence i 2016). 12-års udgaven er nok mere udbredt i Danmark, men det er egentlig en skam; denne 15-års variant byder på en noget større oplevelse. Og hvorfor har El Ron Prohibido så fået dette specielle navn? (oversættes til ”Den Forbudte Rom”). Tjooo historien går, at i omkring år 1700 ankom spanske skibe til det nye kontinent Amerika, fyldt med produkter fra Den Iberiske Halvø. Blandt dem var tønder fyldt med sød rosinvin. Efter at have tømt tønderne i Amerika, blev det besluttet at fylde dem med Chinguirito (Mexicansk sukkerrørs likør/”rom”). Det var jo fjollet at sejle tilbage med tomme tønder! På turen tilbage over havet, afgav tønderne noter fra den søde vin til den mexicanske likør, og da skibet anløb Spanien, var der tale om et helt andet produkt. Denne drik vandt hurtigt utrolig stor opmærksomhed og popularitet overalt. Da den spanske konge hørte om denne mexicanske drik der udkonkurrerede de spanske spiritusser, valgte han at forbyde den, for at redde de spanske mærker. Bandlysningen varede i næsten 100 år. I dag nydes den verden over. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Zacapa 23 Y.O. La Pasión Heavenly Cask Collection', 'https://spitus.dk/product/zacapa-23-y-o-la-passion-heavenly-cask-collection/', 695, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/12/204.png', 'Ron Zacapa fra Guatemala producerer nogle af verdens mest solgte og kendte dram. Udgivelserne laves på sukkerrørssaft i stedet for melasse, hvilket giver den en dyb og kompleks smag. Produkterne modnes som regel i en proces kaldet “Sistema Solera”, hvor nye og gamle rom blendes over tid. Fadene har indeholdt oloroso-sherry, Pedro Ximénez sherry, genbrændte amerikanske egetræsfade samt bourbon, og tilføjer en raffineret karakter og dybde til spiritussen. Ron Zacapa har de seneste år udgivet den eksklusive ”Heavenly Cask Collection” serie på fire forskellige rom, som vil fremhæve de fire forskellige fadtyper (nævnt ovenfor), som benyttes i den klassiske Ron Zacapa 23 Solera-blanding. Denne Selected Cask La Pasión, er den fjerde og sidste af de annoncerede limited edition-udgivelser. Blended er omhyggeligt sammensat af Ron Zacapa’s master blender Lorena Vázquez, og resultatet er en sublim udgivelse, som er blevet yderligere færdiglagret i ex Pedro Ximénez Sherry fade. Zacapa 23 La Pasión er skabt til at være intens, blød og dybt forførende. Den er sød uden at være kvalm, kompleks uden at være svær og så silkeblød, at du næsten får lyst til at give den et kælenavn. Disse fade giver en unik karakteristisk sødme. Svesker, rosiner dadler og rige vanilje-, kaffe- og chokoladenoter skaber en voluminøs overflod af smag. Super lækker og limiteret udgivelse fra Ron Zacapa. Leveres i gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Caribbean Ron Añejo 5+3 år', 'https://spitus.dk/product/dos-maderas-caribbean-ron-anejo-53-aar/', 274, true, 70, 37.5, 'https://spitus.dk/wp-content/uploads/2023/12/197.png', 'Dos Maderas 5+3 er et delikat blend fra Barbados og Guyana. To lande med deres egen romstil. Og sammen giver det en unik oplevelse. Den kraftige og aromatiske rom laves på pot stills, og den mere blide og afrundede rom kommer fra de moderne kolonneanlæg. Dos Maderas 5+3 udgangspunkt er den samme som i Dos Maderas 5+5, og forskellen er lagringstiden. Denne får først 5 år i Caribien i ex-bourbon fade og derefter 3 år i Spanien i ex Dos Cartados Oloroso sherry fade – dermed navnet 5+3 og ”titlen som ”Doubled Aged”. Yderst blød og elegant i næsen. Ristede bananer, tropiske frugter, dadler og figner. I munden ristede fade, vanilje, nødder og varme frugter. Sherry og mahogni. Den lange eftersmag efterlader dig afslappet med svømmende blikke og drømme om Caribien. Herligt produkt il en attraktiv pris, i den søde stil som vi danskere foretrækker det. Alkohol %: 37,5 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Mount Gay XO Triple Cask Rom', 'https://spitus.dk/product/mount-gay-xo-triple-cask/', 379, false, 70, 43, 'https://spitus.dk/wp-content/uploads/2023/12/200.png', 'Hvis du troede, at Barbados kun var kendt for strande, sol og folk der går rundt uden stress, så har du tydeligvis ikke mødt Mount Gay XO Triple Cask endnu. Det her er nemlig rommen, der tager alt det bedste fra øen – varme, charme og en god portion tålmodighed – og pakker det ind i en flaske, der smager af ren luksus. Mount Gay er verdens ældste romdestilleri, og XO Triple Cask er deres måde at sige: “Vi har gjort det her siden 1703… og ja, vi er stadig bedre end de fleste.” Præcis denne udgave er deres signatur-rom. Der er tale om et komplekst blend af specielt udvalgte romdestillater både fra kolonnedestillering og fra dobbelte pot still. Rommen er lagret imellem 7 og 17 år på hele 3 forskellige fade: amerikanske whiskeyfade (tilføjer dybde og krydderi), bourbonfade (giver sødme, vanilje og varme) og cognacfade (giver elegance, frugt og finesse). Det er lidt som at sende rommen på tre forskellige luksusophold og så blande alle de bedste minder sammen bagefter. Mount Gay XO Triple Cask er en rom, der ikke larmer, men alligevel fylder hele rummet. Den er sofistikeret uden at være snobbet og sød uden at blive kvalm. Den er kort sagt… virkelig godt skruet sammen. Meget harmonisk, med en duft af modne bananer, toast og varme krydderier. I munden en rig, blød smag med noter af saltet karamel, vanilje, tørrede frugter og egetræ. Tydeligt fadpræg i den lange, cremede finish, hvor du også finder mørk chokolade. Det er en rom, der både kan nydes rent, med en isterning eller som den slags dram, du tager frem, når du vil imponere nogen – eller bare dig selv. Sippe-rom fra et top-destilleri, der har øvet sig i over 300 år. Leveres i gaveæske. Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Caribbean 5+5 år &#038; 2x10cl sherry', 'https://spitus.dk/product/dos-maderas-caribbean-55-aar-2x10cl-sherry/', 449, true, 20, 43, 'https://spitus.dk/wp-content/uploads/2023/12/196.png', 'Dos Maderas-huset blev grundlagt tilbage i 1877 af Sir Alexander Williams, der var en stor beundrer og connaisseur af sherry, og af Arthur Humbert, der var en fremragende international forretningsmand. Williams &amp; Humbert har siden vundet stor anerkendelse for deres sherry, brandy og rom. I denne Dos Maderas 5+5 Years Old, udvælger Master Blenderen rom fra Barbados og Guyana, hvorefter den lagres 5 år i Caribien. Herefter sejles den over Atlanten til Williams &amp; Humbert i Spanien, hvor anden del af lagringen begynder. Først får den 3 år på ryggen i egetræsfade, der tidligere har været brugt til at modne den respekterede Dos Cartados Oloroso sherry. Den tredje lagring foregår 2 år i fade fra den tungere og mere fyldige ”Don Guido” Pedro Ximenez sherry. (Begge sherry fade indeholdt over 20 år gammel sherry). I næsen får du masser af sherry-noter; rosiner og fad. I munden mere sherry, dadler, figner, vanilje og en dejlig sødme. Fornem og lækker, lang eftersmag. En majestætisk rom med det bedste fra Barbados, Guyana og Spanien Har bl.a. taget Guldmedalje ved International Rum Expert Panel i 2010. Gavesættet her er ret sjovt, for du får, udover den fremragende Dos Maderas 5+5, 10 cl. med af Dos Cartados Oloroso Sherry (+20 år), og 10 cl. af Don Guido Pedro Ximenez sherry (+20 år). Netop de 2 fade som den store flaske er lagret på de sidste 5 år. Spændende kombination, hvor du først prøver det endelige resultat, derefter sherryen &#8211; eller omvendt. Alkohol % : 43,0 Størrelse : 20 + 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Caribbean Añejo 5+3 år &#038; 5+5 år &#8211; 2 x 20cl.', 'https://spitus.dk/product/dos-maderas-caribbean-anejo-53-aar-55-aar-2-x-20cl/', 225, true, 40, 40, 'https://spitus.dk/wp-content/uploads/2023/12/199.png', 'To top-lækre sager fra Barbados og Guyana. To lande med deres egen romstil. Begge lande laver nemlig rom på pot stills og kolonneapparatter. Den kraftige og aromatiske rom laves på pot stills og den mere blide og afrundede på mere moderne kolonneanlæg. Dos Maderas 5+3 og 5+5 er født på ens. Håndlavet og lagret i Caribien som det første. Herefter sendes rommen til Williams &amp; Humbert Bodega i Jerez, Spanien hvor den får en tur i et solera system. ”Dos Maderas” er spansk og betyder netop to slags træ, hvilket henviser til måden destilatet lagres og modnes på. Forskellen på Dos Maderas 5+3 og 5+5 er lagringstiden og at 5+5 får de ekstra 2 år på andre sherry-fade. 5+3-udgaven er 8 år undervejs. Først 5 år i Caribien i ex-bourbon fade og derefter 3 år i Spanien i ex Dos Cortado Oloroso sherry fade (meget tør sherry) – derfor 5+3 😉 Yderst blød og elegant i næsen. En bred pallette af tropiske duftaromaer. Ristet smag i munden med hints af vanilje og nødder. Elegant og vedhængende eftersmag, med dejlig sødme og kompleksitet. 5+5-udgaven hygger sig, ud over de 5+3 år i yderligere i + 2 år i ex Don Guido Pedro Ximenez sherry fade (meget sød sherry) &#8211; derfor 5+3+2=5+5, og navnet Tripple Aged Rum. Rund og fløjlsblød duft af fad, krydderier og dejlig tropisk sødme. Smagen er blød og delikat med noter af rosin, figen og vanilje Den unikke sammensmeltning af kulturer giver denne udgave en lang afrundet sødme. To majestætiske udgivelser med det bedste fra Barbados, Guyana og Spanien i et lækkert gavesæt. Alkohol % : 40,0 &amp; 37,5% Størrelse : 2 x 20 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Millonario XO Solera Reserva Especial', 'https://spitus.dk/product/ron-millonario-xo-solera-reserva-especial/', 675, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/12/195.png', 'Så for pokker; her har vi fat i toppen fra Ron Millonario. Med en alder på 15 &#8211; 20 år er den blandt Sydamerikas ældste rom, og kun de allerbedste fade bliver til Ron Millonario XO, Udgaven her blev kåret som ”Verdens Bedste Rom” i både 2008 og 2009. Nu er der mange kåringer, og det kan være lidt svært at tage seriøst, men godt det smager den!. Millonario XO er skabt i Peru, hvor sukkerrør, solskin og tålmodighed går hånd i hånd. Og det kan smages. Det er en rom, der er så blød, så sød og så elegant, at du næsten får lyst til at sige “Señor” til flasken, hver gang du går forbi den. Duft: En duft af sødme og tropiske frugter (primært appelsin) rammer næsen som det første, hvorefter en mere krydret note med tobak og tørrede frugter tager over. Smag: Smagen er behagelig sødmefyldt til at begynde med, men noter af karamel, dadel og figen. Derefter trænger en note af nelikke frem på tungen, men hele tiden i en fin symbiose med søde, eksotiske frugter. En anelse sødere end 15-års udgaven. Eftersmag: Den lukker med en behagelig og meget landvarig sødme med brun farin, svage krydderier og egetræsfad. Mums en livsglad eliksir, med den vildeste glas-gardiner. Dobbelt Guld v. Spirits Selection 2022 97/100 points af Mads ”Romhatten” Heitmann Super eksklusiv rom i super eksklusiv flaske og tilhørende gaveæske. Hvis der fandtes en rom, der kunne få dig til at føle dig som en sydamerikansk millionær med hængekøje, palmer og nul bekymringer, så ville det være Ron Millonario XO Solera Reserva Especial . Det her er ikke bare en rom – det er en oplevelse . En luksusrejse. En flydende ferie. En “jeg fortjener det her”-flaske, der står og blinker til dig fra hylden. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Millonario 10th Aniversario Reserva m/gaveæske', 'https://spitus.dk/product/ron-millonario-10th-aniversario-reserva-m-gaveaeske/', 265, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/12/198.png', 'Denne lækre Ron Millonario 10th Aniversario Reserva Rum fra det nordlige Peru, kan betragtes som lillebroderen til den kendte Ron Millonario Solera 15 år. Den er udgivet for at fejre Ron Millonario’s 10-års jubilæum, og navnet hentyder altså ikke til alderen på rommen, men alene til selve jubilæet. Den er en anelse mere frisk en 15-års udgaven, og der er tale om et blend af yngre rom der er modnet i brugte bourbonfade, samt en mindre del ældre rom, der er modnet i brugte spanske sherryfade. Resultatet er en herlig sød, let drikkelig rom til en attraktiv pris. I næsen får du noter af honning, bergamotte the, vanilje og et hint af karamel. I ganen er denne Ron Millonario ret let og frisk. Hovedsageligt med noter af kastanje, akaciehonning, kandiserede citrusfrugter og rosin. Derefter kommer en svagere note af nødder, chokolade samt blomme og abrikos. Mere af det samme i den behagelige eftersmag, men den lukker med en fin lille pift af sort peber. Flot flaske i flot gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bumbu Cream', 'https://spitus.dk/product/bumbu-cream/', 295, true, 70, 15, 'https://spitus.dk/wp-content/uploads/2022/03/bumbu-cream.jpg', 'Du kender måske de populære Bumbu rom fra Barbados, som rap-stjerner som Rick Ross, Lil Wayne og Wiz Khalifa har været med til at booste. Nu har destilleriet så udgivet denne Bumbu Cream, som er en blanding af Bumbu Rom, eksotiske krydderier og mælkecreme. Bumbu Cream er flasken, der hvisker: “Du behøver ikke vælge mellem cocktail og dessert… jeg er begge dele.” Det er en cremet, sød og farligt drikkevenlig rom‑likør, der smager som en karibisk ferie pakket ned i en flaske. Smagen er blød, rund og uimodståeligt lækker med noter af karamel, kokos, vanilje, krydret rom og et strejf af kanel. Det hele er pakket ind i en fløjlsblød cream‑tekstur, der gør den lige så nem at drikke, som den er svær at dele. Perfekt over is, i kaffe, i cocktails – eller bare som en “nu skal jeg forkæles”-skænk. Bumbu Cream er det der sker når rom går dessert‑mode og ikke kigger sig tilbage. Oplagt som den er med is, eller i en lækker cocktail. Holder 15% alkohol, så du kan godt sippe hele aftenen! Hvis du vil prøve en lettere og mere cremet Espresso Martini, kan vi ret nemt anbefale denne opskrift: 6 cl. Bumbu Cream 3 cl. vodka 1,5 cl. espresso Isterninger Knivspids espresso havsalt Espressopulver som garnish/pynt Hæld alle ingredienserne, undtaget espressopulveret, i en shaker, og ryst det hele godt sammen. Hæld op i et afkølet martini-glas, og pynt med en anelse espresso-pulver før servering. Alkohol % : 15,0 Størrelse : 70 cl Allegener: indeholder MÆLK');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Reserva Exclusiva Ron Antiguo 35cl', 'https://spitus.dk/product/diplomatico-reserva-exclusiva-ron-antiguo-35cl/', 195, true, 35, 40, 'https://spitus.dk/wp-content/uploads/2023/11/diplomatico-reserva-exclusiva-ron-antiguo-35cl-k.png', 'Okay – halvt så stor, men stadig voksen! Denne Ron Diplomatico Reserva Exclusiva, er et af de mest udbredte lagrede spiritusser i Danmark. Det er et blend af yngre og ældre destillater fra 8 år og op til 12 år. Den er udvundet af lokale sukkerrør høstet ved foden af Andelsbjergene i Venezuela. Sukkerrørsmelassen destilleres i gamle copper pot stills, og resultatet lagres efterfølgende i op til 12 år på amerikanske egetræsfade. Diplomatico er klart i den søde ende, og fans af f.eks. Ron Zacapa og Old St. Croix vil fint kunne være med her. Noterne er egetræ, appelsiner og chokolade. I munden fortsætter den bløde, runde og behagelige stil, og du får også en anelse lakrids og karamel. Sød og delikat. Saftig fudge og meget karamel. Blid og omgængelig – en crowdpleaser! &#8220;Double Gold Medal&#8221; fra den første &#8220;International RUM Conference&#8221; i 2013 Her sælger vi den i en handy 35 cl. udgave. Der findes små flasker, der er praktiske. Og så findes der små flasker, der er direkte farlige, fordi de smager så godt, at du pludselig står og tænker: “Hvorfor købte jeg ikke den store?” Diplomatico Reserva Exclusiva Ron Antiguo 35 cl hører til sidstnævnte kategori. Så; fuld størrelse finder du lige her: Diplomatico Reserva Exclusiva Ron Antiguo Størrelse : 35cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Zacapa Centenario LA ARMONIA Heavenly Cask Collection', 'https://spitus.dk/product/ron-zacapa-centenario-la-armonia-heavenly-cask-collection/', 695, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/11/ron-zacapa-centenario-la-armonia-heavenly-cask-k.png', 'Ron Zacapa fra Guatemala producerer nogle af verdens mest solgte og kendte rom. Rommene laves på sukkerrørssaft i stedet for melasse, hvilket giver den en dyb og kompleks smag. Rommen modnes som regel i en proces kaldet “Sistema Solera”, hvor nye og gamle rom blendes over tid. Fadene har indeholdt oloroso-sherry, Pedro Ximénez sherry, genbrændte amerikanske egetræsfade samt bourbon, og tilføjer en raffineret karakter og dybde til spiritussen. Ron Zacapa har de seneste år udgivet den eksklusive ”Heavenly Cask Collection” serie på fire forskellige rom, som vil fremhæve de fire forskellige fadtyper (nævnt ovenfor), som benyttes i den klassiske Ron Zacapa 23 Solera-blanding. Denne La Armonia er den tredje af de fire meget specielle limited-edition udgivelser fra destilleriet, og slutlagringen er foretaget på brugte oloroso-fade. I næsen er der noter af Oloroso Sherry, karamelliserede bær, pekannødder og honning. I munden tyktflydende, med fyldig karamel, vanilje, mørk chokolade og noter af tørrede frugter. Silkeblød oplevelse. Fyldig og meget lækker. Flaskerne er individuelt nummererede, og præsenteres i et meget elegant design med tilhørende gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Quorhum 30 Aniversario Oporto Finish Limited Edition', 'https://spitus.dk/product/ron-quorhum-30-aniversario-oporto-finish-limited-edition/', 769, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/11/ron-quorhum-30-anniversary-oporto-finish-k.png', 'Særudgave af den populære Ron Quorhum 30 Anivarsario, hvor saften har fået en ekstra lagring på brugte portvinsfade. Quorhum Oporto Finish er et must-try for alle fans af den klassiske Ron Quorhum 30 Aniversario! En god årgangsportvin smager typisk af røde bær, marcipan, blommer, chokolade og vanilje – smagselementer som fungerer godt sammen med rom, hvorfor portvinsfade er velegnede til fadafslutninger af rom. Normalt lagres portvin på store egetræsfade som kan indeholde omkring 500-550 liter portvin. Tømmer man fadet vil der stadig sidde portvinsrester i egetræets struktur, hvilket videregives til rommen, når man på ny har fyldt fadet op. Det betyder altså, at rommen som nu ligger på det brugte portvinsfad, optager nogle af de smagselementer som portvinen besidder. Dette kaldes en finish/afslutning, og det er Ron Quorhum 30 Aniversario Oporto Finish er et godt eksempel på hvor godt kan laves. Ron Quorhum 30 Aniversario Oporto Finish Limited Edition er nemlig flasken, der tager alt det, Quorhum gør godt – dybde, sødme, elegance – og løfter det med et sidste lag magi fra portvinsfade. Resultatet er en mørk, kompleks og silkeblød dram, der smager som en rejse fra Caribien til Douro-dalen. Med smagen af de klassiske elementer fra Ron Quorhum 30 Aniversario som flødekaramel, honning, appelsinskal, egetræ og kaffe, integreres de rødlige og sødmefulde smagsnuancer fra portvinsfadet på smukkeste vis. De friske citruselementer som findes i originalen, akkompagneres af en dyb og bærpræget karakter. Der er masser af tørrede frugter, rosiner, mørke bær, nødder og en vinøs sødme fra Oporto‑finishen. Den lange lagring giver en dyb, varm og harmonisk profil, mens portvinsfadet tilføjer en elegant frugtighed og en næsten dessertagtig finish. Ron Quorhum 30 Aniversario Oporto Finish er Dominikansk luksus med portugisisk finesse. Det er rommen, du vælger, når du vil have noget, der både er eksklusivt, komplekst og uimodståeligt drikkevenligt. En limited edition, der føles som en fejring i sig selv. Leveres i gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas LUXUS Double Aged Rum Limited Edition', 'https://spitus.dk/product/dos-maderas-luxus-double-aged-rum-limited-edition/', 1175, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/11/dos-maderas-double-aged-rum-luxus-k.png', 'Den primære forskel på Dos Maderas forskellige rom er lagringstiden. (”Dos Maderas” er spansk og betyder to slags træ, hvilket henviser til måden rommen lagres og modnes på). Denne Luksus Double Aged Rum er minimum 15 år på vej før den ser en flaske. Først får den 10 år i Caribien i ex-bourbon fade, hvorefter den sendes til Williams &amp; Humberts Bodega i Jerez, Spanien, hvor den får yderligere mindst 5 år i et solera-system med ”Don Guido” (Pedro Ximenez) sherryfade (som tidligere indeholdt 20-årig Don Guido PX). 10 + 5 navnet er simpelt – lagringsprocessen er dyrt og kompliceret. Rommen er et blend fra det bedste fra Barbados og Guyana. 2 forskellige stile og karakterer, hvor den kraftige og aromatiske rom laves på pot stills og den mere blide og afrundede stammer fra et mere moderne kolonneanlæg. I næsen mandler, marcipan, kirsebær og vanilje. Smagen er sød, med en del krydderier. Cremet og fadene er utroligt velintegrerede. Lang, smooth eftersmag med egetræ, søde krydderier, vanilje og sherry. Dos Maderas Luxus Double Aged Rum Limited Edition er en populær og eftertragtet sværvægter, og den kaldes i fagkredse ofte ”The Lord of Rums&#8221;. Elegant flaske i en elegant gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Royal Danish Navy Naval Cadet', 'https://spitus.dk/product/a-h-riise-royal-danish-navy-naval-cadet/', 449, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2022/11/a-h-riise-danish-navy-cadet-k.jpg', 'Naval Cadet er udgivet i en hyldest til havet og søens folk &#8211; i særdeleshed til Søværnets Officersskole (som de sponserer). A.H. Riise Royal Danish Navy Naval Cadet er den unge kadet med krudt i karakteren. Royal Danish Navy Naval Cadet er A.H. Riise‑seriens friske, livlige og mere tilgængelige lillebror – men lad dig ikke narre af navnet. Den har stadig masser af den klassiske A.H. Riise‑sødme, varme og aromatiske dybde, bare i en lettere og mere legende udgave. Smagen er blød, sødmefuld og rund med noter af karamel, vanilje, tropisk frugt, krydderi og et strejf af citrus. Den er mindre tung end de ældre Navy‑udgaver, men stadig rig nok til at føles som “ægte Riise/Old St. Croix”. En perfekt introduktion til Navy‑stilen – uden at blive overvældende. Det er flasken, du vælger, når du vil have noget, der både er smooth, aromatisk og farligt nemt at drikke. Naval Cadet: Den unge søofficer med charme, sødme og masser af A.H. Riise‑DNA. Leveres i gaveæske. Alkohol% : 42,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Maguá &#8211; Old', 'https://spitus.dk/product/ron-magua-old/', 199, true, 70, 38, 'https://spitus.dk/wp-content/uploads/2023/08/ron-magua-old.png', 'Prisvenlig fadlagret rom fra Den Dominikanske Republik, fremstillet af den fineste sukkerørsmelasse. Destilleret på kobberstills, og lagret i minimum 3 år på amerikanske egetræsfade. Mørk ravfarvet med en elegant kobberkant. Fin, delikat og kompleks aroma. De aromatiske nuancer af frisk destilleret sukkerrør er absolut tydelige. Vanilje, nødder og kanel med et dejligt lag egetræ fra tiden i fadene. Blød og letflydende nektar, hvor alle kan være med. Oplagt i læke cocktails og drinks. Uhyre meget rom for pengene. Alkohol % : 38,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Goslings Family Reserve', 'https://spitus.dk/product/goslings-family-reserve/', 598, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/11/gosling-family-reserve-k-1.png', 'Top-rom fra familieejede Gosling. Siden 1806 har de på Bermuda produceret en lang række populære og kendte rom. Mest kendt er de nok for deres signaturcocktail, Dark &#8216;n&#8217; Stormy, hvor Gosling Black Seal Rom spiller hovedrollen. Denne Gosling Family Reserve er i en helt anden vægtklasse en Black Seal. Først og fremmest har den fået ca. 16 år i brændte/ristede egetræsfade, hvilket giver en markant mere voluminøs rom. Farven er ekstrem mørk – og let rødlig. I næsen rosiner, karamel, egetræ og vanilje. I munden julekrydderier, farin, dadler, egetræ og tørrede eksotiske frugter. Dejlig fylde og sødme i eftersmagen. Du er ikke i tvivl om den lange fadlagring, og mundfylden er eminent. Nydes rent, men hvis du f.eks. vil servere luksus-cocktails, er kompleksiteten og fylden i Goslings Family Reserve en oplagt makker. Leveres i voksforseglede og nummererede smukke flasker, samt tilhørende gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('CashCane Saloon Cask', 'https://spitus.dk/product/cashcane-saloon-cask/', 399, true, 70, 55, 'https://spitus.dk/wp-content/uploads/2023/11/cashcane-k.png', 'CashCane Saloon Cask er en rom, der egner sig godt til folk der kan lide bourbon-whisky – og westernfilm. Der er tale om et blend af rom fra Barbados (8 års lagring), Panama (6 år) og Trinidad (6 år) – naturligvis på bourbon-fade hele vejen rundt. Den er identisk med CashCane XO, men er aftappet ved 55% alkohol (i stedet for 40%). Den er destilleret i både kolonner og kobber pot stills, for at få fordelene ved begge metoder med. I næsen vanilje, tobak, karamel, samt ung rom med tropiske frugter. I munden krydrede, amerikanske egetræsfade (vanilje, træ, tobak), lidt kokosnød, mango og karamel. Derefter en pebret note der fylder munden godt ud, og så igen nødder og karamel. Cremet og letflydende. En rom lavet til folk, der kan lide bourbon &#8211; og westerns! Cashcane Saloon Cask er lavet med en blanding af lagret rom fra Barbados, Trinidad og Panama, alle lagret udelukkende på bourbonfade (selvfølgelig). Det er aftappet ved 55% ABV, men forbliver behageligt cremet og blødt. Funky whisky? CashCane Saloon Cask har vundet adskillige priser i internationale konkurrencer. Selv flasken og tilhørende gaveæske ligner noget fra et whisky-destilleri. Alkohol % : 55,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Tabú &#8211; Old', 'https://spitus.dk/product/ron-tabu-old/', 249, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/11/ron-tabu-ron-doninicano.png', 'Denn e Tabú Old Rom er toppen i brandets rom-serie. Der er tale om en ægte fadlagret rom lavet af sukkerørssaft i Den Dominikanske Republik. Farven er mørkt rav – kobberagtig. Næsen byder på en meget fin, delikat og kompleks aroma. De aromatiske nuancer af frisk destilleret sukkerrør skiller sig ud. Dette integreres perfekt med fine træagtige og krydrede noter samt vanilje, kanel og nødder. Ret intens. Smag: fyldig og bestemt med karakter. Velstruktureret. I munden er den fløjlsblød. De subtile noter af vanilje og nødder integreres perfekt med træet fra fadlagringen. (Den er lagret tropisk i mindst 3 år i brugte amerikanske egetræsfade). Du får uendeligt meget rom for pengene her, hvor budgettet er brugt på råvarer og produktion, og ikke på branding og markedsføring! Vi har selv agenturet for Tabu i Norden, og det gør blandt andet, at vi kan sælge til helt uhørt lave priser. Perfekt i cocktails og drinks. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Goslings Gold Seal', 'https://spitus.dk/product/goslings-gold-seal/', 199, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/11/gosling-gold-seal.png', 'Familieejede, og Bermuda-baserede Gosling har produceret rom siden 1806, og er nok især kendte for deres signaturcocktail, Dark n’ Stormy, hvor Gosling rom er rygraden. Denne Gold Seal er en nyere udgivelse, og er et blend af gamle pot still rom som er lagret på brugte Bourbonfade. Farven er mørkt rav. I næsen vanilje, karamel, ristede fade, allehånde og en anelse kanel. I munden ret fyldig, med masser af sødme og tørrede frugter. Julekrydderier, brunkager og karamel. Dejlig viskositet og dejlig fylde på tungen i eftersmagen. Dejlig rom at sippe rent, men den er, qua dens gode fylde, også oplagt i diverse drinks og cocktails. F.eks. passer en Rum Swizzle perfekt til Goslings Gold Seal: Gosling Rum Swizzle: 15 ml Goslings Gold Seal Rum 15 ml ananasjuice 15 ml appelsinjuice 25 ml Grenadine 6 skvæt Angostura Aromatic Bitters Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Captain Morgan Sliced Apple', 'https://spitus.dk/product/captain-morgan-sliced-apple/', 179, true, 70, 25, 'https://spitus.dk/wp-content/uploads/2023/11/captain-morgan-apple-k.png', 'Captain Morgan er et velkendt og populært rom-mærke, der har eksisteret i mere end 70 år. Det er opkaldt efter den berømte walisiske pirat fra det 17. århundrede, Sir Henry Morgan, som var kendt for sin eventyrlyst og kærlighed til den caribiske livsstil. I dag legemliggør Captain Morgan stadig denne eventyrlystne ånd ved at producere en bred vifte af aromatiserede rom, og rombaseret spiritus, der sælges over hele verden. Captain Morgan Sliced Apple er en af de seneste tilføjelser til brandets sortiment af rom med smag. Den er lavet på caribisk rom lagret i mindst 2 år, og derefter blandet med naturlig æblesmag og krydderier. Resultatet er en lækker sød og krydret sag, der er perfekt til at blande i cocktails. Vi kender dog mennesker, der drikker den rent. Sød, frugtagtig aroma, der minder om friskskårne æbler. På tungen har den en glat og cremet tekstur med noter af karamel, æbler, kanel og en anelse ingefær. Eftersmagen er varm og let krydret med noget sødme og prikken fra æblerne. Kun 25% alkohol, og oplagt i diverse drinks og cocktails med lemonade, lime og is. Prøv f.eks.: Sliced Apple Crisp: 2 dele Captain Morgan Sliced Apple 1 del citron-/lemonsaft Citronskive Hæld Captain Morgan Sliced Apple og citronsaft i en shaker med is. Ryst og hæld i shotglas. Pynt med citron. Sliced Apple Mule: 2 dele Captain Morgan Sliced Apple 4 dele Gingerbeer Isterninger Citronskive Metode: Hæld Captain Morgan Sliced Apple og Gingerbeer/ingefærøl i et glas med is. Pynt med citron. Alkohol % : 25,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Admiral Rodney HMS Royal Oak', 'https://spitus.dk/product/admiral-rodney-hms-royal-oak/', 475, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/11/admiral-rodney.png', 'Admiral Rodney-serien af ​​prisvindende rom fejrer det berømte søslag Battle of the Saints i 1782. Det britiske skib HMS Royal Oak var forrest, da briterne gav franskmændene lov til at smage alle dens 74 kanoner. Av. Rommen er heldigvis mere imødekommende, og er et klassisk produkt fra St. Lucia Distillers. Blended er 7-12 år gamle Coffey-still rom, udelukkende lagret i brugte bourbon-fade. Farven er lyst rav. I næsetippen vælter det rundt med svesker, rosiner, ristet eg, sød tobak og tropiske frugter (primært citrus og appelsin). Fyldig og olieret i munden med chokolade, vanilje, søde frugter og karamel. Lækker finish, hvor der lukkes med eksotiske krydderier. Ikke tilsat sukker. Ret krydret rom, men med en herlig balance og struktur. Leveres i gaveæske. Alkohol % : 40 Størrelse : 70cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation &#8211; Panama 18 år Decanter', 'https://spitus.dk/product/rum-nation-panama-18-aar-decanter/', 475, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/11/rum-nation-panama-18-aar-decanter.png', 'Denne 18-årige Panama rom fra Rum Nation leveres her i en ny udgave og i en smuk karaffelflaske. Der er tale om en opdateret og fintunet udgave af den tidligere Panama 18-års fra Rum Nation, men den er heldigvis stadig farverig og ret livlig. Sukkerrørets rigdom og finessen i den spanske destillations stil, giver her en rom med en stor aromatisk kompleksitet. Sødlig, og rig på tropiske frugter, dadler og chokolade. (Selv om sukkerindholdet er reduceret til under 20 gr/liter). Duften er livlig, med honning, cola(!), bergamot, dadler, appelsinskal og en anelse fyldig vermouth. Smagen er sødlig, med masser af tropiske frugter, men også en fin friskhed. Tydelig sukkerrørsmelasse, chokolade, rosiner og en god balance mellem appelsinskal, cola (der var den igen) og kokosnød. I eftersmagen får vi mørk te med honning. Varme noter af kamille og dejligt krydret med bl.a. peber. Flot og dejlig udgivelse, som samtidig er meget let drikkelig. Klasse. Flot decanter-flaske og tilhørende gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation &#8211; Panama 21 år Black Decanter', 'https://spitus.dk/product/rum-nation-panama-21-aar-black-decanter/', 749, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2023/11/rum-nation-panama-21-aar-black-decanter.png', 'Rum Nation Panama 21 år Decanter Black er produceret på det nok bedste destilleri i Panama &#8211; Varela Hermanos Distillery. Rommen er fremstillet af sukkerrørsmelasse, kontinuerligt destilleret i kolonneanlæg, og modnet lokalt i amerikanske Quercus alba fade i minimum 21 år! Så den er gammel, men for at det ikke skal være løgn, tilsættes der faktisk en pæn portion endnu ældre rom – for at øge kompleksiteten og give den endnu mere karakter. Resultatet er overbevisende. Usædvanligt at møde så meget friskhed i så gammel en rom. I næsen mødes du af en sød elegance. Tørrede dadler og figen, tobak og Pedro Ximenez sherry. Smagen er blid, fløjlsblød og cremet. Chokolade, orangeskal og bergamot. Igen finder vi tørrede figner, dadler og tropiske frugter. Rosiner og sprøde sukkerrør. I eftersmagen finder man et strejf af peber, som kontrast til den meget bløde, lidt søde og let cremede stil. Fantastisk rom, der heldigvis ikke overdøves af for megen træ, men lader sukkerrørene og sherry-noterne styre løjerne. I Decanter-udgaven her, lever den elegante indpakning op til indholdet. Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation &#8211; Jamaica 5 år Sherry Finish', 'https://spitus.dk/product/rum-nation-jamaica-5-aar-sherry-finish/', 349, true, 70, 50, 'https://spitus.dk/wp-content/uploads/2023/11/rum-nation-jamaica-5-aar-sherry-finish.png', 'Denne Rum Nation rom er destilleret på destilleriet Worthy Park og lagret i Jamaica i 4 år på brugte amerikanske Bourbon fade. Derefter er den sejlet til Piemonte i Italien, hvor den er tappet over på et egetræsfad, som tidligere husede Oloroso sherry. Jamaica 5 års Sherry Finish er tappet ved 50% alkohol for at beholde den vitale styrke fra den kraftige pot stil rom – samtidig med at du får masser af Jamaica funk med rosiner og kanel. Der er tale om en ret kraftig fætter, med masser af rastafari-hår og smagsfylde. Stadig blød og venlig, og den britiske Navy stil bliver afdæmpet godt af Oloroso-fadet. Intens og balsamisk duft med noter af kamfer og den typiske ”Jamaica funk” fra esterne. Sukkerrør og spinkle fermenterede vinøse noter. I munden går noterne igen, men du får også harpiks og fyrtræsnåle med et hint af peber. Der ligger en sødme i baggrunden men det overordnede indtryk er tørt og krydret. Rosin og gammelt træ. Jamaica man. Livlig, lang og fyldig eftersmag med pebernoter. En typisk Jamaica rom, som er ret kraftig og aromatisk, men som med sine vinøse toner af rosin fra sherryfadet, ender en anelse mere blød og rund end hardcore jamaicanere. Alkohol % : 50,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo Finish Collection Three Pack, 3 x 20cl Rom', 'https://spitus.dk/product/abuelo-finish-collection-three-pack-3-x-20cl/', 699, true, 60, 40, 'https://spitus.dk/wp-content/uploads/2023/11/abuelo-finish-collection-three-pack-3x20cl.png', 'Abuelo XV Finish Collection er et eksklusiv sæt, der viser at Abuelo med deres XV-serie producerer noget aldeles eminent rom! Sættet indeholder 3 aftapninger, alle minimum 15 år gamle. De adskiller sig ved, at de er efterlagret på forskellige fade der tidligere har været brugt til at gemme anden spiritus. Navnet på de 3 rom afspejler ikke blot karakteren fra fadet, men også stedet har inspireret til rommens endelig udformning. Her får du en chance for at smage dem alle 3 i 20 cl flasker &#8211; leveret i en flot gaveæske. Napoleon er Cognac fra Frankrig: En afdæmpet cognac duft, som på fineste vis spiller sammen med rommen. Cognac-fadet giver en krydret tørhed i duften. Vinøs, cremet og sødmefyldt smag, med noter af flødekaramel som integrerer lækkert med fadets krydrede bidrag. De dybe fadnoter forsætter i eftersmagen, men overtages gradvist af lette og friske appelsin-noter, og en anelse tyngde med læder. Oloroso er Sherry fra Spanien: Læder, vanilje, mandarin og tørrede frugter i næsen. I munden fed og cremet, med noter af brændt appelsinskal, abrikos samt søde krydderier. Eftersmagen er lang, sødmefyldt og krydret med noter af sød pibetobak og prikken fra appelsiner. Tawny er Portvin fra Portugal: Tydelig duft af tawny portvin – masser af vanilje og orange noter. Portvinen giver en let krydret smag, hvorefter rommen overtager med de klassiske abuelo-noter: tobak, orange, vanilje og læder. Lang cremet eftersmag, hvor portvinen og rommen på skift giver stor smag og mundfylde. Eksklusivt sæt – oplagt gave til rom-connaisseuren. Alkohol % : 40,0 Størrelse : 3 x 20cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation &#8211; Meticho Chocolate &#038; Toffee', 'https://spitus.dk/product/rum-nation-meticho-chocolate-toffee/', 289, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/11/rum-nation-meticho-chocolate-toffee-70cl.png', 'Kan en chokoladebar være flydende? Så er der fredagsslik for voksne. Rum Nation Meticho Chocolate &amp; Toffee er en rombaseret spiritus lavet på Centralamerikansk rom, blandet med chokolade, toffee, vanilje og karamel. Det er omtrent så sødt som det lyder. Men varmen og fyldigheden fra rommen redder dagen. Cremet, fyldig og næsten konfektagtig smag. Nydes rent med is, gerne til desserten eller når der bare er brug for noget sødt og godt. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation &#8211; Meticho Citrus', 'https://spitus.dk/product/rum-nation-meticho-citrus/', 269, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/11/rum-nation-meticho-citrus.png', 'Rum Nation Meticho Citrus er en rombaseret spiritus, hvor man mixer sød og fyldig mellemamerikansk rom med citrusfrugter. Der indgår bl.a. italienske appelsiner, røde appelsiner, citroner og mandariner. Desuden vanilje og honning. Lyder det en anelse mærkeligt? Yep. Smager det godt? Yep. Let sødlig, med masser af honning og vanilje, men også spark fra rommen., og prikken fra de mange forskellige citrusfrugter. Gold Medal &#8211; International Spirits Awards 2022 Nydes rent med isterninger efter en god middag, men fungerer glimrende i diverse cocktails. Prøv f.eks.: Meticho Dark n’ Stormy: Fyld Isterninger i et glas 1 del Meticho 3 dele Ginger Beer 2 stk limebåde Du kan også nemt lave en rom &amp; cola eller rom &amp; lemon: Fyld isterninger i et glas 1 del Meticho 2-3 dele Cola / Lemon Tonic Citronskive Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario 7 års', 'https://spitus.dk/product/ron-centenario-7-aars/', 239, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/02/6.png', 'I lang tid var Costa Rica primært kendt for produktion af kaffe. Men på grund af sin placering mellem Caribien og Atlanterhavet, kan der dyrkes sukkerrør af meget høj kvalitet, som derefter kan destilleres til rom. Centenario Rums har bragt nogle premium-rums på markedet, der nyder stigende popularitet. Generelt er rommene fra Centenario gode bud på rom i den søde stil, hvor du får meget for pengene. Centenario Anejo Especial Solera 7 er resultatet af flere forskellige typer rom, der er lagret på egetræsfade. Her er de opbevaret omhyggeligt for at skabe en moden rom af høj kvalitet med en delikat duft og smag. Rommen er ideel rent med is, men den gør sig ligeledes godt som smagsforstærker i cocktails. Hvis du ynder at nyde en Daiquiri eller Cuba Libre, skal du prøve at mikse drinken med denne Centenario Anejo Especial Solera 7 &#8211; den er som skabt til netop disse 2 drinks. Derover matcher den godt med frisk citrus, kokosnød eller andre tropiske frugter. En ret lys og frugtrig blends af rom, modnet i hvide amerikanske egetræfade. Denne rom har noter af friske røde æbler, presset cider, grøn guavasaft, frisk græs og grøn melon. Finishen har elementer af ananas, honning og cappuccino. Ron Centenario 7 er en hyldest til enkelhed, varme og nydelse. Den er sød, blød, letdrikkelig og fuld af tropisk charme. En rom, der ikke prøver at være noget, den ikke er – og som netop derfor rammer plet. Den er både prisvenlig og kvalitetsrig – en kombination, der gør den til en af de bedste “go-to”-romme på markedet. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Distillery Collection N°3 Pot Still', 'https://spitus.dk/product/diplomatico-distillery-collection-n3-pot-still/', 495, true, 70, 47, 'https://spitus.dk/wp-content/uploads/2023/09/diplomatico-destillery-collection-no3.png', 'Fra det elskede rom-hus, Diplomatico (Venezuela), præsenterer vi her nr. 3 af tre, i deres ”Distillery Collection Series”. Hver af de tre rom har sit eget særpræg, dannet af, at de er destilleret på forskellige måder. Fælles for dem er det, at de alle er lagrede på fade af amerikansk hvid eg (ex bourbon eller maltwhisky). Diplomático Nº3 Pot Still, er som navnet antyder, destilleret i et kobber Pot Still-system. Destillationssystemet blev oprindeligt brugt i Skotland til produktionen af whisky, og blev indført på Diplomáticos La Miel-destilleri i 1959. Efter destilleringen, modnes rommen på små fade af amerikansk hvid eg, indtil den når sin optimale modenhed efter 8 år. N°3 Pot Still er Diplomático, når de smider silkehandskerne og viser deres mest intense, old‑school destillationsstil frem. Pot still‑rom er kendt for at være tunge, aromatiske og fulde af karakter – og denne udgave er ingen undtagelse. Det er den mørke, dybe og mest “rom‑nørdede” flaske i hele Distillery Collection. Smagen er kraftfuld, varm og kompleks med noter af karamel, mørk frugt, banan, vanilje, krydderi og en markant pot still‑fylde, der giver både dybde og attitude. Den er mindre sød end de klassiske Diplomático‑flasker, men til gengæld langt mere intens og lagdelt. Det er flasken, du vælger, når du vil opleve Diplomático uden filter – ren, ufortyndet destillationskarakter. N°3 Pot Still er Diplomático med muskler, mod og masser af smag. Diplomático Distillery Collection N°3 Pot Still – Den rå, rige og rebelske i familien. Ligesom resten af Diplomáticos Destillery Collection bør Nº3 nydes rent ved ca. 20 grader. En sjov og interessant måde at nyde Diplomáticos Destillery Collection på er, at smage alle tre varianter af serien efter hinanden, for at opleve den markante forskel, som de tre destilleringsmetoder har på både smag, duft og det generelle indtryk af rommen. Leveres i gaverør. Alkohol % : 47,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Ron Prohibido Reserva 22 Y.O', 'https://spitus.dk/product/el-ron-prohibido-reserva-22-y-o/', 475, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/11/ron-mexicano-22-k.jpg', 'El Ron Prohibido Reserva 22 år er d en mørke majestæt i Prohibido‑familien. El Ron Prohibido Reserva 22 er spiritussens svar på en gotisk konge: dyb, dramatisk og pakket med årtiers koncentreret karakter. Hvor 15‑årgangen er intens og sødmefuld, tager 22’eren det hele et niveau op – mere dybde, mere vinøs elegance, mere mørk magi. El Ron Prohibido betyder- og er kendt som &#8220;Den Forbudte Rom&#8221; . Smagen er massiv, silkeblød og kompleks med lag af rosiner, mørk sirup, karamel, vanilje, tørret frugt, mokka og en markant vinøs tone fra de særlige raisin‑wine‑fade. Den har en næsten portvinsagtig fylde, men stadig den karakteristiske mexicanske varme og krydrede kant. Det er flasken, du vælger, når du vil have noget, der både er luksuriøst, anderledes og fuldstændig uimodståeligt. El Ron Prohibido 22: Den forbudte fristelse i sin mest modne og majestætiske form. 22-års udgaven her kommer i et specielt design, idet der medfølger en træ-holder, som ganske smukt udstiller flasken. En god gaveidé 😉 Men hvorfor kaldes El Ron Prohibido så ”Den Forbudte Rom&#8221;? Tjooo, historien går på, at i omkring år 1700 ankom spanske skibe til det nye kontinent Amerika, fyldt med produkter fra Den Iberiske Halvø. Blandt dem var tønder fyldt med sød rosinvin. Efter at have tømt tønderne i Amerika, blev det besluttet at fylde dem med Chinguirito (Mexicansk sukkerrørs-likør/”rom”). Det var jo fjollet at sejle tilbage med tomme tønder. På turen tilbage over havet afgav tønderne noter fra den søde vin til den mexicanske likør, og da skibet anløb Spanien, var der tale om et helt andet produkt. Denne drik vandt hurtigt utrolig stor opmærksomhed og popularitet overalt. Da den spanske konge hørte om denne mexicanske drik, som udkonkurrerede den spanske spiritus, valgte han at forbyde den for at redde de spanske mærker. Bandlysningen varede i næsten 100 år. I dag er den elsket verden over. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Tasting Kit, Albert', 'https://spitus.dk/product/a-h-riise-tasting-kit-albert/', 319, false, 18, 40, 'https://spitus.dk/wp-content/uploads/2023/08/a.h.-riise-tasting-kit-albert-9x2-cl.png', 'A.H. Riise har udgivet 3 forskellige smagebokse, som hver indeholder 8+1 flasker, smageunderlag med smagenoter, et originalt A.H. Riise smageglas og en QR-kode med et link til videoer med A. H. Riise -aficionado Lars Code, som kommenterer hver smagsprøve og fortæller nogle af de fantastiske historier bag dem. Lav din egen smagning, og få en god introduktion til de herlige blends fra A.H. Riise. Dette sæt er opkaldt efter selve Albert Heinrich Riise, og indeholder flere lækkerier, bl.a. den sjældne Founders Reserve No. 1. 1 x A.H. Riise Royal Danish Navy Premium Matured Rom 2 cl 40% 1 x A.H. Riise XO Founders Reserve Batch 1 Premium Matured Rom 2 cl 44,5% 1 x A.H. Riise Ambre d&#8217;Or Reserve XO Premium Matured Rom 2 cl 42% 1 x A.H. Riise Non Plus Ultra Very Rare Premium Matured Rom 2 cl 42% 1 x A.H. Riise 175 Years Anniversary XO Premium Matured Rom 2 cl 42% 1 x A.H. Riise Santos Dumont Palmira XO Premium Matured Rom 2 cl 40% 1 x A.H. Riise Non Plus Ultra Black Edition Premium Matured Rom 2 cl 42% 1 x A.H. Riise Royal Danish Navy Frogman Conventus Ranae Premium Matured Rom 2 cl 60% 1 x A.H. Riise Pharmacy Liquorice Shot 2 cl 18% 1 x Glas med A.H. Riise logo Alkohol%: 18-60 Størrelse: 9 x 2 cl.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Tasting Kit, Henriette', 'https://spitus.dk/product/a-h-riise-tasting-kit-henriette/', 319, false, 18, 42, 'https://spitus.dk/wp-content/uploads/2023/08/a.h.-riise-tasting-kit-henriette-9x2-cl.png', 'A.H. Riise har udgivet 3 forskellige smagebokse, som hver indeholder 8+1 flasker, smageunderlag med smagenoter, et originalt A.H. Riise smageglas og en QR-kode med et link til videoer med A. H. Riise -aficionado Lars Code, som kommenterer hver smagsprøve og fortæller nogle af de fantastiske historier bag dem. Lav din egen smagning, og få en god introduktion til de herlige blends fra A.H. Riise. Dette sæt, Henriette, er opkaldt efter A.H. Riise’s kone og indeholder: 1 x A.H. Riise Royal Danish Navy Naval Cadet Premium Matured Rom 2 cl 42% 1 x A.H. Riise XO Reserve Superior Cask Premium Matured Rom 2 cl 40% 1 x A.H. Riise Santos Dumont XO Gewürztraminer Premium Matured Rom 2 cl 40% 1 x A.H. Riise Copenhagen Gold Medal 1888 Premium Matured Rom 2 cl 40% 1 x A.H. Riise Non Plus Ultra Ambre d&#8217;Or Excellence Premium Matured Rom 2 cl 42% 1 x A.H. Riise Non Plus Ultra Black Edition Premium Matured Rom 2 cl 42% 1 x A.H. Riise Santos Dumont Heritage Hors d&#8217;Age Premium Matured Rom 2 cl 43,8% 1 x A.H. Riise Royal Danish Navy Strength Premium Matured Rom 2 cl 55% 1 x A.H. Riise Pharmacy HOT Liquorice Shot 2 cl 18% 1 x Glas med A.H. Riise logo Alkohol%: 18-55 Størrelse: 9 x 2 cl.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XII Anos &#8216;Three Angels&#8217; Rom', 'https://spitus.dk/product/abuelo-xii-anos-three-angels/', 575, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2023/08/abuelo-xII-anos-three-angels.png', 'Abuelo XII Anos ”Three Angels” er en single estate rum fra Ron Abuelos destilleri i Panama. Denne dybe og elegante udgivelse er – lig sin lillesøster Abuelo XII Anos ”Two Oaks” &#8211; en blanding af dobbelt-lagrede 12 års rom, som først lagres i bourbonfade af hvid amerikansk eg, og dernæst får den noget tid på ryggen i hårdt ristede nye egefade. Til forskel fra ”Two Oaks”, er ”Three Angels” tappet udelukkende fra fadene på den øverste række på Ron Abuelos vintage pallet varehuse. På denne øverste række når temperaturen helt op på 35°C. Dette resulterer i, at Angel’s Share (Englenes andel = den procentdel af væsken, der fordamper hvert år) når op på hele 15%. Det er meget. Men mon ikke englene omkring Pesé – den lille, frodige dal på Azuero-halvøen &#8211; er ganske fornøjede og i godt humør? Den høje angel&#8217;s share er inspirationen til navnet Three Angels. De daglige skift i temperatur og luftfugtighed resulterer i en rom med ekstraordinær kompleksitet og smag. Derudover er Three Angels også tappet ved en højere alkoholstyrke end Ron Abuelos andre udgivelser, hvilket perfekt komplimenterer dens mere voluminøse natur. Three Angels kan betegnes som en mere kraftfuld og intens udgave af den prisvindende Abuelo XII Anos Two Oaks, som blandt andet har vundet Dobbelt Guld ved San Francisco World Spirits Competition i 2022. I næsen eksotiske frugter, søde krydderier, mørk chokolade, ristede hasselnødder og en anelse læder. I munden ret heftig, med tydelige noter af de hårdt-ristede egefade. Vanilje, frugter og honning. Dejlig fylde og varme! Eftersmagen er langvarig, krydret og sød – med noter af kakaobønner og ristet kaffe. Herlig udgivelse fra Abuelo – specielt hvis du er til saft og kraft! Leveres i eksklusiv gaveæske. Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Founders Reserve No 5', 'https://spitus.dk/product/a-h-riise-xo-founders-reserve-no-5/', 569, true, 70, 44.4, 'https://spitus.dk/wp-content/uploads/2023/08/a.h.-riise-xo-founders-reserve-no-5.png', 'Founders Reserve er en ny XO-serie fra A.H. Riise bestående af blends, der repræsenterer et helt unikt øjebliksbillede. De lækre dråber findes kun i begrænsede- og forskellige antal flasker. Hver batch er unik og kan aldrig genskabes. Den første udgivelse er fra medio 2021 (Founders Reserve No. 1) (11.232 flasker) og kom med en styrke på 44,5 % og rød tekst på etiketten. Founders Reserve No. 2 (11.280 flasker) med en styrke på 44,3% blev lanceret i begyndelsen af 2022 og har blå tekst på etiketten. Founders Reserve No. 3 (8.976 flasker) med en styrke på 44,8% blev udgivet medio 2022 og har grøn tekst på etiketten. Founders Reserve No. 4 var klar i butikkerne fra d. 27. januar 2023 (14.225 flasker, mørkerød tekst og 45,1% alkohol). Founders Reserve No. 5 udkom i maj 2023 (13,995 flasker, orange tekst og 44,4% alkohol). Founders Reserve No. 6 udkom d. 1. september i et oplag på 13.665 flasker med lysegrøn tekst og en alkoholprocent på 45,5%. Hver flaske er nummereret med et batch- og flaskenummer. Her præsenterer vi altså No. 5 i serien. Og som de øvrige er den gylden i farven. I næsen tropisk frugt, kirsebær og blide tobaksnoter. I ganen forfriskende tropiske frugter, mørk chokolade, vanilje, blommer, ristede mandler og en anelse brun farin. Vidunderlig blød og vedholdende eftersmag. Med en rigtig god balance mellem den elegante sødme og komplementerende syre, er Founders Reserve Serien en rigtig god repræsentant for A. H. Riise-stilen. Måske en flaske til nydelse, og et par stykker som investering! Leveres i gaveæske, og gratis til din nærmeste pakkeboks. Alkohol % : 44,4 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Founders Reserve No 6', 'https://spitus.dk/product/a-h-riise-xo-founders-reserve-no-6/', 569, true, 70, 45.5, 'https://spitus.dk/wp-content/uploads/2023/08/a.h.-riise-founders-reserve-no-6.png', 'Sidste udgivelse i XO Founders Reserve Serien Founders Reserve er en ny XO-serie fra A.H. Riise bestående af blends, der repræsenterer et helt unikt øjebliksbillede. De lækre dråber findes kun i begrænsede- og forskellige antal flasker. Hver batch er unik og kan aldrig genskabes. Den første udgivelse er fra medio 2021 (Founders Reserve No. 1) (11.232 flasker), og kom med en styrke på 44,5 % og rød tekst på etiketten. Founders Reserve No. 2 (11.280 flasker) med en styrke på 44,3% blev lanceret i begyndelsen af 2022 og har blå tekst på etiketten. Founders Reserve No. 3 (8.976 flasker) med en styrke på 44,8% blev udgivet medio 2022 og har grøn tekst på etiketten. Founders Reserve No. 4 var klar i butikkerne fra d. 27. januar 2023 (14.225 flasker, mørkerød tekst og 45,1% alkohol). Founders Reserve No. 5 udkom i maj 2023 (13,995 flasker, orange tekst og 44,4% alkohol). Founders Reserve No. 6 er udkommet d. 1. september, i et oplag på 13.665 flasker, med lysegrøn tekst og en alkoholprocent på 45,5%. Denne No. 6 er sidste udgivelse i serien, og samtidig den med den højeste alkoholprocent. Skal nok blive et samlerobjekt! Som de øvrige i serien er den gylden i farven. I næsen tropisk frugt, kirsebær og blide tobaksnoter. I ganen forfriskende tropiske frugter, mørk chokolade, vanilje, blommer, ristede mandler og en anelse brun farin. Vidunderlig blød og vedholdende eftersmag. Med en rigtig god balance mellem den elegante sødme og komplementerende syre, er Founders Reserve Serien en rigtig god repræsentant for A. H. Riise-stilen. Måske en flaske til nydelse, og et par stykker som investering! Leveres i gaveæske. Alkohol % : 45,5 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Royal Danish Navy Strength 55% &#8211; Old Rum Edition', 'https://spitus.dk/product/a-h-riise-royal-danish-navy-strength-55-old-edition/', 549, true, 70, 55, 'https://spitus.dk/wp-content/uploads/2023/08/a.h.-riise-royal-danish-navy-strength-old-edition-1.png', 'OBS! Dette er den gamle version – vi har naturligvis også de nyere versioner til en lavere pris på Spitus.dk. Både gaveæsken og flasken er prydet med ”Rum”, og vi har et stærkt begrænset parti, som vi har fundet og taget hjem – forhåbentligt til glæde for nogle entusiastiske Riise-samlere. Alkohol % : 55,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Volbeat Rum No III', 'https://spitus.dk/product/volbeat-rum-no-iii/', 439, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2022/03/volbeat-3-nyflaske-k.jpg', 'Det danske rockband Volbeat, har tidligere udgivet Volbeat Rum I og II i ret begrænsede mængder. De blev primært solgt via specialbutikker, og er for længst udsolgte. De er blevet til samlerobjekter blandt romelskere og naturligvis for Volbeat fans. Priserne er stukket af, men nu er nummer 3 i rækken her, og den er udgivet i større mængder og til en lavere pris. Dette vel og mærke uden at der er gået på kompromis med kvaliteten. Der er tale om et blend fra Den Dominikanske Republik, Barbados, Jamaica, Guyana, Guatemala og Trinidad – så lidt af en sammensætning! Aldersmæssigt er der anvendt rom på op til 15år, og alkoholprocenten er holdt på 43%. Farven er mørk mahogni. Næsen er sød, med rige noter af egetræ og vanilje. I munden går det sødmefulde igen, og du får fine lag af fed vanilje, honning, mørk chokolade, bagte pærer, en anelse mokka og lakrids. Volbeat Rum III er således en meget drikkevenlig dram, i danskernes foretrukne, søde stil. Den byder dog på substans nok til at rom-connaisseurs gerne vil være med – medmindre du er agricole-fanatiker! Det er lidt som at høre en Volbeat-sang: du tror, du ved, hvad der kommer, men så bliver du alligevel overrasket. Som bandet selv skriver på bagetiketten: ”Rommen er til enhver Guitar Gangster, Lonesome Rider, Cheapside Slogger og alle derimellem”. Her får du den i en nyere udgave-flaske, men med samme indhold af lækre dråber! Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise 1888 Copenhagen Gold medal &#8211; Old Edition', 'https://spitus.dk/product/a-h-riise-1888-copenhagen-gold-medal-old-edition-2/', 439, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/08/a.h.-riise-1888-copenhagen-gold-medal-old-edition-1.png', 'Ret sjælden “Old Version” af klassikeren 1888 Copenhagen Gold Medal. Du finder også de nyere versioner lige her: https://spitus.dk/product/a-h-riise-1888-copenhagen-gold-medal/ eller Old St. Croix XO Reserve 1888 Copenhagen &#8211; Spitus.dk Naturligvis ganske få eksemplarer på lager af dette samlerobjekt. Leveres i gaveæske. Alkohol% : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Royal Reserve King Haakon &#8211; Old Rum Edition', 'https://spitus.dk/product/a-h-riise-xo-royal-reserve-king-haakon-old-edition/', 569, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2023/06/a-h-riise-king-haakon-old-edition-k.png', 'A.H. Riise XO Royal Reserve King Haakon &#8220;old edition&#8221; &#8211; du finder også den nyere version på shoppen nu under navnet Old St. Croix. Inden Kong Haakon den 7. af Norge i 1905 blev kronet som konge, havde han titel og opvækst som Prins Carl af Danmark. Han gjorde karriere i Den Kongelige Danske Flåde. Siden førte hans karriere ham til tjeneste på Fregatten Jylland. På et tidspunkt anløb Fregatten Jylland og den unge prins De Vestindiske Øer. Her mødte han Valdemar Riise, søn af A.H. Riise. Deres møde førte til venskab, og de erfarede, at de begge havde gensidig interesse for god, vellagret kvalitetsrom. Denne eksklusive aftapning, , hylder både venskabet mellem de 2 mænd, og mødet over et velskænket dram. A.H. Riise Kong Haakon X.O. Royal Reserve Rum er genskabt med inspiration efter den originale opskrift. Netop denne flaske var efter sigende Kong Haakons absolutte favorit. Der er tale om en herlig dram i den elskede A.H. Riise stil. Dyb, fyldig, sød og med masser af tropiske frugter; primært appelsiner, mango og papaya. Dejlig fløjlsblød tekstur med vanilje, honning og tørrede rosiner, samt et snert af portvin. Lang eftersmag med masser af sødme og velintegreret velsmag. A.H. Riise Kong Haakon X.O. Royal Reserve Rum er en ægte kongelig, vestindisk udgivelse! Her er der tale om den den &#8220;gamle udgave&#8221;, fra før de nye EU-direktiver trådte i kraft. For mange et decideret samlerobjekt! Levers i flot gaveæske. Alkohol % : 42,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas Seleccion', 'https://spitus.dk/product/dos-maderas-seleccion/', 449, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2023/05/dos-maderad-seleccion.png', 'Dos Maderas-huset blev grundlagt tilbage i 1877 af Sir Alexander Williams, der var en stor beundrer og connaisseur af sherry, og af Arthur Humbert, som var en fremragende international forretningsmand. Williams &amp; Humbert har siden vundet stor anerkendelse for deres sherry, brandy og rom. Denne Dos Maderas Seleccion er sammensat er udvalgte fade fra Dos Maderas&#8217; 5+5 program. Der er således udvalgt fade løbende, som synes ekstra gode, og disse udvalgte fade bliver blended med 10-års rom fra Barbados og Guyana og til sidst udgivet under navnet &#8220;Seleccion&#8221;. Der er tale om et mix af destilleringsmetoder, hvor den fra pot still-andelen får noget kraft og power, medens andelen, der er kørt igennem kolonneanlægget, tilføjer blødhed og afrunding. Fadene er dels brugte bourbon-fade men også PX-sherry-fade fra Spanien. I næsen masser af sherry-noter med en dejlig dybde og sødme. I munden først en anelse tør, men så dukker de traditionelle sherry-noter også op her. Mørk chokolade, dadler, vanilje og farin. Medium sød. Lang dejlig, cremet finish. Dos Maderas Selección er skabt til dig, der ikke gider vælge mellem sødme, dybde og kompleksitet. Den kombinerer det hele og serverer det med et smil, som om den siger: “Slap af, jeg har styr på det.” En majestætisk rom med det bedste fra Barbados, Guyana og Spanien. Hvis rom kunne få bonuspoint hos flyselskaber, ville Dos Maderas Selección være guldmedlem for længst. Den her rom har nemlig været på en rejse, der får selv erfarne globetrottere til at nikke respektfuldt. Leveres i gaveæske. Alkohol %: 42,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Guatemala XO 20th Anniversary Edition', 'https://spitus.dk/product/rum-nation-guatemala-xo-20th-anniversary-edition/', 475, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/rum-nation-guatemala-xo-gb.png', 'Rum Nation Guatemala XO 20th Anniversary Edition er, taadamm: udgivet for at fejre Rum Nations 20 år jubilæum. Denne jubilæumsudgave er flaskernes svar på en elegant, velduftende gentleman, der har levet et godt liv i Guatemala – og som nu er klar til at fortælle dig alle de søde historier. Lagret på både bourbon‑ og sherryfade, og afsluttet med et strejf af PX‑magi, er den så smooth, at du næsten glider af stolen. Den er baseret på en sukkerrørsmelasse, og destilleret traditionelt på et kolonneanlæg. ”Hemmeligheden” er primært lagringen den udsættes for: Først transporteres den til det nord-østlige hjørne af Guatemala, hvor den ved Hondo-floden og 185 meter over havets overflade, lagrer i mindst 4 år. Hjemmet er ex bourbon-fade af hvidt egetræ, og det tropiske klima sætter virkelig en acceleration på udviklingen af herlighederne. Herefter lagres den på brugte Olorosso og Pedro Ximenez sherry fade i 16 måneder i kølige lagerbygninger i Italien. Denne del tilføjer et mere vinøst og frugtigt element til det endelige resultat. Næsen er præget af vanilje, eg og rosin. Smagen er meget sødmefuld, næsten cremet og nøddeagtig. Honning, brombær og chokolade. Meget vedvarende og lækker eftersmag. Det er den her du vælger, når du vil have ren forkælelse med guatemalansk finesse – en flaske, der både kan imponere gæster og gøre en tirsdag aften til noget, der minder om ferie. Rum Nation Guatemala XO 20th Anniversary Edition leveres i en flot &#8220;decanter&#8221; flaske og tilhørende gaveæske . Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Flor de Cana Eco 15 Y.O.', 'https://spitus.dk/product/flor-de-cana-eco-15-y-o/', 339, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/flor-de-cana-eco-15.png', 'Flor De Cana har rødder helt tilbage til 1890, og på San Antonio Sugar Mill i Chichigalpa, Nicaragua, producerer 5. generation af Pellas-familien stadigvæk rom, som de gjorde dengang. Flor De Cana betragtes i dag som det førende rom-destilleri i Mellemamerika, og de seneste år har de opnået succes på eksportmarkederne. Destilleriet går forrest med hensyn til bæredygtighed. F.eks. er Flor de Cana certificeret CO2-neutralt, overholder betingelserne for fair trade, bruger 100 % vedvarende energi, og endelig kompenserer de for eventuelle emissioner gennem plantning af træer. Siden 2005 er det blevet til hele 50.000 nye træer om året. Denne 15-årige udgivelse og tilføjelse til sortimentet, tager den lige skridtet videre. Flasken og gaveæsken er nemlig lavet af genbrugsmaterialer, så både produktion og materialer er så bæredygtige som muligt. I næsen smørholdige lag af karamel, eg og bagekrydderier. I munden en anelse duftende tobak, honning, chokolade, toffee og nødder. I den lange eftersmag bliver vanilje, brændt eg, kakao og allehånde hængende. Super produkt, måske især til den bæredygtige rom-kender. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Plantation XO 20th Anniversary', 'https://spitus.dk/product/rom-plantation-xo-20th-anniversary/', 429, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/100183-1.jpg', '&#8220;Plantation XO 20th Anniversary&#8221; er en blanding af flere meget gamle rom fra Barbados. Først modnet lokalt i Bourbon-fade i adskillige år, for derefter at blive hældt på små, franske limosinefade, der førhen har været brugt til lagring af Pierre Ferrand Fine Grande Champagne Cognac. Denne lagring foregår på Château de Bonbonnet i den franske region Charente, hvor den bringes ned i de kølige kældre og modner yderligere. Rommen er således lagret på flere forskellige fadtyper, deriblandt de fineste cognacfade, som er Plantations signatur, men der bruges også helt nye fade af amerikansk hvid-eg. Disse fade giver yderligere vaniljenoter til Barbados-rommen, som i forvejen emmer af tropiske frugter. Denne komplicerede aldringsproces frembringer en uforlignelig blødhed og fylde. Vi ser tit &#8220;Plantation XO 20th Anniversary” annonceret som en 20 års rom, men det er ikke helt korrekt. Der er tale om en jubilæums rom, som er fremstillet for at fejre Alexandre Gabriel&#8217;s 20 års jubilæum som øverste chef for Cognac Ferrand. Det er et blend af 12 år gammel rom, som tilsættes en række tudsegamle årgange for at give yderligere fylde og kompleksitet. Denne rom er sandsynligvis den mest kendte og elskede af alle Plantations rom. I næsen er der vanilje, karamel og ristede bananer. Den er ikke for sød – men utrolig lækker! Orange chokolade, kokos og ananas. Barbados for fuld skrue! I munden fylder den godt; nærmest cremet og olieret. Den er sød, men det tager ikke overhånd, og det hele er perfekt afbalanceret. Du får vanilje, bounty, tørret mango og mazarin. Dernæst en lækker, lækker mørk og krydret smag a’la’ kanel, Demerara rørsukker og kakao. Vi har hørt flere udbryde ”Crème Brulée”, før de bad om et glas mere. Det er svært at forestille sig, at man ikke falder pladask for dens uimodståelige charme. Giv den nogle ture rundt i glasset, og du vil opleve, at den returnerer med endnu flere lag og herlige toner af Barbados og hvide sandstrande. Det er kvalitet og en god oplevelse – heldigvis fader den først ud efter laaaang tid i munden. Den skal naturligvis drikkes rent og gerne i gode venners lag. Vi leverer den i en flot gaveæske; mest hvis du vil forkæle en god veninde eller ven! Rommen vinder rutinemæssigt priser ved diverse smagninger, bl.a.: 2016 Guldmedalje, Paris Rom Festival, Frankrig 2016 Årets spiritus, Whisky Exchange 2015 Guldmedalje, Berlin Rom Festival, Tyskland 2015 Guldmedalje, RumXP Competition, USA, og guld i kategorien, &#8220;Premium Aged Rum&#8221;, ved Miami Rum Festival 2014 Guldmedalje, Rom Festival, Finland 2014 Guldmedalje, RumXP Competition, USA 2013 Guldmedalje, Rum Master, UK 2013 Guldmedalje, RumXP, Competition, USA 2012 Master in the Category Aged over 12 Years, Rum Master, UK 2012 A.Gabriel, World Best Master Blender, Golden Rum Barrel, UK Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Goslings Black Seal Rom', 'https://spitus.dk/product/goslings-black-seal-rom/', 249, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/gosling-black-Seal.png', '96 Point &amp; “best buy” – World Spirits Championships. Gosling’s Black Seal Rum er Bermudas bedst sælgende spiritus, og faktisk har Gosling’s officielt patent på den i nationaldrikken ”Dark’n Stormy”. Gosling’s Black Seal Rum er en intens, mørk, tøndelagret rom, der fremstilles på tre forskellige destillationsapparater. Rommen aldres i forkullede amerikanske egetønder, der tidligere er blevet brugt til at lagre bourbon. Rommen indeholder ingredienser, som også bruges i blandt andet cognac og grappa. Gosling’s Black Seal Rum har en intens- og velbalanceret smag med nuancer af vanilje, flødekaramel og fudge. Hvis romverdenen havde en “mørk ridder”, så ville det uden tvivl være Goslings Black Seal Rum . Den er ikonisk, dyb, mystisk – og så smager den så godt, at du næsten får lyst til at tage en hurtig tur til Bermuda bare for at sige tak. Det her er ikke bare en rom. Det er rommen . The Beverage Tasting Institute tildelte denne rom branchens største ære; nemlig platinmedaljen, og beskrev den som dyb, stærk aromatiseret og duftende med skarpe toner af forskellige urter. Smagen afsluttes med en glathed og elegance. Deres afsluttende bemærkning var ”en kompleks og anderledes spiritus”. Den smager så godt, at du næsten får lyst til at drikke den direkte fra flasken (vi anbefaler dog et glas – mest for stilens skyld). Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Puntacana Esplendido', 'https://spitus.dk/product/punta-cana-esplendido/', 349, true, 70, 38, 'https://spitus.dk/wp-content/uploads/2023/05/punta-cana-esplendido-gb.png', 'Denne Puntacana Esplendido er en blanding af unge og ældre destillater, som igen er blandet med en moder-rom (som har en gennemsnitlig lagringsalder på 25 år). Efter sammenblandingen, får den så lige yderligere 12-20 års lagring på gamle bourbon-fade efter Solera-metoden. Noget af et virvar af forskellige blends og lagringsmetoder, og en endelig aldersangivelse kræver stort kørekort i kulstofkredsløbet. Navnet ”Esplendido” betyder noget i retning af ”fremragende”, og det er den. Temmelig mørk i glasset, og en indbydende duft af toffee og bagværk. I munden god sødme, og noter af farin, mørk chokolade, vanilje og amerikansk eg. Fuldfed oplevelse. I eftersmagen karamelliserede frugter, nødder og frisk brød. Den er… ja, espléndido. Det er en dram for dig, der gerne vil have kvalitet uden at skulle pantsætte bilen. Den er sofistikeret uden at være snobbet, og den er festlig uden at være fjollet. En perfekt balance – lidt ligesom dig, når du rammer det helt rigtige promilleniveau. Det her er flasken, der får gæsterne til at spørge: “Hvad er det, vi drikker?” Og du kan svare med et lille smil: “Bare noget jeg lige fandt hos Spitus.dk.”😉 Vi har selvfølgelig sørget for, at denne caribiske lækkerhed står klar til dig. Klik den hjem, og gør dig klar til at opleve, hvorfor Puntacana-serien har fået så mange romelskere til at kigge længselsfuldt mod syd. Og hey – hvis du ender med at købe to flasker, så siger vi det ikke til nogen. Det er faktisk bare god planlægning. Vi leverer den i en gaveæske – mest hvis du kunne finde på at give den som gave. Alkohol %: 38,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Puntacana XOX', 'https://spitus.dk/product/punta-cana-xox/', 759, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/punta-cana-xox-gb.png', 'Denne Puntacana XOX er en 50 års jubilæumsudgivelse, udgivet for at fejre 50 året for Oliver familiens immigration til Den Dominikanske Republik fra Cuba. Det er altså ikke en fuldlagret 50-års rom, men derimod et blend sammensat af flere yngre og ældre destillater, som blandes med en såkaldt moderrom på 25 år, inden den bliver solera-lagret i 25-30 år. Til slut færdiglagres den 3-6 måneder på portvinsfade fra Graham’s. Hvis Puntacana-serien var en familie, så er denne Puntacana XOX den elegante onkel, der altid møder op i linnedskjorte, dufter af sol og succes og har en mystisk historie om en strandbar et sted i Caribien. Det her er flasken, der ikke behøver at råbe for at blive hørt – den hvisker bare “kom herover”, og pludselig sidder du med et glas i hånden og et smil, du ikke helt kan forklare. Meget mørk mahogni-farve, og i næsen masser af modne frugter, sød tobak, vanilje, egetræ, rosiner og en anelse røg. Fantastisk næse, som vidner om stor rom! I munden bliver du absolut ikke skuffet. Sødlig, men med masser af power. Igen modne og karamelliserede frugter. Flødekarameller, toffee, mokka og en anelse tørhed der holder sødmen fint i skak. Fantastisk balance og fuldfed oplevelse, der heldigvis bliver ved og ved i munden længe. Det er meget gammel rom det her, og det smager så fuglene synger! Et hav af præmier og anerkendelser verden over. Bl.a. Dobbelt Guld ved Romfestivalen i Rom. Mads ”Romhatten” Heitmann konkluderer hans anmeldelse således: &#8220;Puntacana Club XOX 50 Aniversario Oporto får mine varmeste anbefalinger – stor applaus herfra” 95 points. Dette er skrevet i 2013, og der er løbet meget rom gennem blodet siden. Men kvaliteten holder stadig. 😉. Nummererede flasker og gaveæske. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Barbados 8 Y.O.', 'https://spitus.dk/product/rum-nation-barbados-8-y-o/', 299, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/rum-nation-barbados-8-yo.png', 'Fabio Rossi er manden bag Rum Nation, og det karakteristiske ved hans rom er, at det er det enkelte lands særegne kendetegn der er i fokus, og ikke så meget hvem der har destilleret rommen. Det er også derfor flaskerne er forsynet med en label lavet som frimærker fra det enkelte land hvorfra rommen stammer. Så, Rum Nation køber relative unge rom op, lader dem lagre lokalt i f.eks. 6-8 år, hvorefter de lagrer i yderligere en tid på fad i enten Italien eller England. Ifølge Fabio, er det vigtigt at rommen får de første unge år lokalt, hvor den tager mere imod omgivelsernes påvirkning. Romserien er efterhånden verdensomspændende, og består udelukkende af udvalgte fade fra hvert destilleri. Her skal vi til Barbados, også kaldt ”rommens vugge”. Typisk, og som man ofte forbinder med ”Barbados-stilen”, blender man her rom lavet på pot-still og på et mere traditionel kolonne-anlæg. Den første metode giver masser af kraft og saft, og kolonnedestilleringen giver noget blødhed og en bedre afrunding af rommen. I næsen får du karamel, vanilje, modne frugter, og da vi jo er i Barbados; naturligvis kokos. I munden dejlig frisk med noget mint, og frisk hø. Herlig, urteagtig sødme. Blodappelsiner, bananer og ferskner blander sig. Meget let drikkelig, blid og venlig. Ikke sukkersød, da den har en vis tørhed. Meget typisk og lækker Barbados-rom, der har haft godt af den subtropiske lagring. Lukker man øjnene, kan man næsten drømme sig…nej; det virker ikke, men rommen er god nok. Leveres i gaveæske. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rammstein Rum PX Sherry Cask Finish', 'https://spitus.dk/product/rammstein-rum-px-sherry-cask-finish/', 679, true, 70, 46, 'https://spitus.dk/wp-content/uploads/2023/05/rammstein-px-sherry-cask-finish-gb-k.png', 'Rammstein Rum PX Sherry Cask Finish er rommen der giver dig en sødme‑uppercut med pyro i baggrunden. Hvis Rammstein lavede dessert, ville det være denne rom. PX‑sherryfinishen gør den så sød, mørk og intens, at du næsten forventer, at Till Lindemann springer ud af flasken og råber “Bück dich… og skænk en dram!” Rammstein Rum er en perfekt afbalanceret blanding af Jamaica og Guyana Pot Still Rom, samt Column Still Rom fra Trinidad, Guyana og Jamaica. Alderen er op til 12 år, og efter blendingen, får den 5 måneder ekstra i brugte Pedro Ximenez sherryfade. Matchet mellem de tørre noter fra de oprindelige bourbon-fade, og de meget søde noter fra sherry-fadende ser vi ofte, og det er der altså en god grund til. Farven er mørk rav. Næsen er forholdsvis frugtig, men også mandler, honning og krydderkager. I munden søde krydderier, ristet eg, vilde mørke bær og en fint snert af røg. Bemærk: dette er den ret sjældne udgave hvor sherry-fadene er fra PX. Udgivet i i alt 1,930 flasker. Det er flasken til dig, der vil have sødme, power og rock’n’roll i samme slurk – som en rom, der både kan kysse dig og slå dig i gulvet, alt efter humør. Samlerobjekt og naturligvis specielt populær blandt Rammstein-fans (altså bandet 😉). Leveres i gaverør. Alkohol %: 46,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Cubaney 18 Y.O. Seleceto', 'https://spitus.dk/product/cubaney-18-y-o-seleceto/', 348, true, 70, 38, 'https://spitus.dk/wp-content/uploads/2023/05/cubaney-18-yo-gb.png', 'Ron Cubaney Grand Reserve Selecto Solera Rum 18 års (langt navn) er en dominikansk rom fra mastodonterne Oliver &amp; Oliver. Stilen er cubansk med demerarasukker og rige sherry- og kaffenoter. Da Cuba blev ramt af politisk uro, måtte Oliver familien flygte til Den Dominikanske Republik, hvor de stadig bor den dag i dag. Familien holder dog fast i sin cubanske arv, og producerer masser af prisvindende rom i den cubanske stilart. Oliver &amp; Oliver har specialiseret sig i blending af højkvalitetsrom, og har gennem årene vundet en lang række internationale priser – faktisk mere end to hundrede! Solera-metoden er typisk for stilarten, og her er det ældste blend altså 18 år. I næsen er der kakao, chokolade, rosiner, lime og bananer. I munden let krydret, med chokolade, karamel, eksotiske frugter, kanel og appelsiner. Eftersmagen er rig på eg og vanilje, og i det hele taget sødmefuld, blød og meget imødekommende. Meget typisk produkt fra Oliver &amp; Oliver, og et meget godt køb hvis du er til en klar publikumsbasker. Leveres i gaveæske. Alkohol %: 38,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Flor De Cana 12 Y.O., i gaveæske m/glas', 'https://spitus.dk/product/flor-de-cana-12-y-o-i-gaveaeske-m-glas/', 329, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/flor-de-cana-12-yo-gb-glas.png', 'Flor De Cana har rødder helt tilbage til 1890, og på San Antonio Sugar Mill i Chichigalpa, Nicaragua, producerer 5. generation af Pellas-familien stadigvæk rom som de gjorde dengang. Flor De Cana betragtes i dag som det førende rom-destilleri i Mellemamerika, og de seneste år har de opnået stor succes på eksportmarkederne. Denne Flor de Cana 12 års ”Old Rom” er bl.a. vinder af 13 internationale priser, og er vel deres bedst kendte produkt. Farven er rav – med et rødt skær. I næsen er der sherry, eg og karamel. I munden sødlig, men ikke voldsom sød, med smør, honning, nougat, brændte fade, karamel og dadler. I den lange eftersmag, får du mere af det hele, men krydderierne, og nogle mere mørke noter træder fint frem. Uden tilsat kunstige trylleting, og da der er tale om en fuldlagret 12-års rom, mærker man de mange år på ryggen i fadene ganske tydeligt. Dejlig uhyre velafbalanceret rom, der bedst nydes rent med isterninger. Stærkt anbefalet af Wine Enthusiast, og 90 – 95 points. At destilleriet går forrest med hensyn til bæredygtighed, synes vi er et stort plus. F.eks. er Flor de Cana certificeret CO2-neutralt, overholder betingelserne for fair trade, bruger 100 % vedvarende energi, og endelig kompenserer de for eventuelle emissioner gennem plantning af træer. Siden 2005 er det blevet til hele 50.000 nye træer om året. Vi ka’ li det! Hvis du vil forære lidt kærlighed, leverer vi den i en gaveæske (genbrugspap) inkl. 2 Flor De Cana rom-glas. Egentligt vanvittigt, at man kan få så meget ægte fuldlagret rom for de penge. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Flor De Cana 20 Y.O. 130th Anniversary', 'https://spitus.dk/product/flor-de-cana-20-y-o-130th-anniversary/', 679, true, 70, 45, 'https://spitus.dk/wp-content/uploads/2023/05/flor-de-cana-130-anniversary-gb.png', 'Flor De Cana har rødder helt tilbage til 1890, og på San Antonio Sugar Mill i Chichigalpa, Nicaragua, producerer 5. generation af Pellas-familien stadigvæk rom som de gjorde dengang. For at markere deres 130-års jubilæum, udgav de i 2020 denne forrygende 20-års rom, som bl.a. brugerne på Rumratings.com er ret vilde med. I næsen ananas, karamel, peber og egetræ. I munden overraskende super smooth (trods solide 45% alkohol), mørk chokolade, toffee, muskatnødder og vanilje. Meget lang og varm eftersmag. Ikke så kompliceret, men uhyre behagelig, ren og imødekommende. Sådan markerer man sin 130-års fødselsdag, når man er et top-destilleri! At destilleriet går forrest med hensyn til bæredygtighed, synes vi er et stort plus. F.eks. er Flor de Cana certificeret CO2-neutralt, overholder betingelserne for fair trade, bruger 100 % vedvarende energi, og endelig kompenserer de for eventuelle emissioner gennem plantning af træer. Siden 2005 er det blevet til hele 50.000 nye træer om året. Gammelt og bæredygtig kan godt gå hånd i hånd. Alkohol %: 45,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Demerara No. 14 Solera', 'https://spitus.dk/product/rum-nation-demerara-solera/', 349, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/rum-nation-demerara-solera.png', 'Fabio Rossi er manden bag Rum Nation, og det karakteristiske ved hans rom er, at det er det enkelte lands særegne kendetegn der er i fokus, og ikke så meget hvem der har destilleret rommen. Det er også derfor flaskerne er forsynet med en label lavet som frimærker fra det enkelte land, hvorfra rommen stammer. Så, Rum Nation køber relative unge rom op, lader dem lagre lokalt i f.eks. 6-8 år, hvorefter de lagrer i yderligere en tid på fad i enten Italien eller England. Ifølge Fabio, er det vigtigt at rommen får de første unge år lokalt, hvor den tager mere imod omgivelsernes påvirkning. Romserien er efterhånden verdensomspændende, og består udelukkende af udvalgte fade fra hvert destilleri. Med denne Rum Nation Demerara Solera, har vi fat i rum fra Guyana! Og så ved vi godt hvad det betyder. Der er nemlig kun et destilleri tilbage i landet; sagnomspundne Diamond Distillery. De bruger bl.a. stadig de ikoniske gamle trækedler, som ”Port Morant” fra 1732 og ”Enmore”-kedlen lavet i hårdt regnskovstræ. Det er jo navne som får tårerne frem i mange rom-elskers øjne, men det er uvist på præcis hvilke af deres 10 kedler Rum Nation Demerara No. 14 er lavet på. Det er dog ganske sikkert, at der er tale om både potstil- og kolonnedestilleret rom. Det er også sikkert, at den er lagret på brugte amerikanske Bourbon-fade, og at de sidste 12 måneder i Europa foregår på PX-sherry fade. I næsen barbecue, appelsin og krydderier. I munden noget sødere end næsen indikerede. Stor cremethed, med kanel, chokolade, lakrids og sort peber. I den bløde og runde eftersmag, får du mokka, mørk chokolade, honning og vanilje. Meget aromatisk, fløjlsblød rom, der dog har sit eget lille særpræg i form af den fine nuance af barbecue og røg. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation Guatemala Gran Reserva', 'https://spitus.dk/product/rum-nation-guatemala-gran-reserva/', 339, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/rum-nation-guatemala-gran-reserva.png', 'Fabio Rossi er manden bag Rum Nation, og det karakteristiske ved hans rom er, at det er det enkelte lands særegne kendetegn der er i fokus, og ikke så meget hvem der har destilleret rommen. Det er også derfor flaskerne er forsynet med en label lavet som frimærker fra det enkelte land, hvorfra rommen stammer. Så, Rum Nation køber relative unge rom op, lader dem lagre lokalt i f.eks. 6-8 år, hvorefter de lagrer i yderligere en tid på fad i enten Italien eller England. Ifølge Fabio, er det vigtigt at rommen får de første unge år lokalt, hvor den tager mere imod omgivelsernes påvirkning. Romserien er efterhånden verdensomspændende, og består udelukkende af udvalgte fade fra hvert destilleri. Denne herlige Rum Nation Guatemala Gran Reserva, er en melassebaseret rom, gæret og destilleret på destilleriet S.A. TULULA. Efter destilleringen, fragtes rommen til det nord-østlige hjørne af Guatemala, hvor den 185 meter over havets overflade, får 4 år på ryggen i ex-bourbon fade. Området ligger ved Rio Hondo, og er meget frodigt med enorm høj luftfugtighed, og modningen accelerer dermed kraftigt. Det er rom i den spanske stil, dvs. bl.a. sige overvejende sød, med masser af modne frugter, chokolade og nødder. Den er dog ikke så sød som de fleste andre i genren, og den bringer en dejlig lethed og i eftersmagen en dejlig varme. En anelse mint og urter, giver den noget andet end blot traditionelle sukker-rom. En charmerende størrelse. Leveres i en gaveæske. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Austrian Empire Navy Rum 18 Y.O.', 'https://spitus.dk/product/austrian-empire-navy-rum-18-y-o/', 399, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/austrian-empire-navy-rum-18-yo-gb.png', 'Klassisk Barbados rom, produceret af Oliver &amp; Oliver Rums &#8211; som er de store drenge i Den Dominikanske Republik. 18-års solera lagring, dvs. det ældste blend i flasken er 18 år, som så er blendet med andre årgange for at få noget friskhed til rommen (og gøre den væsentligt billigere end en fuldlagret rom). Efter sigende, er gennemsnitsalderen her 12 år, og du får i hvert fald masser af fad. Duften er let krydret med kanel og allehånde. I munden stor sødme med masser af chokolade, karamel, vanilje, eg og nektar. I eftersmagen får du krydderier, og en anelse appelsin og tørrede frugter. Rom i den populære sødlige spanske stil, som danskerne elsker. Leveres i gaveæske. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Ron Prohibido 12 Y.O.', 'https://spitus.dk/product/el-ron-prohibido-12-y-o/', 289, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2023/05/el-ron-prohibido-12-years-k.jpg', 'El Ron Prohibido Reserva 12 år er lagret efter Solera-metoden og indeholder derfor rom, der er op til 12 år gammel. El Ron Prohibido betyder- og er kendt som &#8220;Den Forbudte Rom&#8221;. Men hvorfor kaldes El Ron Prohibido så ”Den Forbudte Rom&#8221;? Tjooo, historien går på, at i omkring år 1700 ankom spanske skibe til det nye kontinent Amerika fyldt med produkter fra Den Iberiske Halvø. Blandt dem var tønder fyldt med sød rosinvin. Efter at have tømt tønderne i Amerika, blev det besluttet at fylde dem med Chinguirito (Mexicansk sukkerrørs-likør/”rom”). Det var jo fjollet at sejle tilbage med tomme tønder. På turen tilbage over havet afgav tønderne noter fra den søde vin til den mexicanske likør, og da skibet anløb Spanien, var der tale om et helt andet produkt. Denne drik vandt hurtigt utrolig stor opmærksomhed og popularitet overalt. Da den spanske konge hørte om denne mexicanske drik, som udkonkurrerede den spanske spiritus, valgte han at forbyde den for at redde de spanske mærker. Bandlysningen varede i næsten 100 år. Når en flaske er så god, at myndighederne bliver nervøse, så ved du, at du har fat i noget særligt. Heldigvis lever vi i en tid, hvor du ikke behøver smugle den i en tønde eller gemme den under gulvbrædderne. Du kan bare bestille den hos Spitus.dk og nyde den helt lovligt. Lagringen i de gamle fade, som har indeholdt sød vin, giver en dram med masser af eksotiske frugter, vanilje, kaffe, mælkechokolade og smørnoter. Munden fyldes med rosiner, ferskner, nødder, eg og chokolade. Et godt bud på en sød flaske i den spanske stil til en meget attraktiv pris. Alkohol %: 42,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bayou Pink', 'https://spitus.dk/product/bayou-pink/', 199, true, 70, 37.5, 'https://spitus.dk/wp-content/uploads/2023/05/bayou-pink.png', 'Pink Rom? Nuvel – der skal være plads til alle. Og når du erfarer, at Bayou Pink er lavet ved at blende lokale Mayhaw-bær med Bayou’s populære pot-stil rom fra Louisiana, kommer armene hurtigt op igen. Mayhaw er et lille syrligt bær, der vokser i det sydlige USA. Det ligner et tranebær, og smager lidt som en blanding af rosenvand og granatæble. Resultatet er, at du får nogle syrlige frugtnoter til rommens tropiske sødme – noget mere friskhed, som i mange drinks og cocktails virker fint. Prøv den f.eks. i Moscow Mule, Mojitos eller Piña Colada, i stedet for Tequila. Eller bland den med Sprite og tilsæt is – enkelt og lækkert. Farven er oplagt til fest og farver, så Bayou Pink falder fint ind i barskabet eller hjemmebaren. Alkohol %: 37,5 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Austrian Empire Navy Reserva 1863', 'https://spitus.dk/product/austrian-empire-navy-reserva-1863/', 339, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/austrian-empire-navy-reserva-1863-rum-based-spir.-k.jpg', 'Austrian Empire Navy Reserva 1863 er flasken der ser ud som en gentleman, men slår som en kejserlig kanon. Denne dram er som at invitere en østrig-ungarsk officer fra 1800‑tallet hjem i stuen: høflig, velklædt og med en duft af eventyr… men du ved også, at han har set ting, du ikke gør dig begreb om. Austrian Empire Navy Reserva 1863 er mørk, sød, fyldig og overraskende fræk – en oplevelse, der kombinerer caribisk varme med europæisk elegance. Det er flasken, du vælger, når du vil have noget, der både er historisk, hedonistisk og helt uimodståeligt – en udgivelse, der smager af gamle søslag, store fortællinger og ren nydelse. Austrian Empire Navy Reserva 1863: Den kejserlige sødmebombe med uniform og attitude. 🥃 Austrian Empire Navy Reserva 1863 er en blanding af 5-12 år gammel rom, der har ligget på både bourbonfade og franske egetræsfade. Der er tale om en &#8220;small batch&#8221; produktion fra specielt udvalgte fade, der efterfølgende er blended af Master Blenders fra den Dominikanske Republik og Barbados. Farven er mørk, og duften emmer honning, karamel, kakao og nødder. Smagen er blød og rund med noter af vanilje, farin og kakao samt et strejf af sherry. En finish så lang og varm, at du overvejer at udstede den en adelstitel Lækker Barbados-sag! Leveres i gaveæske Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador Platinium Colombian Aged Rum', 'https://spitus.dk/product/dictador-platinium-colombian-aged-rum/', 975, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/04/dictador-platinium-78-k.jpg', 'Dictador Platinum er flasken, der glider ind som en colombiansk gentleman med solbriller på indendørs. Den er smooth, elegant og poleret – men du kan stadig mærke, at der gemmer sig en lille rebel under overfladen. Dictador XO Platinum 40% er et eksklusivt blend af rom i alderen 25-35 år. Rommen er lavet af &#8220;Virgin Sugar Cane” – og altså ikke melassebaseret. Sukkerrørsjuicen fermenteres i minimum 60 timer, hvorefter 30% destilleres i en moderne alembic kolonne, og resten destilleres i en kolonnekeddel. Derefter lagres Dictador Platinium på både brugte bourbon- og sherry-fade fra Jerez. Fadene har fået en genbrænding, for at øge noterne af eg., vanilje, karamel og røg. Rommen blendes forsigtigt fra de forskellige fade i hånden, først når master blenderen har godkendt, tappes der på flasker. Resultatet er en meget charmerende og fyldig rom. Masser af vanilje, honning og egetræ. I munden tydelig toffee, kaffe og et touch af karamel. Dejlig balance, og den lette sødme matcher godt noterne fra de brændte fade. Eftersmagen er voluminøs, og Dictador Platinium bliver heldigvis bare ved og ved. Dictador Platinum er stilet, smooth og med nok swagger til at få dig til at smile i skægget. Eksklusiv flaskedesign inkl. gaveæske. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Volbeat Seal the Deal Rum', 'https://spitus.dk/product/volbeat-seal-the-deal-rum/', 369, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/volbeat-seal-the-deal-k.jpg', 'Seal the Deal fra det danske band Volbeat, er et blend af nøje udvalgte caribiske rom, der primært stammer fra de helt klassiske rom-områder: Den Dominikanske Republik, Trinidad og Tobago. Seal The Deal udkom første gang i 2022, og har en lettere profil end bandets tidligere rom “Rum, Rum II, Rum III og 20 Years Single Estate”. Volbeat Seal the Deal Rum er rommen der giver dig et musikalsk nakkeslag af ren hygge. Denne rom er skabt til at fejre Seal the Deal &amp; Let’s Boogie ‑æraen – og den smager præcis som titlen lover: en blanding af rock’n’roll, charme og en lille smule ballade. Det er flasken, der træder ind i stuen, skruer op for volumen og siger: “Skal vi lige have det lidt hyggeligt… på den hårde måde?” En fantastisk gylden rom, med en blød og lækker eftersmag. Volbeat Seal the Deal Rum er lavet til at være alsidig nok til både at kunne nydes præcis som den er, men samtidig også til at kunne bruges i diverse cocktails og drinks. Der er tale om en blanding af ulagret og tre til fem års lagret kolonnedestilleret rom, der er vokset op i brugte bourbon-fade. Der er tale om er en meget velafbalanceret rom, med en blød eftersmag med noter af vanilje, appelsin, lakrids og karamel. Meget god allround rom, som nok skal opnå succes – ganske som bandet selv og de andre rom i serien. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dos Maderas PX 5+5 Years Old Aged Rum, i gaveæske m/2 glas', 'https://spitus.dk/product/dos-maderas-px-55-years-old-aged-rum-i-gaveaeske-m-2-glas/', 449, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/04/dos-maderas-px-55-years-old-aged-rum-k.jpg', 'Dos Maderas-huset blev grundlagt tilbage i 1877 af Sir Alexander Williams, der var en stor beundrer og connaisseur af sherry, og af Arthur Humbert, der var en fremragende international forretningsmand. Williams &amp; Humbert har siden vundet stor anerkendelse for deres sherry, brandy og rom. I denne Dos Maderas 5+5 Years Old, udvælger Master Blenderen rom fra Barbados og Guyana, hvorefter den lagres 5 år i Caribien. Herefter sejles den over Atlanten til Williams &amp; Humbert i Spanien, hvor anden del af lagringen begynder. Først får den 3 år på ryggen i egetræsfade, der tidligere har været brugt til at modne den respekterede Dos Cartados Oloroso sherry. Den tredje lagring foregår 2 år i fade fra den tungere og mere fyldige ”Don Guido” Pedro Ximenez sherry. (Begge sherry fade indeholdt over 20 år gammel sherry). I næsen får du masser af sherry-noter; rosiner og fad. I munden mere sherry, dadler, figner, vanilje og en dejlig sødme. Fornem og lækker, lang eftersmag. Dos Maderas PX 5+5 er spiritussens svar på en gentleman med dessert i lommen; den er sød, den er lækker &#8211; og den har taget glas med. Har bl.a. taget Guldmedalje ved International Rum Expert Panel i 2010. Og i denne gaveæske får du to originale Dos Maderas glas , så du ikke behøver drikke den alene (selvom du godt kunne). Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise X.O. Reserve Port Cask Rum &#8211; Old Edition', 'https://spitus.dk/product/a-h-riise-x-o-reserve-port-cask-rum-old-edition/', 539, true, 70, 45, 'https://spitus.dk/wp-content/uploads/2023/04/ah-riise-xo-reserve-port-cask-rum-old-edi-k.jpg', 'A.H. Riise XO Reserve Port Cask Rom i den sjældne ”Old Edition” (Vi sælger også den nyere version (billigere) på shoppen). Rommen er sammensat af nogle af de bedste og ældste fade fra Vestindien og Centralamerika som destilleriet råder over. Faktisk går der helt op mod 15 forskellige romdestillater til denne rom. Og med en gennemsnitsalder på 20 år er det ikke ligefrem en vårhare. Alle destillater er nøje udvalg af A.H. Riise’s masterblender og skaber en rom udover det sædvanlige. Den nænsomme lagring og sammensætning gør i sig selv A.H. Riise X.O. Port Cask Rum til noget særligt. Men for at gøre oplevelsen endnu større, er rommen efterlagret på udsøgte fade, der tidligere har været hjem for klassisk portvin. Den færdige rom får nemlig mindst seks måneder på portvinsfade fra det kendte hus Cálem. Det giver en unik fadfinish, der gør A.H. Riise XO Reserve Port Cask Rom til en dejlig kompleks og fyldig rum. Hvert fad er specielt udvalgt og håndaftappet enkeltvis. Produktionstallet er begrænset, og alle flaskerne er desuden mærket med et individuelt flaske- og fadnummer samt aftapningsdato. I næsen er den ret frugtagtig med skovbær og portvin. I munden fortsætter det sødmefulde indtryk, og du møder vanilje, portvin, chokolade, rosiner og en anelse tobak. Dejlig fyldig eftersmag, der holder en fin længde. Dejlig dram, men det helt specielle ved netop denne udgivelse er naturligvis at der er tale om den gamle og meget sjældne udgivelse fra før nye EU-direktiver trådte i kraft. Et decideret samlerobjekt! Leveres i gaveæske Alkohol %: 45,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Royal Danish Navy Frogman Rum &#8211; Old Edition (58%)', 'https://spitus.dk/product/a-h-riise-royal-danish-navy-frogman-rum-old-edition-58/', 989, false, 70, 58, 'https://spitus.dk/wp-content/uploads/2023/04/ah-riise-frogman-old-version-k.jpg', 'A.H. Riise Royal Danish Navy Frogman er lavet som en hyldest til det danske Frømandskorps. The Frogman Association Conventus Ranae blev oprettet i 1957 (inspireret af lignende foreninger i den Britiske Specialbådtjeneste (SBS), det Amerikanske Undervandsnedrivningshold (UDT) og Navy SEALS). I de senere år har A.H. Riise samarbejdet med Conventus Ranae, hvilket blandt andet førte til lanceringen af denne berømte A.H. Riise Royal Danish Navy Frogman Rum 58%. Senere kom der andre versioner, bl.a. ”Conventus Ramae” med 60% i alkoholstyrke. Denne A.H. Riise Royal Danish Navy Frogman Rum Old Edition er en dram der kan lave armbøjninger for dig. Frogman Old Edition er ikke bare en rom – det er en militærøvelse i et glas . Den er så kraftig, at den burde komme med egen redningsvest, og så intens, at selv isterningerne står ret, når du hælder den op. Det her er Navy‑styrke med attitude. En hyldest til de danske frømænd – og du kan smage det: rå power, dyb sødme og en varme, der føles som en tropisk eksplosion med uniform på. Men; dette er denne gamle version, som er klart den mest eftertragtede og sjældne for samlere. Prisen er så også steget siden lanceringen, men den vil sikkert fortsætte denne udvikling i takt med at der bliver endnu færre tilbage på markedet. Vi har kun et meget lille parti, og herefter er det slut. Der er tale om et ”hand-blend” i små partier, af flere rom der er op til 20 år gamle. Den destilleres i en traditionel “Pot Still”, og kommer fra karet med en alkoholstyrke på 65 %. Den er ikke koldfiltreret eller tilsat karamel. Den har noter af kaffe, lakrids, brændt karamelmelasse, krydderier og cedertræ. Men der er også en eksotisk og elegant smag af Sevilla appelsiner og bergamot frugt. Finishen er lang, og er i perfekt balance mellem det sødlige, og varmen fra alkoholen. Til kenderen og samleren. Leveres i gaveæske Alkohol %: 58,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise X.O. Reserve 175 Years Anniversary Rum &#8211; Old Edition', 'https://spitus.dk/product/a-h-riise-x-o-reserve-175-years-anniversary-rum-old-edition/', 519, false, 70, 42, 'https://spitus.dk/wp-content/uploads/2023/04/ah-riise-175ann-old-version-k.jpg', 'A.H. Riise XO 175th Anniversary Rom blev fremstillet første gang i 2013 &#8211; præcis 175 år efter A.H. Riise for første gang slog dørene op til sit apotek på St. Thomas. Der er tale om en særlig jubilæumsrom, hvor hovedblended er lagret i 21 år, men tilsat yngre destillater for at øge spændstigheden. A.H Riise XO 175th Anniversary rom er lagret ved lave temperaturer og høj luftfugtighed i dybe mørke kældre, hvor den har haft de bedste betingelser for en god rom. Det specielle ved denne jubilæumsrom er, at den efterlagres på PX- og Oloroso-sherryfade. Netop disse fade giver rommen sit udtryk af mørk, sødmefuld sherry. I næsen og ganen er sherry-noterne tydelige, og du får dertil fyldig vanilje og karamel. Skovbær og figner kommer tydeligst frem i den lange, cremede eftersmag. Det unikke ved denne version er, at det er ”Old Edition”. Dvs. bl.a. fra før EU ændrede på kravene omkring rom, og der er tale om et samlerobjekt, som der kun er ganske få tilbage af på markedet . (Vi sælger naturligvis også den nyere (og billigere) version, som du finder her ) Leveres i gaveæske Alkohol %: 42,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bumbu XO Handcrafted Rum, 35 cl', 'https://spitus.dk/product/bumbu-xo-handcrafted-rum-35-cl/', 219, true, 35, 40, 'https://spitus.dk/wp-content/uploads/2023/04/bumbu-xo-35cl-k.jpg', 'Bumbu XO Handcrafted Rum 35 cl er den lille pirat med stor mund og endnu større charme. Den er spiritussens svar på en kompakt sportsvogn: lille, lækker og fuld af selvtillid. Bumbu XO er destilleret og lagret i Panama. Destillatet er fremstillet på sukkerrør fra 8 forskellige lande. Bumbu XO er lagret i brugte bourbon fade og har efterfølgende fået tid i brugte sherry fade fra Andalusien. I næsen er der masser af tropiske frugter og vanilje. Smagen er karamel, der har været på luksusferie med mørk chokolade, kaffe, og en finish så smooth, at du overvejer at sende den en DM. Meget sød, og med masser af charme og karakter. Det er drammen, du vælger, når du vil have noget, der både er elegant og frækt – en flaske, der er lille nok til at være gavevenlig, men stor nok i smag til at få dig til at smile som en pirat med ny skattekiste. Bumbu XO har vundet mange priser – bl.a. Guld ved Los Angeles International Spirit Competition 2017. Bumbu storsælger over hele verden, og er du til sød, frugtrig forkælelse, skylder du dig selv at prøve Bumbu XO. Den kommer i en flot og dekorativ matsort flaske. Bumbu XO 35 cl er en lille bandit, der smager som en million. Alkohol %: 40,0 Størrelse: 35 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Reserve Super Premium Single Barrel Rum, 35 cl &#8211; Batch 1', 'https://spitus.dk/product/a-h-riise-x-o-reserve-super-premium-single-barrel-rum-35-cl/', 279, true, 35, 40, 'https://spitus.dk/wp-content/uploads/2023/04/a.h.riise_.xo_.35cl-k.jpg', 'A.H. Riise XO er en samling af ekstra gamle blandinger lavet af dobbeltdestilleret førsteklasses modnet caribisk rom. Blandingerne er nøje udvalgt og sammensat af A.H. Riise’s masterblendere for at sikre perfekt afbalancerede og ensartede blandinger. Stilen er den søde, balsamiske og aromatiske med stærke rødder i A. H.Riise’s arv fra Dansk Vestindien. Lagringen i PX og Oloroso sherryfade bidrager til den mørke og søde smag. Blended er sammensat af fine gamle romfade (op til 20 år) samt lidt yngre fade, der giver en perfekt kant og fyldig smagsoplevelse. Hvert fad er specielt udvalgt af A.H. Riise´s Master Blender, aftappet enkeltvis &#8220;Single Barrel&#8221;, og hver flaske er desuden mærket individuelt med fad-nummer samt aftapnings dato. Farven er flot gylden, let mahogniagtig. I munden meget frugtagtig og fyldig smag med nuancer af appelsin, mango, papaya og vanilje, afsluttende med en fløjlsagtig blød og delikat, sødmefuld eftersmag. A.H. Riises rom er nogle af de absolut mest solgte i Danmark, og den meget søde stil har mange fans. Det er en ”let at gå til rom&#8221;, som falder i de flestes smag. OBS! Dette er en special-udgave i &#8220;Old Version&#8221; 35cl. &#8211; Batch 1! Alkohol %: 40,0 Størrelse: 35 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Flor De Cana 18 Y.O. Rom- 1 liter', 'https://spitus.dk/product/flor-de-cana-18-y-o-1-liter/', 549, true, 100, 40, 'https://spitus.dk/wp-content/uploads/2023/05/flor-de-cana-centenario-18-yo-gb.png', 'Flor De Cana har rødder helt tilbage til 1890, og på San Antonio Sugar Mill i Chichigalpa, Nicaragua, producerer 5. generation af Pellas-familien stadigvæk rom som de gjorde dengang. Flor De Cana betragtes i dag som det førende rom-destilleri i Mellemamerika, og de seneste år har de opnået stor succes på eksportmarkederne. Denne Flor de Caña 18 års ”Slow Aged Old Rum”, er en perfekt repræsentant for det destilleri kan. 18 år på fade kræver tålmodighed, men det har man i Chichigalpa, og kvaliteten fornægter sig ikke. Bl.a. tildelt dobbelte guldmedaljer ved 2006 og 2008 San Francisco World Spirits Competition. Næsen er krydret, sprød og med en del eg. Smagen er meget fyldig og ret tyktflydende med tør eg, lidt kakao, krydderier, toffee, nødder og allehånde. I den langvarige finish er den prikkende, med vaniljekrydderier, nødder og fad. Fuldfed kvalitetsrom. At destilleriet går forrest med hensyn til bæredygtighed, synes vi er et stort plus. F.eks. er Flor de Cana certificeret CO2-neutralt, overholder betingelserne for fair trade, bruger 100 % vedvarende energi, og endelig kompenserer de for eventuelle emissioner gennem plantning af træer. Siden 2005 er det blevet til hele 50.000 nye træer om året. Her leverer vi den i en 1 liters version i gaveæske . Alkohol %: 40,0 Størrelse: 1 liter');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Volbeat 20 Years Old Single Estate Rum', 'https://spitus.dk/product/volbeat-20-years-old-single-estate-rum/', 2395, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/05/volbeat-20-aars-k.jpg', 'Samtidig med at Michael og Jon i 2001 gik i Danmark og arbejdede med den allerførste Volbeat sang, startede det ikoniske Diamond Distillery destilleringen af præcis denne rom. Ingen anede dengang, at de 2 ting nu forenes 20 år senere. Volbeat 20 YO er en single estate rom fra Den Dominikanske Republik , tappet i forbindelse med bandets 20‑års jubilæum. Det er en af de mest modne band‑rom på markedet og ligger milevidt fra de søde “fan‑rom”, man ellers ser. Glem alt om en pladerballe rom. Det er Guyana, det er Diamond, det er 20 års fuld fadlagring, det er kræs. Single Estate – alt foregår hos Diamond. Tappet fra 9 forskellige fade udvalgt af bandet. ”Vi håber, I nyder denne unikt destillerede og emballerede rom lige så meget, som vi har nydt at udvælge den til jer. Her er til tyve år mere og endnu længere,” siger Volbeats sanger og guitarist Michael Poulsen. Udgivet i 2022 i alt 2.400 nummererede flasker, og smukt pakket ind i flaske og læderetui. Det er rommen til dig, der vil have noget med både power og polish – en flaske, der smager af håndværk, attitude og 20 års erfaring i at gøre tingene ordentligt. Et decideret samleobjekt, med ganske få tilbage på markedet, og bl.a. derfor forventes den kun at stige yderligere i pris. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cueva 1501 Solera 8', 'https://spitus.dk/product/ron-cueva-1501-solera-8/', 349, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/04/Ron-Cueva-1501-Solera-8.png', 'Her præsenterer vi ungdommens friskhed, i form af denne lækre Ron Cueva , der har lagret i gennemsnit 8 år i solera-systemet. Farven er gyldent kobber. I næsen chokolade, eksotiske frugter og fine krydderier. Dejlig sød note fra fadene (vanilje &amp; eg). I munden karamel, chokolade og tørrede frugter. Kaffebønner, bagte æbler og en anelse kanel. Stor friskhed, og ret livlig på tungen fra den frugtige profil. Sød, men stadig med bid og substans. Hvis Ron Cuerva 8 års var en person, ville den være ham fyren, der altid dukker op til festen med et stort smil, en god historie og en skjorte, der er lige en tand for farverig – men som alligevel får alle til at elske ham. Dejlig harmoni og balance, og uhyre meget rom for pengene. Smuk, smuk flaske og tilhørende gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Founders Reserve No 2', 'https://spitus.dk/product/a-h-riise-founders-reserve-no-2/', 749, true, 70, 44.3, 'https://spitus.dk/wp-content/uploads/2023/03/ah-riise-founders-reserve-no2-k.jpg', 'Founders Reserve er en ny XO-serie fra A.H. Riise bestående af blends, der repræsenterer et helt unikt øjebliksbillede. De lækre dråber findes kun i begrænsede- og forskellige antal flasker. Hver batch er unik, og kan aldrig genskabes. Den første udgivelse er fra medio 2021 (Founders Reserve No. 1) (11.232 flasker), og kom med en styrke på 44,5 % og har rød tekst på etiketten. Founders Reserve No. 2 (11.280 flasker) med en styrke på 44,3% blev lanceret i begyndelsen af 2022 og har blå tekst på etiketten Founders Reserve No. 3 (8.976 flasker) med en styrke på 44,8% blev udgivet medio 2022 og har en grøn tekst på etiketten. Founders Reserve No. 4 var klar i butikkerne fra d. 27. januar 2023 (14.225 flasker, mørkerød tekst og 45,1% alkohol). Founders Reserve No. 5 udkom i maj 2023 (13,995 flasker, orange tekst og 44,4% alkohol). Founders Reserve No. 6 udkom d. 1. september, i et oplag på 13.665 flasker, med lysegrøn tekst og en alkoholprocent på 45,5%. Hver flaske er nummereret med et batch- og flaskenummer. Som de øvrige i serien, er den gylden i farven. I næsen tropisk frugt, kirsebær og blide tobaksnoter. I ganen forfriskende tropiske frugter, mørk chokolade, vanilje, blommer, ristede mandler og en anelse brun farin. Vidunderlig blød og vedholdende eftersmag. Med en rigtig god balance mellem den elegante sødme og komplementerende syre, er Founders Reserve Serien en rigtig god repræsentant for A. H. Riise-stilen. Måske en flaske til nydelse, og et par stykker som investering. Leveres i gaveæske, og gratis til din nærmeste pakkeboks. Alkohol %: 44,3 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Founders Reserve No 3', 'https://spitus.dk/product/a-h-riise-founders-reserve-no-3/', 1049, false, 70, 44.8, 'https://spitus.dk/wp-content/uploads/2023/03/ah-riise-founders-reserve-no3-k.jpg', 'Founders Reserve er en ny XO-serie fra A.H. Riise bestående af blends, der repræsenterer et helt unikt øjebliksbillede. De lækre dråber findes kun i begrænsede- og forskellige antal flasker. Hver batch er unik, og kan aldrig genskabes. Den første udgivelse er fra medio 2021 (Founders Reserve No. 1) (11.232 flasker), og kom med en styrke på 44,5 % og har rød tekst på etiketten. Founders Reserve No. 2 (11.280 flasker) med en styrke på 44,3% blev lanceret i begyndelsen af 2022 og har blå tekst på etiketten. Founders Reserve No. 3 (8.976 flasker) med en styrke på 44,8% blev udgivet medio 2022 og har en grøn tekst på etiketten. Founders Reserve No. 4 var klar i butikkerne fra d. 27. januar 2023 (14.225 flasker, mørkerød tekst og 45,1% alkohol). Founders Reserve No. 5 udkom i maj 2023 (13,995 flasker, orange tekst og 44,4% alkohol). Founders Reserve No. 6 udkom d. 1. september, i et oplag på 13.665 flasker, med lysegrøn tekst og en alkoholprocent på 45,5%. Hver flaske er nummereret med et batch- og flaskenummer. De 5 første er for længst udsolgt fra A.H. Riise, og specielt No. 1 og No. 3 er svære at skaffe, og er blevet eftertragtede samlerobjekter. Denne nummer 3 er altså udgivet i færrest eksemplarer, og nok også derfor den forventes at stige yderligere i pris &#8211; og sikkert bliver den mest eftertragtede i serien. Som de øvrige i serien, er den gylden i farven. I næsen tropisk frugt, kirsebær og blide tobaksnoter. I ganen forfriskende tropiske frugter, mørk chokolade, vanilje, blommer, ristede mandler og en anelse brun farin. Vidunderlig blød og vedholdende eftersmag. Med en rigtig god balance mellem den elegante sødme og komplementerende syre, er Founders Reserve Serien en rigtig god repræsentant for A. H. Riise-stilen. Leveres i gaveæske, og gratis til din nærmeste pakkeboks. Alkohol %: 44,8 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Foursquare Spiced', 'https://spitus.dk/product/foursquare-spiced/', 289, true, 70, 37.5, 'https://spitus.dk/wp-content/uploads/2023/05/foursquare.png', 'Hhmmmm hmmm; krydrede (Spicy) rom? Må indrømme, at vi som regel foretrækker krydderier og rom hver for sig. Overvægt af kanel og kardemomme hører til på risengrød eller julebagværk. Så kan vi drikke rommen bagefter. Men Foursquare fra Barbados rammer den faktisk ret godt her, og dette er én af de absolut bedste Spicy udgivelser på markedet &#8211; overhovedet! Det legendariske Foursquare Distillery er kendte for at lave rom med så meget karakter, at selv din svigermor ville blive imponeret. Her får du en variant, der er krydret med finesse, balanceret med omhu og rundet af med en sødme, der ikke prøver at overdøve smagen, men i stedet giver dig et kærligt klap på skulderen. Hvis almindelig spiced spiritus er som en hyggelig eftermiddag i sofaen, så er Foursquare Spiced som en tropisk ferie, hvor bartenderen kender dit navn, vejret altid er perfekt, og du aldrig får sand i skoene. Det er Barbados på flaske – uden solskoldning og uden at skulle forklare i lufthavnen, hvorfor du har pakket 14 par shorts. Næsen er krydret (surprise), med kanel, pebermynte, julekager, muskatnød og marmelade. I munden toffee, bagte æbler, søde krydderier honningkager. En anelse bitter appelsinskal. Afslutningen er ret lang med hvid chokolade, julekrydderier, mandler, kandiserede frugter, butterscotch og pebernødder. Kan jo godt nydes rent, men i en krydret Mojito&#8230;&#8230;.? For hulen da også. Alkohol %: 37,5 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Zacapa 23 Y.O. i gaveæske m/ 2 glas', 'https://spitus.dk/product/zacapa-23-y-o-i-gaveaeske-m-2-glas/', 569, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/01/ron-zacapa-23-gaveaeske-k.jpg', 'Zacapa 23 år er for mange den første kærlighed til fadlagret rom. Den har vundet utallige priser, herunder flere gange kåret til ”Verdens bedste rom”. Ron Zacapa Centenario 23 års var den første rom, der vandt førstepladsen i kategorien ”Premium Rum” 4 år i træk ved Den Internationale Rom Festival; 1998, 1999, 2000 og 2001. Det var også den første rom, der blev inkluderet i International Rum Festival’s Hall of Fame. Zacapa 23 er spiritussens svar på en klassiker i skræddersyet jakkesæt: elegant, dyb, silkeblød og altid imponerende. Og i denne gaveæske med to smukke glas får du hele Zacapa‑oplevelsen pakket ind i ren forkælelse – perfekt som gave eller som en opgradering til hjemmebaren. Farven er let mahogni, og man fornemmer alderen, hvor de lange spor klæber sig fast til indersiden af glasset. I næsen blød og sød med karamel, vanilje, kakao og rosiner. Man fornemmer de mange lag og kompleksiteten fra de mange forskellige typer fade. Der er sherrynoter og ristede hasselnødder. I munden går indtrykket fra næsen igen, og man får derudover tørret ananas (sikkert fra de amerikanske whisky-fade) og banan. Den er generøs og fyldig med en sød honningviskositet, rosiner, vanilje og abrikoser. Det er stor velsmag, og den lukker med et touch af læder, tobak samt et smæld af kanel og ingefær. Alle kan være med her. Nye ude i rommens verden vil værdsætte den søde, men stadig komplekse stil. Kendere fornægter ikke et godt produkt, om end nogle foretrækker rom med større tørhed. Vi kan sagtens forstå, at Ron Zacapa 23 års har gået sin sejrsgang over hele verden. Det er en dram, der både kan nydes rent, i langsomme slurke, eller deles med en, der fortjener noget ekstra. Zacapa 23 i gaveæske: Luksus, varme og guatemalansk finesse – klar til at blive givet væk eller nydt med stil. Vi har taget et parti hjem, hvor du får den i en gaveæske inkl. 2 af de ægte- og eftertragtede Ron Zacapa rom-glas. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H.Riise XO Founders Reserve No 1', 'https://spitus.dk/product/a-h-riise-x-o-founders-reserve-no-1/', 1499, false, 70, 44.5, 'https://spitus.dk/wp-content/uploads/2023/01/ah-riise-xo-founders-reserve-no-1-k.jpg', 'Founders Reserve er en ny XO-serie fra A.H. Riise bestående af blends, der repræsenterer et helt unikt øjebliksbillede. De lækre dråber findes kun i begrænsede- og forskellige antal flasker. Hver batch er unik, og kan aldrig genskabes. Den neførste udgivelse er fra medio 2021 (Founders Reserve No. 1) (11.232 flasker), og kom med en styrke på 44,5 % og har rød tekst på etiketten. Founders Reserve No. 2 (11.280 flasker) med en styrke på 44,3% blev lanceret i begyndelsen af 2022 og har blå tekst på etiketten. Founders Reserve No. 3 (8.976 flasker) med en styrke på 44,8% blev udgivet medio 2022 og har en grøn tekst på etiketten. Founders Reserve No. 4 var klar i butikkerne fra d. 27. januar 2023 (14.225 flasker, mørkerød tekst og 45,1% alkohol). Founders Reserve No. 5 udkom i maj 2023 (13,995 flasker, orange tekst og 44,4% alkohol). Founders Reserve No. 6 udkom d. 1. september, i et oplag på 13.665 flasker, med lysegrøn tekst og en alkoholprocent på 45,5%. Hver flaske er nummereret med et batch- og flaskenummer. De 5 første er for længst udsolgt fra A.H. Riise, og specielt No. 1 og No. 3 er svære at skaffe, og er blevet eftertragtede samlerobjekter. Mon ikke alle 6 varianter om kort tid vil opleve det samme? Denne nummer 1 indeholder i næsen tropisk frugt, gærede kirsebær og bløde tobaksnoter. I ganen forfriskende mørk chokolade, vanilje, blommer og et touch af ristede mandler. Vidunderlig blød og vedholdende eftersmag. Med en rigtig god balance mellem den elegante sødme og komplementerende syre, er Founders Reserve No. 1 den perfekte hyldest til A.H. Riise. Der er kun ganske få Founders Reserve No. 1 tilbage, og endnu færre der er tilgængelige for køb. Det har naturligt presset prisen op, og den udvikling vil sikkert fortsætte. Vi er blevet tilbudt et lille parti, som vi har taget ind og håber på vil bringe glæde blandt samlere og andre A.H. Riise aficionados. Som nydelse eller investering. Leveres i gaveæske, og gratis hjem til dig eller i nærmeste pakkeboks. Alkohol% : 44,5 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rammstein Rum', 'https://spitus.dk/product/rammstein-rum/', 339, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/11/rammestein-rum-k.jpg', 'Det tyske metalband Rammstein blev grundlagt i 1994 og er i dag et af de mest berømte rockbands i hele verden. De er kendt for kæmpe shows med masser af pyroteknik og ægte metal-stemning. I forbindelse med deres 25-års jubilæum i 2019 udgav de for første gang denne lækre sag. Den er ikke så hårdtslående som bandet, men fint afbalanceret og let tilgængelig. Der er tale om et blend af rom fra hhv. Jamaica og Guyana, som giver en fyldig krop med styrke og sødlig aroma. Dette er blended med rom fra Trinidad, som tilføjer det silkebløde og frugtige lag. Den har både jamaicansk funk, trinidadisk elegance og guyansk dybde – en treenighed, der rammer som et pyroteknisk sceneshow. Sammen er de lagret i op til 12 år på brugte bourbon-fade. Det er flasken, du vælger, når du vil have en rom, der ikke bare smager godt, men føles som en Rammstein‑koncert i slow motion. Rammstein Rum: Feuer frei i glasset. Leveres i gaverør. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Rum Nation &#8211; Meticho Chocolate &amp; Toffee 4,5 liter', 'https://spitus.dk/product/rum-nation-meticho-chocolate-toffee-45-liter/', 2395, false, 450, 40, 'https://spitus.dk/wp-content/uploads/2023/11/rum-nation-meticho-chocolate-toffee-45l.png', 'Okay – her er et monster af en chokoladebar. Bund den, og du rører aldrig konfekt eller chokolade igen. Du rører nok heller ikke så meget andet, men du siger farvel med en herlig sødme i mundvigene. Gedigen fredagsslik for voksne. Rum Nation Meticho Chocolate &amp; Toffee er en rombaseret spiritus lavet på Centralamerikansk rom, blandet med chokolade, toffee, vanilje og karamel. Det er omtrent så sødt som det lyder. Men varmen og fyldigheden fra rommen redder dagen. Cremet, fyldig og næsten konfektagtig smag. Nydes rent med is, gerne til desserten eller når der bare er brug for noget sødt og godt. Her i en 4,5 liters udgave. Så kan du godt nappe et glas hver dag. I lang tid. Alkohol % : 40,0 Størrelse : 4,5 liter');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santos Dumont Heritage Hors D&#8217;Age', 'https://spitus.dk/product/santos-dumont-heritage-hors-dage/', 1495, true, 70, 43.8, 'https://spitus.dk/wp-content/uploads/2022/11/santos-dumont-heritage-k.jpg', 'Her præsenterer vi det absolutte top-produkt fra Santos Dumont! Hors D’Age Heritage ramte verdensmarkedet d. 3. december 2021, og med et oplag på kun 14.000 flasker i alt, er den egentlig udsolgt for længst. Santos Dumont Heritage Hors d’Age er et luksusblend skabt af ekstremt gamle og sjældne fade fra både Brasilien, Caribien og Mellemamerika, samlet i en profil, der er lige så eksotisk som navnet og lige så elegant som flasken. Den er mere præcist lavet af brasiliansk frisk sukkerrørssaft, blandet med melassebaseret rom fra Vestindien og Mellemamerika. Der var ikke mange fade der levede op til kravene for at indgå i blendet, og dermed det begrænsede antal flasker. I næsen får du abrikos, sød tobak, chokolade og en anelse olieret læder. Smagen er dyb, silkeblød og dekadent med lag af abrikoser, karamel, vanilje, kokos, tørret frugt, honning, chokolade og en varm, vinøs tone fra de særlige fade, der bruges i modningen. Det er en rom, der føles som dessert, cigar‑lounge og tropisk solnedgang på én gang. Det er flasken, du vælger, når du vil have noget, der både er luksuriøst, anderledes og fuldstændig uimodståeligt smooth. Santos Dumont Heritage: En gudedrik med charme, eksotisk sødme og aristokratisk selvtillid. Er du til sød spiritus i A. H. Riise stilen, er Santos Dumont Hors D’Age Heritage noget af det absolut ypperste. Selve flasken er med sin pyramideform meget eksklusiv og elegant, og også som gave er den oplagt. Leveres i gaveæske. Alkohol % : 43,8 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santos Dumont XO Gewurztraminer', 'https://spitus.dk/product/santos-dumont-xo-gewurztraminer/', 349, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/11/santos-dumont-xo-gewurztraminer-k.jpg', 'Santos Dumont XO Gewürztraminer er spiritussen der tog en omvej gennem Alsace. Efter EU-reglerne, er det en såkaldt spirit drink, og dermed ikke en egentlig rom. Santos Dumont XO Gewürztraminer er en af de mest charmerende og aromatiske udgaver i hele Santos‑universet. Den starter som en klassisk, sødmefuld og silkeblød XO‑variant – og får derefter et vinøst, parfumeret og eksotisk twist fra lagring i tidligere Gewürztraminer‑fade. Resultatet er noget helt for sig selv. I næsen er der de klassiske tropiske frugter, chokolade og en anelse krydderi. I munden en dejlig varme med appelsiner, abrikoser, søde druer og dessertvin. Afslutningen er ret lang, med stor sødme og lækker cremet viskositet, og blomstrede noter fra Gewürztraminer‑vinen. Det er en variant, der føles som dessert, blomsterhave og tropisk ferie i samme glas – uden at blive for tung. Perfekt til dem, der elsker deres drink med masser af duft, sødme og finesse. Santos Dumont XO Gewürztraminer: Eksotisk, aromatisk og uimodståeligt smooth. Santos Dumont har mange fans, og den appellerer til alle der sætter pris på sød spiritus af høj kvalitet. Er du (&#8220;kun&#8221;) til lak og læder, er dette derimod ikke noget for dig. Flotte, individuelt nummererede flasker. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo Centuria Reserva de la Familia 30 Y.O. Rom', 'https://spitus.dk/product/abuelo-centuria-30-y-o/', 999, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/11/abuelo-centuria-30-y.o.-k.jpg', 'Ron Abuelo Centuria Reserva de la Familia 30 Years blev først udgivet i 2008, i anledning af at det var 100 år siden destilleriets grundlægger, Don José Varela Blanco, byggede den første sukkermølle i byen Pesé i Panama. Der er tale om en &#8220;Single Estate Rom&#8221;, idet Abuelo har egne marker med sukkerrør (der håndplukkes), egne kolonner til destillering og egne lagerfaciliteter til fadene. Faktisk er det sidste meget vigtigt, da Abuelos lagring er ret unik bl.a. grundet klimaet i Pesé Panama. Destilleriet er nemlig beliggende i en lille fertil dal i Azuero Peninsula. Den moderate nedbør, de kolde nætter og den høje luftfugtighed er tydeligvis med til at udvikle og modne rommen på en særlig vis. Der er tale om et nøje sammensat blend, hvor den ældste del består af 30 år gammel rom. Ron Abuelo Centuria Reserva de la Familia 30 års er i den elskede søde, spanske stil, og den har opnået stor popularitet verden over. Specielt efter den i 2011 vandt prisen som verdens bedste nye rom på markedet. I næsen får du en tyk, klæbrig, sirupsagtige duft, med en anelse røg og vanilje. Efter et stykke tid, bliver den mere intens, og der kommer cedertræ, kaffebønner og farin. Smagen er sød, med æblestrudel, muskatnød, kanel, vanilje, karamel og en lille antydning af røg. Abuelo Centuria er ikke bare en rom. Det er rommens svar på en symfoni, komponeret over årtier. Den er skabt af nogle af de ældste fade i Abuelo‑kælderen – en solera, hvor dele af indholdet er over 30 år gammelt – og resultatet er ren, moden perfektion. Leveres i en træ-gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 2010 Port Mourant Uitvlucht', 'https://spitus.dk/product/el-dorado-2010-port-mourant-uitvlucht/', 1398, true, 70, 51, 'https://spitus.dk/wp-content/uploads/2022/11/el-dorado-2010-port-mourant-uitvlucht-k.jpg', 'El Dorado Port Mourant Uitvlugt 2010 Orange er en melasse-rom destilleret hos Diamond i Guyana. Destilleriet i Demerara River-regionen er hjemsted for nogle af de mest legendariske stills i verden. El Dorado har således bevaret knowhow og stills fra landets gamle destillerier, og kan derfor eksperimentere med et uendeligt antal forskellige smagsprofiler. El Dorado udgiver en gang imellem disse fad-blandede rom som et eksklusivt supplement til deres mere kendte og faste sortiment. Denne lækre og unikke rom blev destilleret på den berømte træpot-still Port Mourant, samt på de 4 søjler i Uitvlugt Continuous Savalle Still i 2010. Blandingen fra ​​disse to ikoner (mærket: PM og ICBU) blev udført før den kom på fad, hvorefter den fik 9 år på brugte bourbon-fade, og efterfølgende blev tappet direkte på flaske i 2019. Næsen er domineret af mørke, ristede og noget æteriske nuancer. Det tager et øjeblik for røgskyen at forsvinde, og herefter afslører den dejlige ristede nødder samt kokos-noter. Efter lidt tid i glasset bekræfter rommen sin ristede karakter, og udvikler noter af toast, tør kaffe, derefter muskatnød og en anelse lakrids. I ganen meget blød, og den har en meget flydende tekstur. En mere koncentreret, ristet bølge af chokoladeovertrukne nødder, kaffe og derefter ristet hvidt træ følger. Vaniljen dukker op, og viser en sødere side, der klæder rommen fortrinligt. Kraftfuld rom med masser af punch og fylde! Leveres i gaveæske Alkohol % : 51,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XV 15 Years Napoleon Cognac Cask Rom', 'https://spitus.dk/product/abuelo-xv-15-years-napoleon-cognac-cask/', 569, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/11/abuelo-napoleon-vx-k.jpg', 'Ron Abuelo XV 15 år Napoleon Cognac Cask Finish er en del af en ny serie fra Abuelo på i alt tre rom (de andre er ”Sherry Finish” og ”Port Finish”). Men denne er altså, efter lagringen på brugte boubon-fade, efterlagret på brugte Napoleon cognacfade. Abuelo XV 15 Years Napoleon Cognac Cask er når Panama møder fransk aristokrati. Der er tale om &#8220;Single Estate Rom&#8221;, idet Abuelo har egne marker hvor sukkerrørene håndplukkes, egne kolonner til destillering og egne lagerfaciliteter til fadene. Faktisk er det sidste meget vigtigt, da Abuelos lagring er ret unik grundet klimaet i Pesé Panama. Destilleriet er nemlig beliggende i en lille fertil dal i Azuero Peninsula. Den moderate nedbør, de kolde nætter og høje luftfugtighed er tydeligvis med til at udvikle og modne rommen på en særlig vis. I næsen afdæmpet cognac som spiller harmonisk sammen med rommen, og du fornemmer en dejlig krydret tørhed. I munden er den cremet og sødmefuld. Smagen er elegant, dyb og silkeblød med lag af karamel, vanilje, tørret frugt, druer, let ristet eg og en raffineret vinøs note fra cognacfadene. Den føles både varm og sofistikeret, som en rom der har lært gode manerer i Cognac – men stadig har sin panamanske sjæl intakt. I den lange finish, dukker også læder og nogle jordagtige noter op. Lækker sag i den populære stil. Leveres i gaveæske. Alkohol % : 40,0 Størrelse : 70 cl,');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Santos Dumont XO Palmira', 'https://spitus.dk/product/santos-dumont-xo-palmira/', 349, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/11/santos-dumont-xo-palmira-k1.jpg', 'Santos Dumont XO &#8220;Palmira er ikke en egentlig rom, men en såkaldt &#8220;Rhum Traditionelle&#8221; &#8211; en rombaseret spiritus destilleret på sukkerørssaft. Den minder dog meget om rom i den elskede, spanske-cubanske stil, med masser af sødme og tropiske frugter. Dette er kendetegnet for alle udgivelser i Santos Dumont-serien. Mange elsker dem, og andre synes det bliver for sødt. Lagringen er primært foregået på brugte fade der tidligere indeholdt dessertvine, og vi er i det hele taget langt fra den franske agricole-stil. Farven er flot gylden. I munden milde tanniner, vanilje, eg, honning og sød tobak. I finishen er der også abrikoser og tydelige noter af chokolade. Er du til sød rom a’la’ A.H. Riise, er Santos Dumont et forsøg værd. Er du til læder, olie og brændt gummi er der tale om et dårligt match. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 2010 Diamond Port Mourant', 'https://spitus.dk/product/el-dorado-2010-diamond-port-mourant/', 1398, true, 70, 49.1, 'https://spitus.dk/wp-content/uploads/2022/11/el-dorado-2010-diamand-port-mourant-k.jpg', 'Unikt blend fra rom-specialisten El Dorado. El Dorado Diamond Port Mourant 2010 (Green Label) er en melasse-rom destilleret hos Diamond i Guyana. Destilleriet i Demerara River-regionen er hjemsted for nogle af de mest legendariske stills i verden. El Dorado har således bevaret knowhow og stills fra landets gamle destillerier, og kan derfor eksperimentere med et uendeligt antal forskellige smagsprofiler. El Dorado udgiver en gang imellem disse fad-blandede rom som et eksklusivt supplement til deres mere kendte og faste sortiment. Her har Diamond-destilleriet blandet rom fra Coffey-søjler og den legendariske Port Mourant Wooden Double Pot Still. Disse rom blev destilleret i 2010, herefter lagret i Guyana i gamle bourbontønder frem til de blev blandet og tappet på flaske i 2019. ”Brut de fût”, dvs. uden tilsætninger, nedvanding eller kølefiltrering mm. Næsen er først præget af lidt sød kaffe, derefter brændt træ. Noter af ristede nødder kommer frem, og i glasset er de markante karamelliserede nøddeagtige noter tydelige. Det er jo bl.a. det der gør Demerara-rom så charmerende. Her får du på toppen er let krydret lag. I ganen er der masser af mørkt-ristet egetræsfad, hvis brændte overflade bringer en næsten mineralsk kul-fornemmelse. Fra dette mørke kommer noter af lakrids frem, men med en saftig pift af koncentreret juice. Den intense kerne af nødder er til stede på midten af ​​ganen, men stadig karamelliseret og fløjlsblødt. Afslutningen har et let røget, ristet præg, men frem for alt en masse rundhed og fylde. Det lyder dyrt – bedøm selv! Leveres i gaveæske. Alkohol % : 49,1 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 2008 Uitvlucht Enmore', 'https://spitus.dk/product/el-dorado-2008-uitvlucht-enmore/', 1398, true, 70, 47.4, 'https://spitus.dk/wp-content/uploads/2022/11/el-dorado-2008-uitvlucht-enmore-k.jpg', 'Unikt blend fra rom-specialisten El Dorado. El Dorado Uitvlugt Enmore 2008 Blue er en melasse-rom destilleret hos Diamond i Guyana. Destilleriet i Demerara River-regionen er hjemsted for nogle af de mest legendariske stills i verden. El Dorado har således bevaret knowhow og stills fra landets gamle destillerier, og kan derfor eksperimentere med et uendeligt antal forskellige smagsprofiler. El Dorado udgiver en gang imellem disse fad-blandede rom, som et eksklusivt supplement til deres mere kendte og faste sortiment. Her præsenterer vi resultatet af at Demerara Distillers Ltd. tilbage i 2008 valgte at blende Rum Marques fra legenderne Uitvlugt Continoius Savalle Still og Enmore Wooden Continous Coffey Still i et fad lige efter destillation. Herefter er den 100% tropisk lagret i 11 år på ex-bourbon fade i Guyana, og naturligvis ikke kølefiltreret, reduceret eller tilsat farve etc. Rommen har en dyb gylden ravfarve. Næsen er enormt forførende og påkalder Enmore-søjlens storhedstid. En håndfuld nødder overtrukket med stadig dampende karamel titter frem. En anelse hvidt træ og varm harpiks pifter stemningen op. Efter lidt tid i glasset, kommer der brændt træ, søde krydderier og honning frem. Smagen er eminent med blød, ristet amerikansk eg og den typiske vaniljesmag. Tilføj hertil en meget flydende og let rund tekstur, og du har en nem og tilgængelig Demerara. Nødder med masser af karamel, honning, mørk chokolade og modne frugter fuldender billedet. Unik og meget spændende rom! Historie og kvalitet på flaske. Leveres i gaveæske. Alkohol % : 47,4 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Royal Danish Navy, i gaveæske m/2 glas', 'https://spitus.dk/product/a-h-riise-royal-danish-navy-i-gaveaeske-m-2-glas/', 525, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/12/a.h.riise-royal-danish-navy-gaveaeske-m-glas-k.jpg', 'A.H. Riise Royal Danish Navy 40 % er blended af flere forskellige og op til 20 år gamle romdestillater fra Caribien. Det er en melassebaseret rom, der er frembragt ved langsom gæring. Efterfølgende bliver rommen destilleret til en rom med 85 % alkoholstyrke. Det sker ved den traditionelle pot still-destillering, der giver rommen et højt indhold af estere og kraftig duft. Først til sidst vandes rommen ned til lettere drikkelige 40 %, inden rommen tappes på de eksklusive flasker. A.H. Riise Royal Danish Navy 40 % er skabt med inspiration i de originale recepter på Royal Navy Rum. Opskrifterne blev udviklet af A.H. Riise, og rommen leveret til flådens skibe, når de anløb havnen i Charlotte Amalie i det tidligere Dansk Vestindien. A.H. Riise Royal Danish Navy har ikke samme tørre stil og element som typiske engelske navy-rom. Den er markant lettere at gå til, og har noget ganske fint og sart over sig. I næsen møder du cedertræ, karamel, lakrids og appelsiner. I munden får du eksotiske krydderier, kandiserede æbler, appelsin, kokos og karamel. Meget eksotisk og elegant. Fed, olieret og lang eftersmag med abrikos og sødmefulde krydderier. Vinder af flere internationale priser. Her leverer vi den i en lækker gaveæske inkl. 2 A. H. Riise glas. Alkohol% : 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Matusalem 7 Y.O. Solera', 'https://spitus.dk/product/matusalem-7-y-o-solera/', 189, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/08/matusalem-solera-7-k.jpg', 'Matusalem 7 Y.O. Solera er en smooth cubanske klassiker, der aldrig går af mode. Matusalem 7 er spiritussens svar på en perfekt strøget hvid skjorte: enkel, elegant og altid en sikker vinder. Den er skabt efter solera‑metoden, hvilket giver en overraskende moden og afrundet smag for en 7‑årig rom – og gør den til en af de mest alsidige flasker i sin klasse. Smagen er blød, let sød og velafbalanceret med noter af karamel, vanilje, honning, mildt krydderi og et strejf af tropisk frugt. Den er ren og smooth nok til at drikke rent, men samtidig frisk og livlig nok til at løfte enhver cocktail. Det er flasken, du hiver frem, når du vil have noget, der både er klassisk, let drikkeligt og fuld af cubansk charme. Matusalem 7 Solera er den gyldne allrounder, der altid leverer. Som Mads ”Romhatten” Heitmann skriver: ”Matusalems 7 å rs rom er en klassisk solera-lagret vaniljerom….. Det er en klart anbefalelsesv æ rdig rom, hvis man leder efter en god opblandingsrom. Til en rom og cola sidder den lige i skabet og bestemt ogs å n å r man ser p å prisen. S å n å r du f å r t ø mt din Captain Morgan Spiced Gold og leder efter et alternativ, s å t æ nk p å Matusalem ’ s 7 å rs rom.” Vi vil blot tilføje, at den også sidder i skabet i en Piña Colada. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Kiss Black Diamond 50 cl', 'https://spitus.dk/product/kiss-black-diamond-50-cl/', 299, true, 50, 40, 'https://spitus.dk/wp-content/uploads/2022/08/kiss-black-diamond-k.jpg', 'KISS Black Diamond Rum er en super blanding af forskellige reservedestillater fra Caribien med en alder på op til 15 år. Etiketten, der dekorerer flasken, er naturligvis inspireret af sangen Black Diamond fra bandets første album. KISS Black Diamond er drammen der går på scenen med fuld makeup og nul kompromiser. KISS Black Diamond er flasken, der ikke bare står i baren – den poserer . Det er en mørk, sødmefuld og rock’n’roll‑ladet flaske, der hylder bandets ikoniske energi og deres klassiske “Black Diamond”-attitude: tung, dramatisk og helt uden skam i livet. Farven er mørk, brun/mahogni. I næsen krydret med fadkarakter og et strejf af figner, abrikoser, kakao og vanilje. Smagen er fyldig og smooth med noter af karamel, vanilje, brun farin, mørk frugt og et strejf af krydderi. Den er lige så let at drikke, som den er svær at glemme – præcis som et KISS‑show. Det er flasken, du hiver frem, når du vil have noget, der både smager godt og ser ud som om det kunne starte en verdens­turné. KISS Black Diamond: nærmest skriger “You wanted the best – you got the best!” I munden suppleres der med nødder, tørrede druer og egetræ. Alkohol % : 40,0 Størrelse : 50 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo Anejo 12 Years Rom', 'https://spitus.dk/product/abuelo-anejo-12-years/', 289, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/12/abuelo-anejo-12-y-k.jpg', 'Abuelo Anejo 12 Years er en populær ”Best buy rom”, og nok destilleri Varela Hermanos’ vigtigste eksportprodukt. Der er tale om en fuldlagret rom, der også findes i udgaver lagret i 5- hhv. 7 år. Denne har ligget på fad i 12 år i Panamas varme klima, og der virkeligt tale om et dejligt bekendtskab. Abuelo Añejo 12 Years er rommen, der viser præcis hvorfor Panama er blevet et hotspot for kvalitetsrom. Den er moden, afrundet og elegant – uden at miste den varme, sødmefulde charme, som Abuelo‑familien er kendt for. I næsen er der brændt eg, chokolade, karamel, og en anelse syrlighed fra appelsin og hindbær. Smagen er blød og fyldig med noter af karamel, vanilje, tørret frugt, let krydderi og en mild trævarme fra de 12 års lagring. Den er smooth nok til at drikke ren, men har samtidig nok karakter til at gøre cocktails ekstra luksuriøse. Det er rommen, du hiver frem, når du vil have noget, der både er klassisk, velbalanceret og uimodståeligt drikkevenligt. Abuelo 12 er Panamansk håndværk i perfekt harmoni. Mads ”Romhatten” Heitmann slutter hans anmeldelse således: ”I dag er det en rom, som jeg godt kan lide netop pga. den tunge egetræssmag. Jeg synes at den har mere at byde på end den gennemsnitlige søde rom. Til 300-350 kr. synes jeg at dette er et kanon godt romkøb, specielt hvis man har en sød tand i ny og næ.” Leveres i gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Don Q Gold', 'https://spitus.dk/product/don-q-gold/', 199, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/08/don-q-gold-k.jpg', 'Don Q Gold er Puerto Ricos gyldne allround‑rom. Don Q Gold er rommens svar på en schweizerkniv: alsidig, smooth og altid klar til at levere. Det er en let, gylden og elegant rom fra Puerto Rico, skabt til både cocktails og ren nydelse – uden at blive tung eller sød. Smagen er frisk, blød og velafbalanceret med noter af vanilje, let karamel, citrus og et strejf af krydret eg. Den er ren og letdrikkelig, men stadig med nok karakter til at løfte enhver drink. I traditionel sødlig, spansk romstil, er Don Q Gold Rum destilleret i et kontinuerligt multikolonne-destilleringssystem og efterfølgende modnet mellem 1,5 og fem år i egetræsfade af amerikansk hvideg. Don Q Gold Rum repræsenterer den lette modnede romstil som bl.a. produceres på Cuba, Den Dominikanske Republik og naturligvis som her: Puerto Rico. Det er en rom som er skabt til cocktails som Cuba Libre, Piña Colada, Mai Tai, Mojito og andre klassikere hvor let og modnet rom gør sig godt. Har vundet flere guldmedaljer, f.eks. ved Worlds Spirits Awards 2008. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Kirk &#038; Sweeney Reserva Rom', 'https://spitus.dk/product/kirk-sweeney-reserva/', 399, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/03/kirk-and-sweeney-reserva-k.jpg', 'Kirk and Sweeney er dejlige, klassiske mørke rom fra den Dominikanske Republik. Navnet stammer fra en træskonnert, som under spiritusforbuddet i USA smuglede rom fra Caribien mod nord. Skonnerten blev opbragt i 1924 i New Jersey af US Coast Card, og senere brugt som skoleskib for nye kadetter fra den amerikanske østkyst. I 1948 blev Kirk and Sweeney-skonnerten ophugget, men rommen kan du heldigvis stadig få! Forseglingen på Kirk and Sweeney flaskerne gemmer på en sjov lille detalje. Korken er forseglet med et tyndt messingfarvet bånd med længde og breddegraderne 40 ° 34 &#8216;57.62 &#8220;- 73 ° 19&#8217; 2.14&#8221;. Koordinaterne fører til Jones Beach, der i 1920´erne ofte blev brugt når der blev smuglet rom til USA. Kirk &amp; Sweeney Reserva er rommen, der føles som at få et varmt kram fra Caribien. Den er blød, rund og uimodståeligt drikkevenlig. Smagen er fyldig og lækker med noter af karamel, vanilje, tørret frugt, toffee og et strejf af krydret eg. Den har den klassiske dominikanske sødme, men stadig god dybde og kompleksitet. En rom, der glider ned som en drøm og får dig til at overveje, om du egentlig behøver dessert. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Kirk &#038; Sweeney 12 Years', 'https://spitus.dk/product/kirk-sweeney-12-years/', 429, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/03/kirk-and-sweeney-12-k.jpg', 'Kirk and Sweeney er dejlige, klassiske mørke rom fra den Dominikanske Republik. Navnet stammer fra en træskonnert, som under spiritusforbuddet i USA smuglede rom fra Caribien mod nord. Skonnerten blev opbragt i 1924 i New Jersey af US Coast Card, og senere brugt som skoleskib for nye kadetter fra den amerikanske østkyst. I 1948 blev Kirk and Sweeney-skonnerten ophugget, men rommen kan du heldigvis få! Forseglingen på Kirk and Sweeney flaskerne gemmer på en sjov lille detalje. Korken er forseglet med et tyndt messingfarvet bånd med længde og breddegraderne 40 ° 34 &#8216;57.62 &#8220;- 73 ° 19&#8217; 2.14&#8221;. Koordinaterne fører til Jones Beach, der i 1920´erne ofte blev brugt når der blev smuglet rom til USA. Denne Kirk &amp; Sweeney 12 er rommens svar på den dér ven, der altid møder op i perfekt outfit uden at virke som om han har gjort sig umage. Den er smooth, sødmefuld og overraskende moden for sin alder – en perfekt “gateway‑rom” for både nye og garvede drikkere. Smagen er blød, rund og lækker med noter af karamel, vanilje, tørret frugt og et strejf af krydret eg. Den har den klassiske dominikanske varme, men uden at blive tung – bare ren, velafbalanceret nydelse. Det er flasken, du hiver frem, når du vil have noget, der både er let at elske og svært at lægge fra sig. Kirk &amp; Sweeney 12 Years er den unge charmetrold med caribisk glød. Lækkert produkt og flot flaske! Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Kirk &#038; Sweeney 18 Years', 'https://spitus.dk/product/kirk-sweeney-18-years/', 499, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/03/kirk-and-sweeney-18-k.jpg', 'Kirk and Sweeney er dejlige, klassiske mørke rom fra den Dominikanske Republik. Navnet stammer fra en træskonnert, som under spiritusforbuddet i USA smuglede rom fra Caribien mod nord. Skonnerten blev opbragt i 1924 i New Jersey af US Coast Card, og senere brugt som skoleskib for nye kadetter fra den amerikanske østkyst. I 1948 blev Kirk and Sweeney-skonnerten ophugget, men rommen kan du heldigvis få! Forseglingen på Kirk and Sweeney flaskerne gemmer på en sjov lille detalje. Korken er forseglet med et tyndt messingfarvet bånd med længde og breddegraderne 40 ° 34 &#8216;57.62 &#8220;- 73 ° 19&#8217; 2.14&#8221;. Koordinaterne fører til Jones Beach, der i 1920´erne ofte blev brugt når der blev smuglet rom til USA. 18-års (Solera-lagret) varianten her, kommer med en herlig duft af sherry, vanilje og tørrede eksotiske frugter. I munden går den fede vanilje igen, men der er også rige krydderier, eg og karamel. God repræsentant for den populære sødlige, fløjlsbløde stil, og præsenteret i en flot flaske (synes vi). Det er rommen, du hiver frem, når du vil imponere, forkæle eller bare lade som om du har styr på livet. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Seleccion de Familia', 'https://spitus.dk/product/diplomatico-seleccion-de-familia/', 439, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2022/08/diplomatico-seleccion-de-familia-k.jpg', 'Diplomático Selección de Familia er en af Diplomáticos nyeste skud på stammen . Rommen er produceret af destilleriets egen sukkerrørsstamme, Caña Diplomática, som giver den elskede Diplomatico-twist og -karakter i slutproduktet. Diplomático Selección de Familia er et blend af rom fra tre forskellige destilleringstyper: Pot Still, Batch Kettle og Column Still. 90% af rommen stammer fra den traditionelle destilleringsteknik, Pot Still, som giver rommen en udsøgt dybde og kraftfuld smag. Derefter lagres rommen i ca. 12 år på egetræsfade, der tidligere har været anvendt til produktion af bourbon, single malt og sherry, hvilket giver Selección de Familia ekstra kompleksitet og fylde. Denne ret mørke rom har en velbalanceret duft af sukkerrør og honning, efterfulgt af noter af vanilje og eg. Rommen har en fantastisk fyldig smag af blomme, træ og karamel, som afrundes med en lang, lang og dejlig finish. I forhold til klassikeren og dermed mere kendte Diplomatico Reserva Exclusiva, vil vi sige at Selección de Familia har en smule mere tørhed og kompleksitet, men opretholder den efterspurgte velbalancerede sødme og rundhed – trods lavere sukkerindhold. Diplomático Selección de Familia er rommen, der har taget alt det, folk elsker ved Diplomático – den bløde sødme, den varme dybde, den elegante stil – og givet det et ekstra skud attitude. Det er som Mantuano og Reserva Exclusiva har fået en velklædt storebror, der både kan charme, imponere og holde festen kørende. Fornem rom, med fine vurderinger, bl.a. på rumratings.com. Diplomático Selección de Familia er den venezuelske charmetrold med ekstra swagger. Leveres i gaverør. Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Plantation Rum Experience gaveæske', 'https://spitus.dk/product/plantation-rum-experience-gaveaeske/', 495, true, 60, 41.3, 'https://spitus.dk/wp-content/uploads/2024/12/Plantation-Rum-Experience-gaveaeske-2.png', 'Plantation rom er nogle af de absolut mest populære, og her får du en flot og eksklusiv gaveæske med 6 forskellige rom, der hver især afspejler de respektive stilarter på tværs af Caribien. Oplagt hvis du selv vil lære mere, eller til romsmagning med vennerne. Du får 6 flasker a’ 10 cl. af: 1: Plantation 3 Stars White Rum, Trinidad, Barbados &amp; Jamaica 2: Plantation Original Dark Rum, Barbados &amp; Jamaica 3: Plantation Gran Anejo, Guatemala &amp; Belize 4: Plantation Xaymaca Special Dry, Jamaica 5: Plantation Rum 20th Anniversary XO Extra Old, Barbados 6: Plantation Barbados Rum Grande Reserve Inkl. en lille historie om de enkelte rom. Plantation Rum Experience er den perfekte gaveæske til alle, der elsker rom – eller som bare gerne vil se ud, som om de gør. Her får du en lineup af Plantation‑favoritter i små, lækre flasker, så man kan smage sig gennem Caribien uden at forlade sofaen. Det er en smagekasse fyldt med charme, tropisk sødme og den der klassiske Plantation‑stil, hvor hver rom har sin egen personlighed. Fra blød og frugtig til mørk og krydret – det hele er med. Perfekt som gave, til romnørderi, til hyggeaftener eller som “jeg fortjener noget lækkert”-køb. Plantation Rum Experience: En lille rejse, fire store smagsoplevelser. Alkohol % : 41,3 Størrelse : 6 x 10 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomático AMBASSADOR Selection Cask Strength Rom', 'https://spitus.dk/product/diplomatico-ambassador/', 1899, true, 70, 47, 'https://spitus.dk/wp-content/uploads/2022/03/diplomatico-ambassador-gb.jpg', 'Her præsenterer vi flagskibet fra Diplomatico, skabt af Master Blenderen Tito Cordero (bl.a. tidligere kåret til årets Master Rum Blender). Nøje udvalgt med de bedste destillater fra kældrene, som først lagres i mindst 12 år på fade af hvid eg, og derefter får 2 år på Pedro Ximénez sherry fade. Tappet direkte fra fad, ved en alkoholstyrke på 47%. En stor oplevelse, og ret vild at du ikke fornemmer den høje alkoholprocent. Bevares, den er yderst kraftfuld og med masser af power, men det er ikke rå alkohol-muskler. Man kan godt smage at den er fra Diplomatico, og er du fan af f.eks. den kendte Reserva Exclusiva, SKAL du på et eller andet tidspunkt prøve at tage dette skridt op. Eller rettere: mange skridt faktisk. Prisen er jo så heller ikke den samme, men på hvert deres niveau præsenterer de noget af de ypperste i den sødlige stil som danskerne elsker. Diplomático Ambassador er flasken, der ikke bare banker på døren – den sparker den ind iført smoking og med en cigar i hånden. Det er topniveauet fra Diplomático, lavet af de ældste og mest koncentrerede pot still‑rom, lagret i bourbonfade og afsluttet i sherryfade for maksimal dybde og dekadence. Smagen er vildt fyldig og intens: karamel, mørk chokolade, dadler, rosiner, vanilje, ristet eg, krydderi og en sherry‑sødme, der binder det hele sammen. Den er tung, varm, kompleks og silkeblød – en rom, der ikke beder om opmærksomhed, men kræver den. Det er flasken, du vælger, når du vil have noget, der både imponerer, forkæler og får selv erfarne romnørder til at løfte øjenbrynene. Diplomático Ambassador er den venezuelske luksusrom, der går all‑in på overdådighed. Der er tale om en voldsom opgradering fra den i forvejen gode Diplomatico Reserva Exclusiva. En mastodont af en rom! Leveres i en smuk træboks. 94 points af Mads ”Romhatten” Heitmann. Alkohol % : 47,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Brugal XV Gran Reserva', 'https://spitus.dk/product/brugal-xv-gran-reserva/', 319, true, 100, 38, 'https://spitus.dk/wp-content/uploads/2022/05/brugal-xv-gran-reserva-I-k.jpg', 'Ron Brugal stammer fra Den Dominikanske Republik, og blev etableret af Don Andres Brugal Montaner i 1888, i byen Puerto Plata på den nordlige del af øen. I dag er det 5. generation af familien der leder destilleriet. Brugal XV Gran Reserva er rommen, der glider ind i glasset med samme selvtillid som en bachata‑danser på en varm aften i Santo Domingo. Den er elegant, blød og perfekt balanceret – et møde mellem unge og ældre fade, der giver både friskhed og dybde. Denne XV Gran Reserva består af rom omhyggeligt udvalgt fra gamle, hvide bourbonfade og eksklusive Pedro Ximenez (PX) sherryfade. Noget af det specielle ved Brugul rom er netop, at de anvender absolut førsteklasses sherryfade, som de kun har adgang til, fordi de er ejet af The Edrington Group, som også ejer Macallan Whisky (som er førende indenfor sherrylagret whisky). Resultatet er dejlig blanding mellem det tørre og det søde, men med fokus på at skabe en blød og silkeblød oplevelse. Farven er klar/lys rav. I næsen får du egetræ, karamel, honning og modne frugter. Smagen er rund og harmonisk med noter af karamel, vanilje, tørret frugt, let krydderi og en mild trævarme, der gør den farligt let at drikke. Den er mindre sød end mange Caribiske rom, men stadig charmerende og super smooth. Det er rommen, du vælger, når du vil have noget, der både er let at elske og har nok karakter til at imponere. Brugal XV er Dominikansk elegance i flydende form. Vi er i den elskede, søde spanske stil, men den er ikke ultra sød som andre fra samme kategori, og med dens tørhed og karakter, får du lidt med punch med Brugal XV Gran Reserva. Brugal XV Gran Reserva – Den dominikanske smooth‑operator. Vi sælger den i en 1 liters version og i gaveæske. Alkohol % : 38,0 Størrelse : 100 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Distillery Collection N°2 Barbet', 'https://spitus.dk/product/diplomatico-distillery-collection-n2-barbet/', 495, true, 70, 47, 'https://spitus.dk/wp-content/uploads/2022/05/Skaermbillede-2023-09-22-kl.-11.00.24.png', 'Fra det elskede rom-hus, Diplomatico (Venezuela), præsenterer vi her den anden af tre, i deres ”Distillery Collection Series”. Hver af de tre rom har sit eget særpræg, dannet af, at de er destilleret på forskellige måder. Fælles for dem er det, at de alle er lagrede på fade af amerikansk hvid eg (ex bourbon eller maltwhisky). Diplomatico Distillery Collection N°2 Barbet destilleres på et fransk ”barbet” søjledestillationsapparat i kobber, hvilket giver et mere frugtrigt udtryk . Sukkerrørsmelassen stammer fra Diplomáticos helt egen sukkerrørsstamme, Caña Diplomática, som derefter fermenteres. Dernæst destilleres den fermenterede melasse på et Barbet-kolonnedestillation, som giver rommen en let, skarp og frugtig fornemmelse. Rommen modnes derefter på fade af amerikansk hvid eg, hvor den når sin optimale modning efter 4 år i Venezuelas ideelle klimaforhold. N°2 Barbet er Diplomático, når de skruer op for præcision, finesse og frugtighed. Hvor Batch Kettle (nr. 1) er den muskuløse nørd, er Barbet‑stillen den elegante ingeniør: slankere, lysere, mere aromatisk – men stadig med masser af personlighed. Smagen er friskere og mere frugtig end de klassiske Diplomático‑flasker, med noter af citrus, mango, passionsfrugt samt karamel ,vanilje og en mild krydret trænote. Den er mindre sød, mere “snappy” og overraskende kompleks, især for dem der kun kender Diplomático fra de tungere, sødere udgaver. Det er flasken, du vælger, når du vil opleve Diplomático fra en helt ny vinkel – teknisk, elegant og med masser af destillations‑karakter. N°2 Barbet: Diplomático med friskhed, finesse og laboratorie‑swagger. Diplomático Distillery Collection N°2 Barbet er den elegante ingeniør i serien Diplomatico Distillery Collection N°2 Barbet har, som de øvrige i serien, opnået flotte anmeldelser og vurderinger ved blandt andet Ultimate Spirits Challenge og Tastings.com. Leveres i gaveæske. Alkohol % : 47,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Distillery Collection N°1 Batch Kettle', 'https://spitus.dk/product/diplomatico-distillery-collection-n1-batch-kettle/', 495, true, 70, 47, 'https://spitus.dk/wp-content/uploads/2022/05/Skaermbillede-2023-09-22-kl.-10.57.25.png', 'Fra det elskede rom-hus, Diplomatico (Venezuela), præsenterer vi her den første af tre, i deres ”Distillery Collection Series”. Hver af de tre rom har sit eget særpræg, dannet af, at de er destilleret på forskellige måder. Fælles for dem er det, at de alle er lagrede på fade af amerikansk hvid eg (ex bourbon eller maltwhisky). Batch Kettle‑udgaven er Diplomático, som du ikke har smagt dem før. Her får du en single‑still rom fra deres gamle canadiske batch kettle‑apparat – en slags hybrid mellem pot still og column still – og resultatet er en rom med både muskler, finesse og masser af karakter. Rommen recirkulerer i systemet, indtil Blend Masteren godkender destillatet, hvorefter den lagres i op til 6 år. Smagen er fyldig, varm og aromatisk med noter af karamel, vanilje, tropisk frugt, let krydderi og en elegant trænote. Den er mindre sød end de klassiske Diplomático‑flasker, men til gengæld langt mere kompleks og “nørdet” i udtrykket. En rom, der virkelig viser, hvad destilleriet kan, når de slipper teknikerne løs. Det er flasken, du vælger, når du vil have Diplomático med mere kant, mere dybde og mere personlighed. Batch Kettle er Diplomático, men med laboratoriefrakke og attitude. Diplomático Nº 1 Batch Kettle har opnået flotte anmeldelser og vurderinger ved blandt andet Ultimate Spirits Challenge og Tastings.com. Leveres i gaverør. Alkohol % : 47,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Colon Salvadoreno Coffee Infused', 'https://spitus.dk/product/ron-colon-salvadoreno-coffee-infused/', 315, true, 70, 40.5, 'https://spitus.dk/wp-content/uploads/2022/05/ron-colon-salvadoreno-coffee-infused.jpg', 'Teamet bag Ron Colón Salvadoreño har taget den skridtet videre, og koldt-infuseret deres dejlige rom med hele kaffebønner i 48 timer. Udgangspunktet er deres blend med lagrede rom fra fra El Salvadors Licorera Cihuatan Distillery, ulagrede jamaicanske rom fra Worthy Park, Hampden og Monymusk, samt også lige en portion lagret Worthy Park rom! Kaffebønnerne er håndplukkede og -udvalgte sager fra Jags Head Coffee-team. Medium-ristede, så de tilfører primært chokolade, kirsebær og honning – og knap så meget bitterhed. Ambitionen er at repræsentere El Salvador på bedste vis, og vi synes den holder hele vejen igennem. Ron Colón Salvadoreño Coffee Infused er når rom og kaffe går i band sammen. Ron Colón Coffee Infused er flasken, der beviser, at kaffe og rom ikke bare er venner – de er soulmates. Det er en intens, aromatisk og energifyldt rom, hvor salvadoransk high‑end kaffe møder en kraftig, karakterfuld rombase. Resultatet? En flydende espresso martini uden attitudeproblemer. Smagen er dyb, mørk og uimodståeligt lækker med noter af espresso, kakao, karamel, vanilje og et strejf af tropisk frugt fra rommen. Den er både bitter, sød og varm – som en kaffe, der har besluttet sig for at blive festens midtpunkt. Det er flasken, du hiver frem, når du vil imponere kaffeelskere, romnørder eller bare dig selv efter en lang dag. Ron Colón Coffee Infused er kaffe på steroider, rom med koffein – og ren nydelse i glasset. Alkohol % : 40,5 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Millonario Solera Reserva Especial 15 Years', 'https://spitus.dk/product/millonario-solera-reserva-especial-15-years/', 399, true, NULL, 40, 'https://spitus.dk/wp-content/uploads/2022/02/ron-millonario.jpg', 'Ron Millonario Solera Reserva Especial 15 år blev kåret til bedste premium rom ved International Rum Festival i Florida 2009, og da alle dommerne bedømte den til mere end 90 points, tog den også titlen som ”Best of Show”. Siden er det gået stærkt for destilleriet fra Peru, men denne Solera Reserva Especial er stadig flagskibet. Millonario 15 er spiritussens svar på en silkekåbe: blød, sød, elegant og helt umulig ikke at falde for. Det er en af de mest populære solera‑udgivelser i verden – og det giver mening, for den rammer den perfekte balance mellem dessertlækker og sofistikeret. En sammenligning med de første Ron Zacapa 23 års Solera er absolut ikke helt ved siden af, trods forskellige oprindelseslande. Næsen minder en del om hinanden, med mandler, brun farin, vanilje, mørk chokolade og rosiner. Smagen er rund, dyb og uimodståeligt smooth med noter af karamel, brun farin, tørret frugt, toffee, vanilje og et strejf af krydret varme. Den er sød, men ikke kvalm – bare ren peruviansk forkælelse. Det er flasken, du vælger, når du vil have noget, der både imponerer nybegyndere og tilfredsstiller erfarne romdrikkere. Millonario 15 er en solera‑klassiker med charme, varme og masser af personlighed. Millonario Solera Reserva Especial 15 Years er Peruviansk luksus i flydende form, og er en h erlig dram i danskernes fortrukne ”spanske” stil, som du bare får lyst til at sippe mere af. Her i den originale bast-flaske &#8211; som allerede er ved at blive et samlerobjekt. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Chairman&#8217;s Reserve Vintage 2009', 'https://spitus.dk/product/chairmans-reserve-vintage-2009/', 549, true, 70, 46, 'https://spitus.dk/wp-content/uploads/2022/03/chairmans-reserve-vintage-2009.jpg', 'Chairman&#8217;s Reserve 2009 er den blot anden årgangsudgivelse fra destilleriet (efter den succesfulde 2005-version). Der er tale om melassebaseret rom, fermenteret i 36 timer og derefter destilleret i en kombination af Coffey Still og pot stills med et 1:1-forhold mellem John Dore II Still og Vendome still. Herefter lagret separat i 11 år på tidligere Bourbon-fade, og efter sammenblandingen får den yderligere 6 uger. Sluttelig fik den noget tid i et trækar for at hvile, og endeligt aftappet ved 46 % ABV uden nogen ekstra tilføjelser. Chairman&#8217;s er generelt rigtig gode value-for-money rom, og denne 2009-udgave er absolut ingen undtagelse. Rutinemæssigt flere guldmedaljer og kåringer i bagagen. I forhold til 2005-udgaven, har den ikke samme garvesyrebitterhed, men er en anelse lysere og en del mere frugtrigdom. Der er mere fad over 2005, men mere destillat og nuancer i 2009-udgaven. Smag og behag – vi foretrækker udgaven fra 2009. Chairman’s Reserve Vintage 2009 er rommen, der viser præcis hvor højt niveau Saint Lucia kan levere, når de går full‑on nørd og lader pot still‑magien tale. Det er en single vintage‑udgivelse med dybde, kraft og en kompleksitet, der får selv erfarne romfolk til at nikke anerkendende. I næsen friskbagt brød, mandler, tobak, læder, stenfrugter. Derudover også en anelse farin og kanel. I ganen er den krydret og frugtrig. Mango, After Eight, karamel, pærer og cappuccino. Mange smagslag, og fornem lang eftersmag med mørk chokolade og toffee. Cremet og kraftfuld – lækker dram, og lidt af et røverkøb! Chairman’s Reserve Vintage 2009 er Saint Lucia i sin mest seriøse form. Leveres i gaveæske Alkohol % : 46,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Volbeat Rum III', 'https://spitus.dk/product/volbeat-rum-iii/', 469, false, 70, 43, 'https://spitus.dk/wp-content/uploads/2022/03/volbeat-no-3.png', 'Det danske rockband Volbeat, har tidligere udgivet Volbeat Rum I og II i ret begrænsede mængder. De blev primært solgt via specialbutikker, og er for længst udsolgte. De er blevet til samlerobjekter blandt romelskere og naturligvis for Volbeat fans. Priserne er stukket af, men nu er nummer 3 i rækken her, og den er udgivet i større mængder og til en lavere pris. Dette vel og mærke uden at der er gået på kompromis med kvaliteten. Der er tale om et blend fra Den Dominikanske Republik, Barbados, Jamaica, Guyana, Guatemala og Trinidad – så lidt af en sammensætning! Aldersmæssigt er der anvendt rom på op til 15år, og alkoholprocenten er holdt på 43%. Volbeat Rum III er flasken, der føles som et guitarsolo‑break midt i en stadionkoncert. Den er mørk, sødmefuld, intens – og har præcis den rock’n’roll‑attitude, man forventer, når Volbeat sætter deres navn på noget. Smagen er fyldig og lækker med noter af karamel, vanilje, brun farin, tørret frugt og et strejf af krydderi. Den er smooth nok til at drikke rent, men har stadig kant nok til at føles som en dram med personlighed og power. Det er flasken, du hiver frem, når du vil kombinere god smag med god musik – eller bare vil have en oplevelse, der kan få selv den mest stille aften til at føles som en tourbus‑fest. Volbeat Rum III er den der siger “Let’s get ready to rumble”. Som bandet selv skriver på bagetiketten: ”Rommen er til enhver Guitar Gangster, Lonesome Rider, Cheapside Slogger og alle derimellem”. Alkohol % : 43,0 Størrelse : 70 cl Bemærk: flasken som er afbilledet, er også den flaske, som vi leverer ved bestilling. Vi har 2 forskellige udgaver af volbeat III, hvilket godt kan give lidt forvirring, så derfor denne lille notits :o) Du kan finde den anden udgave her: Volbeat rum no III');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Serum Gorgas, Gran Reserva', 'https://spitus.dk/product/serum-gorgas-gran-reserva-2/', 399, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/02/serum-gorgas-k.jpg', 'Serum Gorgas er opkaldt efter Oberst William Crawford Gorgas, som i legendeberetningerne i hans gennemgang af medicin og andre ejendele som hans forgænger på posten efterlod sig, faldt over nogle tønder rom og en speciel og hemmelig opskrift på fremstillingen af denne. Ved nærmere undersøgelse opdagede han, at rommen faktisk var en lokalt fremstillet eliksir, der indeholdt tørrede frugter og urter med helbredende egenskaber. Det menes, at obersten blev så betaget af rommen og dets renhed og helbredende kræfter, at han drak hele beholdningen undtaget én af tønderne. Denne ene tønde blev sendt til et destilleri i byen Pesé, som brugte den som skabelon til at producere mere af den helbredende rom. For at vise deres taknemmelighed, besluttede de indfødte i Panama fremover hvert år på hans fødselsdag, at sende ham en tønde rom – naturligvis fik den navnet Gorgas Sérum Rum. Sådan går historien i hvert fald! Vi andre kan glæde os over en fuldlagret herlig dram (dvs. ingen anvendelse af Solera-metoden her), som destilleres på høje kolonnedestillationsapparater, og lagres på bourbonfade i hele 8 år – som faktisk er rigtig længe i det tropiske klima i Panama. Duften er marcipan og en krydret aroma med antydning af honning, appelsinskal og eg. Smagen er rund, mild og fyldig med en robust smag af frugt, krydderier og brun farin. En forholdsvis sød fætter, i rigtig god balance så alle kan være med &#8211; også den mere kræsne connaisseur. Bemærk: ny forbedret flaske Størrelse : 70 cl Alkohol % : 40,0 Land : Panama');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('New Grove Double Cask Merisier Rum', 'https://spitus.dk/product/new-grove-double-cask-merisier/', 549, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2022/01/new-grow-double-cask-merisier.jpg', 'New Grove produceres af destilleriet Grays, der er et førsteklasses vin- og spiritusfirma, og samtidig den største producent på paradisøerne Mauritius. De skabte New Grove-serien i 2006, og navngav den efter en lille by på den sydlige del af Mauritius. Denne New Grove Double Cask Merisier blev først modnet på franske egetræsfade i 7 år, før den afsluttede sin lagringsperiode, et ekstra år, på et fad af Merisier-træ (kirsebær). Denne ret unikke lagringsmetode, giver en meget frisk rom. Farven er gyldent og strålende rav. I næsen er den ret massiv, med aromaer af abrikos, mandel og karamel. Derefter en bølge, som bringer øget kompleksitet med peber, såvel som blomster- og myntenoter! Smagen er rund, varm og elegant med noter af karamel, tørret frugt, kirsebærtoner, let krydderi og en blød, næsten vinøs sødme fra merisier‑træet. Vi finder desuden abrikos og peber, mens vanilje og wienerbrød kommer frem. Det giver en rom, der både er eksotisk, kompleks og utroligt drikkevenlig. Det er rommen, du vælger, når du vil have noget, der skiller sig ud – men stadig holder sig i den sofistikerede ende af spektret. New Grove Double Cask Merisier er Mauritius med et kirsebærkys af finesse. New Grove Double Cask Merisier er rommen, hvor Mauritius viser sin mere mystiske side. Spændende og prisvenlig rom, som vi leverer i et gaverør. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Zacapa Royal', 'https://spitus.dk/product/zacapa-royal/', 2249, true, 70, 45, 'https://spitus.dk/wp-content/uploads/2021/11/zacapa-royal-23-aars.jpg', 'Du kender sikkert den populære Ron Zacapa 23 års Solera, som for mange danskere er der interessen og smagen for god, fadlagret rom starter. Her har vi fat i destilleriets top-produkt: Ron Zacapa Royal. Den blev oprindeligt udgivet ifbm. Ron Zacapas 40 års jubilæum som rommærke, og Royal er kreeret af Master Blender Lorena Vásquez. Zacapa Royaler er Guatemalas dronning af spiritus. Zacapa Royal er udgivelsem, der ikke bare vil imponere… den vil regere . Det er topmodellen i Zacapas lineup, lavet på destillater lagret i de eksklusive “Le Bois du Roy”-fade – egetræ fra de franske kongelige skove. Det er luksus, der kan smages. Smagen er dyb, elegant og silkeblød med lag af karamel, mørk honning, tørret frugt, citrusolie, krydderi og en raffineret, næsten dessertvin-agtig sødme. Eftersmagen bliver ved og ved, og den højere alkoholprocent (45%), har helt sikkert en del af æren for at den virker mere voluminøs og komplet end dens slægtninge. Herlig balance mellem det søde og det eksotiske. Opholdet i de franske fade, giver åbenlyst også noget krop og fylde, så det ikke bare er ”endnu en sød rom”. Ron Zacapa Royal evner det søde, men går ikke på kompromis med at du skal kunne smage elementerne den er skabt af. Alt sammen pakket ind i den ikoniske Zacapa‑smoothness, bare endnu mere poleret og majestætisk. Det er flasken, du tager frem, når du vil servere noget, der får folk til at stoppe op og sige “wow”. En flaske med attitude, finesse og kongelig selvtillid. Zacapa Royal er når spiritus bliver til kunst. Uddrag fra Mads ”Romhatten” Heitmanns anmeldelse: ”Hvorfor synes jeg så, at det er den bedste rom Ron Zacapa har at byde på? For det første så holder den 45 % alkohol, hvilket jeg dels synes klæder rommen ift. smagen samt balancen. Det er desuden dejligt at se, at Zacapa begynder at bevæge sig den vej &#8211; personligt kunne jeg virkelig godt tænke mig at smage en +50 % fra dem. Dette “nøk opad” i alkoholprocenten vidner om, at markedet er ved at være klart til andet end sukkersødt rom på 40 %. Fedt! For det andet, så synes jeg, at det klæder rommen noget så grusomt, at den har været i kontakt med fransk egetræ. Det franske egetræ, som er brugt til denne rom, kommer fra fire forskellige skove i Frankrig &#8211; i et område, som i mange år er blevet kaldt “Kongens træer” &#8211; deraf navnet “Royal”. Dette egetræ giver en distinkt krydret smagsprofil til rommen, som ikke er til at komme udenom. Lækkert! For det tredje, så føler jeg, at rommen er langt mindre sød end de normale aftapninger fra Ron Zacapa. Det kan have noget med det franske egetræ at gøre, men jeg tror, at det er mere end det. Skulle jeg gætte på sukkerindholdet, så ville jeg anslå, at vi ligger et sted omkring 15 gram pr. liter. Alt dette er med til at gøre Ron Zacapa Royal langt mere kompleks og intensiv end de andre aftapninger i Zacapa-serien. Rommen performer bedre end forventet. Det er en god overraskelse!” Leveres i en flot gaveæske. Alkohol % : 45,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Abuelo XII Two Oaks Rom', 'https://spitus.dk/product/abuelo-xii-two-oaks/', 465, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2024/12/Abuelo-XII-Two-Oaks.png', 'Abuelo XII Anos Two Oaks er dejlig 12 år gammel rom fra Panama. Som navnet siger, har den været lagret på 2 forskellige typer fade. Abuelo XII Two Oaks er rommen, hvor Master Blenderne virkelig har haft det sjovt. Først fik den nogle år på ryggen i brugte bourbon-fade, hvorefter den, ret specielt, fik en tid i helt nye, men godt forkullede amerikanske ege-fade (sidstnævnte fremstilles i Californien, hvor de først rister de nye fade ved 180° C i 60 minutter, for at åbne træet, og herefter skruer op til 220° C, for at få en dyb forkulning på ca. 0,8 cm.). Dette giver ekstra meget smag fra træet, men også en fin blødhed, da de forbrændte fade fungerer som en slags kulfilter. Det her er Abuelo XII Two Oaks – Panama‑rom med dobbelt fad og dobbelt charme I næsen er der masser af træ, kaffe, ristede nødder og en anelse røg. Smagen er fyldig og kompleks med lag af karamel, vanilje, ristet træ, kakao, toffee og i finishen fortsætter noterne, og der dukker yderligere eksotiske krydderier, ristede kaffebønner og en anelse banan og cola(!) op. De dobbelte fade giver en markant, men silkeblød ristet karakter, der gør den både elegant og uimodståeligt drikkevenlig. En dyb, mørk og intenst aromatisk rom, der smager som en luksusudgave af alt det, Abuelo gør godt. Det er rommen, du vælger, når du vil have noget, der både er klassisk og nytænkende – og som får selv erfarne romdrikkere til at løfte øjenbrynene. Abuelo XII ’Anos Two Oaks’ har vundet adskillige internationale priser. Blandt andet har den vundet vundet Dobbelt Guld ved San Francisco World Spirits Competition 2022. Dejlig rom i præcis den stil som danskerne elsker! Leveret i en gaveæske Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bayou Reserve Rom', 'https://spitus.dk/product/bayou-reserve/', 325, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/12/bayou_reserve_rum-k.jpg', 'Bayou Rum er vaskeægte amerikansk rom fra sydstaten Louisiana. Rommen er produceret på en lokal sukkerrørsmelasse som destilleres på små batch-destilleringsapparater, og herefter modnet i forskellige fade, normalt i et solera-system, men nogle varianter også som single barrel. Destilleriets masterblender er den unge romkomet, Reiniel Vicente Diaz, som har rødder i den cubanske og dominikanske romproduktion. Bayou siger selv, at denne Reserve-udgave er rommen til bourbon-drikkerne. Bayou Reserve er Louisiana‑rom med sydstatscharme og masser af smag. Bayou Reserve er rommen, der smager som en varm aften ved Mississippi: fyldig, krydret og med en charme, der ikke kan forfalskes. Den er lagret på bourbonfade, hvilket giver den en markant amerikansk karakter – uden at miste den bløde rom‑sjæl. I næsen er der cremet vanilje med strejf af æble og kanel. Smagen er rund og varm med noter af karamel, vanilje, ristet eg, toffee og et strejf af krydderi. Den har en let tørhed, der gør den mere voksen end mange sødere rom, men stadig smooth nok til at drikke ren uden at blinke. Det er rommen, du vælger, når du vil have noget med kant, karakter og en lille smule Louisiana‑attitude. Bayou Reserve: Sydstatsrom med swagger. Category Winner, World Rum Awards, 2016 Best in Class, Miami Rum Festival Rum XP Award, 2016 Best of Category, American Distilling Institute, 2015 Guld ved San Francisco World Spirits Competition, 2019. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Reserva Exclusiva Ron Antiguo', 'https://spitus.dk/product/diplomatico-reserva-exclusiva-ron-antiguo/', 329, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/11/diplomatico-reserva-exclusiva-ron-antiguo-k.jpg', 'Hvis der fandtes en “folkets rom”, så ville Diplomático Reserva Exclusiva uden tvivl være en af de stærkeste kandidater. Det her er nemlig en flaske, der kan noget helt særligt: Den får både nybegyndere og hardcore nørder til at smile. Og det er ikke så mærkeligt – den er blød, sød, rund og så charmerende, at man næsten får lyst til at give flasken et kram. Det er den venezuelanske klassiker, der får alle til at nikke anerkendende. Diplomático Reserva Exclusiva er udvundet af lokale sukkerrør høstet ved foden af Andelsbjergene. Sukkerrørsmelassen destilleres i gamle copper pot stills, og rommen lagres efterfølgende i op til 12 år på amerikanske egetræsfade. Diplomatico er klart i den søde ende, og fans af f.eks. Ron Zacapa vil fint kunne være med her. (Vores måling siger ca. 35–40 g/L sukker). Noterne er egetræ, appelsiner og chokolade. I munden fortsætter den bløde, runde og behagelige stil, og du får også en anelse lakrids og karamel. Sød og delikat. Saftig fudge og meget karamel. Blid og omgængelig – en crowdpleaser! &#8220;Do uble Gold Medal&#8221; fra den første &#8220;International RUM Conference&#8221; i 2013 Størrelse : 70cl Alkohol % : 40,0 Land: Venezuela');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado Plinth 12/15/21 Years', 'https://spitus.dk/product/el-dorado-plinth-12-15-21-years/', 1499, false, 210, 42, 'https://spitus.dk/wp-content/uploads/2021/11/el-dorado-15-21-12-YO-k.jpg', 'Du kender sikkert de lækre rom fra El Dorado/Guyana Demerara Distillers, som er nogle af de bedste value-for-money rom, du kan finde. Se bl.a. her hvad Mads ”Romhatten” Heitman skriver i anmeldelsen af den 21 årige variant: ”I denne rom, fra Demerara Distillers, er det bedste fra den 12 årige og den 15 årige samlet i én flaske. Ingen tvivl om at den 15 årige er den mest prestigefyldte og mest vindende El Dorado rom, og der er heller ingen tvivl om at den 12 årige er den mest imødekommende af de to. En forening af disse to i den 21 årige er næsten for meget af bede om. En eksklusiv rom fra Guyana.” 93 points. Her får du muligheden for at skaffe den sjældne og blærede El Dorado Plinth inklusive hele flasker af hhv. 12, 15 og 21 års udgaverne! En smukkere opstilling i din bar eller på dit bord er svær at forestille sig! Og når flaskerne tømmes, kommer du tilbage til Spitus.dk og ”fylder” din Plinth op igen. Levers i gaveæske, hvis du skulle ønske virkeligt at forkæle én du kender! Alkohol % : 42,0 Størrelse : 3 x 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Havana Club Seleccion de Maestros', 'https://spitus.dk/product/havana-club-seleccion-de-maestros/', 399, true, 70, 45, 'https://spitus.dk/wp-content/uploads/2021/11/havana-club-seleccion-de-maestros-k.jpg', 'Havana Club Selección de Maestros -læg mærke til navnet, for det er præcis det du får med denne rom! Det er resultatet af samarbejdet mellem de cubanske maestro roneros &#8211; rommestrene. Det tager minimum 15 års hård oplæring at tilegne sig titlen, og der findes i dag blot seks Maestros Roneros i verden – alle bosat på Cuba. De mødes en gang om året for at udvælge og blande de fineste rom til dette herlige blend. Havana Club Selección de Maestros er rommen, hvor de cubanske Maestros Roneros går all‑in og viser, hvad de egentlig kan, når ingen kigger dem over skulderen. Det er en dyb, krydret og elegant rom, der smager som en aften i Havana med god musik, varme farver og nul planer om at gå tidligt hjem. Smagen er fyldig og kompleks med noter af ristet egetræ, kakao, toffee, krydderi og en lækker, tør varme, der giver den et mere “voksent” udtryk end de sødere romtyper &#8211; de 45% alkohol hjælper også med her. Den er silkeblød, men stadig med kant – som en cubansk danser i jakkesæt. Perfekt til ren nydelse, en god cigar, eller når du vil servere noget, der får folk til at nikke anerkendende uden at sige et ord. Selección de Maestros: Når Cuba virkelig folder sig ud Kun et stort mærke som Havana Club kan tillade sig den ekstravagance at bruge så megen viden og kompetence på et produkt! Efter de har valgt og sammensat de bedste blends, lagres rommen på nøje udvalgte tønder, og tappes når tid er, direkte fra fad (Cuban Barrel Proof). Et sandt hav af kåringer og medaljer. Bl.a. er Selección de Maestros blevet præmieret med guld ved tre af verdens største og vigtigste spiritus konkurrencer : The San Francisco World Spirits Awards, The Beverage Testing Institute’s International Review of Spirits og The International Wine and Spirit Competition (IWSC). Bør nydes rent – og gerne sammen med en god cigar. Alkohol % : 45,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cartavio 12 Años Solera', 'https://spitus.dk/product/ron-cartavio-12-anos-solera/', 325, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/11/ron-cartavio-12-aars-k.png', 'I den meget frodige dal, Chicama Valley på Perus nordkyst finder vi Cartavio destilleriet; Destilerias Unidas, grundlagt den 29. april 1929. Placeringen er perfekt for vækst og dyrkning af sukkerrør, og vandet der anvendes, kommer rindende ned i den reneste og krystalklare form fra Andesbjergene. De geografiske forhold er således perfekte, men arbejdet i destilleriet er også fintunet og lever op til mulighederne. Bl.a. er arbejdet med fadene meget imponerende, og der anvendes f.eks. Pedro Ximenez-fade, samt amerikanske, franske og slovenske egefade. Ron Cartavio 12 Años er en af Perus mest elskede solera-udgivelser – og det er ikke uden grund. Den lange lagring i egetræsfade giver en blød, afrundet og moden smagsprofil, hvor sødme og krydderi spiller perfekt sammen. Smagen byder på noter af karamel, vanilje, tørret frugt, let krydderi og et strejf af ristet træ. En elegant, harmonisk flaske, der både fungerer som ren nydelse og som en luksuriøs base i cocktails. Siden deres XO Anös 18 års vandt en del fornemme priser i 2015, er interessen for destilleriet nærmest eksploderet. Denne er 12-års udgave indeholder mange af de samme elementer som sin berømte storebror, men til en væsentlig lavere pris. Der er, som nævnt, tale om solera-lagring, så blendet indeholder destillater med forskellige aldre, men altså op til 12 år. Det er sød, og let drikkelig i den populære spanske stil. I næse og gane, masser af sødme, tropiske frugter og varme krydderier. Den kammer ikke over og bliver for sød. Den smager bare naturligt og godt. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bumbu Original, 35cl', 'https://spitus.dk/product/bumbu-original-35cl/', 199, true, 35, 40, 'https://spitus.dk/wp-content/uploads/2021/11/bumbu-original-35cl-I-k.jpg', 'Bumbu er sødmefuld rom-baseret spiritus fra Barbados, som falder i de flestes smag. Destillationen sker på to ældgamle kolonne destillationsapparater og destillatet lagres herefter op til 15 år på de fineste brugte bourbon egetræsfade. Bumbu er en uhyre populær ”rom”, med sukkerrør fra 8 forskellige lande med hver deres karakteristika. Efter destilleringen infuseres der med eksotiske frugter, som trækker sødme og smag. Farven er gylden. Duften er meget sød, med banan, vanilje og karamel. I munden masser af eksotiske frugter, men med dejlig kraft og krop fra spiritussen. Den er let krydret, og alt i alt en behagelig oplevelse der kan drikkes af alle. Desuden rigtig god i rom-cocktails. Bumbu har opnået stor succes verden over, og den er ideel for dem som gerne vil have noget sødt og frugtrigt, og måske ikke går efter tørheden eller den voldsomme kompleksitet fra ældgammel rom. Bumbu 35 cl – Den lille flaske med den store personlighed Bumbu i 35 cl er som en mini-ferie til Caribien, bare uden solcreme og sand i skoene. Den ikoniske rom kommer her i en mere kompakt størrelse – perfekt til gaver, smagsprøver, hjemmebaren eller når du bare vil have lidt luksus uden at købe en hel liter.. Perfekt til cocktails, cola, ren nydelse – eller som den lille flaske, der altid forsvinder hurtigere end planlagt. Bumbu 35 cl: lille størrelse, stor charme. Bemærk: dette er en 35cl. flaske. Vi sælger den også i den normale 70cl. udgave. Alkohol % : 40,0 Størrelse : 35 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario Tasting Collection 4 x 20cl', 'https://spitus.dk/product/ron-centenario-tasting-collection-4-x-20cl/', 379, true, 80, 40, 'https://spitus.dk/wp-content/uploads/2021/11/ron-centenario-4x20cl.jpg', 'I lang tid var Costa Rica primært kendt for produktion af kaffe. Men på grund af sin placering mellem Caribien og Atlanterhavet, kan der dyrkes sukkerrør af meget høj kvalitet, som derefter kan destilleres til rom. Centenario Rums har bragt nogle premium-rums på markedet, der nyder stigende popularitet. Generelt er rommene fra Centenario gode bud på rom i den søde stil, hvor du får meget for pengene. Nu tilbyder Spitus.dk dig en god mulighed for at smage 4 forskellige af deres mest prisvenlige rom til en uhørt lav pris . Du får nemlig 20 cl. af hver (i alt 80 cl.) af deres meget populære 5 års, 7 års, 9 års samt 12 års rom hver med deres egen personlighed, charme og “hola amigo”-energi. Leveret i en flot gaveæske. Det er Costa Rica i fire små kærlighedsbreve Ron Centenario Tasting Collection er som at få en VIP‑tur gennem Costa Ricas romunivers – uden at skulle pakke kuffert eller lære spansk. Du får en lineup, der spænder fra blød og sød til moden og kompleks, så du kan smage dig gennem hele Centenario‑familien uden at forpligte dig til én stor flaske. Det er rommens svar på en smagekasse chokolade… bare bedre. Perfekt som gave, til nørderi, til romaftener – eller når du vil finde din nye favorit uden at gamble på en hel liter. Fire flasker. Fire stilarter. Én lækker rejse til Costa Rica. Alkohol % : 40,0 Størrelse : 4 x 20 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Zafra Master Series 30 Years', 'https://spitus.dk/product/zafra-master-series-30-years/', 1499, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/11/zafra-master-30yo.jpg', 'Zafra Master Series 30 års er en unik rom lagret i 30 år på brugte bourbonfade (ikke noget solera-metode her, men simpelthen mindst 30 på ryggen i et fad). Zafra betyder &#8220;sukkerrørshøst&#8221;, og det er da også netop anvendelsen af helt friske sukkerrør der er med til at gøre rom fra Zafra, produceret af Don Pancho Las Cabras Distillery i Panama, til noget ganske særligt. Der er kun produceret 6720 flasker til hele verdensmarkedet. Valgt i Cigar Affcionado til verdens bedste cigarrom på grund af sin unikke kombination af kompleksitet og sødme. Så ingen tvivl om at det er en ganske særlig rom vi har fat i her. Og vi elsker den! Vi er kæmpefan! Der anvendes fortrinsvis kolonnedestillation på helt specielle og meget høje destillationsapparater, hvilket helt bevidst gør indtrykket meget &#8220;rent&#8221; og forbedrer balancen i rommen. Flot mahogni farve og duften er vidunderlig. Karamel, vanilje, aromatisk pibetobak og træ. Én af bedste rom-næser du kan finde! Super smooth i munden, sød og så velafbalanceret med smag af vanilje, brændt sukker, karamel, eg, et strejf af røg og et strejf af bagekrydderier. Et mesterværk af en rom. Leveres i flot graveret og nummereret flaske, samt tilhørende gaveæske. Scoret til 9,4 af brugerne på Rum Ratings. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Emperor Mauritian Rum Private Collection Château Pape Clément Finish', 'https://spitus.dk/product/emperor-mauritian-rum-private-collection-chateau-pape-clement-finish/', 945, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2021/11/emperor-private-collection-k.jpg', 'Emperor Rom har specialiseret sig i at lave blended rom af sukkerrørsdestillater og sukkerrørssaft fra Mauritius. Her præsenterer vi den absolutte top-udgivelse fra destilleriet . Dette er den første i en serie kaldet ”Private Selection”. Planen er at tage deres bedste og specielle vintage tønder ud, og lade dem efterlagre på fade fra verdens bedste vin- og spiritushuse. Denne første udgave er således lagret i egetræsfade, der engang blev brugt til at producere de komplekse, fløjlsagtige vine fra Grand Cru Classé Château Pape Clément i Bordeaux, Frankrig. Emperor Private Collection er den eneste rom i verden der har fået lov til at lagre på disse ret kostbare fade. Resultatet er en sødmefuld, mørk, fløjsblød sag. Uhyre rig og voluminøs, men alligevel dejlig glat. Den særlige finish på rødvinsfade giver en tung og kompleks smag af røde bær og ristet egetræ. Masser af modne eksotiske frugter, og herlige krydrede noter samt varme fra tanninen i den laaaange eftersmag. En forrygende udgivelse, som ikke er som alle de andre. De søde rødvinsnoter er det der primært gør at den skiller sig ud. Emperor Private Collection med Château Pape Clément-finish er spiritussens svar på et luksuriøst møde mellem Mauritius og Bordeaux. Her får du en eksklusiv blend, der først modnes i tropisk klima og derefter får sin finale i fade fra det legendariske Grand Cru Classé-slot Pape Clément. Resultatet er dybt, komplekst og uimodståeligt elegant. Smagen folder sig ud med noter af røde bær, tørret frugt, vanilje, karamel og et strejf af vinøs fylde fra de franske fade. En udgivelse med aristokratisk finesse og tropisk varme i perfekt balance. Perfekt til ren nydelse, som samlerobjekt eller som den flaske, der får dine gæster til at løfte øjenbrynene i ren beundring. En sand luksus oplevelse i Emperor-universet. Elegant flaske og tilhørende gaveæske. Størrelse : 70 cl Alkohol % : 42,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Bumbu Original', 'https://spitus.dk/product/bumbu-original/', 319, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/02/100339-1-Bumbu-.jpg', 'Bumbu er sødmefuld spirit drink (rom-baseret spiritus) fra Barbados, som falder i de flestes smag. Destillationen sker på to ældgamle kolonne destillationsapparater og destillatet lagres herefter op til 15 år på de fineste brugte bourbon egetræsfade. Bumbu er en uhyre populær ”rom”, med sukkerrør fra 8 forskellige lande med hver deres karakteristika. Efter destilleringen infuseres der med eksotiske frugter, som trækker sødme og smag. Farven er gylden. Duften er meget sød, med banan, vanilje og karamel. I munden masser af eksotiske frugter, men med dejlig kraft og krop fra spiritussen. Den er let krydret, og alt i alt en behagelig oplevelse der kan drikkes af alle. Desuden rigtig god i rom-cocktails. Bumbu har opnået stor succes verden over, og den er ideel for dem som gerne vil have noget sødt og frugtrigt, og måske ikke går efter tørheden eller den voldsomme kompleksitet fra ældgammel rom. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Professor Cornelius Rumbullion XO 15 YO', 'https://spitus.dk/product/professor-cornelius-rumbullion-xo-15-yo/', 699, true, 50, 46.2, 'https://spitus.dk/wp-content/uploads/2020/12/professor-cornelius-rumbullion-xo-15-yo.jpg', 'Måske troede du at Rumbullion! og Rumbullion! Navy-Strength rom var vilde, men så kommer her Ableforth’s Rumbullion! XO 15 YO. Blandingen af ​​vanilje, appelsinskal, honning, nelliker, kardemomme og kanel bringer originalens velkendte, fantastiske noter tilbage. Men den ekstraordinære 15 år gamle caribiske udgivelse, som er kernen i Rumbullion! XO 15 YO, giver et ekstra spark af krydderier og varme. Der er tale om en decideret sødlig elixir, men en velafbalanceret smagsfuld fætter. Winner – World Rum Awards 2017 &amp; 2015 – World’s Best Spiced Rum. Næse: Sød vanilje og saftige, friske skiver appelsiner. Der er en gløgglignende note af ristet kanel og nelliker – og touch af gammel fadlagret rom. Den udvikler sig med mørk chokolade, modne blommer og egetræ. Gane: Cremet konsistens. Sevilla-appelsiner og strejf af brombær. Blødt læder og cedertræ giver en kompleks rygrad sammen med en markant dosering af kanel, nelliker og lakrids. Finish: Lang, mousserende finish med krydderi og intens bittersød appelsin. Den lukker med ristet eg og honning. Alt i alt indeholder denne XO-udgave den rige og fyldige stil fra den originale Rumbullion!, men med en ekstra dimension af dybde og kompleksitet. Som alle fine spiritusser i professor Cornelius Ampleforth&#8217;s arsenal, er hver flaske pakket ind i plisseret brunt papir, viklet med sejlgarn og forseglet med sort voks. Alkohol % : 46,2 Størrelse : 50 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Barcelo Imperial', 'https://spitus.dk/product/barcelo-imperial/', 249, true, 70, 38, 'https://spitus.dk/wp-content/uploads/2021/09/barcelo-imperial-k.jpg', 'Med en drøm om at fremstille verdens bedste rom ankom den unge spanier, Julián Barceló, i 1929 til Santo Domingo i Den Dominikanske Republik. Her grundlagde han Barceló &amp; Co., og siden 1950’erne har Ron Barceló-brandet været førende i den Dominikanske Republik. En position, som i 1980 blev befæstet med lanceringen af denne verdenskendte premium-rom; Ron Barceló Imperial (“den bedste rom i verden”, Beverage Institue of Chicago). Ron Barcelo er i dag en stor og verdensberømt eksportør af rom og andet spiritus med salg og distribution over hele verden. Barceló Imperial er den Dominikanske gentleman i glasset. Den der dukker op i jakkesæt, men stadig danser som en, der har fået lidt for meget sol. Den er elegant, afrundet og fuld af den varme, modne sødme, som kun dominikansk rom kan levere. Smagen er blød og fyldig med noter af karamel, vanilje, tørret frugt, let egetræ og en snert af krydderi. Det hele er pakket ind i en silkeblød mundfølelse, der gør den farligt let at drikke. Det er rommen, du hiver frem, når du vil imponere uden at virke som om du prøver. En klassiker, en crowd-pleaser og en af de flasker, der altid forsvinder hurtigere end planlagt. Barceló Imperial er den eneste rom fra Den Dominikanske Republik, som fremstilles på frisk sukkerørssaft. Men det er egetræsfadene, der adskiller Barceló Imperial fra de andre Barcelo rom. Egetræsfadene har fået en meget hård brænding – faktisk dobbelt så hård som ved de øvrige Barceló rom, og det, kombineret med 8-10 års lagring i 37 graders varme, gør en forskel! Vi sælger den også i en version (Barcelo Imperial Onyx), som er blevet filtreret gennem sorte onyx-sten inden flaskningen, medens denne er filtreret på traditionel vis. Der er i begge tilfælde tale om en enestående- og topanmeldt rom. “Vil helt sikkert blive et hit hos romdrikkere, der er til autentisk ikke-sødet rom” Whisky &amp; Rom Magasinet, April 2017. ” Super-premium nyhed! I glasset ravfarvet med nuancer af mahogni. 92/100” Gastroactitud, Marts 2017 Leveres i gaveæske. Alkohol % : 38,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Barcelo Imperial Onyx', 'https://spitus.dk/product/barcelo-imperial-onyx/', 359, true, 70, 38, 'https://spitus.dk/wp-content/uploads/2021/09/barcelo-imperial-onyx-k.jpg', 'Med en drøm om at fremstille verdens bedste rom ankom den unge spanier, Julián Barceló, i 1929 til Santo Domingo i Den Dominikanske Republik. Her grundlagde han Barceló &amp; Co., og siden 1950&#8217;erne har Ron Barceló-brandet været førende i den Dominikanske Republik. En position, som i 1980 blev befæstet med lanceringen af den verdenskendte premium-rom, Ron Barceló Imperial (&#8220;den bedste rom i verden&#8221;, Beverage Institue of Chicago). Ron Barcelo er i dag en stor og verdensberømt eksportør af rom med distribution over hele verden. Barceló Imperial Onyx er på mange måder en unik rom. Det er den eneste rom fra Den Dominikanske Republik, som fremstilles på frisk sukkerørssaft. Men det er egetræsfadene, der adskiller Barceló Imperial ONYX fra de andre Barcelo rom. Egetræsfadene til ONYX har fået en meget hård brænding – faktisk dobbelt så hård som de øvrige Barceló rom, og det, kombineret med 8-10 års lagring i 37 graders varme, gør en forskel! Det faktum, at rommen filtreres gennem sorte ONYX sten, før den tappes på flaske, kan vi ikke lige smage i forhold til den almindelige filtrerede (Barcelo Imperial), men ifølge dominikanerne har det en helbredende effekt. Dette kan vi ikke garantere, men indholdet fejler absolut intet! Barceló Imperial Onyx er en enestående og topanmeldt rom. Næsen forfører med dybe, ristede aromaer af egetræ, espressokaffe, vanilje og chokolade. I munden forfører den med vanilje og en let bitterhed fra de hårdtbrændte fade. Den er tør, intens og vedvarende. Der er et elegant pift af kirsebær og tørrede frugter, men også nødder og toffee-sødme. &#8220;Vil helt sikkert blive et hit hos romdrikkere, der er til autentisk ikke-sødet rom&#8221; Whisky &amp; Rom Magasinet, April 2017. ”Super-premium nyhed! I glasset ravfarvet med nuancer af mahogni. 92/100” Gastroactitud, Marts 2017 Flot, flot flaske, og indtrykket forstærkes af, at vi leverer den i en lækker gaveæske. Størrelse : 70cl Alkohol % : 38,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('San Lino Carta Oro Extra Anejo Rom', 'https://spitus.dk/product/san-lino-carta-oro-extra-anejo-rom/', 249, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/08/san-lino-ron-de-cuba-carta-oro.jpg', 'San Lino Carta Oro er en cubansk rom, produceret efter gamle forskrifter og fremstillingsmetode. Den er baseret på de bedste sukkerør, og destilleret på traditionelle og ældgamle kolonneapparater. San Lino Carta Oro Extra Añejo er den gyldne rom, der tror den er kongen af hjemmebaren. San Lino Carta Oro Extra Añejo er rommen, der har ligget længe nok på brugte bourbon-fade til at blive klog, men stadig opfører sig som den sjove onkel til familiefesten. Den er blød, gylden og fuld af charme – og den ved det godt selv. Smagen er rund og varm med noter af karamel, vanilje, let krydderi og et strejf af tropisk sødme. Det er den slags rom, der får dig til at tænke: “Hmm… måske skulle jeg lave en cocktail?” og to minutter senere står du med en drink, der smager som en ferie, du ikke har bestilt endnu. Perfekt til Cuba Libres, Mai Tais, ren nydelse – eller når du bare vil have en rom, der gør alt lidt mere lækkert uden at kræve særlig opmærksomhed. Carta Oro Extra Añejo leverer. Lagring: 5 år. Alkohol % : 40,0 Størrelse: 70cl.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('San Lino Carta Blanca Rom', 'https://spitus.dk/product/san-lino-carta-blanca-rom/', 249, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/08/san-lino-ron-de-cuba-carta-blanca.jpg', 'San Lino Carta Blanca – Den lyse, cubanske rom, der altid er klar på ballade. San Lino Carta Blanca er rommens svar på en frisk havbrise: let, lys, smooth og farligt nem at drikke. Det er den type rom, der ikke gør stort væsen af sig – men som alligevel ender med at være den, alle spørger efter, når festen først er i gang. Smagen er mild og ren med et strejf af vanilje, citrus og let sødme. Ikke noget tungt, ikke noget kompliceret – bare en super anvendelig rom, der spiller perfekt sammen med cola, mojitos, daiquiris eller hvad end du lige har lyst til at ryste sammen. Perfekt til hjemmebaren, til cocktails, til sommerhygge – og til dig, der vil have en rom, der gør sit job uden at kræve spotlight. Her får du så meget mere rom for pengene, end hos mange traditionelle main-stream brands. Alkohol %: 40,0 Størrelse: 70cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Goslings 151 Proof Rom', 'https://spitus.dk/product/goslings-151-proof-rom/', 319, true, 70, NULL, 'https://spitus.dk/wp-content/uploads/2021/06/goslings-151-proof-k.jpg', 'Gosling&#8217;s Black Seal Rum er Bermudas bedst sælgende spiritus, og faktisk har Gosling&#8217;s officielt patent på den i nationaldrikken ”Dark’n Stormy”. Gosling’s begyndte som et held i uheld. James Gosling ville gerne udvide hans spiritusbutik, i den nye verden i Virginia i 1806. Han lejede en båd og fyldte den med vin og spiritus for £10,000. Efter at have ligget stille i mere end 96 dage, udløb hans lejeperiode, og han blev smidt af båden i den eneste havn mellem London og Virginia; Bermuda. Den 3. december 1806 fik han licens, og åbnede kort efter en spiritusbutik på Bermuda. Det var dog ikke før i 1850 at Bermudas nationalrom rigtig blev udbredt. Efter at have eksperimenteret med forskellige blandinger af forskellige destillater, fandt Gosling og hans virksomhed en blanding de fortrak. For at kunne købe rom den gang, skulle man medbringe sin egen flaske, og få fyldt på lige fra tønden, og sådan forblev det faktisk indtil Første Verdenskrig. Med tiden og som turismen udviklede sig på øen, og rommen blev mere og mere populære, ville folk have muligheden for at tage rommen med dem hjem. Så butikken var på jagt efter den stærkeste flaske de kunne finde, og det var genbrugte champagneflasker. The Goslings gik ned til flådebasen i havnen, og solgte champagne til dem, for at vende tilbage med hest og vogn for at hente de tomme flasker og rense dem. De fyldte dem med hvad de kaldte &#8216;Old Rum&#8217;, satte en korkprop i og forsegle dem med sort voks. Da flaskerne kom på hylden, ville kunderne pege på de sort-toppede champagneflasker, og sige &#8216; giv mig en af dem med sort forsegling (black seal). Efter 45 år blev navnet officielt ændret til Black Seal og Gosling&#8217;s er i dag en integreret og stolt del af Bermuda. Her har vi fat i den virkelig kraftige 151 Proof version, som med sine respektable 75,5% alkohol tilbyder saft og kraft som ganske få. Vi kalder den for Den Bermuda-baserede brandalarm i flaskestørrelse. Goslings 151 er rommen, der ikke bare banker på døren – den sparker den ind. Med sine 75,5% alkohol er den så potent, at selv isterningerne får respekt. Det her er ikke en rom, du drikker for sjov… men du kommer helt sikkert til at have det sjovt, hvis du gør det rigtigt. (Samtidig er den for mange den foretrukne rom til at flambere desserter med) Smagen? Overraskende rund og fyldig for en rom med så meget power. Du får mørk karamel, krydderi, melasse og en varm, intens finish, der minder dig om, at du lige har inviteret en Bermuda-orkan indenfor. Perfekt til tiki-cocktails, Dark ’n Stormy med attitude – eller når du vil lave en drink, der får dine venner til at sige “wow… og måske også lidt ‘av’”. Goslings 151: For dem, der synes almindelig rom er lidt for høflig. En del priser, medaljer og udmærkelser ved diverse rumfestivaller og romkåringer. Serveringsforslag: DARK &#8216;N&#8217; STORMY 5 cl. Gosling&#8217;s Black Seal Rum 151 Proof Ginger beer Limesaft og en skive lime Isterninger Alkohol %: 75,5 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Chairman&#8217;s Reserve Rum LEGACY Edition', 'https://spitus.dk/product/chairmans-reserve-rum-legacy-edition/', 395, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2021/03/chairmans-legacy.jpg', 'Vi indrømmer meget gerne, at vi hos Spitus.dk er kæmpefan af rom fra det lille destilleri St. Lucia Distillers. Deres Chairman’s Reserve rom giver ufattelig meget god rom og velsmag for ganske få penge. Der er ofte tale om deciderede røverkøb! Chairman’s Reserve Legacy er en af de mest transparente rom i St. Lucia Distillers’ portefølje. Den er uden tilsat sukker , og producenten har en officiel no additives ‑politik for deres core range. Det gør Legacy til en af de mest ærlige, tørre blends i mellemklassen. Chairman’s Reserve Rum Legacy er en hyldest til den navnkundige men desværre nu afdøde formand for St. Lucia Distillers; Laurie Bernard. Laurie ”The Chairman” Bernard har en meget stor del af æren for at destilleriet er hvor de er i dag, og betragtes som en sand pioner inden for blending af rom fra forskellige destillationstyper – St. Lucia’s kendetegn! Hyldesten kunne derfor kun være et blend fra forskellige destilleringsapparater, og i Legacy er der anvendt rom fra hhv. pot still, batch still og Coffey still. Størstedelen af blended til Legacy kommer fra traditionel sukkerrørsmelasse, men der er tilsat 8% agricole rom, produceret af friske sukkerrør fra destilleriets omkringliggende sukkerrørsmarker. Det giver klart et ekstra pift og tyngde i slutproduktet. Modningen af de forskellige destillater er foregået i ex bourbonfade imellem 5 og 7,5 år (agricole-rommen har fået 5 år). Farven er gylden mahogni. I næsen får du karamel, rosiner, vanilje og eksotiske krydderier. Herlig kompleksitet og dybde! Munden fyldes af flydende nektar. I retning af créme brûlée og smørbagte muffins med nødder. Masser af tyngde og lag. Ananas, fersken og mango danser på tungen sammen med andre eksotiske frugter. Et lille bid fra agricole-delen, for lige at holde det hele i snor. Mesterlig sammensætning fra mestrene i den disciplin! Chairman’s Reserve LEGACY Edition er flasken, der samler alt det, der gør Saint Lucia til et romparadis: dybde, varme og en kompromisløs kærlighed til håndværk. Her får du en elegant blend af pot still og column still rom, lagret i tropisk klima for maksimal fylde og karakter. Chairman’s Reserve Legacy har opnået rigtige fine anmeldelser rundt omkring, og siden Mads ”Romhatten” Heitmann i slutningen af december 2020 lavede en flot anbefaling, har den virkeligt fundet plads i manges hjerter. Mads afslutter sin anmeldelse således: ”Det er virkelig en flot rom, og samtidig en rom som emmer af St. Lucia. Den klassiske St. Lucia-romsmag er bestemt til stede. Det er sjældent at man ser en rom på dette kvalitetsniveau til så lav en pris…. Det er svært at finde fyldig rom med en god del batch-destilleret rom i blendet til under 400 kr., men det gør du altså her. Hvis man elsker rom fra St. Lucia, så kan man roligt gå ud og købe en flaske Chairman’s Reserve Legacy Rum. Det er god gedigne rom uden så meget fis! En kæmpe anbefaling herfra.” Størrelse : 70 cl Alkohol % : 43,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Emperor Mauritian Rum Heritage', 'https://spitus.dk/product/emperor-mauritian-rum-heritage/', 279, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/03/emperor-mauritian-rum-heritage-k.jpg', 'Emperor Rom har specialiseret sig i at lave blendede udgivelser af sukkerrørsdestillater og sukkerrørssaft fra Mauritius. De eksperimenterer også med forskellige fadtyper, og i denne heritage, er der anvendt flere forskellige typer fade. Selve navnet Emperor, er skabt for at ære Kong George den 5. som var kejser af det britiske imperium og dermed også over Mauritius. Dette store mix af metoder og tilgange, skal måske ses i sammenhæng med Mauritius temmelig diverse historie. Mauritius har nemlig både været en hollandsk koloni (1638-1710), en fransk koloni (1715-1810) og en britisk koloni (1810-1968). Derfor er øen også multietnisk, multireligiøs, multikulturel, flersproget og naturligvis multi-romproducerende. Emperor Rum er derfor et godt eksempel på øens arv og historie. Der er i dag 6 destillerier på øen som producerer alt fra den traditionelle Agricole Rom til den sødere britiske/spanske stil. Øen er for 85 % vedkommende dækket af sukkerrørsmarker, så jorden er prioriteret rigtigt! Duften er imødekommende med noter af ristede mandler, vanilje og eg. Smagen er ret kraftfuld med mørk chokolade, karamelliseret frugt, mokka og krydderier, samt et lille touch af toffee og svirp fra sukkerørssaften i afslutningen. Emperor Heritage er flasken, der indkapsler øens historie, håndværk og varme i én elegant blend. Den kombinerer både agricole- og melassebaseret ophav, hvilket giver en unik dybde og en smagsprofil, der både er frisk, fyldig og raffineret. Leveres i flot gaveæske Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Emperor Mauritian Rum Royal Spiced', 'https://spitus.dk/product/emperor-mauritian-rum-royal-spiced/', 339, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/03/emperor-mauritan-rum-royal-spiced-k.jpg', 'Emperor Rom har specialiseret sig i at lave blendede udgivelser af sukkerrørsdestillater og sukkerrørssaft fra Mauritius. De eksperimenterer også med forskellige fadtyper og lagringsmetoder. Selve navnet Emperor, er skabt for at ære Kong George den 5. som var kejser af det britiske imperium og dermed også over Mauritius. Emperor Rum Royal Spiced er en krydret sag, som bl.a. har lagret ”Mono-Matuation”, hvor fadet tilsættes forskellige krydderier. Her er der tilsat bl.a. kardemomme, stjerne anis og kanel. Profilen er sød, men med en herlig krydret note. Der er en fin balance mellem det krydrede og det søde, og den bringer masser af varme og karakter. Emperor Royal Spiced er flasken, der beviser, at Mauritius ikke kun laver paradisstrande – de laver også paradis på flaske . Her får du en krydret, aromatisk og uimodståeligt smooth oplevelse, der smager som en tropisk fest med VIP-adgang. Smagen er fyldt med vanilje, kanel, citrus, let varme og en eksotisk sødme, der føles som at få et high-five af en solbrun ø-gud. Den er blød, rund og farligt let at drikke – præcis som en god spiced skal være. Perfekt til cocktails, cola, ginger beer eller bare ren hygge i sofaen. Royal Spiced? Ja tak – kronen passer. Leveres i en gaveæske. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Opthimus 25 Años Summa Cum Laude', 'https://spitus.dk/product/opthimus-25-anos-summa-cum-laude/', 635, true, 70, 38, 'https://spitus.dk/wp-content/uploads/2021/03/opthimus-25-anos-summa-cum-laude-k.jpg', 'Denne Opthimus 25 års siges at være stoltheden i huset . Opthimus 25 Años Summa Cum Laude er spiritussens svar på at tage eksamen med topkarakter. En sjælden, håndlavet soleraperle, hvor op til 25 års tropisk modning skaber en dybde og elegance, der kun findes i de mest prestigefyldte udgivelser. Smagen er intens, moden og silkeblød med lag af karamel, mørke bær, rosiner, vanilje, egetræ og en lang, varm finish. Alt er balanceret, afrundet og forfinet – som et destillat, der har fået lov at udvikle sig helt uden kompromiser. En flaske til samlere, connaisseurs og alle, der vil opleve, hvad ægte tålmodighed smager af. Den er ret sød, og præcis som de fleste danskere foretrækker deres rom! Mads ”Romhatten” Heitmann kvitterede med hele 91 points i hans begejstrede anmeldelse. Størrelse : 70 cl Alkohol % : 38,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Opthimus 15 Años Solera OportO', 'https://spitus.dk/product/opthimus-15-anos-solera-oporto/', 415, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2021/03/opthimus-15-anos-solera-oporto.jpg', 'Opthimus har haft stor succes med deres 25 års udgave der har lagret på brugte portvinsfade. Nu har de derfor udgivet en 15-års version, også lagret efter solera-metoden, og som til sidst er færdiglagret på brugte portvinsfade. Forskellen på denne aftapning og den normale Opthimus 15 års er netop efterlagringen på portvinsfade, samt 5% højere alkohol. Rom og portvin fungerer ofte godt sammen, og denne Opthimus 15 Años Solera OportO har bl.a. vundet guld i kategorien &#8220;Aged Rum Special Cask&#8221; ved Miami Rum Festival. Næsen er meget sød, og med tydelige noter af portvin. Der er figner, tørrede frugter og kanel. I munden går krydderierne hånd i hånd med de søde portvins-noter. Masser af vanilje, dadler, karamel og nødder. I den lange eftersmag går smagene igen, og den efterlader munden med en dejlig varme og velsmag. Super imødekommende repræsentant, hvor den lidt højere alkoholprocent spiller godt sammen med elementerne fra portvinsfadene. Leveres i gaveæske. Størrelse : 70 cl Alkohol % : 43,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Pussers British Navy Rum 15 Y.O. Nelsons Blood', 'https://spitus.dk/product/pussers-british-navy-rum-15-y-o-nelsons-blood/', 589, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/02/pussers-british-navy-rum-15-Y.O.-nelsons-blood.jpg', 'Denne kraftige Navy-rom, er pot still-destilleret i noget så sjældent som en træ-kedel. Iflg. Pusser selv, findes der kun 2 af disse træ-kedler tilbage, der bliver anvendt til produktion. Efter sigende, skulle trækedlen give mere smag og power i rommen. Om det passer ved vi ikke, men faktum er, at denne ”Pussers British Navy Rum 15 års Nelson’s Blood” i hvert fald ikke mangler smag eller power! I næsen får du masser af kompleksitet og sødmefuld eg og vanilje. Meget mørk og brandy-agtig i stilen. I munden er der rigtig meget smæk på! En rigtig sømands-rom! Den er cremet og meget mørk i smagen – opleves som en noget ældre rom. Mørke krydderier, tørrede frugter og godt med ege fad. Finishen er lang, cremet og dejlig krydret. Mads ”Romhatten” Heitmann skriver bl.a. i anmeldelsen: ”Normalt er jeg ikke til navy-rum, men jeg kan faktisk rigtig godt lide denne. Måske er mine smagsløg ved at vende sig eller måske er dette bare den bedste navy-rum jeg indtil nu har sat tænderne i?”. Pusser’s British Navy Rum 15 Y.O. “Nelson’s Blood” er en af de mest klassiske, tørre navy‑rom på markedet. Pusser’s er kendt for ingen tilsætning af sukker, farve eller aroma , og 15‑års udgaven følger samme linje. Det gør den til en af de mest “ærlige” mørke rom i premium‑klassen. Vinder af flere kåringer og priser. Leveres i flot gaveæske. Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Pyrat XO Reserve', 'https://spitus.dk/product/pyrat-xo-reserve/', 345, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/02/Pyrat-xo.jpg', 'Pyrat XO Reserve er en fin sag blended fra 9 forskellige fade (fransk Limousin- &amp; amerikansk eg) fra 7 forskellige destillerier fra forskellige øer i Caribien. Det var en masse ”forskellige fra’er”, og det siger vel meget godt, at der er tale om en sammensat rom, der dog hænger rigtig fint sammen! Pyrat XO har en flot gylden farve med et blidt skær. I næsen er der en del appelsin og let sødlig tobak. I munden får du tydelige noter fra fadene, men stadig en del appelsin og lime. Meget frisk stil, som har opnået stor popularitet verden over. Pyrat XO Reserve smager af Caribisk overskud Den er spiritussens svar på en solnedgang over Caribien: blød, rund og uimodståeligt sødmefuld. Den ikoniske orange flaske gemmer på en oplevelse fyldt med noter af appelsinskal, vanilje, honning og et strejf af egetræ, der giver en luksuriøs og næsten dessertagtig oplevelse. Perfekt til dig, der elsker din dram med charme, varme og masser af karakter. Nyd den ren, over is – eller som den hemmelige ingrediens, der løfter dine cocktails til nye højder. En crowd-pleaser med stil og personlighed. Pyrat XO Reserve er lavet på Solera metoden, og alderen er sat til 15 år (men den består af rom op til 40 år). Størrelse : 70 cl Alkohol % : 40,0%');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 12 Y.O.', 'https://spitus.dk/product/el-dorado-12-y-o/', 349, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/100185-1.jpg', 'El Dorado 12 Years Old er en rom fra det sidste overlevende destilleri på Guyana; Diamond Distillery. Rommen her er sammensat af destillater fra flere af deres kedler, blandt andet den berømte coffey still, Enmore. Den er lagret i minimum 12 år på amerikanske egetræsfade og er uden tvivl startskuddet for mange romelskere samt en rom, man gerne vender tilbage til. Destilleriet blev grundlagt tilbage i år 1670. Sukkeret fra de lokale producenter i Guyana og de unikke destilleringsmetoder, Wooden Coffey Still og Wooden Pot Still, bidrager til den unikke smag af El Dorado rom. Rommen bliver anset for at være en af verdens bedste &#8220;price for value&#8221;-rom, og har vundet utallige priser. Demerara-regionen i Guyana har produceret verdens måske bedste sukker og rom siden starten af 1700-tallet. I over 250 år producerede mere end 300 sukkerplantager, udover gyldent rørsukker og sirup, den fineste rom, som blev eksporteret til hele verden. Den engelske flåde var den største aftager af den kraftige mørke rom fra bl.a. Port Mourant-plantagen, som indgik i den famøse britiske Navy Rum. I dag er de fleste af plantagerne og alle destillerierne desværre nedlagte. Heldigvis lever de bedste destillerier videre i, hvad der bedst kan beskrives som, et ”levende museum”; Diamond Distillery bragte de bedste af de lukkede plantagedestilleriers produktionsudstyr med til Georgetown, hvor der i dag produceres 20 forskellige romstilarter på 9 forskellige gamle kolonne- og pot stills. El Dorado 12 års rom har en mørk gylden farve. I næsen får du en attraktiv aroma af vanilje, karamel, moden abrikos, mandel og honning, samt toffee og rosiner. Det er er en sød og forholdsvis kompleks rom med en afrundet smag og lang, tør finish. Karamel, toffee og vanilje går igen, men man får også noget brun farin. Størrelse : 70cl Alkohol % : 40,0 Vi leverer den i en flot gaveæske Mads &#8220;Romhatten&#8221; Heitmann: ”Denne mørke rom fra Guyana er det man forstår ved „rigtig rom“. Den yngste rom der er brugt er hele 12 år gammel og så er den vinder af utallige priser, og er meget respekteret. Guyanas tropiske klima tilbyder de optimale vilkår til forædling af rom. I El Dorado 12 års rom fornemmer man straks rommens spændende oprindelse. Den blev blandt andet drukket af mandskabet på den Engelske Flåde, tilbage i 1800’tallet. Det er uden tvivl en af mine yndlingsrom når man kigger på pris og kvalitet. Den er fabelagtig i en rom og cola, men samtidig er den meget, meget drikkevenlig hvis man vil nyde en ren rom. Har du ikke været forbi El Dorado 12 års endnu, så er det ved at være på tide. Du vil IKKE blive skuffet”.');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 15 Y.O.', 'https://spitus.dk/product/el-dorado-15-y-o/', 445, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2021/02/el-dorado-15-YO.png', 'El Dorado 15 års er en fabelagtig ”klassiker” fra Guyana. Du kender måske El Dorado 12 års som er en storsællert, men her har vi faktisk fat i noget ganske andet, og du må ikke tro, at denne 15 års ”bare” er et lidt ældre blend af en i forvejen rigtig, rigtig god rom. Der er temmelig meget mere kompleksitet og volumen i denne version. El Dorado 15 års er da også destilleriets mest vindende og prestigefyldte rom, med et helt utroligt pokalskab bag sig. Bl.a. vandt den blindsmagningerne ved International Wine and Spirits Competition i London i 1999, 2000 og 2001. I 2011 vandt den ”Gold Medal &amp; Best in its Class&#8221; ved IWSC, samt mange andre fornemme titler. Rommen er generelt anerkendt som Caribien&#8217;s førende rom, og den 15-årige El Dorado Special Reserve anses som en elegant, cognac-agtig rom, der har den mest komplekse og sammensatte karakter i klassen. Der er tale om en blanding af særligt udvalgte gamle rom, hvor den yngste er mindst 15 år gammel, og nogle er 25 år gamle. Den er lavet på en kombination af Enmore og Diamond Coffey Stills, Port Mourant double wood Pot Stills og Versailles single wood pot stills, hvorefter den blandes til perfektion, og lagres på gamle, forholdsvist små (45 gallons) bourbon egetræsfade. Lagringen i de små fade, er med til at sikre en ret mørk rom, men ikke mindst giver det en blødhed og nøddeagtig karakter som bare er vidunderlig. Næsen er søde appelsiner, mørkristet kaffe, nødder, vanilje og mørk chokolade. I munden suppleres der med noget friskhed fra tropiske frugter og en anelse krydderi. Ekstrem rund og silkeblødt, men med pondus nok til at du tydeligt mærker alderen og det gode håndværk. Mads ”Romhatten” Heitmann afslutter hans anmeldelse således: ”… s å er det også en af mine yndlingsrom. En smuk, smuk rom, som altid formår at overraske mig, også selvom jeg har smagt den 100 gange!” Et virkeligt godt køb, og et fortrinlig valg hvis du vil prøve hvor meget rom man kan få i 400kr’s klassen. Leveres i gaveæske (bemærk: gaveæsken har ændret udseende, og er nu rå-hvid i stedet for blå &#8211; vi har begge versioner på lager) Alkohol % : 43,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado 21 Years Old Finest Demerara Rum SPECIAL Reserve', 'https://spitus.dk/product/el-dorado-21-years-old-finest-demerara-rum-special-reserve/', 749, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2021/02/el-dorado-21-special-reserve-k.jpg', '&#8220;En monumental ældet rom, der er en af verdens største rom-oplevelser&#8221; (oversat), konkluderede ”The Beverage Tasting Institute of Chicago&#8221;, og kvitterede samtidig med hele 98 points, da de anmeldte denne El Dorado 21 Y.O. Deres Master Blender udvælger og blander selv de bedste rom fra kælderen, der er lagret i mindst 21 år. Destilleringen er foregået på en Enmore wooden Coffey still, Versailles single wood pot still og Albion Savalle still. Farven er mørk gylden, og i næsen er der mørk chokolade, vanilje og lakrids. I munden komplementeres der med en sødlig honning og appelsin og mandarin. Dejlig fylde, og masser af naturlig sødme. I eftersmagen er der krydderier og eksotiske frugter. Fremragende rom! Demerara Distillers fra Guyana ved om nogen hvordan man skærer en god rom, og deres 12- og 15-års udgaver er nogen af de mest solgte på markedet overhovedet. Denne 21-års beviser, at de også kan frembringe value-for-money rom med en noget højere alder. Leveres i gaverør. Størrelse : 70 cl Alkohol % : 43,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('El Dorado Port Mourant Demerara Rum RARE Collection, 1999', 'https://spitus.dk/product/el-dorado-port-mourant-demerara-rum-rare-collection-1999/', 2249, true, 70, 61.4, 'https://spitus.dk/wp-content/uploads/2021/02/el-dorado-port-mourant-demerara-rum-rare-1999.jpg', 'El Dorado Port Mourant Rare Collection Limited Release 1999 er på alle måder en unik rom! Tidligere havde Velier enorm succes med Guyana single stills med fadstyrke. Denne kombi står for noget af den bedste rom denne verden har set! Derfor kom det som et chok, da de i 2015 meddelte at det var slut med disse aftapninger. Heldigvis tog Demerara Distillery handsken op i 2016, og udgav en lille meget eksklusiv serie kaldet ”Rare Collection” – efter samme koncept som Velier for nu en del år siden. Denne eminente udgave, er som navnet siger, destilleret på det ældgamle pot still lavet af træ kaldet Port Mourant. Præcis Port Mourant, er kendetegnet ved at levere enormt kraftige, tunge og nærmest tyktflydende fuldblodsrom af en anden verden. Apparatet har flyttet en del rundt på øen, i takt med at de forskellige destillerier lukkede, men nu er den altså i kyndige hænder igen. Demerara Distillers har nøje udvalgt fade destilleret i 1999 i dette blend, og efter årene i bourbon-fadene, er den altså aftappet ved fadstyrke (61,4%). I næsen emmer den af farin, gamle brændte fade, mørk chokolade, appelsiner og kaffebønner. I munden bliver du blæst fuldstændig bagover! Du er ikke i tvivl om fadstyrken, men hold da op det spiller det her. Mørke, varme eksotiske krydderier, tropiske modne frugter, vanilje, rosiner og nødder. Eftersmagen bliver ved længere end du kan vente med at tage næste sip. Det er voldsom power, spark, fuldfed, vild, og utæmmet kærlighed. Mads ”Romhatten” Heitmann gav i januar 2016 denne rom 96 points ved en pris på 2.385kr. Vild rom? Så er El Dorado Port Mourant Rare Collection 61,4% et oplagt og fantastisk bud. Leveres i flot gaveæske Størrelse : 70 cl Alkohol % : 61,4');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Professor Cornelius Rumbullion!', 'https://spitus.dk/product/professor-cornelius-rumbullion/', 369, false, 70, 42.6, 'https://spitus.dk/wp-content/uploads/2020/12/professor-cornelius-rumbullion.jpg', 'Her præsenterer vi den ”normale” Professor Cornelius Rumbullion! på 42,6%. (Se også Navy Strength samt XO-udgaverne her på Spitus.dk). Der er tale om en uhyre populær udgivelse, som bare smager herligt med en sød og krydret smag. Professor Cornelius Rumbullion! består af et blend af forskellige caribiske mørke rom, hvor der er tilført ekstra krydderier; primært vanilje fra Madagaskar, kanel, nelliker, appelsinskaller og en smule kardemomme. Farven er mørkt rav, og i næsen får du en herlig sød aroma med vanilje, appelsiner og en anelse nellike. I munden er den cremet og fylder munden godt. Der er sød vanilje, honning, appelsiner og ristet kanel. I finishen er der chokolade og modne blommer, samt vanilje og fin kompleksitet. Stor, sødlig velsmag! Som alle fine spiritusser i professor Cornelius Ampleforths arsenal, er hver flaske pakket ind i plisseret brunt papir, viklet med sejlgarn og forseglet med sort voks. Professor Cornelius Rumbullion! er flasken, der nægter at stå stille på hylden. Fyldig, krydret og uimodståeligt varm – som et kram fra en victoriansk gentleman med en hemmelig flaske i inderlommen. Noter af vanilje, kanel og mørk karamel gør den perfekt til både cocktails og ren nydelse. Personlighed, kant og masser af charme. Perfekt til dig, der elsker smag med en historie bag. Skal den med i kurven? Størrelse: 70 cl Alkohol % : 42,6');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cartavio Black Dark Rum', 'https://spitus.dk/product/ron-cartavio-black-dark-rum/', 179, true, 70, 37.5, 'https://spitus.dk/wp-content/uploads/2021/03/ron-cartavio-black.jpg', 'I den meget frodige dal, Chicama Valley på Perus nordkyst finder vi Cartavio destilleriet; Destilerias Unidas, grundlagt den 29. april 1929. Placeringen er perfekt for vækst og dyrkning af sukkerrør, og vandet der anvendes kommer rindende ned i den reneste og krystalklare form fra Andesbjergene. De geografiske forhold er således perfekte, men arbejdet i destilleriet er også fintunet og lever op til mulighederne. Bl.a. er arbejdet med fadene meget imponerende, og der anvendes f.eks. Pedro Ximenez-fade, samt amerikanske, franske og slovenske egefade. Denne prisbasker, kommer med søde noter af eg, tørret kokosnød og antydninger af tørret frugt. Blendet er sammensat af destillater fra destilleriet, som har ligget på fad imellem 2 og 5 år. Mørk, fyldig og lige tilpas fræk – som en nat i Lima, hvor ingen helt ved, hvad der sker, men alle er glade for at være der. Smagen er dyb og rund med noter af karamel, krydderi, ristet træ og et strejf af mørk chokolade. Den fungerer både som “bare én mere”-dram og som turbo-opgradering til dine cocktails. Perfekt til dig, der elsker din dram med kant, karakter og en god portion mørk charme. Størrelse : 70 cl Alkohol% : 37,5');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Cartavio XO 18 Años', 'https://spitus.dk/product/ron-cartavio-xo-18-anos/', 669, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/12/ron-cartavio-xo-18-ny-flaske-k.jpg', 'I den meget frodige dal, Chicama Valley på Perus nordkyst finder vi Cartavio destilleriet; Destilerias Unidas, grundlagt den 29. april 1929. Placeringen er perfekt for vækst og dyrkning af sukkerrør, og vandet der anvendes, kommer rindende ned i den reneste og mest krystalklare form fra Andesbjergene. De geografiske forhold er således perfekte, men arbejdet i destilleriet er også fintunet og lever op til mulighederne. Bl.a. er arbejdet med fadene meget imponerende, og der anvendes f.eks. Pedro Ximenez-fade, samt amerikanske, franske og slovenske egefade. Ron Cartavio XO 18 YO Solera, blev kåret til “Verdens Bedste Rom&#8221; i både 2015 og 2016 ved San Francisco World Spirits Competition, hvor den vandt i den fine kategori ”Premium Aged Rums”. Siden er salget og fanskaren eksploderet, og det forstår vi sådan set godt! Lagringen er efter Solera-metoden, og blendet er et miks af både kedeldestillater og kolonnedestillater. Lidt usædvanligt med anvendelsen af kedeldestillat i en spansk inspireret stil, og måske er det netop de mere fyldige destillater herfra der giver den store kompleksitet? Ron Cartavio XO 18 Años er udgivelsen, der beviser, at Peru kan meget mere end alpakaer og Machu Picchu. Her får du en seriøst velmodnet udgivelse, der har brugt mange år på at blive blød, dyb og uimodståeligt elegant. Smagen er fyldig og rund med lag af karamel, vanilje, tørret frugt, krydderi og et strejf af mørk chokolade. Det hele pakket ind i en silkeblød mundfølelse, der får dig til at tænke: “Okay… den her flaske skal gemmes til de gode stunder.” Perfekt som ren nydelse, til dessert – eller når du vil imponere nogen uden at sige et ord. Cartavio XO 18 er ren peruviansk charme på flaske Rommen har også vundet talrige andre udmærkelser, herunder 2 * Guld i ”Fifty Best Aged Rums”, med kommentaren &#8216;Outstanding, perfect&#8217;. Mads ”Romhatten” Heitmann scorer den til 92 points. Fantastisk flaske, leveret i en meget flot og elegant karaffel og gaveæske. Det hele er uhyre godt gennemført! Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador 12 Y.O.', 'https://spitus.dk/product/dictador-12-y-o/', 389, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/12/dictador-12-year-k.jpg', 'Dictador 12 Y.O. er en herlig klassiker fra Columbia. Som noget helt særligt tilsættes der colombiansk honning til sukkerrørsmelassen under gæringen. Dette bevirker, at smagen bliver mere fyldig, krydret og kompleks. Farven er ravgylden, og i næsen er der en intens aroma af karamel, vanilje, honning, kaffe og egetræ. I munden er der kakao, sød karamel, honning og en anelse sød lakrids. Man fornemmer de sødmefyldte bourbonfade. Eftersmagen er temmelig fedmefyldt og olieret med knasende rørsukker og et let strejf af kanel og egetræ. En meget elegant ”sippe” rom fra Caribiske superliga. Vi leverer den i en elegant gaveæske &#8211; og som altid til Danmarks absolut laveste pris &#8211; med garanti! Størrelse : 70cl Alkohol % : 40,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador 20 Y.O', 'https://spitus.dk/product/dictador-20-aars-rom/', 489, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/12/dictador-20-yo.png', 'Her præsenterer vi én af klassikerne indenfor rom og rombaserede spiritusser. Den har siden 2011 vundet et hav af priser og medaljer, og sætter på mange måder standarden for prisklassen. Det specielle ved Dictador 2o års, udover at den stammer fra Columbia, er at den er fremstillet på et mix af sukkerrørs- og honning-melasse. En rom som Ron Zacapa laves også på honning-melasse, og kan på visse områder sammenlignes med denne Dictador-udgivelse. Hvis du er fan af sødlige rom, anbefaler vi på det varmeste at prøve denne. (Vi måler ca. 25–35 g/L sukker) I ganen får du en varm, cremet vanilje og karamel, med toner af brændt honning, toffee, anisfrø og ny ristede kaffebønner. Det hele er pakket ind i noterne af ege fad. Du fornemmer tydeligt honningen fra destillatet. Og netop dette ekstra lag af honning, er der hvor denne 20 års udgave adskiller sig mest fra dens 12-årige lillesøster. Stilen er således den samme, men der er noget mere fylde og tyngde her. Ganske som forventet. Eftersmagen er fedmefyldt og olieret, med en delikat smag af abrikos, romrosin og en herlig blid bourbon sødme. Størrelse : 70cl Alkohol % : 40,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Dictador 2 Masters Glenfarclas 1972', 'https://spitus.dk/product/dictador-2-masters-glenfarclas-1972/', 9495, true, 70, 45, 'https://spitus.dk/wp-content/uploads/2020/12/dictador-2-masters-glen-k.jpg', 'Dictador 2 Masters Glenfarclas 1972 er et produkt skabt af kærlighed af 2 af de største og bedste indenfor henholdsvis rom og whisky: Dictador og Glenfarclas! Rommen blev destilleret i 1972, og efter årtiers ældning på et enkelt fad, blev den transporteret til Glenfarclas i Skotland. Her tilbragte den yderligere 7 måneder i et ex-Glenfarclas Vintage 2002 Jerez Sherry-fad. Den er aftappet ved 45% ABV, og der blev lavet 378 flasker i alt . Flaskerne bærer fingeraftrykkene fra både Dictador-masterblender Hernan Parra og Glenfarclas produktionschef Callum Fraser. Næse: uden tvivl en monumental gammel rom gift med en fremragende whisky. Meget tydelige maltede bygtoner, sherrynoter og tørrede abrikoser, og med en sødlig duft af ahornsirup, smeltet brun sukker og tropiske frugter. I ganen er whiskyen mere i baggrunden, og du får et lag med uhyre afrundede, tropiske tørrede frugter med medjool dadler, soltørrede rosiner og akaciehonning. Det er rom fra en anden verden, der er blevet kælet for i dens 50-årige tilstedeværelse. Eminent god, ældgammnel rom! Finish: Den sparker tilbage med en utrolig balance mellem alkohol, frugt og syre. Den har en fabelagtig finish, der bare dvæler i flere minutter. Og når &#8220;burnet&#8221; fader ud, sidder du tilbage med et smil og noter af karamel, sød tobak og ristet kokosnød. Rom af denne kaliber er jo ikke billigt, og alene det begrænsede oplag fra 2 så stærke brands, gør efterspørgslen stor. Den vil kun stige i værdi. Alkohol %: 45,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Black Barrel Navy Spiced', 'https://spitus.dk/product/a-h-riise-black-barrel-navy-spiced/', 295, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/12/A.H.-Riise-Black-Barrel-Navy-Spiced.png', 'A.H. Riise Black Barrel Navy Spiced fra A.H. Riise er tæt knyttet til verdenshavene og søfart, hvilket flaskens udformning også bærer stærkt præg af, og den bygger på mere end 175 års knowhow i at blende og lagre rom og rombaserede spiritusser. Via lagringen på stærkt brændte egefade, ja faktisk forkullede indersider på fadene, får den en krydret karakter og ’spice’, der fuldt ud lever op til dens navn. I glasset er Black Barrel Navy Spiced næsten kulsort, og i næsen får du velkendte toner af vanilje, kaffe, nødder og eksotiske krydderier. Smagen er sødmefuld og fyldig, med chokolade, kanel, mokka, eg og søde krydderier. Eftersmagen er ”spiced”, og med mørk chokolade og mere mokka. Black Barrel Navy Spiced er i den søde stil, som altid med A.H. Riise og Old St. Croix, men denne er infuseret med en række eksotiske krydderier, og dermed får du masser af krydret velsmag! Selve flasken er lidt anderledes, og udformet som en tønde. Oplagt gaveidé Alkohol %: 40,0% Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Reserve Superior Cask', 'https://spitus.dk/product/a-h-riise-x-o-reserve-superior-cask/', 379, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2023/01/a-h-riise-xo-superior-cask-reserve-k.jpg', 'A.H. Riise XO Reserve Superior Cask er den klassiske Riise‑oplevelse i sin reneste form. A.H. Riise XO Reserve Superior Cask er en af de mest ikoniske flasker i hele Riise‑universet. Den er sød, rund, aromatisk og pakket med den varme, tropiske signatur, som har gjort brandet til en favorit blandt romnydere, der elsker blødhed og fylde. A.H. Riise XO er en samling af ekstra gamle blandinger lavet af dobbeltdestilleret førsteklasses modnet caribisk rom. Blandingerne er nøje udvalgt og sammensat af A.H. Riise’s masterblendere for at sikre perfekt afbalancerede og ensartede blandinger. Stilen er den søde, balsamiske og aromatiske med stærke rødder i A. H.Riise’s arv fra Dansk Vestindien. Lagringen i PX og Oloroso sherryfade bidrager til den mørke og søde smag. Blended er sammensat af fine gamle romfade (op til 20 år) samt lidt yngre fade, der giver en perfekt kant og fyldig smagsoplevelse. Hvert fad er specielt udvalgt af A.H. Riise´s Master Blender, aftappet enkeltvis &#8220;Single Barrel&#8221;, og hver flaske er desuden mærket individuelt med fad-nummer samt aftapnings dato. Farven er flot gylden, let mahogniagtig. I munden meget frugtagtig og fyldig smag med nuancer af appelsin, mango, papaya og vanilje, afsluttende med en fløjlsagtig blød og delikat, sødmefuld eftersmag. A.H. Riises spiritusser, er nogle af de absolut mest solgte i Danmark, og den meget søde stil har mange fans. Det er en meget ”let-at-gå-til-dram&#8221;. Det er en oplevelse, der føles som ren forkælelse – perfekt til langsomme aftener, dessertmomenter eller når du bare vil have noget, der smager rigtig godt uden at kræve noget af dig. A.H. Riise XO Reserve Superior Cask: Klassisk sødme, luksus i glasset og en sikker vinder hos enhver Riise‑fan. Leveres i flot gaveæske Størrelse : 70 cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise X.O. Reserve Super Premium Single Barrel Rum &#8211; Old Version', 'https://spitus.dk/product/a-h-riise-x-o-reserve-super-premium-single-barrel-rum/', 579, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/12/a.h.-riise-xo-reserve-k.jpg', 'A.H. Riise X.O. Reserve Super Premium Single Barrel &#8211; Old Version Rum A.H. Riise XO er en samling af ekstra gamle blandinger lavet af dobbeltdestilleret førsteklasses modnet caribisk rom. Blandingerne er nøje udvalgt og sammensat af A.H. Riises masterblendere for at sikre perfekt afbalancerede og ensartede blandinger. Stilen er den søde, balsamiske og aromatiske med stærke rødder i A. H.Riises arv fra Dansk Vestindien. Lagringen i PX og Oloroso sherryfade bidrager til den mørke og søde smag. Blended er sammensat af fine gamle romfade (op til 20 år) samt lidt yngre fade, der giver en perfekt kant og fyldig smagsoplevelse. Hvert fad er specielt udvalgt af A.H. Riises Master Blender, aftappet enkeltvis &#8220;Single Barred&#8221;, og hver flaske er desuden mærket individuelt med fadnummer samt aftapningsdato. Farven er flot gylden, let mahogniagtig. I munden meget frugtagtig og fyldig smag med nuancer af appelsin, mango, papaya og vanilje, afsluttende med en fløjlsagtig blød og delikat, sødmefuld eftersmag. A.H. Riises rom er nogle af de absolut mest solgte i Danmark, og den meget søde stil har mange fans. Det er en ”let-at-gå-til rom&#8221;, som falder i de flestes smag. OBS! Dette er den gamle version, og der er derfor naturligvis kun en begrænset mængde tilbage på lager. (Find den nye (og billigere version) andet sted på shoppen) Størrelse : 70 cl Alkohol % : 40,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Royal Danish Navy', 'https://spitus.dk/product/a-h-riise-royal-danish-navy/', 359, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/12/100299-1-A.H.-Riise-Royal-Danish-Navy.jpg', 'A.H. Riise Royal Danish Navy 40 % er blended af flere forskellige og op til 20 år gamle romdestillater fra Caribien. Efterfølgende bliver den destilleret til den rammer 85 % i alkoholstyrke. Det sker ved den traditionelle pot still-destillering, der giver den et højt indhold af estere og kraftig duft. Først til sidst vandes blended ned til lettere drikkelige 40 %, inden der tappes på de eksklusive flasker. Når man kalder sin spiritus for The Original , så er det ikke bare for sjov. A.H. Riise Royal Danish Navy The Original er selve fundamentet – den klassiske, den ikoniske, det produkt, der har været med til at skrive historien. Den er som en fanfare i flydende form: kraftfuld, krydret og med en pondus, der får dig til at rette ryggen og sige: “Skål – for kongen og flåden!” Duften er som at åbne en skattekiste på en caribisk ø. Noter af cedertræ, vanilje, karamel og krydderier vælter frem, blandet med et strejf af ristet egetræ. Det er en bouquet, der både lover sødme og styrke – som en sømand, der kan synge både vuggevise og kampsang. Smagen er fyldig, krydret og med en robust karakter, der matcher navnet. Først kommer den bløde sødme med kandiserede æbler, appelsin, kokos og karamel, så krydderierne, og til sidst en fed eftersmag, der hænger ved længere end en god sømandsanekdote. Det er ikke bare god dram – det er en oplevelse, der kræver, at du tager dig tid til at nyde hvert eneste lag. A.H. Riise Royal Danish Navy The Original er en hyldest til Danmarks stolte søfartshistorie, til eventyrlyst og til krydderiernes magi. Den er til dig, der vil have mere end bare spiritus i glasset. Den er til dig, der vil have historier, smagslag og en snert af havets rå kraft. Vinder af flere internationale priser. Flot flaske og gaveæske. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Ambre d&#8217;Or', 'https://spitus.dk/product/a-h-riise-xo-ambre-dor/', 419, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2020/12/A.H.-Riise-XO-Ambre-dOr-k.jpg', 'Riise Ambre d&#8217;Or XO Reserve er baseret på rom fra det caribiske og mellemamerikanske område og er en videreudvikling af den ”almindelige” men populære A.H. Riise XO Reserve. Forskellen består i, at denne Ambre d&#8217;Or XO Reserve er blevet lagret i eksklusive egetræsfade, der tidligere har været anvendt til hvide dessertvine. Farven er gylden lys, rav. I næsen giver den primært vanilje, karamel og blomster. I munden fornemmer du tydeligt noterne fra de søde hvidvine. Det er en fremragende kombination med de mere traditionelle noter fra god rom. Eftersmagen er nærmest cremet, og der er masser af kompleksitet med modne frugter, blommer, nødder, sauternes og vanilje. Super spændende udgivelse i den velkendte, søde A.H. Riise/Old St. Croix stil, men dog anderledes qua sauterne-noterne fra fadene. Leveres i gaveæske. Alkohol %: 42,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H.Riise XO 175th Anniversary', 'https://spitus.dk/product/a-h-riise-xo-175th-anniversary/', 425, false, 70, 42, 'https://spitus.dk/wp-content/uploads/2020/12/100302-1-A.H.Riise-XO-175th-Anniversary.jpg', 'A.H. Riise XO 175th Anniversary blev fremstillet første gang i 2013 &#8211; præcis 175 år efter A.H. Riise for første gang slog dørene op til sit apotek på St. Thomas. 175 Years Anniversary er en hyldest til fortiden, men også en toast til fremtiden – en rom, der kombinerer tradition med innovation. Der er tale om en særlig jubilæumsmodel, hvor hovedblended er lagret i 21 år, men tilsat yngre destillater for at øge spændstigheden. A.H Riise XO 175th Anniversary er lagret ved lave temperaturer og høj luftfugtighed i dybe mørke kældre, hvor den har haft de bedste betingelser for en god spirit drink. Det specielle ved denne jubilæums-udgivelse er, at den efterlagres på PX- og Oloroso-sherryfade. Netop disse fade giver drikken sit udtryk af mørk, sødmefuld sherry. I næsen og ganen er sherry-noterne tydelige, og du får dertil fyldig vanilje og karamel. Skovbær og figner kommer tydeligst frem i den lange, cremede eftersmag. Som altid med A.H. Riise og Old St. Croix er der tale om en sød spirit drink. En let tilgængelig stil som danskerne i den grad har taget til sig. Leveres i flot gaveæske. Alkohol % : 42,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Thin Blue Line', 'https://spitus.dk/product/a-h-riise-xo-thin-blue-line/', 439, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/02/100338-1-A.H.-Riise-Thin-blue-line.jpg', 'A.H. Riise The Thin Blue Line Denmark er en helt særlig udgave af A.H. Riises X.O. Reserve. Det er et blend af førsteklasses rom fra Vestindien og Centralamerika, hvor destillaterne , der skaber det velsmagende ravfarvede guld, ikke er under 7 år, og nogle er helt op til 21 år gamle. I munden er der vanilje, honning, eksotiske krydderier, læder, lakrids og mild, sødlig tobak. I den lange eftersmag fortsætter noterne og indtrykkene, og det hele lukker med dejlig mørk chokolade og modne blommer. A.H. Riise The Thin Blue Line Denmark er samtidig en rombaseret spiritus med en mærkesag at støtte. Udgivelsen er nemlig sammensat til ære for- og som støtte til det danske politi. Den specialudviklede dram har taget navn efter den danske Thin Blue Line-forening. Foreningen yder støtte til danske betjente, der har lidt skade på krop eller sjæl i tjenesten. Ved at købe A.H. Riise The Thin Blue Line Denmark støtter du således betjente i Danmark, som har betalt en alt for høj pris for at udføre deres arbejde. Køb dette særlige blend, få en dejlig oplevelse, og støt samtidig politiets og betjentenes arbejde i Danmark. Leveres i gaveæske. Alkohol %: 40,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Royal Danish Navy Strength 55%', 'https://spitus.dk/product/a-h-riise-royal-danish-navy-strength/', 499, true, 70, 55, 'https://spitus.dk/wp-content/uploads/2020/12/100300-1-A.H.-Riise-Royal-Danish-Navy-Strength.jpg', 'A.H. Riise Royal Danish Navy Strength er hånd-blended af flere, op til 20 år gamle rom af typen ”Vedderburn og Plummer” &#8211; melassebaseret rom, der kendetegnes ved langsom gæring og Pot-still destilleret op til 85% alkohol styrke inden nedvandingen. Den er ikke koldfiltreret eller tilsat karamel. Den deler gener med den traditionelle A.H. Riise Royal Danish Navy, men her er den altså i ”Strength-udgaven”, hvilket betyder 55% istf. 40% alkohol. Den højere alkoholprocent giver bestemt et større bid, men smagene og stilen er de samme som udgaven med 40%. A.H. Riise Royal Danish Navy Strength har i næsen karamel, cedertræ, appelsiner og lakrids. I ganen cremet med karamel, eksotiske krydderier, sherry, appelsin og chokolade. Sødmefuld eftersmag, med mange af de samme elementer som umiddelbart i ganen, men der er også et twist af mynte og eukalyptus. Den højere alkoholprocent mærkes, men der er på ingen måde tale om et sprittet udtryk, og faktisk har vi i en blindsmagning svært ved at stadfæste at der er tale om en ”Navy Strength”. Er du til spiritus i den søde stil, og gerne vil have et lille ekstra bid og varme fra den højere alkohol, er A.H. Riise Royal Danish Navy Strength et af de meste populære produkter overhovedet. Flot flaske og gaveæske. Alkohol %: 55,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Reserve Port Cask Rum 45%', 'https://spitus.dk/product/a-h-riise-xo-reserve-port-cask-rum/', 449, true, 70, 45, 'https://spitus.dk/wp-content/uploads/2025/12/AHR-port-cask.png', 'A.H. Riise XO Reserve Port Cask er sammensat af nogle af de bedste og ældste fade fra Vestindien og Centralamerika som destilleriet råder over. Faktisk går der helt op mod 15 forskellige romdestillater til denne rombaserede spiritus. Og med en gennemsnitsalder på 20 år er det ikke ligefrem en vårhare. Alle destillater er nøje udvalg af A.H. Riise’s masterblender og skaber en dram udover det sædvanlige. Den nænsomme lagring og sammensætning gør i sig selv A.H. Riise X.O. Port Cask til noget særligt. Men for at gøre oplevelsen endnu større, er den efterlagret på udsøgte fade, der tidligere har været hjem for klassisk portvin. Den får nemlig en slut-lagring på mindst seks måneder på portvinsfade fra det kendte hus Cálem. Det giver en unik fadfinish, der gør denne udgivelse til noget særligt, med stor kompleksitet og fylde. Hvert fad er specielt udvalgt og håndaftappet enkeltvis. Produktionstallet er begrænset, og alle flaskerne er desuden mærket med et individuelt flaske- og fadnummer samt aftapningsdato. Når du åbner flasken, mødes du af en bouquet, der er som en kærlighedserklæring fra både Caribien og Douro-dalen. Tænk tørret frugt, modne bær, et strejf af chokolade og den der varme, vinøse sødme, som kun portvin kan levere. Det er som at få en krammer af både solen og en vinbonde på samme tid. XO Reserve betyder, at vi er i den modne afdeling. Ingen ungdommelige kanonslag – men en dram, der har fundet sin ro og besluttet sig for at blive voksen på den lækre måde. Port Cask-finishen giver den et ekstra lag af kompleksitet, som gør, at du næsten får lyst til at tage noter, mens du smager. Men bare rolig – du behøver ikke være sommelier for at nyde den. Smagen? Rund, fyldig og med en sødme, der balancerer perfekt med krydderier og egetræ. Den starter blødt, bygger op med bær og chokolade, og slutter med en lang, elegant eftersmag, der hænger ved som en god punchline. Det er den slags oplevelser, der får dig til at tænke: “Hvorfor drikker jeg egentlig andet?” Flasken? Den ser ud som noget, du ville finde i en hemmelig kælder under et portugisisk slot – tung, elegant. Perfekt til gave, til gæster eller til dig selv, når du vil forkæle din indre livsnyder. A.H. Riise XO Reserve Port Cask er ikke bare en flaske spiritus – det er en rejse mellem kontinenter, en fusion af tradition og tropisk livsglæde. Den er til dig, der vil have mere end bare spiritus i glasset. Den er til dig, der vil have historier, smagslag og et strejf af luksus. I flot gaveæske. Alkohol % : 45,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise XO Royal Reserve Kong Haakon', 'https://spitus.dk/product/a-h-riise-xo-royal-reserve-kong-haakon/', 499, false, 70, 42, 'https://spitus.dk/wp-content/uploads/2020/12/a.h.-riise-xo-haakon-royal-reserve-med-gaveaeske-k.png', 'Inden Kong Haakon den 7. af Norge i 1905 blev kronet som konge, havde han titel og opvækst som Prins Carl af Danmark. Han gjorde karriere i Den Kongelige Danske Flåde. Siden førte hans karriere ham til tjeneste på Fregatten Jylland. På et tidspunkt anløb Fregatten Jylland og den unge prins De Vestindiske Øer. Her mødte han Valdemar Riise, søn af A.H. Riise. Deres møde førte til venskab, og de erfarede, at de begge havde gensidig interesse for god, vellagret kvalitetsrom. Denne fine aftapning, A.H. Riise Kong Haakon X.O. Royal Reserve, hylder både venskabet mellem disse 2 mænd, og mødet over en velskænket dram. Den står rankt, værdigt og med en elegance, der får dig til at overveje at tiltale flasken med “Deres Majestæt”. A.H. Riise Kong Haakon X.O. Royal Reserve er genskabt med inspiration efter den originale opskrift. Netop denne udgivelse var efter sigende Kong Haakons absolutte favorit. Der er tale om en herlig blend i den elskede A.H. Riise stil. Dyb, fyldig, sød og med masser af tropiske frugter; primært appelsiner, mango og papaya. Dejlig fløjlsblød tekstur med vanilje, honning og tørrede rosiner, samt et snert af portvin. Lang eftersmag med masser af sødme og velintegreret velsmag. Den ankommer med kongelig eskorteføring, sætter sig i din hjemmebar og siger: “Du må gerne kysse ringen.” A.H. Riise er kendt for at lave flasker, der er så bløde og aromatiske, at selv folk, der normalt drikker øl, pludselig begynder at tale om fadlagring og aromaer. A.H. Riise Kong Haakon X.O. Royal Reserve er en ægte kongelig, vestindisk rombaseret spiritus der får dig til at rette ryggen, pudse kronen og føle dig som en del af kongehuset. Levers i flot gaveæske. Alkohol % : 42,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('A.H. Riise Non Plus Ultra Very Rare', 'https://spitus.dk/product/a-h-riise-non-plus-ultra/', 798, true, 70, 42, 'https://spitus.dk/wp-content/uploads/2020/12/ah-riise-non-plus-ultra-very-rare-old-st-croix.png', 'A.H. Riise Non Plus Ultra Very Rare er mærkets &#8220;Ultra Premium Product&#8221;, der fuldender A. H. Riise sortimentet. Begrebet, &#8220;Non Plus Ultra&#8221;, stammer fra Herkules&#8217; Søjler, der, ifølge den romerske mytologi, blev bygget nær Gibraltarstrædet og markerede grænsen af den kendte verden. Søjlerne bar skriften, &#8220;Non Plus Ultra&#8221; (Latinsk for: Nothing Further Beyond), som en advarsel til søfarende om ikke at fortsætte sejladsen ud i det ukendte. Denne A. H. Riise rom lever fuldt op til sit navn. Non Plus Ultra er håndblendet af deres Master Blender, som personligt udvælger hvert fad, der indgår i det færdige produkt. Farven på A.H Riise Non Plus Ultra er mørk maghoni. I næsen er der en elegant krydret bouquet af appelsin, egetræ, vanilje, tobak og rosiner. I munden får du sherrynoter, appelsin, karamel, vanilje og egetræ. Det hele lukker i en flot finish, der efterlader et sødmefuldt velbehag. Spirits drinks fra Albert Heinrich Riis er søde i stilen, og danskerne er vilde med dem! De ligger konstant i toppen af listen over ”mest solgte”. Er du fan af sødt, rombaseret spiritus eller rom, bliver det ikke bedre end dette! A.H. Riise Non Plus Ultra er en drik, der udgives i begrænsede mængder, da der kun bliver aftappet 2.000 flasker om året. Flasken ligner en million (cirka), og leveres i en flot gavekasse, der matcher. Størrelse : 70 cl Alkohol % : 42,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Diplomatico Mantuano Ron Extra Anejo', 'https://spitus.dk/product/diplomatico-mantuano-ron-extra-anejo/', 245, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/11/diplomatico-mantuano-ron-extra-anejo-k.jpg', 'Diplomático Mantuano – Den venezuelanske smooth‑bandit. Diplomático Mantuano Ron Extra Añejo er rommen, der leverer seriøs kvalitet uden at gøre et stort nummer ud af sig selv. Den er mørk, rund og uimodståeligt smooth – præcis den type rom, der får dig til at hælde et glas mere op, før du overhovedet opdager det. Diplomático Mantuano er lagret på brugte bourbon-fade. Den er en anelse mere krydret og tør end sit verdensberømte og storsælgende familiemedlem; Diplomático Reserva Exclusiva. I næsen får du chokolade, figner, abrikos og krydderier. I munden ret kompleks, med tørrede frugter, vanilje, honning, en mild trævarme og masser af krydderier. Sød og meget behagelig mundfølelse. Pæn afslutning med blommer, krydderier og kandiserede frugter. Perfekt til ren nydelse, old fashioned‑agtige cocktails eller som den faste flaske i hjemmebaren, der aldrig skuffer. Diplomático Mantuano: En ægte gentleman-bandit med latinamerikansk charme. Diplomatico Rum har vundet mere end 54 medaljer ved internationale konkurrencer, såsom SIP Awards, San Francisco World Spirits, Miami Rum XP, Monde Selection samt mange andre internationale konkurrencer. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hunter Laing Kill Devil Trinidad 13 Years Old Single Cask Rum 2003', 'https://spitus.dk/product/hunter-laing-kill-devil-trinidad-13-years-old-single-cask-rum-2003/', 649, false, 70, 46, 'https://spitus.dk/wp-content/uploads/2020/11/hunter-laing-kill-devil-trinidad-13y-k.jpg', 'Hunter Laing, kendt for whisky af høj kvalitet, har udvalgt en række single casks/fade fra de bedste destillerier i primært Caribien, sendt dem til Skotland for efterlagring, og derefter håndtappet i flasker, ofte ved fadstyrke. Serien kalder de ”Kill Devil” – navnet som øboerne oprindeligt gav deres forskellige destillater. Der justeres ikke på smagen med f.eks. karamel eller sukker, og det der er i tønden, er det du får i flasken. Der er tale om ret vilde oplevelser, hvor der virkelig er smæk på smagsindtrykkene og alkoholen. En super spændende, og stærkt eftertragtet serie! Her er der tale om et fad destilleret i 2003 i Trinidad. Næsen: masser af vanilje og den typiske mynte. Derefter eukalyptus samt nogle egetræs- og urtetoner, der rydder næsen godt. I ganen mere af det samme, dog ikke helt så markant med vanilje, men en anelse nougat og en del tropiske frugter. Mynten er der stadig, og til sidst er der mango og lidt krydderi. Voldsom og solid rom, hvor der i alt kun er tappet 373 flasker. Leveres i gaverør til Danmarks laveste pris. Størrelse : 70 cl Alkohol % : 46,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hunter Laing Kill Devil Guyana 8 Years Old Single Cask Rum 2008', 'https://spitus.dk/product/hunter-laing-kill-devil-guyana-8-years-old-single-cask-rum-2008/', 799, false, 70, 59.3, 'https://spitus.dk/wp-content/uploads/2020/11/hunter-laing-kill-devil-guyana-8-years-old-single-cask-rum-2008-k.jpg', 'Hunter Laing, kendt for whisky af høj kvalitet, har udvalgt en række single casks/fade fra de bedste destillerier i primært Caribien, sendt dem til Skotland for efterlagring, og derefter håndtappet i flasker, ofte ved fadstyrke. Serien kalder de ”Kill Devil” – navnet som øboerne oprindeligt gav deres forskellige destillater. Der justeres ikke på smagen med f.eks. karamel eller sukker, og det der er i tønden, er det du får i flasken. Der er tale om ret vilde oplevelser, hvor der virkelig er smæk på smagsindtrykkene og alkoholen. En super spændende, og stærkt eftertragtet serie! Her præsenterer vi en fabelagtig rom destilleret i 2008 på det ikoniske Port Mourant pot-still af træ. Næsen er rå, men alligevel ikke decideret ung i sit udtryk. I ganen masser af frugter; pærer, abrikoser og kandiserede æbler. Fine træ-noter, karamel, lyng og herlig sødmefuld honning. En temmelig vild kombination, og det viser meget godt hvad Port Mourant kan gøre for en rom. Der er dog ikke så meget anis og nelliker, som vi normalt forbinder med PM, men den er til gengæld mere drevet af søde og syrlige frugter. Fortrinligt produkt med respektable 59,3% alkohol tappet i kun 239 flasker! Leveres i gaverør. Størrelse : 70 cl Alkohol % : 59,3');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hunter Laing Kill Devil Guatemala 9 Years Old Single Cask Rum 2007', 'https://spitus.dk/product/hunter-laing-kill-devil-guatemala-9-years-old-single-cask-rum-2007/', 799, false, 70, NULL, 'https://spitus.dk/wp-content/uploads/2020/11/hunter-laing-kill-devil-guatemala-9-years-old-single-cask-rum-2007-k.jpg', 'Hunter Laing, kendt for whisky af høj kvalitet, har udvalgt en række single casks/fade fra de bedste destillerier i primært Caribien, sendt dem til Skotland for efterlagring, og derefter håndtappet i flasker, ofte ved fadstyrke. Serien kalder de ”Kill Devil” – navnet som øboerne oprindeligt gav deres forskellige destillater. Der justeres ikke på smagen med f.eks. karamel eller sukker, og det der er i tønden, er det du får i flasken. Der er tale om ret vilde oplevelser, hvor der virkelig er smæk på smagsindtrykkene og alkoholen. En super spændende, og stærkt eftertragtet serie! Dette fad er en 9-årig rom fra Darsa-destilleriet i Guatemala, destilleret i juli 2007 og aftappet af Hunter Laing i 2016. I fadet var der rom til i alt 322 flasker. I næsen er der sød karamel, og fyldige krydderier, men faktisk også noter af friske grønne frugter. I munden er den ekstremt fyldig, med fudge, demerara sødme, dadler og en del krydderi. Konsistensen er cremet, og krydderierne og kokosnødderne giver en herlig prikken. Dejlig balance, og super crispy og sødmefuld finish. Leveres til en ekstrem lav pris på Spitus.dk i et tilhørende gaverør. Størrelse : 70 cl Alkohol %: 46,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Hunter Laing Kill Devil Guyana 12 Years Old Single Cask Rum 2004', 'https://spitus.dk/product/hunter-laing-kill-devil-guyana-12-years-old-single-cask-rum-2004/', 1099, true, 70, 61.1, 'https://spitus.dk/wp-content/uploads/2020/11/kill-devil-single-cask-rum-guyana-12-years-k.jpg', 'Hunter Laing, kendt for whisky af høj kvalitet, har udvalgt en række single casks/fade fra de bedste destillerier i primært Caribien, sendt dem til Skotland for efterlagring, og derefter håndtappet i flasker, ofte ved fadstyrke. Serien kalder de ”Kill Devil” – navnet som øboerne oprindeligt gav deres forskellige destillater. Der justeres ikke på smagen med f.eks. karamel eller sukker, og det der er i tønden, er det du får i flasken. Der er tale om ret vilde oplevelser, hvor der virkelig er smæk på smagsindtrykkene og alkoholen. En super spændende, og stærkt eftertragtet serie! Denne 12 års rom blev destilleret af Diamond (Versailles) destilleriet i Guyana i 2004, og derefter uafhængigt aftappet ved fadstyrke (61,1%) af folkene hos Hunter Laing i 2016. Tønden gav kun 246 flasker, så det er stærkt begrænset hvor mange der endnu findes. Næse og mund er ret typiske for Diamond/Guyana, og der er falafel, forskellige træsorter, lakrids og stor cremet sødme. Du møder også modne frugter, og en anelse lime der prikker herligt i ganen. Der er smæk på indtrykkene, og den ender tørt med træ og en anelse citrus. Leveres i gaverør. Størrelse : 70 cl Alkohol % : 61,1');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Matusalem 10 Y.O. Clasico', 'https://spitus.dk/product/matusalem-10-y-o-clasico/', 209, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/10/Matusalem-Clasico-100290-1.jpg', 'Matusalem Clasico 10 års Solera er en klassisk fadlagret, mørk rom, som tager sig godt ud i mange forskellige drinks. Det er et godt valg, hvis man vil rykke op fra de billige rom, men samtidig ikke agter at tømme hele kontoen. ”Mange drikker f.eks. Captain Morgan i sin rom &amp; cola, uden at vide at Matusalem 10 Classico er klasser bedre. Man får meget mere for pengene med Matusalem 10 års, som tager dig med på en ægte smagsrejse ”, Citat: Mads ”Romhatten” Heitmann. Matusalem Clasico 10 års har en dyb kobber/honningbrun farve. En varm og cremet duft af vanilje, abrikoser, blommer, sirup og karamel. I munden primært toffe og vanilje. Ikke så rund og kompleks, som dens storebror, og med en anelse sprit, som dog fordufter efter lidt tid. Ingen, eller kun meget begrænset sukkerindhold. VinAvisen – 5 stjerner – “En god mørk rom med en typisk duft af sukkerrør og karamel med et strejf af vanilje.” (Uge 5 / 2014) Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Matusalem 15 Y.O. Gran Reserva', 'https://spitus.dk/product/matusalem-15-y-o-gran-reserva/', 255, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/11/Matusalem-15-Y.O.-Gran-Reserva-100291-1.jpg', 'Kendt som &#8220;The cognac of rums&#8221;, er denne Ron Matusalem Gran Reserva 15 års solera rom det perfekte valg for dem, der søger en enestående og sofistikeret rom. Matusalem Gran Reserva 15 har en klar, dyb gylden farve med skinnende røde og ravfarvede reflekser. Dejlig duft af vanilje, mørk farin, karamel, blommer og abrikoser. Delikat og fløjlsblød smag med en fantastisk vifte af aromaer omkring en kerne af vanilje og karamel. Flot lang eftersmag med ristede noter fra fadlagringen. Vi synes ikke der meget cognac over denne rom, men den besidder en vis tørhed, så måske derfra dens kælenavn er opstået. Matusalem Gran Reserva 15 er en dejlig allround rom, ideel til at drikke rent eller naturligvis med is. Kåret til ”Best Buy” i Ekstra Bladets test med teksten: ”Produktionen af denne rom startede for 130 år siden i Santiago på Cuba. Siden er den blevet kaldt Rommens Cognac. Duft af tørrede tropiske frugter og en tør smag af fersken, nødder, karamel. En rigtig flot rom i den tørre stil til en god pris”. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Matusalem Gran Reserva 23 Y.O', 'https://spitus.dk/product/matusalem-gran-reserva-23-y-o/', 469, false, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/11/matusalem-23-yo.gaveaeske-k.png', 'Matusalem Gran Reserva 23 Solera er en super premium rom fra øverste hylde! Farven er dyb rav, med nuancer af orange og kobber. I næsen får du en raffineret note af tørret frugt samt en ristet og sødmefyldt duft a’la honning og mandler. Derudover en snert af noget floral som magnolia og mandelblomster. En bund af karamel med toner af mango, hvid chokolade og mandler. I munden er yderst elegant og smooth. Igen får du ristede mandler, toner af hasselnød samt et pift af lakrids. Frugt- og blomstertonerne går også igen, med mango, fersken og karamel . Eftersmagen er ret kompleks, og med en enorm længde med sherry-noter. Fantastisk! I forhold til 15-års udgaven, er den klar mere voluminøs, men også mindre sprittet. Mads ”Romhatten” Heitmann: ”Endnu engang har Matusalem æstetikken i højsædet, både i smag, men i særdeleshed også i den fysiske indpakning. Ligesom med Matusalem 15 års er 23&#8217;erens flaske noget for sig og gør helt igennem smagsoplevelsen til en af de store. Yderst delikat rom!” Størrelse : 70cl Alkohol % : 40,0 Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Chairman&#8217;s Reserve', 'https://spitus.dk/product/chairmans-reserve/', 285, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/100188-1.jpg', 'Chairman&#8217;s Reserve Original Rum blev først produceret i 1999, under skarp overvågning af daværende formand, Laurie Barnard, som et specielt projekt og med det formål, at skabe en fin kvalitetsrom, der kan repræsentere den ikoniske stil af St. Lucia rom. Den er lavet af udvalgte rom, der er destilleret på både en Coffey kolonne og gamle kobber-pot apparater, der efter modning i gamle bourbonfade fra Jim Beam, Jack Daniel’s og Buffalo Trace, blendes og derefter igen lagres på egefade. St. Lucia rom er kendte for dens harmoniske velafrundede finesse og stil med enorm karakter. Den lette alkohol fra kolonnen supplerer pot still-rommen fantastisk godt. Farven er flot mørk rav. Næsen giver dig tydelige frugter, egetræ og krydret vanilje. Honning supplerer fint duftindtrykket. I munden går vanilje og egetræ igen, men der er også rosiner og en dejlig fornemmelse af alkohol. Meget velproduceret og velafstemt. Mads &#8220;Romhatten&#8221; Heitmann: ”Efter at have anmeldt en række rom i den meget dyre ende, så synes jeg, at det er blevet tid til nogle såkaldte “best buys”&#8230; altså nogle flasker, hvor man får meget rom for pengene. Den første i rækken af mine “god til prisen” anmeldelser&#8230;&#8230;.., er naturligvis fra en af mine yndlingsproducenter, nemlig St. Lucia Distillers. Rommen er ikke vildt sød som sådan, da der ikke er tilsat sukker, men alligevel er den meget flot balanceret og rummer en del sødmelignende elementer, som gør en forholdsvis ung rom drikkevenlig. Vanilje, tropiske frugter og honning. Her får du meget rom for pengene! Som tidligere skrevet; en fantastisk hverdagsrom, som både kan drikkes rent og som ligeledes er fabelagtig i longdrinks og cocktails.” Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Chairman&#8217;s Reserve Spiced', 'https://spitus.dk/product/chairmans-reserve-spiced/', 245, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/100190-1.jpg', 'Chairmans Reserve Spiced. Det er langt fra altid, vi bifalder at ”spice” en allerede fremragende rom op med flere krydderier. Men med St. Lucia Destillers udgave må vi bøje os i støvet og acceptere, at det er godt håndværk med høj, høj kvalitet. Rommen fra St. Lucia er altid blandt de absolut bedste value-for-money rom, og de har høstet masser af internationale medaljer (da de i 2013 talte deres præmier, havde de samlet 209 internationale anerkendelser, heraf 79 guldmedaljer for deres rom!) og er sågar blevet kåret til verdens bedste romdestilleri. St. Lucia rom er så ren som det næsten er muligt. Udover lidt karamel for farvens skyld tilsættes intet andet. Ingen sukker, likør, brandy, sherry eller andre svinkeærinder. St. Lucia Rum Chairmans Reserve Spiced er fremstillet ligesom den almindelige Chairmans Reserve, men den er krydret med lokale krydderier og frugt &#8211; heriblandt kanel, nelliker, muskat, vanilje, kokos, lemon, appelsin og det lokale afrodisiakum, bois bande (en lokal træsort). En dyb rødlig, næsten mahogni-lignende, farve. Næsen afslører alt, hvad flasken siger, den er infuseret med. Den har en ganske tydelig kanelnote forrest på tungen, og der er lidt vanilje, nelliker og muskatnød, men ikke meget. Dette er ikke en vanilje-tung krydret rom, modsat mange andre i samme kategori. Den fylder ganen godt ud, og er du til kanel og muskatnød, er dette flasken, du har længtes efter! I modsætning til en del andre krydrede rom, er den rom, som danner basen (nemlig standard Chairmans Reserve) allerede en fremragende rom og ikke et eller andet billigt produkt, der forsøges skjult med en masse krydderier. Der destilleres i fire forskellige kedler – tre pottstills og én kolonnekedel. Rommen ændrer profil afhængig af hvilke kedler, der bruges. St. Lucia Distillers lagrer deres rom på amerikanske 200 ltrs egetræsfade, som tidligere har huset whisky. Når man lagrer spiritus i troperne, sker modningen med en hastighed, der er omkring 2 ½ gang hurtigere, end hvad der er tilfældet her i Europa. Dette skyldes den højere temperatur og luftfugtighed. Rom med en alder over 10 år er derfor ofte meget træede og tanninholdige, og derfor blender man på St. Lucia (næsten) altid gamle fade med nyere fade, så der kommer en fin balance i blendet. Af samme årsag skriver man heller ikke alder på rommen. Se evt. mere under Chaimans Reserve her på siden! Ganske imponerende var det den eneste krydret eller aromatiserede rom, der modtog en guldmedalje ved International Spirits Challenge 2013. Du modtager den i en flot gaveæske. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Plantation 3 Stars', 'https://spitus.dk/product/plantation-3-stars-412-70-cl/', 199, false, 70, 41.2, 'https://spitus.dk/wp-content/uploads/2020/06/100182-1.jpg', 'Plantation 3 Stars er en blanding af rom fra de 3 stjerner i den caribiske romproduktion: Barbados, Trinidad og Jamaica – deraf navnet. Blandingen består af ulagret Barbados-rom, 2-3 år gammel Trinidad-rom, ulagret Jamaica-rom og et touch af 10 år gammel Jamaica-rom, som giver en dybde i smagen, man sjældent finder i ”cocktailrom”. Den let modnede Trinidad rom giver den klassiske elegance, Barbados leverer sofistikationen med en afbalanceret fornemmelse i munden og Jamaica formidler sin umiskendelige struktur og rustikke kant. Farven er klar med et svagt gyldent skær, i næsen er der vanilje, nellike og banan og i munden er der tropiske frugter og en fin sødme. Der er tale om en prisbillig rom, som er beregnet til at mixe og anvende i cocktails. Det job gør den bedre end stort set alle andre, og blandt andet er den decideret fremragende i daiquiri. Den fortjener en plads i alle barskabe. Størrelse : 70cl Alkohol % : 41,2');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Plantation 5 Y.O. Grande Reserve', 'https://spitus.dk/product/plantation-5-y-o-grande-reserve/', 279, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/10/Plantation-5-Y.O.-Grande-Reserve-100293-1.jpg', 'Plantation Grande Reserve 5 Years er en klassisk Barbados-rom &#8211; men med et twist. Gæringen er lavet på sukkerrørssaft, som har gæret i 3-5 dage for derefter at blive destilleret. Dernæst ligger rommen på bourbonfade i Caribien i mellem 3 og 4 år, før den krydser Atlanterhavet til Chateau Bonbonnet i Frankrig. Dér fortsætter rommen sin modning i 1-2 år i kontinentalt klima på små egetræsfade, som primært har indeholdt Pierre Ferrand cognac. Til sidst bliver rommen blandet for at opnå den ønskede smagsprofil, vandet ned til 40% abv og tappet på flaske. Plantation Grande Reserve 5 Years har en smuk ravguld farve. I næsen er der farin, Barbados-kokos, brændte mandler og sød pibetobak. Munden rammes af mørk chokolade, banan, brunkager, rosiner og vanilje. I eftersmagen fortsætter noterne, og chokoladen bliver meget tydeligt i slutningen. Rigtig meget rom for pengene, men hvis man er til ultra-søde rom, er der bedre flasker derude. Vi anbefaler den til romdrikkere, der gerne vil prøve en mere ”tør” rom end de mange søde spansk-inspirerede kolonne-rom . Hvis den ikke falder i din smag, selv efter der er prøvet med isterninger, er den ikke dyrere end at det går an at mikse cocktails og drinks med den. Det er den nemlig fantastisk til. Men de fleste synes det er synd, og drikker den rent. 😉 En af verdens mest solgte rom &#8211; og det er fuld fortjent. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Plantation Gran Anejo', 'https://spitus.dk/product/plantation-gran-anejo/', 289, false, 70, 42, 'https://spitus.dk/wp-content/uploads/2020/10/plantation-grande-anejo.jpg', 'Maison Ferrand, med spiritus-guruen Alexandre Gabriel i front, er firmaet bag nogle af de mest succesrige cognac, rom og ginner. Under paraplyen findes blandt andet Pierre Ferrand Cognac, Plantation Rum, Citadelle Gin, Kaniché rom og Claude Chatelier Cognac &#8211; samt en række eksklusive likører mv. Plantation Rum har gået deres sejrsgang over hele verden. Præcis som de fleste af de projekter Alexandre Gabriel kaster sig over. Uanset prisklasse eller produktvariant, er der tårnhøje krav og forventninger til kvalitet og godt håndværk. Heldigvis kan det smages i flaskerne! Denne Plantation Grande Anejo er naturligvis ingen undtagelse. Der er tale om et blend sammensat af et destillat lagret 3 år på nye Bourbon-fade i Guatemala, og et 4-6-årig blend fra Belize også på Bourbon-fade. Derefter får den min. 1 år i kældrene på cognac-fade i Frankrig hos Maison Ferrand . Der destilleres i klassiske pot-stills, og der er tale om en rom i den spanske stil. Det vil sige blød, fyldig, aromatisk og sødlig. Farven er gylden kobber. I næsen er der mandler, sherry, ristet eg og karamel, men også lidt mørkere krydderier. I munden er den cremet og sødmefuld, med akaciehonning, gammel portvin, lakrids og en del noter fra fadene. I den lange eftersmag kommer der mørke krydderier, muskatnød og et svagt touch af sødlig tobak. Bestemt en ”crowdpleaser” hvor alle kan være med, men samtidig kvalitet og dybde nok til at kendere må bukke sig i støvet for resultatet af godt håndværk. Vi tror, at den omfattende og dyre fadlagring har en stor del af æren for, at Plantation Grande Anejo er meget mere end blot endnu en sød rom fra Caribien. Vi leverer den til en skarp pris i en eksklusiv gaveæske. Størrelse : 70cl Alkohol % : 42,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Plantation Rum Isle of Fiji', 'https://spitus.dk/product/plantation-rum-isle-of-fiji/', 288, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/11/plantation-isle-of-fiji.jpg', 'Plantation Isle of Fiji er rommen, der smager som en ferie, du ikke har fået endnu. Den er lavet på Fiji, hvor sukkerrørene får sol, regn og vulkansk jord nok til at blive ekstra lækre – og det kan man smage. I næsen er den funky (men ikke så vild som Jamaica-rom), krydret og eksotisk. Smagen er fyldig, frugtig og eksotisk med noter af banan, kokos, vanilje, karamel og et strejf af krydderi. Det hele er pakket ind i den klassiske Plantation‑stil: blød, rund og farligt drikkevenlig. Det er rommen, du hiver frem, når du vil have noget, der både er sjovt, smagfuldt og lidt anderledes end de sædvanlige Caribiske flasker. Isle of Fiji: En flybillet til Stillehavet – bare billigere og i 70 cl. Rommen er sammensat af blends destilleret på både pot stills og kolonner, og den er primært/indledningsvist lagret på bourbonfade i troperne, for så at få Plantations karakteristiske ”finish” på cognac-fade i Frankrig. Meget potent, flot og absolut fyldig stil. Fin sødme, uden det på nogen måde tager overhånd. En tæmmet jamaicaner, der har charmen og varmen fra en Ø i Stillehavet. Herligt bekendtskab fra dette populære destilleri, som bare bliver ved med at udgive eminente flasker, der får mundvandet til at løbe! Kan nydes rent eller i cocktails. Alkohol % : 40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Plantation Xaymaca rom', 'https://spitus.dk/product/plantation-xaymaca/', 279, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2021/02/plantation-xaymaca.jpg', 'Maison Ferrand, med spiritus-guruen Alexandre Gabriel i front, er firmaet bag nogle af de mest succesrige cognac, rom og gins. Under paraplyen findes blandt andet Pierre Ferrand Cognac, Plantation Rum, Citadelle Gin, Kaniché rom og Claude Chatelier Cognac samt en række eksklusive likører mv. Deres Plantation Rum har gået deres sejrsgang over hele verden. Præcis som de fleste af de projekter Alexandre Gabriel kaster sig over. Uanset prisklasse eller produktvariant, er der tårnhøje krav og forventninger til kvalitet og godt håndværk. Heldigvis kan det smages i flaskerne! At Maison Ferrand nu udgiver en vaskeægte Jamaica-rom overrasker ikke, da de har købt 1/3 af ”National Rums of Jamaica Limited”, som bl.a. ejer Long Pond Distillery og Clarendon Distillery. Derfor er Plantation Xaymaca et blend fra disse to destillerier. ”Xaymaca” lyder næsten som ”Jamaica” i udtale, og er da også det gamle ord for netop disse øer. Direkte oversat betyder det ”Land of Wood and Water”, hvilket må siges at passe meget godt. Som flere andre rom fra Plantation, udnytter de adgangen til førsteklasses cognac-fade og lagringsbetingelser hos Maison Ferrand i Frankrig. Den får ca. 3 år på brugte bourbon-fade i Jamaica, og til sidst ca. 1 år på brugte cognac-fade i Frankrig. Destillatet er rent pot still rom, men for at øge kompleksiteten yderligere, iblandes der en andel af 17-år gammel Jamaica-rom. Der tilsættes ikke sukker overhovedet. Det er således en af de få Plantation‑rom, der er 100 % tør og uden dosage, hvilket gør den til en favorit blandt romnørder, der vil have ægte jamaicansk pot still‑stil. Farven er gyldent rav. I næsen er der fuld smæk på Jamaica-noterne med banan og ristede ananas, appelsiner og overmodne tropiske frugter. I munden er den mørkere og tungere end man ville forvente, alderen taget i betragtning. Dette skyldes muligvis det tilsatte 17-år gamle rom. Den er sødmefuld (selvom der ikke er tilsat sukker), med kokos, abrikos og allehånde. Dertil en let syrlighed fra modne appelsiner. Mads ”Romhatten” Heitmann skriver i hans anmeldelse af rommen: ”Det er et harmonisk glas rom, det er sammenhængende og helstøbt, og så smager det bare god. Ikke så meget fis.”. Det har vi ingen mulighed for at udtrykke bedre. Størrelse : 70cl Alkohol % : 43,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Serum Elixir', 'https://spitus.dk/product/serum-elexir/', 295, true, 70, 35, 'https://spitus.dk/wp-content/uploads/2020/08/serum-elixir-k.png', 'Serum Elixir er kendetegnet ved en stor ”smoothness”, og udpræget grad af honning og frugter &#8211; med tydelige ferskner, kanel og mandler. Serum Elixir har en mørk rav-lignende farve. Duften emmer af dejlig honning, ferskner, mandler samt kanel. Smagen er fløjlsagtig med sødme, blommer, vanilje, mandel, cookies samt krydderier. Den er rund og meget tilforladelig, med en rig smag af frugter og urter. Den føles tyktflydende, og den fylder munden og ganen godt ud, med en dejlig eftersmag af honning, kokus og krydderier. God value-for-money &#8211; og mange fans i Danmark og andre steder! Til alle dem med hang til sødlig rom! Størrelse : 70 cl Alkohol % : 35,0 Land : Panama');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Serum Ancon, 10 y.o.', 'https://spitus.dk/product/serum-ancon-10-y-o/', 489, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/08/serum-ancon-k.jpg', 'Denne Ancon er opkaldt efter det første skib der passerede Panamakanalen. Det var i 1914 dampskibet Ancon skrev historie ved at blive det første &#8220;søværdige&#8221; fartøj der passerede den nybyggede Panamakanal. I bestyrelsen var velhavende industrialister, kendte statsmænd, rutinerede sejlere og uærlige eventyrsøgende &#8211; alle ivrige efter at være en del af denne epokegørende begivenhed. For at byde disse berømte gæster velkommen, åbnede de panamanske indfødte tønderne med deres mest værdsatte rom – kaldet Serum. Forbløffet over denne flydende &#8220;talisman&#8221;, som oven i det hele endda siges at bringe godt helbred til dem der drikker det, var passagerene og besætningen meget begejstrede, og de kaldte den for &#8220;Ancon&#8221; i hyldest til det skib, som sikkert havde bragt dem til dette fortryllende land. Lige siden da, har rejsende i håb om sikker passage gennem Panamakanalen drukket mindst et glas med Ancon rom – eller sådan siger legenden det i hvert fald… Ancon er en fuldlagret dram &#8211; lagret i hele perioden &#8211; 10 år på brugte bourbonfade. Der er tale om en kolonnedestilleret sag lavet på den bedste friske sukkerørssaft, og lagret i det tropiske klima i Panama. I næsen en rig blanding af vanilje, rosin, figner, dadler, mandler og træ. Ganen er smukt afrundet med et ekstraordinært potpourri af tørrede frugter, egetræ, vanilje og eksotiske krydderier. En ret sød, silkeagtig rom i rigtig god balance og med masser af kraft og kompleksitet fra den lange fadlagring. Størrelse : 70 cl Alkohol % : 40,0 Land : Panama');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Opthimus 15 Años Res Laude', 'https://spitus.dk/product/opthimus-15-anos-res-laude/', 369, true, 70, 38, 'https://spitus.dk/wp-content/uploads/2020/06/100250-1.jpg', 'Denne 15-års version har en meget sødlig duft af nødder og egetræ. Der er ydermere en anelse kokos og dadler, og meget leder tankerne hen på ekstrem dyr portvin. Meget flot og elegant! I munden er der karamel, vanilje og kanel. Generelt smager Opthimus meget ældre (og dyrere) end de reelt er, og deres 15-års udgave er ingen undtagelse. Den kommer godt rundt i munden og ganen, og er bare kvalitet på flaske. Som Mads ”Romhatten ”Heitmann afslutter hans anmeldelse af netop denne version: ”Det er og bliver et formidabelt produkt”. Vi har svært ved at formulere det bedre. Som de andre i serien, leveres den i en eksklusiv flaske og gaveæske, og hos Spitus.dk til Danmarks laveste pris. Størrelse : 70cl Alkohol % : 38,0 Land: Den Dominikanske Republik Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Opthimus 15 Años Malt Whisky Finish', 'https://spitus.dk/product/opthimus-15-y-o-malt-whisky/', 419, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2020/12/100310-1-Opthimus-15Y-Malt-Whisky.jpg', 'Opthimus producerer en serie af fremragende spiritusser, hvor du generelt får meget for pengene. Denne variant er bl.a. lagret på gamle whisky-fade fra Tomatin Destillery. Det giver en unik blanding af fremragende rombaseret spiritus og noter fra whisky. Farve: mørk orange. Aroma: krydrede og frugtagtige noter. Smag: blød sødme af vanilje, moden frugt, karamel og muskatnød. Finish: lang, forførende med en subtil sødme. Opthimus 15YO Malt Whisky Finish er et spændende valg for elskere af klassiske Pot Still-rom. Opthimus&#8217; -udgivelserne har et overvejende indhold af cubansk rom, men også rom fra Trinidad, Pananama, Nicaragua og Colombia. Folkene bag Opthimus ejer ikke selv et destilleri, men har perfektioneret sin spidskompetence &#8211; nemlig at blande nøje udvalgte rom til det bedst mulige resultat. Da firmaet grundlagdes, var det cubanske rom-nørder som var med til at udvælge og sammensætte de opskrifter vi i dag kender som Opthimus Rom. Der er stor prestige i at levere til det store Oliver &amp; Oliver Destillery, som står bag Opthimus. Alkohol %: 43,0 Størrelse: 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Opthimus 21 Años Magna Cum Laude', 'https://spitus.dk/product/opthimus-21-anos-magna-cum-laude/', 649, true, 70, 38, 'https://spitus.dk/wp-content/uploads/2020/06/100251-1.jpg', 'I denne 21-års version (husk det er efter Solera-metoden, så det er det ældste blend i produktet der er mindst 21 år) får du som forventet mere af det hele. Temmelig sød i næsen, i retning af sød og eksklusiv portvin. Vanilje, eg og kokos. I munden siger det slaammm, og du rammes af et fyrværkeri af smagsindtryk. Stadig sødme, men ikke for meget, og det er nærmest tyktflydende nektar af fineste kaliber. Det hele lykkedes her, og der er tale om et virkeligt luksus-produkt fra en producent som om nogen ved og viser hvordan man laver spiritus, hvor der ikke er sammenhæng mellem pris og kvalitet. Det her er alt for billigt ift. de større brands, men det skal vi jo ikke klage over. Vi overlader de sidste ord til Mads ”Romhatten” Heitmann, som i konklusionen skriver: ”Bedømmelse Dette er en rom 21 års solera rom, lavet i den spanske stil, som fx Ron Millonario 15 er det. Der er kun ét at sige, om denne totale luksus-rom og det er at man får en behagelig imødekommende, og ekstravagant Dominikansk spiritus. Den er ekstremt blid og cremet og vil med garanti lande sikkert hos de fleste. Den har en mørkerød fremtoning og smager helt fantastisk. Det er en rom i den sødere ende, men jeg synes ikke, at det bliver for meget på noget tidspunkt. Det er klart en favorit!” Vi siger tak! Naturligvis flot flaske og i gaveæske. Størrelse : 70cl Alkohol % : 38,0 Land: Den Dominikanske Republik');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Opthimus 25 Años Solera Metodo Solera OportO Ron Artesanal', 'https://spitus.dk/product/opthimus-25-anos-solera-metodo-solera-oporto-ron-artesanal/', 695, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2021/03/opthimus-ron-artesanal-oporto-25y.jpg', 'Opthimus 25 Años Oporto er en Dominikansk udgivelse i den absolutte luksusklasse. Opthimus 25 Años Oporto er flasken, der viser, hvad et kvart århundrede i solerasystemet kan gøre. Den lange, tålmodige lagring giver en dybde og modenhed, som kun de færreste kan matche – og portvinsfinishen sætter kronen på værket med en elegant, frugtig sødme. Smagen er intens, mørk og silkeblød med lag af rosiner, brombær, karamel, vanilje, egetræ og et strejf af chokolade. Den både forkæler, overrasker og bliver hængende længe i både glas og hukommelse. Den har efterlagret i ca. 2 år på brugte portvinsfade. Herudover adskiller den sig fra den ”normale” 25-års ved at have 43% alkohol i stedet for 38%. De ekstra 5% gør bestemt rigtig meget godt, og i samspillet med de søde noter fra portvinsfadene, løfter de oplevelsen op på et andet niveau (medmindre du ikke kan lide portvin). Med mindre man udelukkende er til lak og læder, er der ikke andet at gøre end at overgive sig til Opthimus 25 Anös Solera OportO. Eminent flot og gedigen. Mads ”Romhatten” Heitmann er på linje med os, og gav den hele 93 points i hans anmeldelse! Det var tilbage i 2012, hvor han anmeldte den til en pris på 1000kr. Det er den værd, men du slipper billigere her på Spitus.dk! Leveres i gaveæske. Størrelse : 70 cl Alkohol % :43,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Opthimus 25 Años Malt Whisky Finish', 'https://spitus.dk/product/opthimus-25-anos-malt-whisky-finish/', 699, true, 70, 43, 'https://spitus.dk/wp-content/uploads/2020/06/100252-1.jpg', 'I næsen super, super kompleks. Ikke så sød som de ”normale” Opthimus. Man kan sagtens fornemme malten fra whisky-fadene, og det er bare en vanvittigt elegant og behagelig aroma, der spiller eminent sammen med chokolade og egetræ. I munden rammer alkoholstyrken på de 43% dig, men hold da op det matcher den høje kompleksitet. Den er ikke spiritus-skarp, men blød og rund, og en meget behagelig sødme med en lag-efter-lag oplevelse der breder sig i munden. Dette bombardement af velsmag, bliver heldigvis hængende i flere minutter, og selv om vi nødig vil slippe glasset, er det nødvendigt før man er klar til næste slurk. Ikke overraskende, at slutlagringen på whisky-fadene gør en forskel, men vi er ærligt talt overraskede over at det øger kompleksiteten så meget, og at det faktisk ikke er fordi at der er noget decideret whisky-agtig over selve smagen. Det er det hele der går op i en højere enhed her, og når det sker, er det svært at holde glædestårerne tilbage. Vi overgiver os. I en blindsmagning ville vi vurdere denne til at koste langt, langt over det den reelt koster. Ofte er det den anden vej rundt vi bliver overraskede, men her er vi game on. Den er jo ikke billig, men målt mod dem den slår i diverse blindsmagninger og anmeldelser, er den et af de bedste køb ! Opthimus laver naturligvis også en ”almindelig” 25-års udgave, men vi har valgt at tage denne specielle udgave hjem der har finish-lagret på whiskyfade. Årsagen er den simple, at lige netop denne udgave er ret vild. Den almindelige 25-års er god, og en snert bedre end 21-års udgaven, men whisky-versionen her er bare på et andet niveau . Den kan noget mere og noget andet end de andre i serien. 96 points Romhatten.dk Størrelse : 70cl Alkohol % : 43,0 Land: Den Dominikanske Republik Leveres i flot gaveæske');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario Añejo Especial 7 Años', 'https://spitus.dk/product/ron-centenario-anejo-especial-7-anos/', 239, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/100238-1.jpg', 'I lang tid var Costa Rica primært kendt for produktion af kaffe. Men på grund af sin placering mellem Caribien og Atlanterhavet, kan der dyrkes sukkerrør af meget høj kvalitet, som derefter kan destilleres til rom. Centenario Rums har bragt nogle premium-rums på markedet, der nyder stigende popularitet. Generelt er rommene fra Centenario gode bud på rom i den søde stil, hvor du får meget for pengene. Centenario Anejo Especial Solera 7 er resultatet af flere forskellige typer rom, der er lagret på egetræsfade. Her er de opbevaret omhyggeligt for at skabe en moden rom af høj kvalitet med en delikat duft og smag. Rommen er ideel rent med is, men den gør sig ligeledes godt som smagsforstærker i cocktails. Hvis du ynder at nyde en Daiquiri eller Cuba Libre, skal du prøve at mikse drinken med denne Centenario Anejo Especial Solera 7 &#8211; den er som skabt til netop disse 2 drinks. Derover matcher den godt med frisk citrus, kokosnød eller andre tropiske frugter. En ret lys og frugtrig blends af rom, modnet i hvide amerikanske egetræfade. Denne rom har noter af friske røde æbler, presset cider, grøn guavasaft, frisk græs og grøn melon. Finishen har elementer af ananas, honning og cappuccino. Klart i den søde ende af skalen. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario Conmemorativo 9 Years', 'https://spitus.dk/product/ron-centenario-conmemorativo-9-years/', 259, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2021/11/ron-centenario-9-aars-uden-gaveaeske.jpg', 'I lang tid var Costa Rica primært kendt for produktion af kaffe. Men på grund af sin placering mellem Caribien og Atlanterhavet, kan der dyrkes sukkerrør af meget høj kvalitet, som derefter kan destilleres til rom. Centenario Rums har bragt nogle premium-rums på markedet, der nyder stigende popularitet. Generelt er rommene fra Centenario gode bud på rom i den søde stil, hvor du får rigtig meget for pengene. Ron Centenario 9 Års Conmemorativo, er en blanding af fine, lagrede rom, der har modnet på amerikanske egetræsfade der tidligere indeholdt whisky og cognac. Rommen har en afrundet, sød og mild smag af lidt karamel, vanilje og antydninger af frugt, bl.a. æble, kanel og pære. En lille antydning af lakrids i slutningen er med til at give den karakter af en kompleks rom. Ron Centenario 9 Years er rommen, der beviser, at man ikke behøver være gammel for at være lækker. Den er let, sød, rund og fuld af den der “nu skal vi hygge”-energi, som Centenario gør så godt. Smagen er blød og behagelig med noter af karamel, vanilje, let frugtighed og et strejf af egetræ. Ikke tung, ikke kompleks – bare super drikkevenlig og perfekt til både cocktails og ren nydelse. Det er rommen, du hiver frem, når du vil have noget, der er nemt at elske, nemt at dele og nemt at drikke. Centenario 9: Costa Ricas bud på en smooth hverdagsrom med charme. Den kan nydes rent med is, eller i et utal af cocktails. Alkohol % :40,0 Størrelse : 70 cl');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario Gran Legado 12 Años', 'https://spitus.dk/product/ron-centenario-gran-legado-12-anos/', 339, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/100240-1.jpg', 'I lang tid var Costa Rica primært kendt for produktion af kaffe. Men på grund af sin placering mellem Caribien og Atlanterhavet, kan der dyrkes sukkerrør af meget høj kvalitet, som derefter kan destilleres til rom. Centenario Rums har bragt nogle premium-rums på markedet, der nyder stigende popularitet. Generelt er rommene fra Centenario gode bud på rom i den søde stil, hvor du får meget for pengene. Den frugtbare jord og det tropiske klima i Costa Rica byder på de ideelle betingelser for dyrkning af sukkerrør. Ron Centenario Rum Gran Legado 12 Años er i næsen den perfekte blanding af smag af mørk karamel, krydderier og nødder. Disse noter fortsætter i den vidunderlige harmoniske smag, og er understreget i den langvarige finish af egtræsnoter. Ron Centenario har en behagelig sødme med en krop med medium fylde. En meget populær rom, der kvalitetsmæssigt matcher langt dyrere flasker. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario Gran Reserva Solera 25', 'https://spitus.dk/product/ron-centenario-gran-reserva-solera-25/', 669, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/centenario-solera-25-years-gran-reserva-k.jpg', 'Man skal ikke forveksle rommærket Ron Centenario med det mere kendte Ron Zacapa Centenario. Ikke kun fordi de kommer fra forskellige lande, men også fordi de repræsenterer lidt forskellige stilarter. Sidstnævnte produceres i Guatemala, medens førstnævnte hører hjemme i det mellemamerikanske land Costa Rica. I lang tid var Costa Rica primært kendt for produktion af kaffe. Men på grund af sin placering mellem Caribien og Atlanterhavet, kan der dyrkes sukkerrør af meget høj kvalitet &#8211; eminent til fremstilling af god rom! Disse rom og rombaserede spiritusser nyder efterhånden stor respekt blandt kendere, og Centenario Rums har bragt nogle premium-rums på markedet, der er blevet meget populære. Ron Centenario 25 Års Gran Reserva, er en super premium gudedrik, der er lagret i op til 25 år efter solera-metoden i små amerikanske egetræsfade, som tidligere blev brugt til bourbon. Ron Centenario 25 års Gran Reserva er en sød og elegant Solera. med en rig aroma af tropiske frugter, tobak, og vanilje. Smagen er blød med eg og vanilje, samt søde frugtnoter ledsaget af sarte pift af træ og citrus. Farven er som mørk rav. Et produkt, hvor det hele går op i en højere enhed. En fantastisk udgivelse, der har vundet en del guldmedaljer og smagninger &#8211; bl.a. ved German Rum Fest i 2012 i kategorien Solera Rum. Størrelse : 70cl Alkohol % : 40,0 Leveres i et flot gaverør');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Centenario REAL Select Cask Reserve Rum &#8211; Old Edition', 'https://spitus.dk/product/ron-centenario-real-select-cask-reserve-rum/', 2575, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/Ron-Centenario-REAL-Select-Cask-Reserve-Rum-100243-1.jpg', 'Ron Centenario REAL Select Cask Reserve Rum i gaveæske I lang tid var Costa Rica primært kendt for produktion af kaffe. Men på grund af sin placering mellem Caribien og Atlanterhavet, kan der dyrkes sukkerrør af meget høj kvalitet, som derefter kan destilleres til rom. Centenario Rums har bragt nogle premium-rums på markedet, der nyder stigende popularitet. Her præsenterer vi en super eksklusiv, og smuk, smuk aftapning fra destilleriet. Ron Centenario Real, Select Cask Reserve er en Solera-udgivelse, lavet af nøje udvalgte blend af deres bedste rom fra 15 år og op til 30 år. De skotske egetræsfade er helt særligt udvalgte specifikt til denne dram – som navnet også afslører. Fokus ved udvælgelsen har været at kunne skabe den blødeste og rigeste Centenario &#8211; overhovedet! Og det er lykkedes! Farven er dyb ravglød. I næsen er den voluminøs med eg, mandler, røde bær og vanilje. I munden byder den på en unik blødhed, med intense noter af røde bær, mandler, træ, vanilje og chokolade. Meget balanceret og silkeblød finish, der bare bliver ved og ved. Absolut verdensklasse. Brugerne på Rumratigs.com scorer den 9.6/10, hvilket rangerer den som ”Truly a fantastic choice”. Ikke overraskende, fremhæver adskillige den som den bedste rom de nogensinde har smagt. Leveres naturligvis i eksklusiv gaveæske. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Havana Club Anejo 7 Y.O.', 'https://spitus.dk/product/havana-club-anejo-7-y-o/', 249, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/100184-1.jpg', 'Havana Club Añejo 7 Años er en fuldstændig uundgåelig og ikonisk cubansk rom og betragtes som cubansk roms stolthed. Den er, som navnet angiver, fadlagret i 7 år. Faktisk indgår der i blendet en del noget ældre rom, men alderen på den yngste er altid mindst 7 år. Det færdige blend får lov at lagre sammen på fade, og denne ”continuos aging” teknik, er selve DNA’et i Havana Club 7 Años. Havana Club er et af verdens mest kendte rommærker og nok hovedårsagen til, at de fleste tænker ”Cuba”, når snakken falder på rom. Stilmæssigt er Havana Club helt klassisk cubansk; lavet på sukkerrørsmelasse og destilleret på kolonnekedler, hvilket er med til at give den lette og friske karakter. Aromaerne er som at dufte til Cuba: Tobak, vanilje og kakao. I munden er der modne frugter med kakao, vanilje, kastanjer og mørke krydderier. Mads &#8220;Romhatten&#8221; Heitmann: ”Añejo 7 Años er Cubanernes stolthed og Havana Clubs flagskib, der sætter standarden for lagret mørk rom i hele verden. Sammensat af udvalgte fade med rom, der alle har lagret i minimum 7 år. Havana Club er Cubas største rommærke og denne 7 års lagrede rom er helt i topklasse uden at sprænge budgettet. Den har en flot gylden mahognifarve”. Størrelse : 70cl Alkohol % : 40,0');
INSERT INTO stg_spitus_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description) VALUES ('Ron Zacapa Centenario 23 SISTEMA SOLERA Gran Reserva', 'https://spitus.dk/product/zacapa-23-y-o-40-70-cl-gaveaeske/', 469, true, 70, 40, 'https://spitus.dk/wp-content/uploads/2020/06/ron-zacapa-23-yo.i-gaveaeske.png', 'Zacapa 23 år er for mange den første kærlighed til fadlageret rom. Den har vundet utallige priser, herunder flere gange kåret til ”Verdens bedste rom”. Ron Zacapa Centenario 23 års var den første rom, der vandt førstepladsen i kategorien, ”Premium Rum”, 4 år i træk ved Den Internationale Rom Festival; 1998, 1999, 2000 og 2001. Det var også den første rom, der blev inkluderet i International Rum Festival&#8217;s Hall of Fame. I glasset er den let mahogni, og man fornemmer alderen, hvor de lange spor klæber sig fast til indersiden af glasset. I næsen blød og sød med karamel, vanilje, kakao og rosiner. Man fornemmer de mange lag og kompleksiteten fra de mange forskellige typer fade. Der er sherry-noter og ristede hasselnødder. I munden går indtrykket fra næsen igen, og man får derudover tørret ananas (sikkert fra de amerikanske whisky-fade) og banan. Den er generøs og fyldig med en sød honningviskositet, rosiner, vanilje og abrikoser. Det er stor velsmag, og den lukker med et touch af læder, tobak samt et smæld af kanel og ingefær. Alle kan være med her. Nye ude i rommens verden vil værdsætte den søde, men stadig komplekse stil. Kendere fornægter ikke et godt produkt. Vi kan sagtens forstå, at Ron Zacapa 23 års har gået sin sejrsgang over hele verden. Den er den dag i dag den mest solgte fadlagrede rom i Danmark og mange andre lande. Størrelse : 70cl Alkohol % : 40,0 Leveres i gaveæske.');
