-- ============================================================
-- SPITUS.DK: Staging-tabel + 348 produkter (hentet 2026-11-08
-- via WooCommerces Store-API — ingen scraping nødvendig!)
--
-- Kør hele filen i Supabase SQL Editor.
-- Bagefter kør:  SELECT * FROM import_shop('Spitus.dk',
--                  'https://spitus.dk', 'stg_spitus_dk', 'Rom');
-- ============================================================

DROP TABLE IF EXISTS stg_spitus_dk;

CREATE TABLE stg_spitus_dk (
    name         TEXT,
    url          TEXT UNIQUE,
    price_dkk    NUMERIC,
    in_stock     BOOLEAN,
    volume_cl    NUMERIC,      -- NULL = ikke fundet (kits m.m.)
    abv          NUMERIC,
    image_url    TEXT,
    description  TEXT,
    scraped_at   TIMESTAMPTZ DEFAULT '2026-11-08 09:30:00+01'
);


-- KONTROL
SELECT count(*) AS total,
       count(*) FILTER (WHERE in_stock) AS paa_lager,
       count(*) FILTER (WHERE volume_cl IS NULL) AS uden_volumen,
       count(*) FILTER (WHERE abv IS NULL) AS uden_abv,
       min(price_dkk) AS billigste,
       max(price_dkk) AS dyreste
FROM stg_spitus_dk;
